module csa_budget_acc (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] inc,
    output wire [8:0] o_total,
    output wire       o_full
);
    // accumulator kept in carry-save form: the two halves always sum to the
    // true running total, and at most 10 increments of at most 3 are consumed
    reg [7:0] sum_h;
    reg [7:0] car_h;
    reg [3:0] n;

    initial sum_h = 8'd0;
    initial car_h = 8'd0;
    initial n     = 4'd0;

    wire [7:0] x       = {6'd0, inc};
    wire [7:0] nxt_sum = sum_h ^ car_h ^ x;
    wire [7:0] maj     = (sum_h & car_h) | (sum_h & x) | (car_h & x);
    wire [7:0] nxt_car = {maj[6:0], 1'b0};

    wire budget = (n < 4'd10);

    always @(posedge clk) begin
        if (rst) begin
            sum_h <= 8'd0;
            car_h <= 8'd0;
            n     <= 4'd0;
        end else if (ce && budget) begin
            sum_h <= nxt_sum;
            car_h <= nxt_car;
            n     <= n + 4'd1;
        end
    end

    // the true total is the sum of the two carry-save halves
    wire [8:0] total = {1'b0, sum_h} + {1'b0, car_h};

    assign o_total = total;
    assign o_full  = ~budget;

    // bounded existence: the accumulated total never exceeds 30,
    // far below what the 9-bit total could hold
    assert property (total <= 9'd30);
endmodule

module trace_fifo (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       full,
    output wire       empty
);
    // depth 8 trace queue: 3 address bits + 1 wrap bit per pointer
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        for (k = 0; k < 8; k = k + 1)
            mem[k] = 8'h00;
    end

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);
    assign rdata = mem[rptr[2:0]];

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
        end else begin
            if (do_push) begin
                mem[wptr[2:0]] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;

            if (do_push && !do_pop)
                count <= count + 4'd1;
            else if (do_pop && !do_push)
                count <= count - 4'd1;
        end
    end

    // P: two universal pointer/occupancy agreements, checked in every state
    always @(*) begin
        assert (count != 4'd0 || wptr == rptr);
        assert (count != 4'd8 || wptr[2:0] == rptr[2:0]);
    end
endmodule

module fifo_deadline #(parameter DW = 8) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire push,
    input wire [DW-1:0] wdata,
    output wire [DW-1:0] rdata,
    output wire o_pop,
    output wire full,
    output wire empty
);
    // service deadline: an accepted entry must be drained within K steps
    localparam [2:0] K = 3'd4;

    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, 0..4
    reg [2:0] timer = 3'd0;   // countdown to forced service

    reg [DW-1:0] mem [0:3];
    integer i;
    initial begin
        for (i = 0; i < 4; i = i + 1) mem[i] = {DW{1'b0}};
    end

    // derived flags
    assign full  = (count == 3'd4);
    assign empty = (wptr == rptr);

    wire do_push = step && push && !full;
    wire do_pop  = step && !empty && (timer == 3'd1);

    assign rdata = mem[rptr[1:0]];
    assign o_pop = do_pop;

    wire [2:0] count_nxt = count + (do_push ? 3'd1 : 3'd0)
                                 - (do_pop  ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 3'd0;
            timer <= 3'd0;
        end else if (step) begin
            if (do_push) begin
                mem[wptr[1:0]] <= wdata;
                wptr <= wptr + 3'd1;
            end
            if (do_pop)
                rptr <= rptr + 3'd1;

            count <= count_nxt;

            if (count_nxt == 3'd0)
                timer <= 3'd0;                 // nothing outstanding
            else if (do_pop || (count == 3'd0))
                timer <= K;                    // fresh deadline granted
            else
                timer <= timer - 3'd1;         // tick toward forced service
        end
    end

    // P: the countdown never expires while an entry is still outstanding
    always @(posedge clk)
        if (count != 3'd0)
            assert (timer != 3'd0);

endmodule

module token_bucket_shaper (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low => all state frozen
    input  wire       req,       // request a grant
    output wire       grant,
    output reg  [3:0] tokens,    // tokens available in the bucket
    output reg  [3:0] reserve,   // tokens not yet refilled (pool)
    output reg  [1:0] timer      // refill timer
);
    // burst size of the shaper: the bucket plus the pool always hold
    // exactly this many tokens between them.
    localparam [3:0] BURST = 4'd6;

    initial tokens  = BURST;
    initial reserve = 4'd0;
    initial timer   = 2'd0;

    wire tick      = (timer == 2'd3);
    wire do_refill = tick && (reserve != 4'd0);
    wire do_grant  = req  && (tokens  != 4'd0);

    assign grant = i_ce && do_grant;

    always @(posedge clk) begin
        if (rst) begin
            tokens  <= BURST;
            reserve <= 4'd0;
            timer   <= 2'd0;
        end else if (i_ce) begin
            timer <= timer + 2'd1;
            case ({do_refill, do_grant})
                2'b10: begin
                    // refill: a token migrates pool -> bucket
                    tokens  <= tokens  + 4'd1;
                    reserve <= reserve - 4'd1;
                end
                2'b01: begin
                    // drain: a token migrates bucket -> pool
                    tokens  <= tokens  - 4'd1;
                    reserve <= reserve + 4'd1;
                end
                default: begin
                    // idle, or refill and grant cancelling out
                    tokens  <= tokens;
                    reserve <= reserve;
                end
            endcase
        end
    end

    // P: neither the bucket nor the pool ever holds more than the burst
    // size, even though each register is 4 bits wide.
    always @(posedge clk) assert (tokens  <= BURST);
    always @(posedge clk) assert (reserve <= BURST);
endmodule

module pingpong_double_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       wbank_full,
    output wire       rbank_empty
);
    // Two halves of an 8-entry RAM: half 0 is entries 0..3, half 1 is 4..7.
    // The writer owns half `wsel`, the reader owns half `rsel`; the two halves
    // are exchanged only when the write half is full and the read half drained.

    reg        wsel;
    reg        rsel;
    reg [2:0]  wcnt;
    reg [2:0]  rcnt;
    reg [7:0]  mem [0:7];

    initial begin
        wsel = 1'b0;
        rsel = 1'b1;
        wcnt = 3'd0;
        rcnt = 3'd4;   // reader's half starts empty (already drained)
    end

    wire wdone = (wcnt == 3'd4);
    wire rdone = (rcnt == 3'd4);
    wire swap  = wdone && rdone;

    wire [2:0] waddr = {wsel, wcnt[1:0]};
    wire [2:0] raddr = {rsel, rcnt[1:0]};

    assign wbank_full  = wdone;
    assign rbank_empty = rdone;
    assign rdata       = mem[raddr];

    always @(posedge clk) begin
        if (rst) begin
            wsel <= 1'b0;
            rsel <= 1'b1;
            wcnt <= 3'd0;
            rcnt <= 3'd4;
        end else if (swap) begin
            // hand the filled half to the reader, the drained half to the writer
            wsel <= ~wsel;
            rsel <= ~rsel;
            wcnt <= 3'd0;
            rcnt <= 3'd0;
        end else begin
            if (wr_en && !wdone) begin
                mem[waddr] <= wdata;
                wcnt <= wcnt + 3'd1;
            end
            if (rd_en && !rdone) begin
                rcnt <= rcnt + 3'd1;
            end
        end
    end

    // P: the write port and the read port never address the same RAM location.
    always @(posedge clk)
        assert (waddr != raddr);

endmodule

module pdm_cic_precedence (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_pdm,
    output wire [31:0] o_pcm
);
    localparam [31:0] DEC = 32'd64;

    reg [31:0] integ1;
    reg [31:0] integ2;
    reg [31:0] dly1;
    reg [31:0] dly2;
    reg [31:0] pcm;
    reg [31:0] phase;
    reg        seen_one;
    reg        armed;

    initial integ1   = 32'd0;
    initial integ2   = 32'd0;
    initial dly1     = 32'd0;
    initial dly2     = 32'd0;
    initial pcm      = 32'd0;
    initial phase    = 32'd0;
    initial seen_one = 1'b0;
    initial armed    = 1'b0;

    wire [31:0] integ1_n = integ1 + {31'd0, i_pdm};
    wire [31:0] integ2_n = integ2 + integ1;
    wire [31:0] comb1    = integ2 - dly1;
    wire [31:0] comb2    = comb1 - dly2;
    wire        tick     = (phase == DEC - 32'd1);

    always @(posedge clk) begin
        if (i_ce) begin
            integ1 <= integ1_n;
            integ2 <= integ2_n;
            if (i_pdm)
                seen_one <= 1'b1;
            if (tick) begin
                phase <= 32'd0;
                dly1  <= integ2;
                dly2  <= comb1;
                pcm   <= comb2;
                armed <= 1'b1;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    assign o_pcm = pcm;

    always @(posedge clk) assert (!armed || pcm == 32'd0 || seen_one);
endmodule

module raw_hazard_wq (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire [63:0] wr_addr,
    input  wire [7:0]  wr_mask,
    input  wire        pop,
    input  wire        rd_valid,
    input  wire [63:0] rd_addr,
    input  wire [7:0]  rd_mask,
    output wire [31:0] o_match,
    output wire        o_fwd,
    output wire        o_stall,
    output wire        o_full,
    output wire        o_empty
);
    reg [63:0] q_addr [0:31];
    reg [7:0]  q_mask [0:31];
    reg [63:0] wptr, rptr, count;
    reg [31:0] match_vec;
    reg        fwd_r, stall_r;
    integer i;
    initial begin
        wptr = 64'd0; rptr = 64'd0; count = 64'd0;
        match_vec = 32'd0; fwd_r = 1'b0; stall_r = 1'b0;
        for (i = 0; i < 32; i = i + 1) begin
            q_addr[i] = 64'd0;
            q_mask[i] = 8'd0;
        end
    end

    wire full  = ((wptr - rptr) == 64'd32);
    wire empty = (count == 64'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;

    wire [31:0] hit;
    wire [31:0] cov_ok;
    genvar g;
    generate
        for (g = 0; g < 32; g = g + 1) begin : cmp
            localparam [4:0] IDX = g;
            wire [4:0] off = IDX - rptr[4:0];
            wire pend = ({59'd0, off} < count);
            assign hit[g]    = pend && (q_addr[g] == rd_addr) && ((q_mask[g] & rd_mask) != 8'd0);
            assign cov_ok[g] = ((q_mask[g] & rd_mask) == rd_mask);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 64'd0;
            rptr <= 64'd0;
            count <= 64'd0;
            match_vec <= 32'd0;
            fwd_r <= 1'b0;
            stall_r <= 1'b0;
        end else begin
            if (do_push) begin
                q_addr[wptr[4:0]] <= wr_addr;
                q_mask[wptr[4:0]] <= wr_mask;
                wptr <= wptr + 64'd1;
            end
            if (do_pop)
                rptr <= rptr + 64'd1;
            case ({do_push, do_pop})
                2'b10: count <= count + 64'd1;
                2'b01: count <= count - 64'd1;
                default: count <= count;
            endcase
            if (rd_valid) begin
                match_vec <= hit;
                fwd_r   <= (hit != 32'd0) && ((hit & cov_ok) == hit);
                stall_r <= (hit != 32'd0) && ((hit & cov_ok) != hit);
            end
        end
    end

    assign o_match = match_vec;
    assign o_fwd   = fwd_r;
    assign o_stall = stall_r;
    assign o_full  = full;
    assign o_empty = empty;

    assert property (!(full && empty));
endmodule

module tia_pll_seq (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire band_ok,
    input wire lock_in,
    output wire pll_pwr,
    output wire cal_active,
    output wire loop_closed,
    output wire clk_release,
    output reg [3:0] band
);
    localparam [2:0] S_OFF      = 3'd0;
    localparam [2:0] S_PWRUP    = 3'd1;
    localparam [2:0] S_BANDCAL  = 3'd2;
    localparam [2:0] S_CLOSE    = 3'd3;
    localparam [2:0] S_LOCKWAIT = 3'd4;
    localparam [2:0] S_RUN      = 3'd5;

    reg [2:0]  state;
    reg [15:0] cnt;

    initial state = S_OFF;
    initial cnt   = 16'd0;
    initial band  = 4'd0;

    assign pll_pwr     = (state != S_OFF);
    assign cal_active  = (state == S_BANDCAL);
    assign loop_closed = (state == S_CLOSE) || (state == S_LOCKWAIT) || (state == S_RUN);
    assign clk_release = (state == S_RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S_OFF;
            cnt   <= 16'd0;
            band  <= 4'd0;
        end else if (en) begin
            case (state)
                S_OFF: begin
                    state <= S_PWRUP;
                    cnt   <= 16'd0;
                end
                S_PWRUP: begin
                    if (cnt >= 16'd511) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
                end
                S_LOCKWAIT: begin
                    if (!lock_in) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else if (cnt >= 16'd1200) begin
                        state <= S_RUN;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_RUN: begin
                    cnt <= 16'd0;
                    if (!lock_in)
                        state <= S_BANDCAL;
                end
                default: begin
                    state <= S_OFF;
                    cnt   <= 16'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (state == 3'd4) assert (cnt <= 16'd1200);
endmodule

module pwm_fault_trip (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       fault_in,
    input  wire       cfg_we,
    input  wire [3:0] cfg_hi,
    input  wire [3:0] cfg_lo,
    input  wire       clr_req,
    input  wire       duty_we,
    input  wire [7:0] duty_in,
    output reg  [3:0] out_hi,
    output reg  [3:0] out_lo
);
    reg [7:0] cnt;
    reg [7:0] duty;
    reg       fault_lat;
    reg [3:0] safe_hi;
    reg [3:0] safe_lo;
    reg       clr_arm;
    reg       no_clear_yet;

    initial cnt = 8'd0;
    initial duty = 8'd128;
    initial fault_lat = 1'b0;
    initial safe_hi = 4'b0000;
    initial safe_lo = 4'b1111;
    initial clr_arm = 1'b0;
    initial no_clear_yet = 1'b1;
    initial out_hi = 4'b0000;
    initial out_lo = 4'b1111;

    wire pwm_on = (cnt < duty);

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= 8'd0;
            duty      <= 8'd128;
            fault_lat <= 1'b0;
            safe_hi   <= 4'b0000;
            safe_lo   <= 4'b1111;
            clr_arm   <= 1'b0;
            out_hi    <= 4'b0000;
            out_lo    <= 4'b1111;
        end else if (ce) begin
            cnt <= cnt + 8'd1;
            if (duty_we)
                duty <= duty_in;
            if (cfg_we) begin
                safe_hi <= cfg_hi;
                safe_lo <= cfg_lo & ~cfg_hi;
            end
            if (clr_req)
                clr_arm <= 1'b1;
            if (fault_in)
                fault_lat <= 1'b1;
            else if (clr_arm && fault_lat) begin
                fault_lat    <= 1'b0;
                clr_arm      <= 1'b0;
                no_clear_yet <= 1'b0;
            end
            if (fault_in || fault_lat) begin
                out_hi <= safe_hi;
                out_lo <= safe_lo;
            end else begin
                out_hi <= {4{pwm_on}};
                out_lo <= {4{~pwm_on}};
            end
        end
    end

    always @(posedge clk)
        if (no_clear_yet)
            assert ((out_hi & out_lo) == 4'd0);
endmodule

module tile_polarity_lock (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         retrain,
    input  wire [127:0] rx_data,
    output wire [127:0] data_out,
    output reg          locked
);
    localparam [7:0] TS     = 8'hBC;
    localparam [7:0] TS_INV = 8'h43;

    reg [15:0] inv_flag;
    reg [15:0] det_mask;
    reg [4:0]  det_cnt;
    reg        pre_rt;
    reg        pv;

    initial inv_flag = 16'd0;
    initial det_mask = 16'd0;
    initial det_cnt  = 5'd0;
    initial locked   = 1'b0;
    initial pre_rt   = 1'b1;
    initial pv       = 1'b0;

    reg [15:0] new_mask;
    reg [15:0] nxt_inv;
    reg [4:0]  new_cnt;
    integer i;

    always @(*) begin
        new_mask = 16'd0;
        nxt_inv  = inv_flag;
        new_cnt  = 5'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (!det_mask[i]) begin
                if (rx_data[8*i +: 8] == TS) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b0;
                end else if (rx_data[8*i +: 8] == TS_INV) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b1;
                end
            end
            new_cnt = new_cnt + {4'd0, new_mask[i]};
        end
    end

    wire [4:0] sum_cnt = det_cnt + new_cnt;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_lane
            assign data_out[8*g +: 8] = rx_data[8*g +: 8] ^ {8{inv_flag[g]}};
        end
    endgenerate

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            inv_flag <= 16'd0;
            det_mask <= 16'd0;
            det_cnt  <= 5'd0;
            locked   <= 1'b0;
            pre_rt   <= 1'b1;
        end else if (en) begin
            if (retrain) begin
                inv_flag <= 16'd0;
                det_mask <= 16'd0;
                det_cnt  <= 5'd0;
                locked   <= 1'b0;
                pre_rt   <= 1'b0;
            end else begin
                inv_flag <= nxt_inv;
                det_mask <= det_mask | new_mask;
                det_cnt  <= sum_cnt;
                locked   <= locked | (sum_cnt == 5'd16);
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && pre_rt && $rose(locked))
            assert (&det_mask);
endmodule

module SsiFir8 (
    input  wire        clk,
    input  wire        en,
    input  wire        load_req,
    input  wire [31:0] coef_in,
    input  wire        s_valid,
    input  wire [31:0] s_data,
    input  wire        frame_end,
    output wire [31:0] y,
    output wire        y_valid
);
    reg [31:0] tap  [0:7];
    reg [31:0] coef [0:7];
    reg [31:0] fill_cnt = 32'd0;
    reg        primed   = 1'b0;
    reg        loading  = 1'b0;
    reg [31:0] load_ptr = 32'd0;
    reg        win      = 1'b0;
    reg        pv       = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 32'd0;
            coef[i] = 32'd0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (load_req) begin
                loading  <= 1'b1;
                load_ptr <= 32'd0;
                fill_cnt <= 32'd0;
                primed   <= 1'b0;
            end else begin
                primed <= (fill_cnt >= 32'd8);
                if (loading) begin
                    coef[load_ptr[2:0]] <= coef_in;
                    if (load_ptr == 32'd7) begin
                        loading  <= 1'b0;
                        load_ptr <= 32'd0;
                    end else begin
                        load_ptr <= load_ptr + 32'd1;
                    end
                end else if (s_valid) begin
                    for (i = 7; i > 0; i = i - 1)
                        tap[i] <= tap[i-1];
                    tap[0]   <= s_data;
                    fill_cnt <= (fill_cnt < 32'd8) ? (fill_cnt + 32'd1) : 32'd8;
                end
            end
            if (load_req)
                win <= 1'b1;
            else if (frame_end)
                win <= 1'b0;
        end
    end

    assign y = tap[0]*coef[0] + tap[1]*coef[1] + tap[2]*coef[2] + tap[3]*coef[3]
             + tap[4]*coef[4] + tap[5]*coef[5] + tap[6]*coef[6] + tap[7]*coef[7];
    assign y_valid = primed;

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(primed) && $past(loading)));
endmodule

module trivium_core (
    input  wire        clk,
    input  wire        ce,
    input  wire        load,
    input  wire        zeroize,
    input  wire [79:0] key,
    input  wire [79:0] iv,
    output wire        ks_bit,
    output wire        ks_valid,
    output reg         ready
);
    reg [287:0] s = 288'd0;
    reg [63:0]  wcnt = 64'd0;
    reg         busy = 1'b0;
    reg         seen_load = 1'b0;
    reg         armed = 1'b1;
    reg         pv = 1'b0;
    initial ready = 1'b0;

    wire t1a = s[65]  ^ s[92];
    wire t2a = s[161] ^ s[176];
    wire t3a = s[242] ^ s[287];
    wire z   = t1a ^ t2a ^ t3a;
    wire t1  = t1a ^ (s[90]  & s[91])  ^ s[170];
    wire t2  = t2a ^ (s[174] & s[175]) ^ s[263];
    wire t3  = t3a ^ (s[285] & s[286]) ^ s[68];

    wire [287:0] nxt  = {s[286:177], t2, s[175:93], t1, s[91:0], t3};
    wire [287:0] init = {3'b111, 108'd0, 4'd0, iv, 13'd0, key};

    assign ks_bit   = z;
    assign ks_valid = ready && ce && !load && !zeroize;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (zeroize) begin
            s         <= 288'd0;
            wcnt      <= 64'd0;
            busy      <= 1'b0;
            ready     <= 1'b0;
            seen_load <= 1'b0;
            armed     <= 1'b0;
        end else if (ce) begin
            if (load) begin
                s         <= init;
                wcnt      <= 64'd0;
                busy      <= 1'b1;
                ready     <= 1'b0;
                seen_load <= 1'b1;
            end else if (busy) begin
                s <= nxt;
                if (wcnt == 64'd1151) begin
                    busy  <= 1'b0;
                    ready <= 1'b1;
                    wcnt  <= 64'd0;
                end else begin
                    wcnt <= wcnt + 64'd1;
                end
            end else if (ready) begin
                s <= nxt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(ready))
            assert (seen_load);
endmodule

module tlb32_ice40 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [51:0] lookup_vpn,
    input wire [7:0] lookup_asid,
    input wire fill,
    input wire [51:0] fill_vpn,
    input wire [7:0] fill_asid,
    input wire [51:0] fill_ppn,
    input wire [2:0] fill_perm,
    input wire flush_all,
    input wire flush_asid,
    input wire [7:0] asid_sel,
    output reg hit,
    output reg [51:0] ppn_out,
    output reg [2:0] perm_out
);
    reg [31:0] valid = 32'd0;
    reg [63:0] occ = 64'd0;
    reg [63:0] hits = 64'd0;
    reg [4:0] victim = 5'd0;

    reg [51:0] tag_vpn [0:31];
    reg [7:0] tag_asid [0:31];
    reg [51:0] data_ppn [0:31];
    reg [2:0] data_perm [0:31];

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            tag_vpn[i] = 52'd0;
            tag_asid[i] = 8'd0;
            data_ppn[i] = 52'd0;
            data_perm[i] = 3'd0;
        end
    end

    function [6:0] popcount32;
        input [31:0] v;
        integer k;
        begin
            popcount32 = 7'd0;
            for (k = 0; k < 32; k = k + 1)
                popcount32 = popcount32 + {6'd0, v[k]};
        end
    endfunction

    reg [31:0] asid_match;
    reg [4:0] free_idx;
    reg has_free;
    integer j;

    always @(*) begin
        asid_match = 32'd0;
        hit = 1'b0;
        ppn_out = 52'd0;
        perm_out = 3'd0;
        has_free = 1'b0;
        free_idx = 5'd0;
        for (j = 31; j >= 0; j = j - 1) begin
            if (!valid[j]) begin
                has_free = 1'b1;
                free_idx = j;
            end
        end
        for (j = 0; j < 32; j = j + 1) begin
            if (valid[j] && (tag_asid[j] == asid_sel))
                asid_match[j] = 1'b1;
            if (valid[j] && !hit && (tag_vpn[j] == lookup_vpn) && (tag_asid[j] == lookup_asid)) begin
                hit = 1'b1;
                ppn_out = data_ppn[j];
                perm_out = data_perm[j];
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= 32'd0;
            occ <= 64'd0;
            hits <= 64'd0;
            victim <= 5'd0;
        end else if (en) begin
            if (flush_all) begin
                valid <= 32'd0;
                occ <= 64'd0;
            end else if (flush_asid) begin
                valid <= valid & ~asid_match;
                occ <= occ - {57'd0, popcount32(asid_match)};
            end else if (fill) begin
                if (has_free) begin
                    tag_vpn[free_idx] <= fill_vpn;
                    tag_asid[free_idx] <= fill_asid;
                    data_ppn[free_idx] <= fill_ppn;
                    data_perm[free_idx] <= fill_perm;
                    valid <= valid | (32'd1 << free_idx);
                    occ <= occ + 64'd1;
                end else begin
                    tag_vpn[victim] <= fill_vpn;
                    tag_asid[victim] <= fill_asid;
                    data_ppn[victim] <= fill_ppn;
                    data_perm[victim] <= fill_perm;
                    victim <= victim + 5'd1;
                end
            end
            if (hit)
                hits <= hits + 64'd1;
        end
    end

    assert property (occ <= 64'd32);
endmodule

module conv_enc_win (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    input wire start,
    input wire stop,
    output reg c0,
    output reg c1,
    output reg win,
    output reg [15:0] nbits
);
    // constraint-length-4 shift register of past input bits (4 entries)
    reg [3:0] sr;
    initial sr = 4'b0000;
    initial c0 = 1'b0;
    initial c1 = 1'b0;
    initial win = 1'b0;
    initial nbits = 16'd0;

    wire [3:0] sr_n = {sr[2:0], din};

    // G0 = 1111 computed incrementally as a sliding-window parity,
    // G1 = 1011 computed directly from the next shift-register contents
    always @(posedge clk) begin
        if (rst) begin
            sr    <= 4'b0000;
            c0    <= 1'b0;
            c1    <= 1'b0;
            nbits <= 16'd0;
        end else if (ce) begin
            sr    <= sr_n;
            c0    <= c0 ^ din ^ sr[3];
            c1    <= sr_n[3] ^ sr_n[1] ^ sr_n[0];
            nbits <= nbits + 16'd1;
        end
    end

    // observation window: opened by start, closed by stop
    always @(posedge clk) begin
        if (rst)
            win <= 1'b0;
        else if (start)
            win <= 1'b1;
        else if (stop)
            win <= 1'b0;
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    // inside the window, the XOR of the two code bits equals the input bit
    // that sat in tap position 1 before the shift
    always @(posedge clk)
        if (pv && win && $past(ce) && !$past(rst))
            assert ((c0 ^ c1) == $past(sr[1]));
endmodule

module issie_dbi_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [63:0] wdata,
    input  wire        q_start,
    input  wire        r_stop,
    output wire [63:0] rdata,
    output wire [63:0] beat_count
);
    reg [63:0] bus_q;
    reg [7:0]  dbi_q;
    reg [63:0] plain_q;
    reg [63:0] beat_cnt;
    reg        win;
    reg        pv;
    initial begin
        bus_q = 64'd0; dbi_q = 8'd0; plain_q = 64'd0;
        beat_cnt = 64'd0; win = 1'b0; pv = 1'b0;
    end

    function [3:0] pop8;
        input [7:0] b;
        integer k;
        begin
            pop8 = 4'd0;
            for (k = 0; k < 8; k = k + 1)
                pop8 = pop8 + {3'd0, b[k]};
        end
    endfunction

    wire [7:0]  f;
    wire [63:0] enc;
    wire [63:0] xdbi;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : g_lane
            assign f[i] = ((4'd8 - pop8(wdata[8*i +: 8])) > 4'd4);
            assign enc[8*i +: 8]  = wdata[8*i +: 8] ^ {8{f[i]}};
            assign xdbi[8*i +: 8] = {8{dbi_q[i]}};
        end
    endgenerate

    assign rdata = bus_q ^ xdbi;
    assign beat_count = beat_cnt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            bus_q <= 64'd0;
            dbi_q <= 8'd0;
            plain_q <= 64'd0;
            beat_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (wr) begin
                bus_q <= enc;
                dbi_q <= f;
                plain_q <= wdata;
                beat_cnt <= beat_cnt + 64'd1;
            end
            if (q_start)
                win <= 1'b1;
            else if (r_stop)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && $past(win) && $stable(bus_q) && $stable(dbi_q))
            assert ($stable(plain_q));
endmodule

module fp8_reduce_minmax (
    input wire clk,
    input wire rst,
    input wire en,
    input wire valid,
    input wire op,
    input wire [7:0] x,
    output reg [7:0] mx,
    output reg [7:0] mn,
    output reg [7:0] res,
    output reg inv,
    output reg armed
);
    initial mx = 8'hFC;
    initial mn = 8'h7C;
    initial res = 8'h00;
    initial inv = 1'b0;
    initial armed = 1'b0;

    function isnan;
        input [7:0] a;
        isnan = (a[6:2] == 5'h1F) && (a[1:0] != 2'b00);
    endfunction

    function [7:0] key;
        input [7:0] a;
        key = a[7] ? ~a : (a | 8'h80);
    endfunction

    function [7:0] fmax;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmax = 8'h7E;
            else if (isnan(a)) fmax = b;
            else if (isnan(b)) fmax = a;
            else if (key(a) >= key(b)) fmax = a;
            else fmax = b;
        end
    endfunction

    function [7:0] fmin;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmin = 8'h7E;
            else if (isnan(a)) fmin = b;
            else if (isnan(b)) fmin = a;
            else if (key(a) <= key(b)) fmin = a;
            else fmin = b;
        end
    endfunction

    function fle;
        input [7:0] a;
        input [7:0] b;
        fle = !isnan(a) && !isnan(b) && (key(a) <= key(b));
    endfunction

    wire [7:0] nmax = fmax(mx, x);
    wire [7:0] nmin = fmin(mn, x);

    always @(posedge clk) begin
        if (rst) begin
            mx <= 8'hFC;
            mn <= 8'h7C;
            res <= 8'h00;
            inv <= 1'b0;
            armed <= 1'b0;
        end else if (en && valid) begin
            mx <= nmax;
            mn <= nmin;
            res <= op ? nmin : nmax;
            inv <= isnan(x) && !x[1];
            armed <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!isnan(mx) && !isnan(mn) && (fle(mn, mx) || (mx == 8'hFC && mn == 8'h7C)));
endmodule

module mem_stream_reader (
    input  wire        clk,
    input  wire        rst,
    input  wire        start,
    input  wire [31:0] i_len,
    input  wire [31:0] i_psize,
    input  wire        ce,
    input  wire        wr_en,
    input  wire [4:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_valid,
    output wire [31:0] o_data,
    output wire        o_start,
    output wire        o_last
);
    reg [31:0] mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) mem[i] = 32'd0;
    end
    always @(posedge clk)
        if (wr_en) mem[wr_addr] <= wr_data;

    reg [31:0] rd_ptr    = 32'd0;
    reg [31:0] remaining = 32'd0;
    reg [31:0] pkt_size  = 32'd8;
    reg [31:0] beat      = 32'd0;
    reg        busy      = 1'b0;
    reg        in_pkt    = 1'b0;

    wire fire = busy && ce;
    assign o_valid = busy;
    assign o_data  = mem[rd_ptr[4:0]];
    assign o_start = busy && (beat == 32'd0);
    assign o_last  = busy && ((beat == pkt_size - 32'd1) || (remaining == 32'd1));

    wire [31:0] len_c = (i_len > 32'd32) ? 32'd32 : i_len;
    wire [31:0] psz_c = ((i_psize == 32'd0) || (i_psize > 32'd8)) ? 32'd8 : i_psize;

    always @(posedge clk) begin
        if (rst) begin
            rd_ptr    <= 32'd0;
            remaining <= 32'd0;
            pkt_size  <= 32'd8;
            beat      <= 32'd0;
            busy      <= 1'b0;
            in_pkt    <= 1'b0;
        end else if (start && !busy) begin
            rd_ptr    <= 32'd0;
            remaining <= len_c;
            pkt_size  <= psz_c;
            beat      <= 32'd0;
            busy      <= (len_c != 32'd0);
            in_pkt    <= 1'b0;
        end else if (fire) begin
            rd_ptr    <= rd_ptr + 32'd1;
            remaining <= remaining - 32'd1;
            busy      <= (remaining != 32'd1);
            beat      <= o_last ? 32'd0 : beat + 32'd1;
            if (o_last)
                in_pkt <= 1'b0;
            else if (o_start)
                in_pkt <= 1'b1;
        end
    end

    always @(posedge clk)
        if (in_pkt) assert (beat <= 32'd7);
endmodule

module cdc_line_edge_fifo (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [127:0] din,
    input  wire         rd_en,
    input  wire         cfg_set,
    output wire [127:0] dout,
    output reg          full,
    output reg          empty
);
    reg [127:0] prev;
    reg [127:0] mem [0:15];
    reg [3:0]   wr_ptr;
    reg [3:0]   rd_ptr;
    reg [4:0]   count;
    reg         armed;
    reg         pv;
    integer i;

    initial begin
        prev   = 128'd0;
        wr_ptr = 4'd0;
        rd_ptr = 4'd0;
        count  = 5'd0;
        full   = 1'b0;
        empty  = 1'b1;
        armed  = 1'b0;
        pv     = 1'b0;
        for (i = 0; i < 16; i = i + 1) mem[i] = 128'd0;
    end

    wire edge_seen = en && (din != prev);
    wire push = edge_seen && !full;
    wire pop  = en && rd_en && !empty;
    wire [4:0] count_next = count + {4'd0, push} - {4'd0, pop};

    assign dout = mem[rd_ptr];

    always @(posedge clk) begin
        if (!rst_n) begin
            prev   <= 128'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count  <= 5'd0;
            full   <= 1'b0;
            empty  <= 1'b1;
            armed  <= 1'b0;
        end else if (en) begin
            prev <= din;
            if (push) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (pop)
                rd_ptr <= rd_ptr + 4'd1;
            count <= count_next;
            full  <= (count_next == 5'd16);
            empty <= (count_next == 5'd0);
            armed <= armed | cfg_set;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && armed && $rose(edge_seen))
            assert (!(full && empty));
endmodule

module mesi_pair (
    input wire clk,
    input wire rst,
    input wire step,
    input wire who,
    input wire wr,
    output reg [1:0] st_a,
    output reg [1:0] st_b,
    output reg bus_req,
    output reg [31:0] bus_cnt,
    output reg [31:0] wb_cnt
);
    localparam [1:0] ST_I = 2'b00;
    localparam [1:0] ST_S = 2'b01;
    localparam [1:0] ST_E = 2'b10;
    localparam [1:0] ST_M = 2'b11;

    initial st_a = ST_I;
    initial st_b = ST_I;
    initial bus_req = 1'b0;
    initial bus_cnt = 32'd0;
    initial wb_cnt = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            st_a <= ST_I;
            st_b <= ST_I;
            bus_req <= 1'b0;
            bus_cnt <= 32'd0;
            wb_cnt <= 32'd0;
        end else if (step) begin
            bus_req <= 1'b0;
            if (!who) begin
                if (wr) begin
                    if (st_a == ST_E) begin
                        st_a <= ST_M;
                    end else if (st_a != ST_M) begin
                        st_a <= ST_M;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_a == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_b == ST_I) begin
                        st_a <= ST_E;
                    end else begin
                        st_a <= ST_S;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_S;
                    end
                end
            end else begin
                if (wr) begin
                    if (st_b == ST_E) begin
                        st_b <= ST_M;
                    end else if (st_b != ST_M) begin
                        st_b <= ST_M;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_b == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_a == ST_I) begin
                        st_b <= ST_E;
                    end else begin
                        st_b <= ST_S;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_S;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!(st_a == ST_M && st_b == ST_M));
endmodule

module async_mem_bus_ctrl (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         req,
    input  wire         req_wr,
    input  wire [4:0]   req_cs,
    input  wire [63:0]  req_addr,
    input  wire [63:0]  req_wdata,
    input  wire [63:0]  i_rdata,
    input  wire         cfg_we,
    input  wire [4:0]   cfg_cs,
    input  wire [63:0]  cfg_setup,
    input  wire [63:0]  cfg_access,
    input  wire [63:0]  cfg_hold,
    output wire [31:0]  cs_n,
    output wire         oe_n,
    output wire         we_n,
    output wire [63:0]  addr,
    output wire [63:0]  wdata,
    output wire [63:0]  rdata,
    output wire         busy
);
    localparam [1:0] P_IDLE = 2'd0, P_SETUP = 2'd1, P_ACCESS = 2'd2, P_HOLD = 2'd3;

    reg [1:0]    phase     = P_IDLE;
    reg [63:0]   cnt       = 64'd0;
    reg          wr_lat    = 1'b0;
    reg [4:0]    cs_lat    = 5'd0;
    reg [63:0]   addr_lat  = 64'd0;
    reg [63:0]   wdata_lat = 64'd0;
    reg [63:0]   rdata_lat = 64'd0;
    reg          oe        = 1'b0;
    reg          we        = 1'b0;
    reg          armed     = 1'b0;

    // per-chip-select timing registers: 32 entries x 64 bits each
    reg [2047:0] tsetup_flat  = {32{64'd1}};
    reg [2047:0] taccess_flat = {32{64'd2}};
    reg [2047:0] thold_flat   = {32{64'd1}};

    wire [63:0] t_setup  = tsetup_flat[cs_lat*64 +: 64];
    wire [63:0] t_access = taccess_flat[cs_lat*64 +: 64];
    wire [63:0] t_hold   = thold_flat[cs_lat*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            phase  <= P_IDLE;
            cnt    <= 64'd0;
            wr_lat <= 1'b0;
            oe     <= 1'b0;
            we     <= 1'b0;
        end else if (i_ce) begin
            if (cfg_we) begin
                tsetup_flat[cfg_cs*64 +: 64]  <= cfg_setup;
                taccess_flat[cfg_cs*64 +: 64] <= cfg_access;
                thold_flat[cfg_cs*64 +: 64]   <= cfg_hold;
            end
            case (phase)
                P_IDLE: begin
                    if (req) begin
                        phase     <= P_SETUP;
                        cnt       <= 64'd0;
                        wr_lat    <= req_wr;
                        cs_lat    <= req_cs;
                        addr_lat  <= req_addr;
                        wdata_lat <= req_wdata;
                        armed     <= 1'b1;
                    end
                end
                P_SETUP: begin
                    if (cnt >= t_setup) begin
                        phase <= P_ACCESS;
                        cnt   <= 64'd0;
                        if (wr_lat) we <= 1'b1;
                        else        oe <= 1'b1;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_ACCESS: begin
                    if (cnt >= t_access) begin
                        phase <= P_HOLD;
                        cnt   <= 64'd0;
                        if (!wr_lat) rdata_lat <= i_rdata;
                        oe    <= 1'b0;
                        we    <= 1'b0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_HOLD: begin
                    if (cnt >= t_hold) begin
                        phase <= P_IDLE;
                        cnt   <= 64'd0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
            endcase
        end
    end

    assign cs_n  = (phase == P_IDLE) ? 32'hFFFFFFFF : ~(32'd1 << cs_lat);
    assign oe_n  = ~oe;
    assign we_n  = ~we;
    assign addr  = addr_lat;
    assign wdata = wdata_lat;
    assign rdata = rdata_lat;
    assign busy  = (phase != P_IDLE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Absence after first accepted transaction: OE and WE strobes never both active
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(oe) && $past(we)));
endmodule

module wwdg_window (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       stop,
    input  wire       kick,
    input  wire [7:0] cfg_reload,
    input  wire [7:0] cfg_win,
    output wire [1:0] o_fault,
    output wire       o_armed,
    output wire [7:0] o_cnt
);
    reg       pv       = 1'b0;
    reg       armed    = 1'b0;
    reg [7:0] cnt      = 8'd64;
    reg [7:0] reload   = 8'd64;
    reg [7:0] win_thr  = 8'd0;
    reg [1:0] fault    = 2'b00;
    reg       win_open = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (start) begin
            armed    <= 1'b1;
            reload   <= cfg_reload | 8'h40;
            win_thr  <= cfg_win & 8'h3F;
            cnt      <= cfg_reload | 8'h40;
            fault    <= 2'b00;
            win_open <= 1'b0;
        end else if (stop) begin
            armed <= 1'b0;
        end else if (armed && ce && fault == 2'b00) begin
            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
endmodule

module nfc_rst_escalator (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire rx_fault,
    output wire sub_rst,
    output wire chip_rst
);
    localparam [63:0] T1 = 64'd4;
    localparam [63:0] T2 = 64'd8;
    localparam [63:0] DECAY = 64'd1000;
    localparam [63:0] CNT_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] fault_cnt = 64'd0;
    reg [63:0] decay_tmr = 64'd0;
    reg sub_rst_q = 1'b0;
    reg chip_rst_q = 1'b0;
    reg armed = 1'b0;

    wire [63:0] inc = fault_cnt + 64'd1;
    wire [63:0] dec = fault_cnt - 64'd1;

    always @(posedge clk) begin
        if (!rst_n) begin
            fault_cnt <= 64'd0;
            decay_tmr <= 64'd0;
            sub_rst_q <= 1'b0;
            chip_rst_q <= 1'b0;
            armed <= 1'b0;
        end else if (en) begin
            armed <= armed | sub_rst_q;
            if (rx_fault) begin
                if (fault_cnt != CNT_MAX) begin
                    fault_cnt <= inc;
                    if (inc == T1)
                        sub_rst_q <= 1'b1;
                    if (inc == T2) begin
                        chip_rst_q <= 1'b1;
                        sub_rst_q <= 1'b0;
                    end
                end
            end else begin
                if (decay_tmr == DECAY) begin
                    decay_tmr <= 64'd0;
                    if (fault_cnt != 64'd0) begin
                        fault_cnt <= dec;
                        if (dec == T2 - 64'd1) begin
                            chip_rst_q <= 1'b0;
                            sub_rst_q <= 1'b1;
                        end
                        if (dec == T1 - 64'd1)
                            sub_rst_q <= 1'b0;
                    end
                end else begin
                    decay_tmr <= decay_tmr + 64'd1;
                end
            end
        end
    end

    assign sub_rst = sub_rst_q;
    assign chip_rst = chip_rst_q;

    always @(*)
        if (armed)
            assert (!(sub_rst_q && chip_rst_q));
endmodule

module mcast_demux (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire [7:0] i_mask,
    input  wire [7:0] i_data,
    input  wire [7:0] i_ready,
    output wire [7:0] o_valid,
    output wire [7:0] o_data,
    output wire       o_done,
    output wire       o_busy
);
    localparam IDLE  = 2'd0;
    localparam ARMED = 2'd1;
    localparam SEND  = 2'd2;
    localparam FIN   = 2'd3;

    reg [1:0] phase;
    reg [7:0] mask;
    reg [7:0] delivered;
    reg [7:0] data;
    initial phase = IDLE;
    initial mask = 8'd0;
    initial delivered = 8'd0;
    initial data = 8'd0;

    assign o_valid = (phase == SEND) ? (mask & ~delivered) : 8'd0;
    assign o_data  = data;
    assign o_done  = (phase == FIN);
    assign o_busy  = (phase != IDLE);

    wire [7:0] accepted = o_valid & i_ready;
    wire [7:0] next_del = delivered | accepted;

    always @(posedge clk) begin
        if (i_reset) begin
            phase     <= IDLE;
            mask      <= 8'd0;
            delivered <= 8'd0;
            data      <= 8'd0;
        end else if (i_ce) begin
            case (phase)
                IDLE: begin
                    if (i_arm && (i_mask != 8'd0)) begin
                        mask      <= i_mask;
                        data      <= i_data;
                        delivered <= 8'd0;
                        phase     <= ARMED;
                    end
                end
                ARMED: begin
                    phase <= SEND;
                end
                SEND: begin
                    delivered <= next_del;
                    if (next_del == mask)
                        phase <= FIN;
                end
                FIN: begin
                    phase     <= IDLE;
                    mask      <= 8'd0;
                    delivered <= 8'd0;
                end
            endcase
        end
    end

    // finish implies a copy was started (at least one delivery)
    always @(*)
        if (phase == FIN) assert (delivered != 8'd0);

    // finish implies an arm with a non-empty destination mask happened
    always @(*)
        if (phase == FIN) assert (mask != 8'd0);
endmodule

module remap_unit (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_seq_go,
    input  wire        i_unlock,
    input  wire        i_cfg_we,
    input  wire        i_cfg_sel,
    input  wire        i_cfg_en,
    input  wire [63:0] i_cfg_src,
    input  wire [63:0] i_cfg_size,
    input  wire [63:0] i_cfg_tgt,
    input  wire [63:0] i_addr,
    output wire [63:0] o_addr,
    output wire        o_hit
);
    localparam [63:0] ROM_BASE  = 64'h0000_0000_2000_0000;
    localparam [63:0] ROM_SIZE  = 64'h0000_0000_0001_0000;
    localparam [63:0] DRAM_BASE = 64'h0000_0000_8000_0000;
    localparam [63:0] DRAM_SIZE = 64'h0000_0000_4000_0000;

    // scope register: high until software unlocks the remap table
    reg        boot_phase = 1'b1;
    // boot handoff sequencer: 0 alias, 1 copy, 2 drain, 3 ram at zero
    reg [63:0] seq        = 64'd0;
    // window 0: boot ROM aliased to address zero
    reg        alias_en   = 1'b1;
    reg [63:0] src0       = 64'd0;
    reg [63:0] size0      = ROM_SIZE;
    reg [63:0] tgt0       = ROM_BASE;
    // window 1: DRAM mapped at address zero
    reg        ram_en     = 1'b0;
    reg [63:0] src1       = 64'd0;
    reg [63:0] size1      = DRAM_SIZE;
    reg [63:0] tgt1       = DRAM_BASE;

    always @(posedge clk) begin
        if (i_reset) begin
            boot_phase <= 1'b1;
            seq        <= 64'd0;
            alias_en   <= 1'b1;
            src0       <= 64'd0;
            size0      <= ROM_SIZE;
            tgt0       <= ROM_BASE;
            ram_en     <= 1'b0;
            src1       <= 64'd0;
            size1      <= DRAM_SIZE;
            tgt1       <= DRAM_BASE;
        end else if (i_ce) begin
            if (i_unlock)
                boot_phase <= 1'b0;
            if (i_seq_go && (seq != 64'd3))
                seq <= seq + 64'd1;
            if (i_seq_go && (seq == 64'd1))
                alias_en <= 1'b0;
            if (i_seq_go && (seq == 64'd2))
                ram_en <= 1'b1;
            if (i_cfg_we && !boot_phase) begin
                if (i_cfg_sel) begin
                    src1   <= i_cfg_src;
                    size1  <= i_cfg_size;
                    tgt1   <= i_cfg_tgt;
                    ram_en <= i_cfg_en;
                end else begin
                    src0     <= i_cfg_src;
                    size0    <= i_cfg_size;
                    tgt0     <= i_cfg_tgt;
                    alias_en <= i_cfg_en;
                end
            end
        end
    end

    wire [63:0] off0 = i_addr - src0;
    wire [63:0] off1 = i_addr - src1;
    wire hit0 = alias_en && (i_addr >= src0) && (off0 < size0);
    wire hit1 = ram_en   && (i_addr >= src1) && (off1 < size1);

    assign o_hit  = hit0 || hit1;
    assign o_addr = hit0 ? (tgt0 + off0) : (hit1 ? (tgt1 + off1) : i_addr);

    // Absence, before unlock: address zero never has two owners
    always @(posedge clk)
        if (boot_phase)
            assert (!(alias_en && ram_en));
endmodule

module spi_snoop_filter (
    input wire clk,
    input wire en,
    input wire sclk_rise,
    input wire mosi,
    output wire [4:0] o_occ
);
    reg [15:0] sr;
    reg [3:0]  bitcnt;
    reg [15:0] pvec [0:15];
    reg [4:0]  occ_cnt;
    reg        armed;

    integer k;
    initial begin
        sr = 16'd0;
        bitcnt = 4'd0;
        occ_cnt = 5'd0;
        armed = 1'b0;
        for (k = 0; k < 16; k = k + 1)
            pvec[k] = 16'd0;
    end

    wire [15:0] w   = {sr[14:0], mosi};
    wire [1:0]  op  = w[15:14];
    wire [3:0]  idx = w[13:10];
    wire [3:0]  cid = w[9:6];
    wire [15:0] cur = pvec[idx];
    wire [15:0] cmask = 16'd1 << cid;
    wire [15:0] set_v = cur | cmask;
    wire [15:0] clr_v = cur & ~cmask;

    always @(posedge clk) begin
        if (en && sclk_rise) begin
            sr <= w;
            bitcnt <= bitcnt + 4'd1;
            if (bitcnt == 4'd15) begin
                case (op)
                    2'b01: begin
                        pvec[idx] <= set_v;
                        if (cur == 16'd0)
                            occ_cnt <= occ_cnt + 5'd1;
                    end
                    2'b10: begin
                        pvec[idx] <= clr_v;
                        if (cur != 16'd0 && clr_v == 16'd0)
                            occ_cnt <= occ_cnt - 5'd1;
                    end
                    2'b11: begin
                        pvec[idx] <= 16'd0;
                        if (cur != 16'd0) begin
                            occ_cnt <= occ_cnt - 5'd1;
                            armed <= 1'b1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_occ = occ_cnt;

    always @(posedge clk)
        if (armed)
            assert (occ_cnt <= 5'd16);
endmodule

// Host-side scheduler for the flow classifier. The flow table only takes a
// lookup or a rule write while it is not scanning, so both are queued here
// and handed over while no lookup is outstanding; every accepted lookup is
// given a sequence tag that comes back with its completion.
module lookup_scheduler #(
   parameter RQ_AW = 2,
   parameter WQ_AW = 2,
   parameter TAG_W = 4
) (
   input  wire             clk,
   input  wire             rst,
   input  wire             i_ce,
   input  wire             in_req,
   input  wire [63:0]      in_key,
   input  wire [15:0]      in_len,
   output wire             in_ready,
   output wire [TAG_W-1:0] in_tag,
   input  wire             in_wr,
   input  wire [6:0]       in_wr_idx,
   input  wire [63:0]      in_wr_key,
   input  wire [31:0]      in_wr_action,
   output wire             wr_ready,
   input  wire             tb_rsp_valid,
   input  wire             tb_rsp_hit,
   output wire             tb_req,
   output wire [63:0]      tb_key,
   output wire [15:0]      tb_len,
   output wire             tb_wr,
   output wire [6:0]       tb_wr_idx,
   output wire [63:0]      tb_wr_key,
   output wire [31:0]      tb_wr_action,
   output wire             done_valid,
   output wire             done_hit,
   output wire [TAG_W-1:0] done_tag,
   output wire             pend_o,
   output wire [RQ_AW:0]   rq_cnt_o,
   output wire [WQ_AW:0]   wq_cnt_o,
   output wire [RQ_AW:0]   rq_hwm_o,
   output wire [15:0]      miss_cnt_o
);
   localparam RQ_DEPTH = 1 << RQ_AW;
   localparam WQ_DEPTH = 1 << WQ_AW;
   reg [63:0]      rq_key [0:RQ_DEPTH-1];
   reg [15:0]      rq_len [0:RQ_DEPTH-1];
   reg [TAG_W-1:0] rq_tag [0:RQ_DEPTH-1];
   reg [RQ_AW-1:0] rq_wp;
   reg [RQ_AW-1:0] rq_rp;
   reg [RQ_AW:0]   rq_cnt;
   reg [RQ_AW:0]   rq_hwm;
   reg [TAG_W-1:0] tag_ctr;
   reg [6:0]       wq_idx [0:WQ_DEPTH-1];
   reg [63:0]      wq_key [0:WQ_DEPTH-1];
   reg [31:0]      wq_act [0:WQ_DEPTH-1];
   reg [WQ_AW-1:0] wq_wp;
   reg [WQ_AW-1:0] wq_rp;
   reg [WQ_AW:0]   wq_cnt;
   reg             pend;
   reg [TAG_W-1:0] cur_tag;
   reg [15:0]      miss_cnt;
   integer k;
   initial begin
       for (k = 0; k < RQ_DEPTH; k = k + 1) begin
           rq_key[k] = 64'd0;
           rq_len[k] = 16'd0;
           rq_tag[k] = {TAG_W{1'b0}};
       end
       for (k = 0; k < WQ_DEPTH; k = k + 1) begin
           wq_idx[k] = 7'd0;
           wq_key[k] = 64'd0;
           wq_act[k] = 32'd0;
       end
       rq_wp    = {RQ_AW{1'b0}};
       rq_rp    = {RQ_AW{1'b0}};
       rq_cnt   = {(RQ_AW+1){1'b0}};
       rq_hwm   = {(RQ_AW+1){1'b0}};
       tag_ctr  = {TAG_W{1'b0}};
       wq_wp    = {WQ_AW{1'b0}};
       wq_rp    = {WQ_AW{1'b0}};
       wq_cnt   = {(WQ_AW+1){1'b0}};
       pend     = 1'b0;
       cur_tag  = {TAG_W{1'b0}};
       miss_cnt = 16'd0;
   end
   wire rq_full  = (rq_cnt == RQ_DEPTH);
   wire rq_empty = (rq_cnt == 0);
   wire wq_full  = (wq_cnt == WQ_DEPTH);
   wire wq_empty = (wq_cnt == 0);
   // the table is handed work only while none of ours is outstanding
   assign tb_req = !pend && !rq_empty;
   assign tb_wr  = !pend && !wq_empty;
   wire rq_pop  = i_ce && tb_req;
   wire wq_pop  = i_ce && tb_wr;
   wire rq_push = i_ce && in_req && !rq_full;
   // a rule write to the same index as the newest queued write replaces it
   // in place, unless that entry is the one leaving for the table this cycle
   wire [WQ_AW-1:0] wq_tail = wq_wp - 1'b1;
   wire wq_tail_leaving = tb_wr && (wq_cnt == 1);
   wire wr_merge = !wq_empty && !wq_tail_leaving && (wq_idx[wq_tail] == in_wr_idx);
   wire wr_take  = i_ce && in_wr && (!wq_full || wr_merge);
   wire wr_push  = wr_take && !wr_merge;
   assign in_ready = !rq_full;
   assign in_tag   = tag_ctr;
   assign wr_ready = !wq_full || wr_merge;
   assign tb_key       = rq_key[rq_rp];
   assign tb_len       = rq_len[rq_rp];
   assign tb_wr_idx    = wq_idx[wq_rp];
   assign tb_wr_key    = wq_key[wq_rp];
   assign tb_wr_action = wq_act[wq_rp];
   wire done = tb_rsp_valid && pend;
   always @(posedge clk) begin
       if (rst) begin
           rq_wp   <= {RQ_AW{1'b0}};
           rq_rp   <= {RQ_AW{1'b0}};
           rq_cnt  <= {(RQ_AW+1){1'b0}};
           rq_hwm  <= {(RQ_AW+1){1'b0}};
           tag_ctr <= {TAG_W{1'b0}};
       end else if (i_ce) begin
           if (rq_push) begin
               rq_key[rq_wp] <= in_key;
               rq_len[rq_wp] <= in_len;
               rq_tag[rq_wp] <= tag_ctr;
               rq_wp         <= rq_wp + 1'b1;
               tag_ctr       <= tag_ctr + 1'b1;
           end
           if (rq_pop)
               rq_rp <= rq_rp + 1'b1;
           if (rq_push && !rq_pop)
               rq_cnt <= rq_cnt + 1'b1;
           else if (rq_pop && !rq_push)
               rq_cnt <= rq_cnt - 1'b1;
           if (rq_cnt > rq_hwm)
               rq_hwm <= rq_cnt;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           wq_wp  <= {WQ_AW{1'b0}};
           wq_rp  <= {WQ_AW{1'b0}};
           wq_cnt <= {(WQ_AW+1){1'b0}};
       end else if (i_ce) begin
           if (wr_take && wr_merge) begin
               wq_key[wq_tail] <= in_wr_key;
               wq_act[wq_tail] <= in_wr_action;
           end else if (wr_push) begin
               wq_idx[wq_wp] <= in_wr_idx;
               wq_key[wq_wp] <= in_wr_key;
               wq_act[wq_wp] <= in_wr_action;
               wq_wp         <= wq_wp + 1'b1;
           end
           if (wq_pop)
               wq_rp <= wq_rp + 1'b1;
           if (wr_push && !wq_pop)
               wq_cnt <= wq_cnt + 1'b1;
           else if (wq_pop && !wr_push)
               wq_cnt <= wq_cnt - 1'b1;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           pend     <= 1'b0;
           cur_tag  <= {TAG_W{1'b0}};
           miss_cnt <= 16'd0;
       end else if (i_ce) begin
           if (rq_pop) begin
               pend    <= 1'b1;
               cur_tag <= rq_tag[rq_rp];
           end else if (tb_rsp_valid) begin
               pend <= 1'b0;
           end
           if (done && !tb_rsp_hit && (miss_cnt != 16'hFFFF))
               miss_cnt <= miss_cnt + 16'd1;
       end
   end
   assign done_valid = done;
   assign done_hit   = tb_rsp_hit;
   assign done_tag   = cur_tag;
   assign pend_o     = pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   assign miss_cnt_o = miss_cnt;
endmodule
module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
   output wire        g_write_o,
   output wire        req_ready,
   output wire [3:0]  req_tag,
   output wire        wr_ready,
   output wire        lk_done,
   output wire        lk_hit,
   output wire [3:0]  lk_tag,
   output wire        sch_pend_o,
   output wire [2:0]  rq_cnt_o,
   output wire [2:0]  wq_cnt_o,
   output wire [2:0]  rq_hwm_o,
   output wire [15:0] miss_cnt_o
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
   wire        s_req;
   wire [63:0] s_key;
   wire [15:0] s_len;
   wire        s_wr;
   wire [6:0]  s_wr_idx;
   wire [63:0] s_wr_key;
   wire [31:0] s_wr_action;
   wire        sch_pend;
   wire [2:0]  rq_cnt;
   wire [2:0]  wq_cnt;
   wire [2:0]  rq_hwm;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
       .req(s_req),
       .req_key(s_key),
       .req_len(s_len),
       .wr_en(s_wr),
       .wr_idx(s_wr_idx),
       .wr_key(s_wr_key),
       .wr_action(s_wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;
   lookup_scheduler #(
       .RQ_AW(2),
       .WQ_AW(2),
       .TAG_W(4)
   ) u_sched (
       .clk(clk),
       .rst(rst),
       .i_ce(i_ce),
       .in_req(req),
       .in_key(req_key),
       .in_len(req_len),
       .in_ready(req_ready),
       .in_tag(req_tag),
       .in_wr(wr_en),
       .in_wr_idx(wr_idx),
       .in_wr_key(wr_key),
       .in_wr_action(wr_action),
       .wr_ready(wr_ready),
       .tb_rsp_valid(rsp_valid),
       .tb_rsp_hit(rsp_hit),
       .tb_req(s_req),
       .tb_key(s_key),
       .tb_len(s_len),
       .tb_wr(s_wr),
       .tb_wr_idx(s_wr_idx),
       .tb_wr_key(s_wr_key),
       .tb_wr_action(s_wr_action),
       .done_valid(lk_done),
       .done_hit(lk_hit),
       .done_tag(lk_tag),
       .pend_o(sch_pend),
       .rq_cnt_o(rq_cnt),
       .wq_cnt_o(wq_cnt),
       .rq_hwm_o(rq_hwm),
       .miss_cnt_o(miss_cnt_o)
   );
   assign sch_pend_o = sch_pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   // every response the flow table produces belongs to a lookup the scheduler handed it
   always @(posedge clk)
       if (rsp_valid)
           assert (sch_pend);

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [63:0] o_hist_stamp,
   output wire [15:0] o_hist_sig,
   output wire [1:0] o_hist_state,
   output wire [2:0] o_hist_level,
   output wire o_hist_open,
   output wire [15:0] o_last_sig,
   output wire [7:0] o_hist_drops,
   output wire [7:0] o_abort_cnt,
   output wire [63:0] o_ret_stamp,
   output wire [15:0] o_ret_sig,
   output wire [1:0] o_ret_state,
   output wire o_ret_valid
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;
   localparam [1:0] ST_FREE = 2'd0, ST_OPEN = 2'd1, ST_DONE = 2'd2, ST_ABRT = 2'd3;
   localparam [4:0] HIST_CLR = 5'd30, HIST_ACK = 5'd31;
   localparam [2:0] HIST_DEPTH = 3'd4;
   // frame history: one record per launched frame, oldest at hist_rd_ptr
   reg [63:0] hist_mem [0:3];
   reg [15:0] hist_sum [0:3];
   reg [1:0]  hist_st  [0:3];
   reg [1:0]  hist_wr_ptr;
   reg [1:0]  hist_rd_ptr;
   reg [2:0]  hist_cnt;
   reg [7:0]  hist_drop;
   reg [7:0]  abort_cnt;
   reg [15:0] frame_sig;
   // last record retired through HIST_ACK
   reg [63:0] ret_stamp;
   reg [15:0] ret_sum;
   reg [1:0]  ret_st;
   reg        ret_vld;
   integer j;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           hist_mem[j] = 64'd0;
           hist_sum[j] = 16'd0;
           hist_st[j] = ST_FREE;
       end
   end
   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire [1:0]  hist_last  = hist_wr_ptr - 2'd1;
   wire        hist_empty = (hist_cnt == 3'd0);
   wire        hist_full  = (hist_cnt == HIST_DEPTH);
   // a new record is opened whenever a frame is launched
   wire        hist_push  = !abort_req && (phase == ARMED) && start_req;
   // the record of the frame on screen (running or just finished) may not be acked away
   wire        hist_pin   = (hist_cnt == 3'd1) && ((phase == RUN) || done);
   wire        hist_ack   = wr_en && (wr_addr == HIST_ACK) && !hist_empty && !hist_push && !hist_pin;
   wire        hist_clr   = wr_en && (wr_addr == HIST_CLR) && (phase != RUN) && !done && !hist_push;
   wire        frame_end  = !abort_req && (phase == RUN) && last_col && last_row;
   wire        frame_kill = abort_req && (phase == RUN);
   wire [7:0]  next_pix   = font_row(cur_char, row_cnt[2:0]);
   wire [15:0] next_sig   = {frame_sig[14:0], frame_sig[15] ^ frame_sig[12]} ^ {frame_sig[3:0], 4'h0, next_pix};

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (j = 0; j < 4; j = j + 1) begin
               hist_mem[j] <= 64'd0;
               hist_sum[j] <= 16'd0;
               hist_st[j] <= ST_FREE;
           end
           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
           // ---- frame history ----
           if (hist_push)
               frame_sig <= 16'd0;
           else if (!abort_req && (phase == RUN))
               frame_sig <= next_sig;
           if (hist_push) begin
               hist_mem[hist_wr_ptr] <= frame_cnt + 64'd1;
               hist_sum[hist_wr_ptr] <= 16'd0;
               hist_st[hist_wr_ptr] <= ST_OPEN;
               hist_wr_ptr <= hist_wr_ptr + 2'd1;
               if (hist_full) begin
                   // overwrite the oldest record and account for the loss
                   hist_rd_ptr <= hist_rd_ptr + 2'd1;
                   if (hist_drop != 8'hFF)
                       hist_drop <= hist_drop + 8'd1;
               end else begin
                   hist_cnt <= hist_cnt + 3'd1;
               end
           end else if (hist_ack) begin
               ret_stamp <= hist_mem[hist_rd_ptr];
               ret_sum <= hist_sum[hist_rd_ptr];
               ret_st <= hist_st[hist_rd_ptr];
               ret_vld <= 1'b1;
               hist_st[hist_rd_ptr] <= ST_FREE;
               hist_rd_ptr <= hist_rd_ptr + 2'd1;
               hist_cnt <= hist_cnt - 3'd1;
           end else if (hist_clr) begin
               for (j = 0; j < 4; j = j + 1)
                   hist_st[j] <= ST_FREE;
               hist_rd_ptr <= hist_wr_ptr;
               hist_cnt <= 3'd0;
               ret_vld <= 1'b0;
           end
           if (frame_kill) begin
               hist_st[hist_last] <= ST_ABRT;
               hist_sum[hist_last] <= frame_sig;
               if (abort_cnt != 8'hFF)
                   abort_cnt <= abort_cnt + 8'd1;
           end
           if (frame_end) begin
               hist_st[hist_last] <= ST_DONE;
               hist_sum[hist_last] <= next_sig;
           end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_hist_stamp = hist_empty ? 64'd0 : hist_mem[hist_rd_ptr];
   assign o_hist_sig = hist_empty ? 16'd0 : hist_sum[hist_rd_ptr];
   assign o_hist_state = hist_empty ? ST_FREE : hist_st[hist_rd_ptr];
   assign o_hist_level = hist_cnt;
   assign o_hist_open = !hist_empty && (hist_st[hist_last] == ST_OPEN);
   assign o_last_sig = hist_empty ? 16'd0 : hist_sum[hist_last];
   assign o_hist_drops = hist_drop;
   assign o_abort_cnt = abort_cnt;
   assign o_ret_stamp = ret_stamp;
   assign o_ret_sig = ret_sum;
   assign o_ret_state = ret_st;
   assign o_ret_valid = ret_vld;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);

   always @(posedge clk)
       if (done)
           assert (hist_cnt != 3'd0 && hist_st[hist_last] == ST_DONE && hist_mem[hist_last] == frame_cnt);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
    output wire uart_online_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
    assign a_aw_ready = uart_online && !address_pending;
    assign a_w_ready = uart_online && address_pending && !tx_wait &&
                       !response_pending && (!address_is_tx || uart_ready);
    assign uart_valid = m_ce && uart_online && address_pending &&
                        !tx_wait && !response_pending && address_is_tx && a_w_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
    wire uart_take = uart_valid && uart_ready;
    wire write_reject = write_take && !address_is_tx;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
        .s_data(a_w_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
            if (uart_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
            if (tx_wait && !uart_busy) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module uart_word_formatter #(
   parameter WORD_W = 16,
   parameter WORDS = (WORD_W / 4) + 4,
   parameter IW = $clog2(WORDS),
   parameter CW = $clog2(WORDS + 1)
) (
   input  wire                    clk,
   input  wire                    rst_n,
   input  wire                    ce,
   input  wire                    in_valid,
   output wire                    in_ready,
   input  wire [WORD_W-1:0]       in_word,
   input  wire                    in_packet,
   output wire                    byte_valid,
   input  wire                    byte_ready,
   output wire [WORD_W-1:0]       byte_data,
   input  wire                    tx_busy,
   output wire                    done,
   input  wire                    done_ready,
   output wire [1:0]              state_o,
   output wire [IW-1:0]           pos_o,
   output wire [CW-1:0]           span_o,
   output reg  [WORD_W*WORDS-1:0] words_o
);
   localparam DIGITS = WORD_W / 4;
   localparam [1:0] IDLE = 2'd0;
   localparam [1:0] SEND = 2'd1;
   localparam [1:0] WAIT_BYTE = 2'd2;
   localparam [1:0] DONE = 2'd3;
   localparam [CW-1:0] FULL_SPAN = WORDS;

   reg [1:0] state = IDLE;
   reg [IW-1:0] pos = 0;
   reg [CW-1:0] span = 1;
   reg [WORD_W-1:0] frame [0:WORDS-1];
   reg [WORD_W-1:0] encoded [0:WORDS-1];
   integer init_idx;
   integer build_idx;
   integer seq_idx;

   initial begin
       for (init_idx = 0; init_idx < WORDS; init_idx = init_idx + 1)
           frame[init_idx] = 0;
   end

   function [WORD_W-1:0] hex_symbol;
       input [3:0] nibble;
       begin
           if (nibble < 4'd10)
               hex_symbol = 16'h0030 + nibble;
           else
               hex_symbol = 16'h0041 + nibble - 16'd10;
       end
   endfunction

   // CRC-8/ATM, most significant payload bit first.
   function [7:0] crc_word;
       input [WORD_W-1:0] word;
       reg [7:0] residue;
       reg feedback;
       integer bit_idx;
       begin
           residue = 8'd0;
           feedback = 1'b0;
           for (bit_idx = WORD_W - 1; bit_idx >= 0; bit_idx = bit_idx - 1) begin
               feedback = residue[7] ^ word[bit_idx];
               residue = {residue[6:0], 1'b0};
               if (feedback)
                   residue = residue ^ 8'h07;
           end
           crc_word = residue;
       end
   endfunction

   wire [7:0] input_crc = crc_word(in_word);
   wire input_take = in_valid && in_ready;
   wire byte_take = byte_valid && byte_ready;

   assign in_ready = (state == IDLE);
   assign byte_valid = (state == SEND);
   assign byte_data = frame[pos];
   assign done = (state == DONE);
   assign state_o = state;
   assign pos_o = pos;
   assign span_o = span;

   // A packet carries the complete word and its checksum as printable text.
   // Raw writes use the same completion machinery, but only one symbol.
   always @(*) begin
       for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1) begin
           encoded[build_idx] = 0;
           words_o[build_idx*WORD_W +: WORD_W] = frame[build_idx];
       end
       encoded[0] = 16'h003a;
       for (build_idx = 0; build_idx < DIGITS; build_idx = build_idx + 1)
           encoded[build_idx + 1] =
               hex_symbol(in_word[(DIGITS-1-build_idx)*4 +: 4]);
       encoded[DIGITS + 1] = hex_symbol(input_crc[7:4]);
       encoded[DIGITS + 2] = hex_symbol(input_crc[3:0]);
       encoded[WORDS - 1] = 16'h000a;
       if (!in_packet) begin
           for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1)
               encoded[build_idx] = 0;
           encoded[0] = {8'd0, in_word[7:0]};
       end
   end

   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           state <= IDLE;
           pos <= 0;
           span <= 1;
           for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
               frame[seq_idx] <= 0;
       end else if (ce) begin
           case (state)
               IDLE: begin
                   if (input_take) begin
                       for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
                           frame[seq_idx] <= encoded[seq_idx];
                       pos <= 0;
                       span <= in_packet ? FULL_SPAN : 1;
                       state <= SEND;
                   end
               end
               SEND: begin
                   // Acceptance is not completion: retain the frame until
                   // the UART has shifted the accepted symbol's stop bit.
                   if (byte_take)
                       state <= WAIT_BYTE;
               end
               WAIT_BYTE: begin
                   if (!tx_busy) begin
                       if (({1'b0, pos} + 1'b1) == span) begin
                           state <= DONE;
                       end else begin
                           pos <= pos + 1'b1;
                           state <= SEND;
                       end
                   end
               end
               DONE: begin
                   // Keep completion and the encoded frame until acknowledged.
                   if (done_ready)
                       state <= IDLE;
               end
           endcase
       end
   end
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
   output wire uart_online_o,
   output wire [1:0] format_state_o,
   output wire [FORMAT_PW-1:0] format_pos_o,
   output wire [FORMAT_CW-1:0] format_span_o,
   output wire [16*FORMAT_WORDS-1:0] format_words_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;
   localparam [15:0] PACKET_ADDR = 16'h0008;
   localparam FORMAT_WORDS = 8;
   localparam FORMAT_PW = $clog2(FORMAT_WORDS);
   localparam FORMAT_CW = $clog2(FORMAT_WORDS + 1);

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;
   wire format_input_valid, format_input_ready;
   wire format_output_valid, format_done;
   wire [15:0] format_output_data;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
   wire address_is_packet = (address_hold == PACKET_ADDR);
   wire address_is_serial = address_is_tx || address_is_packet;
   assign format_input_valid = uart_online && address_pending &&
                               !tx_wait && !response_pending &&
                               address_is_serial && a_w_valid;
    assign a_aw_ready = uart_online && !address_pending;
   assign a_w_ready = uart_online && address_pending && !tx_wait &&
                      !response_pending && (!address_is_serial || format_input_ready);
   assign uart_valid = m_ce && uart_online && format_output_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
   wire format_take = write_take && address_is_serial;
   wire write_reject = write_take && !address_is_serial;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
       .s_data(format_output_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

   uart_word_formatter #(
       .WORD_W(16), .WORDS(FORMAT_WORDS),
       .IW(FORMAT_PW), .CW(FORMAT_CW)
   ) formatter (
       .clk(clk), .rst_n(rst_n), .ce(m_ce),
       .in_valid(format_input_valid), .in_ready(format_input_ready),
       .in_word(a_w_data), .in_packet(address_is_packet),
       .byte_valid(format_output_valid),
       .byte_ready(uart_online && uart_ready),
       .byte_data(format_output_data), .tx_busy(uart_busy),
       .done(format_done), .done_ready(tx_wait),
       .state_o(format_state_o), .pos_o(format_pos_o),
       .span_o(format_span_o), .words_o(format_words_o)
   );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
           if (format_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
           if (tx_wait && format_done) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ldpc_edge_ingress #(
    parameter W = 32,
    parameter FRAME = 24,
    parameter DEPTH = 4,
    parameter IW = $clog2(FRAME),
    parameter CW = $clog2(DEPTH + 1)
) (
    input wire clk,
    input wire offer,
    output wire ready,
    input wire [W-1:0] mag_i,
    input wire sign_i,
    input wire take,
    output wire valid,
    output wire [W-1:0] mag_o,
    output wire sign_o,
    output wire [IW-1:0] index_o,
    output reg [CW-1:0] queued,
    output reg [IW-1:0] next_idx,
    output wire [DEPTH*IW-1:0] queued_idx
);
    reg [W-1:0] magnitude [0:DEPTH-1];
    reg polarity [0:DEPTH-1];
    reg [IW-1:0] edge_index [0:DEPTH-1];
    integer i, n;
    wire pop = valid && take;
    wire push = offer && ready;
    assign valid = (queued != 0);
    assign ready = (queued < DEPTH) || pop;
    assign mag_o = magnitude[0];
    assign sign_o = polarity[0];
    assign index_o = edge_index[0];
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin: export_tags
            assign queued_idx[g*IW +: IW] = edge_index[g];
        end
    endgenerate
    initial begin
        queued = 0;
        next_idx = 0;
        for (n = 0; n < DEPTH; n = n + 1) begin
            magnitude[n] = {W{1'b0}};
            polarity[n] = 1'b0;
            edge_index[n] = 0;
        end
    end
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: queued <= queued + 1'b1;
            2'b01: queued <= queued - 1'b1;
            default: queued <= queued;
        endcase
        if (pop) begin
            for (i = 0; i < DEPTH-1; i = i + 1) begin
                magnitude[i] <= magnitude[i+1];
                polarity[i] <= polarity[i+1];
                edge_index[i] <= edge_index[i+1];
            end
        end
        if (push) begin
            magnitude[queued - pop] <= mag_i;
            polarity[queued - pop] <= sign_i;
            edge_index[queued - pop] <= next_idx;
            if (next_idx == FRAME - 1)
                next_idx <= 0;
            else
                next_idx <= next_idx + 1'b1;
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] pending_edges
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    localparam IIW = $clog2(DEG);
    wire ingress_valid, ingress_sign;
    wire [W-1:0] ingress_mag;
    wire [IIW-1:0] ingress_idx, ingress_next_idx;
    wire [INGRESS_DEPTH*IIW-1:0] ingress_tags;
    wire ingress_take = (state == S_ACCUM);
    ldpc_edge_ingress #(
        .W(W), .FRAME(DEG), .DEPTH(INGRESS_DEPTH)
    ) ingress (
        .clk(clk), .offer(in_valid), .ready(in_ready),
        .mag_i(in_mag), .sign_i(in_sign), .take(ingress_take),
        .valid(ingress_valid), .mag_o(ingress_mag),
        .sign_o(ingress_sign), .index_o(ingress_idx),
        .queued(pending_edges), .next_idx(ingress_next_idx),
        .queued_idx(ingress_tags)
    );
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = ingress_valid && ingress_take;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ ingress_sign;
            if (ingress_mag < min1) begin
                min2    <= min1;
                min1    <= ingress_mag;
                min_idx <= ingress_idx;
            end else if (ingress_mag < min2) begin
                min2 <= ingress_mag;
            end
            if (ingress_idx == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
    always @(posedge clk) if (pv && rel && ingress_valid) assert (ingress_idx == 0);
endmodule

module div3_serial_checker (
    input  wire clk,
    input  wire i_ce,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_bit,
    output wire o_verdict,
    output wire o_done
);
    parameter WIDTH = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3} ctl_t;
    typedef enum logic [1:0] {R0 = 2'd0, R1 = 2'd1, R2 = 2'd2} rem_t;

    ctl_t ctl = IDLE;
    rem_t rem = R0;
    reg [WIDTH-1:0] value = {WIDTH{1'b0}};
    reg [WIDTH-1:0] nbits = {WIDTH{1'b0}};
    reg armed = 1'b0;
    reg started = 1'b0;

    rem_t rem_next;
    always @(*) begin
        case (rem)
            R0: rem_next = i_bit ? R1 : R0;
            R1: rem_next = i_bit ? R0 : R2;
            R2: rem_next = i_bit ? R2 : R1;
            default: rem_next = R0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (ctl)
                IDLE: begin
                    if (i_arm) begin
                        ctl   <= ARMED;
                        armed <= 1'b1;
                    end
                end
                ARMED: begin
                    if (i_start) begin
                        ctl     <= RUN;
                        started <= 1'b1;
                        value   <= {WIDTH{1'b0}};
                        nbits   <= {WIDTH{1'b0}};
                        rem     <= R0;
                    end
                end
                RUN: begin
                    value <= {value[WIDTH-2:0], i_bit};
                    nbits <= nbits + 1'b1;
                    rem   <= rem_next;
                    if (nbits == WIDTH-1)
                        ctl <= DONE;
                end
                DONE: begin
                    if (i_arm)
                        ctl <= ARMED;
                end
                default: ctl <= IDLE;
            endcase
        end
    end

    assign o_done    = (ctl == DONE);
    assign o_verdict = (ctl == DONE) && (rem == R0);

    always @(*)
        assert (!(armed && ctl == DONE && rem == R0) || (started && (value % 32'd3) == 32'd0));
endmodule

module preload_timer #(
    parameter W = 16
) (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire [W-1:0] o_cnt,
    output wire         o_match,
    output wire         o_wrap
);
    reg [W-1:0] cnt        = {W{1'b0}};
    reg [W-1:0] period_act = 16'd9;
    reg [W-1:0] period_sh  = 16'd9;
    reg [W-1:0] cmp_act    = 16'd4;
    reg [W-1:0] cmp_sh     = 16'd4;
    reg         pend       = 1'b0;
    reg         armed      = 1'b0;
    reg         pv         = 1'b0;

    assign in_ready = !pend;
    wire accept = in_valid && in_ready;
    wire wrap   = i_ce && (cnt >= period_act);

    assign o_cnt   = cnt;
    assign o_match = (cnt == cmp_act);
    assign o_wrap  = wrap;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cnt >= period_act) begin
                cnt        <= {W{1'b0}};
                period_act <= period_sh;
                cmp_act    <= cmp_sh;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
        if (accept) begin
            period_sh <= in_period;
            cmp_sh    <= in_cmp;
            pend      <= 1'b1;
        end else if (wrap) begin
            pend      <= 1'b0;
        end
        if (accept)
            armed <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed && $stable(pend))
            assert ($stable(period_act));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module eye_scan_mon #(
    parameter W  = 128,
    parameter NS = 8,
    parameter NH = 8,
    parameter NV = 4,
    parameter CW = $clog2(NS),
    parameter HW = $clog2(NH),
    parameter VW = $clog2(NV),
    parameter EW = $clog2(NS) + 1
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [W-1:0]  s_data,
    input  wire [W-1:0]  s_off,
    output reg           m_valid,
    input  wire          m_ready,
    output reg  [HW-1:0] m_hoff,
    output reg  [VW-1:0] m_voff,
    output reg  [EW-1:0] m_errs
);
    reg [HW-1:0]    hoff       = {HW{1'b0}};
    reg [VW-1:0]    voff       = {VW{1'b0}};
    reg [CW-1:0]    sample_cnt = {CW{1'b0}};
    reg [EW-1:0]    err_cnt    = {EW{1'b0}};
    reg [NH*EW-1:0] emap       = {(NH*EW){1'b0}};
    reg             armed      = 1'b1;

    initial m_valid = 1'b0;
    initial m_hoff  = {HW{1'b0}};
    initial m_voff  = {VW{1'b0}};
    initial m_errs  = {EW{1'b0}};

    assign s_ready = !m_valid;

    wire          s_fire    = s_valid && s_ready;
    wire          mis       = |(s_data ^ s_off);
    wire [EW-1:0] err_next  = err_cnt + {{(EW-1){1'b0}}, mis};
    wire          last      = (sample_cnt == NS-1);
    wire          scan_done = s_fire && last && (hoff == NH-1) && (voff == NV-1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hoff       <= {HW{1'b0}};
            voff       <= {VW{1'b0}};
            sample_cnt <= {CW{1'b0}};
            err_cnt    <= {EW{1'b0}};
            emap       <= {(NH*EW){1'b0}};
            armed      <= 1'b1;
            m_valid    <= 1'b0;
            m_hoff     <= {HW{1'b0}};
            m_voff     <= {VW{1'b0}};
            m_errs     <= {EW{1'b0}};
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (s_fire) begin
                if (last) begin
                    sample_cnt <= {CW{1'b0}};
                    err_cnt    <= {EW{1'b0}};
                    m_valid    <= 1'b1;
                    m_errs     <= err_next;
                    m_hoff     <= hoff;
                    m_voff     <= voff;
                    emap[hoff*EW +: EW] <= err_next;
                    if (hoff == NH-1) begin
                        hoff <= {HW{1'b0}};
                        voff <= voff + 1'b1;
                    end else begin
                        hoff <= hoff + 1'b1;
                    end
                end else begin
                    sample_cnt <= sample_cnt + 1'b1;
                    err_cnt    <= err_next;
                end
            end
            if (scan_done)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (err_cnt < NS);
endmodule

module an_arbiter #(
    parameter W = 64,
    parameter NPAGES = 2,
    parameter [63:0] LINK_TIME = 64'd6,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          page_valid,
    input  wire [W-1:0]  page_data,
    output wire          page_ready,
    input  wire          tick,
    input  wire          restart,
    output wire          link_up,
    output reg  [W-1:0]  resolved_mode
);
    localparam [1:0] ST_BASE = 2'd0;
    localparam [1:0] ST_NEXT = 2'd1;
    localparam [1:0] ST_WAIT = 2'd2;
    localparam [1:0] ST_DONE = 2'd3;

    reg [1:0]          neg_state  = ST_BASE;
    reg [W-1:0]        link_timer = {W{1'b0}};
    reg [NPAGES*W-1:0] rx_abil    = {(NPAGES*W){1'b0}};
    reg                win        = 1'b0;
    reg                pv         = 1'b0;
    initial resolved_mode = {W{1'b0}};

    assign page_ready = (neg_state == ST_BASE) || (neg_state == ST_NEXT);
    wire accept = page_valid && page_ready;
    assign link_up = (neg_state == ST_DONE);
    wire tmr_expired = (link_timer == {W{1'b0}});
    wire tmr_last    = (link_timer == {{(W-1){1'b0}}, 1'b1});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            neg_state     <= ST_BASE;
            link_timer    <= {W{1'b0}};
            rx_abil       <= {(NPAGES*W){1'b0}};
            win           <= 1'b0;
            resolved_mode <= {W{1'b0}};
        end else begin
            if (tick && !tmr_expired)
                link_timer <= link_timer - {{(W-1){1'b0}}, 1'b1};
            case (neg_state)
                ST_BASE: if (accept) begin
                    rx_abil[W-1:0] <= page_data;
                    neg_state      <= ST_NEXT;
                end
                ST_NEXT: if (accept) begin
                    rx_abil[2*W-1:W] <= page_data;
                    neg_state        <= ST_WAIT;
                    link_timer       <= LINK_TIME;
                    win              <= 1'b1;
                end
                ST_WAIT: if (tick && tmr_last) begin
                    neg_state     <= ST_DONE;
                    win           <= 1'b0;
                    resolved_mode <= (rx_abil[W-1:0] | rx_abil[2*W-1:W]) & LOCAL_ABIL;
                end
                ST_DONE: if (restart) begin
                    neg_state <= ST_BASE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win) assert (!$rose(tmr_expired));
endmodule

module thr_cross_det #(
    parameter W = 32,
    parameter [W-1:0] THR_INIT = 32'h8000_0000
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire [W-1:0] i_thr,
    input  wire [W-1:0] i_sample,
    output reg          o_xflag,
    output reg          o_xdir,
    output reg  [W-1:0] o_xcnt
);
    reg [W-1:0] thr;
    reg [W-1:0] prev;
    reg         have_prev;
    reg         seen_below;

    initial begin
        thr        = THR_INIT;
        prev       = {W{1'b0}};
        have_prev  = 1'b0;
        seen_below = 1'b0;
        o_xflag    = 1'b0;
        o_xdir     = 1'b0;
        o_xcnt     = {W{1'b0}};
    end

    wire s_below = (i_sample < thr);
    wire p_below = (prev < thr);
    wire cross   = have_prev && (s_below != p_below);

    always @(posedge clk) begin
        if (rst) begin
            thr        <= THR_INIT;
            prev       <= {W{1'b0}};
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
            o_xdir     <= 1'b0;
            o_xcnt     <= {W{1'b0}};
        end else if (i_load) begin
            thr        <= i_thr;
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
        end else if (i_ce) begin
            prev      <= i_sample;
            have_prev <= 1'b1;
            if (s_below)
                seen_below <= 1'b1;
            o_xflag <= cross;
            if (cross) begin
                o_xdir <= p_below;
                o_xcnt <= o_xcnt + 1'b1;
            end
        end
    end

    always @(*) assert (!(o_xflag && o_xdir) || seen_below);
endmodule

module seg_rot_shifter #(
    parameter W = 32,
    parameter SEGS = 4
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [W-1:0]      in_data,
    input  wire [31:0]       in_amt,
    input  wire              step,
    output reg               out_valid,
    input  wire              out_ready,
    output wire [SEGS*W-1:0] out_data
);
    reg [SEGS*W-1:0] segs;
    reg [SEGS-1:0]   spill;
    reg              par;
    reg              busy;
    reg [31:0]       cnt;

    initial segs = {SEGS*W{1'b0}};
    initial spill = {SEGS{1'b0}};
    initial par = 1'b0;
    initial busy = 1'b0;
    initial cnt = 32'd0;
    initial out_valid = 1'b0;

    assign in_ready = !busy && !out_valid;
    assign out_data = segs;

    reg [SEGS*W-1:0] seg_nxt;
    reg [SEGS-1:0]   sp_nxt;
    integer i;
    always @(*) begin
        for (i = 0; i < SEGS; i = i + 1) begin
            seg_nxt[i*W +: W] = {segs[i*W +: (W-1)], spill[(i+SEGS-1)%SEGS]};
            sp_nxt[i] = segs[i*W + W - 2];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            segs <= {SEGS*W{1'b0}};
            spill <= {SEGS{1'b0}};
            par <= 1'b0;
            busy <= 1'b0;
            cnt <= 32'd0;
            out_valid <= 1'b0;
        end else begin
            if (in_valid && in_ready) begin
                segs <= {{((SEGS-1)*W){1'b0}}, in_data};
                spill <= {{(SEGS-1){1'b0}}, in_data[W-1]};
                par <= ^in_data;
                cnt <= in_amt;
                busy <= 1'b1;
            end else if (busy && step) begin
                if (cnt == 32'd0) begin
                    busy <= 1'b0;
                    out_valid <= 1'b1;
                end else begin
                    segs <= seg_nxt;
                    spill <= sp_nxt;
                    cnt <= cnt - 32'd1;
                end
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    always @(posedge clk)
        if (busy) assert ((^segs) == par);
endmodule

module islip_alloc #(
    parameter N = 4
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           en,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   release_i,
    output wire [N-1:0]   o_in_busy,
    output wire [31:0]    o_active
);
    localparam PW = (N <= 2) ? 1 : $clog2(N);

    reg [N-1:0]    in_busy    = {N{1'b0}};
    reg [N-1:0]    out_busy   = {N{1'b0}};
    reg [N*PW-1:0] g_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] a_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] conn       = {(N*PW){1'b0}};
    reg [31:0]     active_cnt = 32'd0;
    reg            armed      = 1'b0;

    reg [N*N-1:0]  ereq, gnt, acc;
    reg [N-1:0]    new_in, new_out, rel_in, rel_out;
    reg [N*PW-1:0] acc_out, acc_in;
    reg [31:0]     new_cnt, rel_cnt;
    integer i, j, k, idx;
    reg found;

    always @(*) begin
        ereq = {(N*N){1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                ereq[i*N+j] = req[i*N+j] & ~in_busy[i] & ~out_busy[j];
        gnt = {(N*N){1'b0}};
        for (j = 0; j < N; j = j + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (g_ptr[j*PW +: PW] + k) % N;
                for (i = 0; i < N; i = i + 1)
                    if (!found && (i == idx) && ereq[i*N+j]) begin
                        gnt[j*N+i] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        acc = {(N*N){1'b0}};
        acc_out = {(N*PW){1'b0}};
        acc_in = {(N*PW){1'b0}};
        new_in = {N{1'b0}};
        new_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (a_ptr[i*PW +: PW] + k) % N;
                for (j = 0; j < N; j = j + 1)
                    if (!found && (j == idx) && gnt[j*N+i]) begin
                        acc[i*N+j] = 1'b1;
                        acc_out[i*PW +: PW] = j;
                        acc_in[j*PW +: PW] = i;
                        new_in[i] = 1'b1;
                        new_out[j] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        rel_in = release_i & in_busy;
        rel_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                if (rel_in[i] && (conn[i*PW +: PW] == j))
                    rel_out[j] = 1'b1;
        new_cnt = 32'd0;
        rel_cnt = 32'd0;
        for (i = 0; i < N; i = i + 1) begin
            new_cnt = new_cnt + new_in[i];
            rel_cnt = rel_cnt + rel_in[i];
        end
    end

    integer p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            in_busy    <= {N{1'b0}};
            out_busy   <= {N{1'b0}};
            g_ptr      <= {(N*PW){1'b0}};
            a_ptr      <= {(N*PW){1'b0}};
            conn       <= {(N*PW){1'b0}};
            active_cnt <= 32'd0;
            armed      <= 1'b0;
        end else if (en) begin
            in_busy  <= (in_busy & ~rel_in) | new_in;
            out_busy <= (out_busy & ~rel_out) | new_out;
            for (p = 0; p < N; p = p + 1) begin
                if (new_in[p]) begin
                    conn[p*PW +: PW]  <= acc_out[p*PW +: PW];
                    a_ptr[p*PW +: PW] <= (acc_out[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_out[p*PW +: PW] + 1'b1;
                end
                if (new_out[p])
                    g_ptr[p*PW +: PW] <= (acc_in[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_in[p*PW +: PW] + 1'b1;
            end
            active_cnt <= active_cnt + new_cnt - rel_cnt;
            if (new_cnt != 32'd0)
                armed <= 1'b1;
        end
    end

    assign o_in_busy = in_busy;
    assign o_active  = active_cnt;

    always @(posedge clk)
        if (armed)
            assert (active_cnt <= N);
endmodule

module frame_beat_ripple #(
    parameter W = 32,
    parameter MAX_BEATS = 12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    input  wire         s_last,
    output wire         s_ready,
    output wire         m_valid,
    input  wire         m_ready,
    output wire [W-1:0] m_count
);
    typedef enum logic [1:0] {IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0] LIMIT    = MAX_BEATS;
    localparam [W-1:0] LAST_IDX = MAX_BEATS - 1;

    state_t state;
    reg in_frame;
    reg [W-1:0] q;
    integer i;

    initial begin
        state    = IDLE;
        in_frame = 1'b0;
        q        = {W{1'b0}};
    end

    assign s_ready = (state != DONE);
    assign m_valid = (state == DONE);
    assign m_count = q;

    wire accept = s_valid && s_ready;
    wire drain  = m_valid && m_ready;

    // Ripple chain of toggle flip-flops: stage 0 toggles on each accepted
    // beat; stage g toggles when stage g-1 falls from 1 to 0 (its 'clock').
    wire [W-1:0] t;
    assign t[0] = accept;
    genvar g;
    generate
        for (g = 1; g < W; g = g + 1) begin : rip
            assign t[g] = t[g-1] & q[g-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            state    <= IDLE;
            in_frame <= 1'b0;
            q        <= {W{1'b0}};
        end else begin
            if (drain)
                q <= {W{1'b0}};
            else
                for (i = 0; i < W; i = i + 1)
                    if (t[i]) q[i] <= ~q[i];

            case (state)
                IDLE: begin
                    if (accept) begin
                        in_frame <= 1'b1;
                        state    <= (s_last || q == LAST_IDX) ? DONE : COUNTING;
                    end
                end
                COUNTING: begin
                    if (accept && (s_last || q == LAST_IDX))
                        state <= DONE;
                end
                DONE: begin
                    if (drain) begin
                        state    <= IDLE;
                        in_frame <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (in_frame) assert (q <= LIMIT);
endmodule

module its_xlate #(
    parameter DEV_ENTRIES = 16,
    parameter CQ_DEPTH = 16,
    parameter DW = 64,
    parameter DEVW = 4,
    parameter AW = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            cmd_valid,
    output wire            cmd_ready,
    input  wire [1:0]      cmd_op,
    input  wire [DEVW-1:0] cmd_dev,
    input  wire [DW-1:0]   cmd_base,
    input  wire [DW-1:0]   cmd_coll,
    input  wire            exec_en,
    input  wire            req_valid,
    output wire            req_ready,
    input  wire [DEVW-1:0] req_dev,
    input  wire [DW-1:0]   req_event,
    output reg             out_valid,
    input  wire            out_ready,
    output reg  [DW-1:0]   out_intid,
    output reg  [DW-1:0]   out_coll,
    output reg  [DW-1:0]   xlat_count,
    output reg  [DW-1:0]   miss_count
);
    localparam [1:0] OP_MAPD = 2'd1;
    localparam [1:0] OP_UNMAPD = 2'd2;

    reg [1:0]      cq_op   [0:CQ_DEPTH-1];
    reg [DEVW-1:0] cq_dev  [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_base [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_coll [0:CQ_DEPTH-1];
    reg [AW:0]     wptr;
    reg [AW:0]     rptr;

    reg [DEV_ENTRIES-1:0] dev_valid;
    reg [DW-1:0]   dt_base [0:DEV_ENTRIES-1];
    reg [DW-1:0]   dt_coll [0:DEV_ENTRIES-1];

    reg seen_map;

    wire [AW:0] cq_count = wptr - rptr;
    assign cmd_ready = (cq_count != CQ_DEPTH);
    assign req_ready = !out_valid || out_ready;

    wire [1:0]      ex_op   = cq_op[rptr[AW-1:0]];
    wire [DEVW-1:0] ex_dev  = cq_dev[rptr[AW-1:0]];
    wire [DW-1:0]   ex_base = cq_base[rptr[AW-1:0]];
    wire [DW-1:0]   ex_coll = cq_coll[rptr[AW-1:0]];

    integer i;
    initial begin
        wptr = 0;
        rptr = 0;
        dev_valid = 0;
        seen_map = 1'b0;
        out_valid = 1'b0;
        out_intid = 0;
        out_coll = 0;
        xlat_count = 0;
        miss_count = 0;
        for (i = 0; i < CQ_DEPTH; i = i + 1) begin
            cq_op[i] = 0;
            cq_dev[i] = 0;
            cq_base[i] = 0;
            cq_coll[i] = 0;
        end
        for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
            dt_base[i] = 0;
            dt_coll[i] = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 0;
            rptr <= 0;
            dev_valid <= 0;
            seen_map <= 1'b0;
            out_valid <= 1'b0;
            out_intid <= 0;
            out_coll <= 0;
            xlat_count <= 0;
            miss_count <= 0;
            for (i = 0; i < CQ_DEPTH; i = i + 1) begin
                cq_op[i] <= 0;
                cq_dev[i] <= 0;
                cq_base[i] <= 0;
                cq_coll[i] <= 0;
            end
            for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
                dt_base[i] <= 0;
                dt_coll[i] <= 0;
            end
        end else begin
            if (cmd_valid && cmd_ready) begin
                cq_op[wptr[AW-1:0]]   <= cmd_op;
                cq_dev[wptr[AW-1:0]]  <= cmd_dev;
                cq_base[wptr[AW-1:0]] <= cmd_base;
                cq_coll[wptr[AW-1:0]] <= cmd_coll;
                wptr <= wptr + 1'b1;
            end
            if (exec_en && (cq_count != 0)) begin
                if (ex_op == OP_MAPD) begin
                    dev_valid[ex_dev] <= 1'b1;
                    dt_base[ex_dev] <= ex_base;
                    dt_coll[ex_dev] <= ex_coll;
                    seen_map <= 1'b1;
                end else if (ex_op == OP_UNMAPD) begin
                    dev_valid[ex_dev] <= 1'b0;
                end
                rptr <= rptr + 1'b1;
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (req_valid && req_ready) begin
                if (dev_valid[req_dev]) begin
                    out_valid <= 1'b1;
                    out_intid <= dt_base[req_dev] + req_event;
                    out_coll <= dt_coll[req_dev];
                    xlat_count <= xlat_count + 1'b1;
                end else begin
                    miss_count <= miss_count + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (xlat_count != {DW{1'b0}}) assert (seen_map);
endmodule

module idle_autopd #(
    parameter DATA_W = 128,
    parameter CNT_W  = 4,
    parameter [CNT_W-1:0] DEF_THR = 4'd6
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [DATA_W-1:0] in_data,
    input  wire              tick,
    input  wire              cfg_thr_we,
    input  wire [CNT_W-1:0]  cfg_thr,
    input  wire              cfg_en,
    input  wire              cfg_dis,
    output wire              pwr_down_req,
    output reg  [DATA_W-1:0] blk_data
);
    reg [CNT_W-1:0] idle_cnt = {CNT_W{1'b0}};
    reg [CNT_W-1:0] thresh   = DEF_THR;
    reg             pd_req   = 1'b0;
    reg             apd_en   = 1'b0;
    initial blk_data = {DATA_W{1'b0}};

    assign in_ready     = !pd_req;
    assign pwr_down_req = pd_req && apd_en;

    wire accept = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            idle_cnt <= {CNT_W{1'b0}};
            thresh   <= DEF_THR;
            pd_req   <= 1'b0;
        end else if (cfg_thr_we) begin
            thresh   <= (cfg_thr == {CNT_W{1'b0}}) ? {{(CNT_W-1){1'b0}}, 1'b1} : cfg_thr;
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (in_valid) begin
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (tick && !pd_req) begin
            idle_cnt <= idle_cnt + 1'b1;
            if (idle_cnt + 1'b1 == thresh)
                pd_req <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (!rst && accept)
            blk_data <= in_data;
    end

    always @(posedge clk) begin
        if (rst)
            apd_en <= 1'b0;
        else if (cfg_dis)
            apd_en <= 1'b0;
        else if (cfg_en)
            apd_en <= 1'b1;
    end

    always @(*) assert (!apd_en || idle_cnt <= thresh);
endmodule

module fft_twiddle_rom #(
    parameter ENTRIES = 16,
    parameter AW = 4,
    parameter W = 16,
    parameter CW = 6
) (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [W-1:0] re_q,
    output reg [W-1:0] im_q,
    output reg [AW-1:0] idx_q
);
    // butterfly sequencing counter: position and stage fields
    reg [CW-1:0] cnt;
    wire [1:0]    stage = cnt[5:4];
    wire [AW-1:0] pos   = cnt[AW-1:0];
    wire [AW-1:0] k     = pos << stage;

    // ROM contents: cos(pi*k/16) and -sin(pi*k/16) in Q15
    wire [W-1:0] cos_k =
        (k == 4'd0)  ? 16'h7FFF :
        (k == 4'd1)  ? 16'h7D89 :
        (k == 4'd2)  ? 16'h7641 :
        (k == 4'd3)  ? 16'h6A6D :
        (k == 4'd4)  ? 16'h5A82 :
        (k == 4'd5)  ? 16'h471D :
        (k == 4'd6)  ? 16'h30FC :
        (k == 4'd7)  ? 16'h18F9 :
        (k == 4'd8)  ? 16'h0000 :
        (k == 4'd9)  ? 16'hE707 :
        (k == 4'd10) ? 16'hCF04 :
        (k == 4'd11) ? 16'hB8E3 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'h9593 :
        (k == 4'd14) ? 16'h89BF :
                       16'h8277;
    wire [W-1:0] msin_k =
        (k == 4'd0)  ? 16'h0000 :
        (k == 4'd1)  ? 16'hE707 :
        (k == 4'd2)  ? 16'hCF04 :
        (k == 4'd3)  ? 16'hB8E3 :
        (k == 4'd4)  ? 16'hA57E :
        (k == 4'd5)  ? 16'h9593 :
        (k == 4'd6)  ? 16'h89BF :
        (k == 4'd7)  ? 16'h8277 :
        (k == 4'd8)  ? 16'h8001 :
        (k == 4'd9)  ? 16'h8277 :
        (k == 4'd10) ? 16'h89BF :
        (k == 4'd11) ? 16'h9593 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'hB8E3 :
        (k == 4'd14) ? 16'hCF04 :
                       16'hE707;

    // registered ROM read stage
    reg [W-1:0]  re_d;
    reg [W-1:0]  im_d;
    reg [AW-1:0] idx_d;

    initial cnt = {CW{1'b0}};
    initial re_d = 16'h7FFF;
    initial im_d = 16'h0000;
    initial idx_d = {AW{1'b0}};
    initial re_q = 16'h7FFF;
    initial im_q = 16'h0000;
    initial idx_q = {AW{1'b0}};

    always @(posedge clk) begin
        if (rst) begin
            cnt   <= {CW{1'b0}};
            re_d  <= 16'h7FFF;
            im_d  <= 16'h0000;
            idx_d <= {AW{1'b0}};
            re_q  <= 16'h7FFF;
            im_q  <= 16'h0000;
            idx_q <= {AW{1'b0}};
        end else if (ce) begin
            cnt   <= cnt + 1'b1;
            idx_d <= k;
            re_d  <= cos_k;
            im_d  <= msin_k;
            idx_q <= idx_d;
            re_q  <= re_d;
            im_q  <= im_d;
        end
    end

    // unity twiddle W^0 = 1
    always @(*) assert (idx_q != 4'd0 || (re_q == 16'h7FFF && im_q == 16'h0000));
    // quarter twiddle W^8 = -j
    always @(*) assert (idx_q != 4'd8 || (re_q == 16'h0000 && im_q == 16'h8001));
endmodule

module ecc_scrubber #(
    parameter LINES = 16,
    parameter AW = 4,
    parameter DW = 128,
    parameter SW = 7,
    parameter TW = 4,
    parameter [TW-1:0] INTERVAL = 4'd9,
    parameter CW = 8
)(
    input  wire          clk,
    input  wire          tick,
    input  wire          rd_valid,
    output wire          rd_ready,
    input  wire [DW-1:0] rd_data,
    input  wire          rd_err,
    input  wire [SW-1:0] rd_syn,
    output wire [AW-1:0] rd_addr,
    output wire          wb_valid,
    input  wire          wb_ready,
    output reg  [AW-1:0] wb_addr,
    output reg  [DW-1:0] wb_data,
    output reg  [CW-1:0] err_count,
    output reg  [AW-1:0] scrub_addr,
    output reg  [LINES-1:0] err_map
);
    localparam [1:0] S_WAIT = 2'd0;
    localparam [1:0] S_READ = 2'd1;
    localparam [1:0] S_WB   = 2'd2;

    reg [1:0]    phase;
    reg [TW-1:0] timer;
    reg          first_pass;

    initial begin
        phase      = S_WAIT;
        timer      = INTERVAL;
        wb_addr    = {AW{1'b0}};
        wb_data    = {DW{1'b0}};
        err_count  = {CW{1'b0}};
        scrub_addr = {AW{1'b0}};
        err_map    = {LINES{1'b0}};
        first_pass = 1'b1;
    end

    assign rd_ready = (phase == S_READ);
    assign wb_valid = (phase == S_WB);
    assign rd_addr  = scrub_addr;

    wire rd_fire    = rd_valid && rd_ready;
    wire done_clean = rd_fire && !rd_err;
    wire done_wb    = wb_valid && wb_ready;
    wire wrap_event = (done_clean && scrub_addr == LINES-1) ||
                      (done_wb && wb_addr == LINES-1);

    wire [DW-1:0] flip_mask = {{(DW-1){1'b0}}, 1'b1} << rd_syn;

    always @(posedge clk) begin
        case (phase)
            S_WAIT: begin
                if (tick) begin
                    if (timer == {TW{1'b0}}) begin
                        phase <= S_READ;
                        timer <= INTERVAL;
                    end else begin
                        timer <= timer - 1'b1;
                    end
                end
            end
            S_READ: begin
                if (rd_fire) begin
                    if (rd_err) begin
                        wb_data <= rd_data ^ flip_mask;
                        wb_addr <= scrub_addr;
                        phase   <= S_WB;
                    end else begin
                        scrub_addr <= scrub_addr + 1'b1;
                        phase      <= S_WAIT;
                    end
                end
            end
            S_WB: begin
                if (wb_ready) begin
                    scrub_addr       <= wb_addr + 1'b1;
                    err_map[wb_addr] <= 1'b1;
                    if (err_count != {CW{1'b1}})
                        err_count <= err_count + 1'b1;
                    phase <= S_WAIT;
                end
            end
            default: phase <= S_WAIT;
        endcase
        if (wrap_event)
            first_pass <= 1'b0;
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && first_pass && $stable(scrub_addr))
            assert ($stable(err_count));
endmodule

module irq_first_arrival #(
    parameter NCH  = 8,
    parameter IDXW = 3,
    parameter TW   = 64
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire            clr,
    input  wire [NCH-1:0]  irq,
    output reg             captured,
    output reg [IDXW-1:0]  win_idx,
    output reg [NCH-1:0]   win_mask,
    output reg [TW-1:0]    cap_time
);
    localparam [NCH-1:0] ONE = 1;

    reg [TW-1:0] tick;

    initial begin
        captured = 1'b0;
        win_idx  = {IDXW{1'b0}};
        win_mask = {NCH{1'b0}};
        cap_time = {TW{1'b0}};
        tick     = {TW{1'b0}};
    end

    function [IDXW-1:0] first_idx;
        input [NCH-1:0] v;
        integer i;
        begin
            first_idx = {IDXW{1'b0}};
            for (i = NCH-1; i >= 0; i = i - 1)
                if (v[i]) first_idx = i;
        end
    endfunction

    wire [IDXW-1:0] enc = first_idx(irq);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            captured <= 1'b0;
            win_idx  <= {IDXW{1'b0}};
            win_mask <= {NCH{1'b0}};
            cap_time <= {TW{1'b0}};
            tick     <= {TW{1'b0}};
        end else if (ce) begin
            tick <= tick + {{(TW-1){1'b0}}, 1'b1};
            if (!captured && (|irq)) begin
                captured <= 1'b1;
                win_idx  <= enc;
                win_mask <= ONE << enc;
                cap_time <= tick;
            end else if (captured && clr) begin
                captured <= 1'b0;
                win_mask <= win_mask & ~(ONE << win_idx);
            end
        end
    end

    always @(*) assert (captured || win_mask == {NCH{1'b0}});
endmodule

module islip_alloc #(
    parameter N  = 4,
    parameter W  = 2,
    parameter CW = 64
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           step,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   rel,
    output reg  [N-1:0]   in_busy,
    output reg  [N*W-1:0] in_dst,
    output reg  [N-1:0]   out_busy,
    output reg  [N*W-1:0] out_src,
    output reg  [CW-1:0]  match_count,
    output reg            armed
);
    reg [N*W-1:0] g_ptr;
    reg [N*W-1:0] a_ptr;

    initial begin
        in_busy     = {N{1'b0}};
        in_dst      = {(N*W){1'b0}};
        out_busy    = {N{1'b0}};
        out_src     = {(N*W){1'b0}};
        g_ptr       = {(N*W){1'b0}};
        a_ptr       = {(N*W){1'b0}};
        match_count = {CW{1'b0}};
        armed       = 1'b0;
    end

    // grant phase: each free output picks a free requesting input, round robin from g_ptr
    integer gi, go, gk;
    reg [W-1:0]   tmp_g;
    reg [N-1:0]   gnt_v;
    reg [N*W-1:0] gnt_in;
    always @(*) begin
        gnt_v  = {N{1'b0}};
        gnt_in = {(N*W){1'b0}};
        tmp_g  = {W{1'b0}};
        for (go = 0; go < N; go = go + 1)
            for (gk = N-1; gk >= 0; gk = gk - 1) begin
                tmp_g = g_ptr[go*W +: W] + gk;
                for (gi = 0; gi < N; gi = gi + 1)
                    if (tmp_g == gi && !out_busy[go] && !in_busy[gi] && req[gi*N+go]) begin
                        gnt_v[go] = 1'b1;
                        gnt_in[go*W +: W] = gi;
                    end
            end
    end

    // accept phase: each free input accepts one granting output, round robin from a_ptr
    integer ai, ao, ak;
    reg [W-1:0]   tmp_a;
    reg [N-1:0]   acc_v;
    reg [N*W-1:0] acc_out;
    always @(*) begin
        acc_v   = {N{1'b0}};
        acc_out = {(N*W){1'b0}};
        tmp_a   = {W{1'b0}};
        for (ai = 0; ai < N; ai = ai + 1)
            for (ak = N-1; ak >= 0; ak = ak - 1) begin
                tmp_a = a_ptr[ai*W +: W] + ak;
                for (ao = 0; ao < N; ao = ao + 1)
                    if (tmp_a == ao && !in_busy[ai] && gnt_v[ao] && gnt_in[ao*W +: W] == ai) begin
                        acc_v[ai] = 1'b1;
                        acc_out[ai*W +: W] = ao;
                    end
            end
    end

    // next-state: releases tear down, accepted matches connect, pointers advance only on accept
    integer ni, no;
    reg [N-1:0]   in_busy_n;
    reg [N*W-1:0] in_dst_n;
    reg [N-1:0]   out_busy_n;
    reg [N*W-1:0] out_src_n;
    reg [N*W-1:0] g_ptr_n;
    reg [N*W-1:0] a_ptr_n;
    reg [W:0]     n_acc;
    always @(*) begin
        in_busy_n  = in_busy;
        in_dst_n   = in_dst;
        out_busy_n = out_busy;
        out_src_n  = out_src;
        g_ptr_n    = g_ptr;
        a_ptr_n    = a_ptr;
        n_acc      = {(W+1){1'b0}};
        for (ni = 0; ni < N; ni = ni + 1) begin
            if (rel[ni] && in_busy[ni])
                in_busy_n[ni] = 1'b0;
            if (acc_v[ni]) begin
                in_busy_n[ni]        = 1'b1;
                in_dst_n[ni*W +: W]  = acc_out[ni*W +: W];
                a_ptr_n[ni*W +: W]   = acc_out[ni*W +: W] + 1'b1;
                n_acc                = n_acc + 1'b1;
            end
            for (no = 0; no < N; no = no + 1) begin
                if (rel[ni] && in_busy[ni] && in_dst[ni*W +: W] == no)
                    out_busy_n[no] = 1'b0;
                if (acc_v[ni] && acc_out[ni*W +: W] == no) begin
                    out_busy_n[no]       = 1'b1;
                    out_src_n[no*W +: W] = ni;
                    g_ptr_n[no*W +: W]   = ni + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            in_busy     <= {N{1'b0}};
            in_dst      <= {(N*W){1'b0}};
            out_busy    <= {N{1'b0}};
            out_src     <= {(N*W){1'b0}};
            g_ptr       <= {(N*W){1'b0}};
            a_ptr       <= {(N*W){1'b0}};
            match_count <= {CW{1'b0}};
        end else if (step) begin
            in_busy     <= in_busy_n;
            in_dst      <= in_dst_n;
            out_busy    <= out_busy_n;
            out_src     <= out_src_n;
            g_ptr       <= g_ptr_n;
            a_ptr       <= a_ptr_n;
            match_count <= match_count + n_acc;
            if (|acc_v)
                armed <= 1'b1;
        end
    end

    // absence: two inputs never own the same output (after the first match)
    integer pi, pj;
    reg dup;
    always @(*) begin
        dup = 1'b0;
        for (pi = 0; pi < N; pi = pi + 1)
            for (pj = pi + 1; pj < N; pj = pj + 1)
                if (in_busy[pi] && in_busy[pj] && in_dst[pi*W +: W] == in_dst[pj*W +: W])
                    dup = 1'b1;
    end

    assert property (!armed || !dup);
endmodule

module desc_own_table #(
    parameter DEPTH = 8,
    parameter AW = 3,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          we,
    input  wire [AW-1:0] waddr,
    input  wire [DW-1:0] wdata,
    input  wire          dma_take,
    input  wire          adv,
    input  wire          start,
    input  wire          stop,
    output wire [DW-1:0] rdata,
    output wire          cpu_own,
    output wire          dma_own
);
    // asynchronous-read distributed descriptor RAM
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] ptr = {AW{1'b0}};
    reg armed = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    // combinational read of the word addressed by the DMA fetch pointer
    assign rdata   = mem[ptr];
    assign cpu_own = rdata[0];
    assign dma_own = rdata[1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= {DW{1'b0}};
            ptr   <= {AW{1'b0}};
            armed <= 1'b0;
        end else if (ce) begin
            if (we)
                // CPU write: CPU ownership bit wins, DMA bit is cleared if CPU claims
                mem[waddr] <= {wdata[DW-1:2], wdata[1] & ~wdata[0], wdata[0]};
            else if (dma_take && !rdata[0])
                // DMA claims the fetched descriptor only if CPU does not own it
                mem[ptr] <= {rdata[DW-1:2], 2'b10};
            if (adv)
                ptr <= ptr + 1'b1;
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pv <= 1'b0;
        else
            pv <= 1'b1;
    end

    // after start until stop: the fetched descriptor never has two owners
    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(cpu_own) && $past(dma_own)));
endmodule

module fll_cnt_cmp #(
    parameter W = 64,
    parameter [W-1:0] WINDOW = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         osc_tick,
    input  wire         tgt_load,
    input  wire [W-1:0] tgt_in,
    output reg  [W-1:0] osc_code,
    output reg          locked
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_COUNT = 2'd1, S_CMP = 2'd2, S_ADJ = 2'd3} state_t;

    state_t state = S_IDLE;
    reg [W-1:0] cyc_cnt = {W{1'b0}};
    reg [W-1:0] win_tmr = {W{1'b0}};
    reg [W-1:0] target  = {W{1'b0}};
    reg up_req = 1'b0;
    reg dn_req = 1'b0;
    reg armed  = 1'b0;

    initial osc_code = {W{1'b0}};
    initial locked   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state   <= S_IDLE;
            cyc_cnt <= {W{1'b0}};
            win_tmr <= {W{1'b0}};
            up_req  <= 1'b0;
            dn_req  <= 1'b0;
            locked  <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tgt_load) target <= tgt_in;
                    cyc_cnt <= {W{1'b0}};
                    win_tmr <= WINDOW;
                    armed   <= 1'b1;
                    state   <= S_COUNT;
                end
                S_COUNT: begin
                    if (osc_tick) cyc_cnt <= cyc_cnt + 1'b1;
                    win_tmr <= win_tmr - 1'b1;
                    if (win_tmr == 1) state <= S_CMP;
                end
                S_CMP: begin
                    up_req <= (cyc_cnt < target);
                    dn_req <= (cyc_cnt > target);
                    state  <= S_ADJ;
                end
                S_ADJ: begin
                    if (up_req)      osc_code <= osc_code + 1'b1;
                    else if (dn_req) osc_code <= osc_code - 1'b1;
                    locked <= !up_req && !dn_req;
                    up_req <= 1'b0;
                    dn_req <= 1'b0;
                    state  <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!armed || !(state == S_CMP && cyc_cnt > WINDOW));
endmodule

module morse_decoder #(
    parameter SRW = 8,
    parameter [7:0] MAXSYM = 8'd7,
    parameter [7:0] DOT_MAX = 8'd3,
    parameter [7:0] CHAR_GAP = 8'd5
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire key,
    output reg [SRW-1:0] char_code,
    output reg [7:0] char_len,
    output reg char_valid
);
    typedef enum logic [1:0] {IDLE = 2'd0, MARK = 2'd1, SPACE = 2'd2} state_t;
    state_t state;
    reg [7:0] dur;
    reg [SRW-1:0] sym_sr;
    reg [7:0] sym_cnt;
    reg armed;

    initial begin
        state = IDLE;
        dur = 8'd0;
        sym_sr = {{(SRW-1){1'b0}}, 1'b1};
        sym_cnt = 8'd0;
        armed = 1'b0;
        char_code = {SRW{1'b0}};
        char_len = 8'd0;
        char_valid = 1'b0;
    end

    wire is_dash = (dur > DOT_MAX);
    wire [7:0] dur_inc = (dur == 8'hFF) ? dur : (dur + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            dur <= 8'd0;
            sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
            sym_cnt <= 8'd0;
            armed <= 1'b0;
            char_code <= {SRW{1'b0}};
            char_len <= 8'd0;
            char_valid <= 1'b0;
        end else if (step) begin
            char_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end
                end
                MARK: begin
                    if (key) begin
                        dur <= dur_inc;
                    end else begin
                        if (sym_cnt < MAXSYM) begin
                            sym_sr <= {sym_sr[SRW-2:0], is_dash};
                            sym_cnt <= sym_cnt + 8'd1;
                        end
                        armed <= 1'b1;
                        state <= SPACE;
                        dur <= 8'd1;
                    end
                end
                SPACE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end else if (dur_inc >= CHAR_GAP) begin
                        char_code <= sym_sr;
                        char_len <= sym_cnt;
                        char_valid <= 1'b1;
                        sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
                        sym_cnt <= 8'd0;
                        armed <= 1'b0;
                        state <= IDLE;
                        dur <= 8'd0;
                    end else begin
                        dur <= dur_inc;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Scope: after a symbol is accepted (armed set) until the character is emitted (armed cleared)
    always @(posedge clk)
        if (armed)
            assert (sym_sr != {{(SRW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (armed && sym_cnt < MAXSYM)
            assert (sym_sr[SRW-1] == 1'b0);
endmodule

module assoc_bitserial #(
    parameter N  = 8,
    parameter W  = 32,
    parameter CW = 6,
    parameter TW = 4
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire          in_op,
    input  wire [2:0]    in_addr,
    input  wire [W-1:0]  in_data,
    input  wire [W-1:0]  in_mask,
    input  wire          i_step,
    output reg           res_valid,
    input  wire          res_ready,
    output wire [N-1:0]  res_tag,
    output wire          res_any
);
    reg [N*W-1:0] words;
    reg [W-1:0]   comparand;
    reg [W-1:0]   mask;
    reg [N-1:0]   tag;
    reg [TW-1:0]  hit_cnt;
    reg [CW-1:0]  col;
    reg           busy;

    initial begin
        words = {N*W{1'b0}};
        comparand = {W{1'b0}};
        mask = {W{1'b0}};
        tag = {N{1'b0}};
        hit_cnt = {TW{1'b0}};
        col = {CW{1'b0}};
        busy = 1'b0;
        res_valid = 1'b0;
    end

    assign in_ready = !busy && !res_valid;
    assign res_tag  = tag;
    assign res_any  = (hit_cnt != {TW{1'b0}});

    wire [4:0] bit_idx = col[4:0];
    wire cmp_bit = comparand[bit_idx];
    wire msk_bit = mask[bit_idx];

    wire [N-1:0] keep;
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_col
            assign keep[g] = !msk_bit || (words[g*W + bit_idx] == cmp_bit);
        end
    endgenerate

    wire [N-1:0] cleared = tag & ~keep;
    reg [TW-1:0] drop;
    integer k;
    always @(*) begin
        drop = {TW{1'b0}};
        for (k = 0; k < N; k = k + 1)
            drop = drop + {{(TW-1){1'b0}}, cleared[k]};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            words <= {N*W{1'b0}};
            comparand <= {W{1'b0}};
            mask <= {W{1'b0}};
            tag <= {N{1'b0}};
            hit_cnt <= {TW{1'b0}};
            col <= {CW{1'b0}};
            busy <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready)
                res_valid <= 1'b0;
            if (in_valid && in_ready) begin
                if (in_op) begin
                    comparand <= in_data;
                    mask <= in_mask;
                    tag <= {N{1'b1}};
                    hit_cnt <= N[TW-1:0];
                    col <= {CW{1'b0}};
                    busy <= 1'b1;
                end else begin
                    words[in_addr*W +: W] <= in_data;
                end
            end else if (busy && i_step) begin
                tag <= tag & keep;
                hit_cnt <= hit_cnt - drop;
                if (col == W-1) begin
                    col <= W[CW-1:0];
                    busy <= 1'b0;
                    res_valid <= 1'b1;
                end else begin
                    col <= col + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert ((hit_cnt != {TW{1'b0}}) == (tag != {N{1'b0}}));
endmodule

module ola_block_conv #(
    parameter W = 32,
    parameter BLK = 64,
    parameter TAPS = 4,
    parameter [TAPS*W-1:0] COEF = {32'd1, 32'd3, 32'd3, 32'd1}
)(
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_sample,
    output reg  [W-1:0] o_y,
    output reg          o_valid,
    output wire         o_busy,
    output wire [31:0]  o_blocks
);
    localparam [31:0] LAST  = BLK + TAPS - 2;
    localparam [31:0] TLAST = TAPS - 2;

    reg [W-1:0] in_buf [0:BLK-1];
    reg [W-1:0] tail   [0:TAPS-2];
    reg [31:0] wr_idx   = 32'd0;
    reg [31:0] out_idx  = 32'd0;
    reg [31:0] tail_idx = 32'd0;
    reg [31:0] blk_cnt  = 32'd0;
    reg        phase    = 1'b0;

    integer i;
    initial begin
        o_y = 0;
        o_valid = 1'b0;
        for (i = 0; i < BLK; i = i + 1) in_buf[i] = 0;
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = 0;
    end

    assign o_busy   = phase;
    assign o_blocks = blk_cnt;

    reg [W-1:0] acc;
    reg [31:0]  src;
    integer j;
    always @(*) begin
        acc = 0;
        src = 0;
        for (j = 0; j < TAPS; j = j + 1) begin
            src = out_idx - j;
            if (out_idx >= j && src < BLK)
                acc = acc + COEF[j*W +: W] * in_buf[src];
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (i_reset) begin
            wr_idx   <= 32'd0;
            out_idx  <= 32'd0;
            tail_idx <= 32'd0;
            blk_cnt  <= 32'd0;
            phase    <= 1'b0;
            o_valid  <= 1'b0;
            o_y      <= 0;
        end else if (i_ce) begin
            o_valid <= 1'b0;
            if (!phase) begin
                in_buf[wr_idx] <= i_sample;
                if (wr_idx == BLK-1) begin
                    wr_idx   <= 32'd0;
                    phase    <= 1'b1;
                    out_idx  <= 32'd0;
                    tail_idx <= 32'd0;
                end else begin
                    wr_idx <= wr_idx + 32'd1;
                end
            end else begin
                if (out_idx >= BLK) begin
                    tail[tail_idx] <= acc;
                    if (tail_idx == TLAST) begin
                        phase    <= 1'b0;
                        out_idx  <= 32'd0;
                        tail_idx <= 32'd0;
                        blk_cnt  <= blk_cnt + 32'd1;
                    end else begin
                        tail_idx <= tail_idx + 32'd1;
                        out_idx  <= out_idx + 32'd1;
                    end
                end else begin
                    o_y     <= acc;
                    o_valid <= 1'b1;
                    out_idx <= out_idx + 32'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv) assert (!$past(i_ce) || out_idx <= LAST);
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    assign in_ready = (phase == S_ARM) || (phase == S_RUN);
    wire acc = in_valid && in_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            rem     <= rnext(rem, in_bit);
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter DW = 16
)(
    input  wire          clk,
    input  wire          flush,
    input  wire [DW-1:0] flush_addr,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_desc,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_desc,
    output wire [DW-1:0] out_tag,
    output wire [DW-1:0] fetch_req_addr,
    input  wire [DW-1:0] lk_addr,
    output wire          lk_hit
);
    localparam AW = $clog2(DEPTH);

    reg [DW-1:0] desc_mem [0:DEPTH-1];
    reg [DW-1:0] tag_mem  [0:DEPTH-1];
    reg [DEPTH-1:0] valid = {DEPTH{1'b0}};
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [AW-1:0] rd_ptr = {AW{1'b0}};
    reg [DW-1:0] count = {DW{1'b0}};
    reg [DW-1:0] fetch_addr = {DW{1'b0}};
    reg armed = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            desc_mem[i] = {DW{1'b0}};
            tag_mem[i]  = {DW{1'b0}};
        end
    end

    assign in_ready = !flush && (count != DEPTH);
    wire in_fire = in_valid && in_ready;
    wire push = in_fire && !valid[wr_ptr];
    assign out_valid = !flush && valid[rd_ptr];
    wire pop = out_valid && out_ready;

    assign out_desc = desc_mem[rd_ptr];
    assign out_tag = tag_mem[rd_ptr];
    assign fetch_req_addr = fetch_addr;

    wire [DEPTH-1:0] set_mask = push ? ({{(DEPTH-1){1'b0}}, 1'b1} << wr_ptr) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_mask = pop  ? ({{(DEPTH-1){1'b0}}, 1'b1} << rd_ptr) : {DEPTH{1'b0}};

    wire [DEPTH-1:0] exp_valid;
    wire [DEPTH-1:0] hit_vec;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_slot
            wire [AW-1:0] off = g - rd_ptr;
            assign exp_valid[g] = ({{(DW-AW){1'b0}}, off} < count);
            assign hit_vec[g] = valid[g] && (tag_mem[g] == lk_addr);
        end
    endgenerate
    assign lk_hit = |hit_vec;

    always @(posedge clk) begin
        if (flush) begin
            valid <= {DEPTH{1'b0}};
            count <= {DW{1'b0}};
            rd_ptr <= wr_ptr;
            fetch_addr <= flush_addr;
            armed <= 1'b0;
        end else begin
            if (push) begin
                desc_mem[wr_ptr] <= in_desc;
                tag_mem[wr_ptr] <= fetch_addr;
                wr_ptr <= wr_ptr + 1'b1;
                armed <= 1'b1;
            end
            if (in_fire)
                fetch_addr <= fetch_addr + {{(DW-1){1'b0}}, 1'b1};
            if (pop)
                rd_ptr <= rd_ptr + 1'b1;
            valid <= (valid | set_mask) & ~clr_mask;
            count <= count + {{(DW-1){1'b0}}, push} - {{(DW-1){1'b0}}, pop};
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(wr_ptr))
            assert ($stable(fetch_addr));
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
endmodule

module rename_table #(
    parameter NARCH = 4,
    parameter NPHYS = 8,
    parameter AW = $clog2(NARCH),
    parameter TW = $clog2(NPHYS),
    parameter CW = 16
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          i_req,
    input  wire [AW-1:0] i_dst,
    output wire [TW-1:0] o_tag,
    output wire [CW-1:0] o_cnt
);
    typedef enum logic [1:0] {S_IDLE, S_ARM, S_START, S_FINISH} state_t;

    state_t state = S_IDLE;

    // rename map: architectural register -> physical tag
    reg [NARCH-1:0][TW-1:0] map_q;
    // free-tag list as a bit vector (1 = tag free)
    reg [NPHYS-1:0] free_vec = {NPHYS{1'b1}} << NARCH;
    reg [AW-1:0]    dst       = {AW{1'b0}};
    reg [TW-1:0]    alloc_tag = {TW{1'b0}};
    reg [CW-1:0]    rename_cnt = {CW{1'b0}};
    reg             seen_q    = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < NARCH; i = i + 1)
            map_q[i] = i;
    end

    // lowest free physical tag
    reg [TW-1:0] pick;
    integer k;
    always @(*) begin
        pick = {TW{1'b0}};
        for (k = NPHYS-1; k >= 0; k = k - 1)
            if (free_vec[k]) pick = k;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        dst    <= i_dst;
                        seen_q <= 1'b1;
                        state  <= S_ARM;
                    end
                end
                S_ARM: begin
                    if (free_vec != {NPHYS{1'b0}}) begin
                        alloc_tag      <= pick;
                        free_vec[pick] <= 1'b0;
                        state          <= S_START;
                    end
                end
                S_START: begin
                    map_q[dst]           <= alloc_tag;
                    free_vec[map_q[dst]] <= 1'b1;
                    state                <= S_FINISH;
                end
                S_FINISH: begin
                    rename_cnt <= rename_cnt + 1'b1;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    assign o_tag = alloc_tag;
    assign o_cnt = rename_cnt;

    // after the first accepted rename request: a finished rename must have
    // passed through allocation (tag taken off the free list)
    always @(posedge clk)
        if (seen_q && state == S_FINISH)
            assert (!free_vec[alloc_tag]);
endmodule

module pkt_framer #(
    parameter W = 16,
    parameter DEPTH = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_start,
    input  wire [W-1:0] i_len,
    input  wire [W-1:0] i_data,
    output reg  [W-1:0] o_word,
    output reg          o_sof,
    output reg          o_eof
);
    localparam [W-1:0] MAX_LEN    = DEPTH;
    localparam [W-1:0] START_DELIM = 16'hA5A5;
    localparam [W-1:0] END_DELIM   = 16'h5A5A;
    localparam [1:0] S_IDLE = 2'd0, S_HDR = 2'd1, S_PAY = 2'd2, S_TRL = 2'd3;

    reg [1:0]   frame_state = S_IDLE;
    reg [W-1:0] byte_cnt    = {W{1'b0}};
    reg [W-1:0] len_reg     = {{(W-1){1'b0}}, 1'b1};
    reg         armed       = 1'b0;
    reg         pv          = 1'b0;
    initial o_word = {W{1'b0}};
    initial o_sof  = 1'b0;
    initial o_eof  = 1'b0;

    wire [W-1:0] len_clamped = (i_len == {W{1'b0}}) ? {{(W-1){1'b0}}, 1'b1} :
                               ((i_len > MAX_LEN) ? MAX_LEN : i_len);
    wire over_lim = (byte_cnt > MAX_LEN);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            frame_state <= S_IDLE;
            byte_cnt    <= {W{1'b0}};
            len_reg     <= {{(W-1){1'b0}}, 1'b1};
            o_word      <= {W{1'b0}};
            o_sof       <= 1'b0;
            o_eof       <= 1'b0;
        end else if (i_ce) begin
            case (frame_state)
                S_IDLE: begin
                    o_sof <= 1'b0;
                    o_eof <= 1'b0;
                    if (i_start) begin
                        len_reg     <= len_clamped;
                        o_word      <= START_DELIM;
                        o_sof       <= 1'b1;
                        armed       <= 1'b1;
                        frame_state <= S_HDR;
                    end
                end
                S_HDR: begin
                    o_sof       <= 1'b0;
                    o_word      <= len_reg;
                    byte_cnt    <= {W{1'b0}};
                    frame_state <= S_PAY;
                end
                S_PAY: begin
                    o_word <= i_data;
                    if (byte_cnt == len_reg - 1'b1) begin
                        byte_cnt    <= {W{1'b0}};
                        frame_state <= S_TRL;
                    end else begin
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                end
                S_TRL: begin
                    o_word      <= END_DELIM;
                    o_eof       <= 1'b1;
                    frame_state <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(frame_state))
            assert ($stable(over_lim));
endmodule

module exp_scale_unit #(
    parameter W = 32,
    parameter signed EMAX = 127,
    parameter signed EMIN = -126
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [W-1:0] i_exp,
    input  wire [W-1:0] i_scale,
    input  wire [W-1:0] i_sig,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [W-1:0] o_exp,
    output reg  [W-1:0] o_sig,
    output reg          o_ovf,
    output reg          o_uf,
    output reg  [W-1:0] ovf_in_cnt,
    output reg  [W-1:0] ovf_out_cnt
);
    initial begin
        o_valid = 1'b0; o_exp = {W{1'b0}}; o_sig = {W{1'b0}};
        o_ovf = 1'b0; o_uf = 1'b0;
        ovf_in_cnt = {W{1'b0}}; ovf_out_cnt = {W{1'b0}};
    end

    assign i_ready = !o_valid || o_ready;
    wire accept = i_valid && i_ready;
    wire fire   = o_valid && o_ready;

    // scaleB: exponent + signed scale, computed wide to avoid wrap
    wire signed [W+1:0] sum = $signed({{2{i_exp[W-1]}}, i_exp}) + $signed({{2{i_scale[W-1]}}, i_scale});
    wire ovf_now = (sum > EMAX);
    wire uf_now  = (sum < EMIN);
    wire signed [W+1:0] ushift = EMIN - sum;
    wire flush = uf_now && (ushift >= W);
    wire [W-1:0] den_sig = flush ? {W{1'b0}} : (i_sig >> ushift[$clog2(W):0]);
    wire [W-1:0] emax_p1 = EMAX + 1;
    wire [W-1:0] emin_m1 = EMIN - 1;
    wire [W-1:0] res_exp = ovf_now ? emax_p1 : (uf_now ? emin_m1 : sum[W-1:0]);
    wire [W-1:0] res_sig = ovf_now ? {W{1'b0}} : (uf_now ? den_sig : i_sig);

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0; o_exp <= {W{1'b0}}; o_sig <= {W{1'b0}};
            o_ovf <= 1'b0; o_uf <= 1'b0;
            ovf_in_cnt <= {W{1'b0}}; ovf_out_cnt <= {W{1'b0}};
        end else begin
            if (accept) begin
                o_valid <= 1'b1;
                o_exp   <= res_exp;
                o_sig   <= res_sig;
                o_ovf   <= ovf_now;
                o_uf    <= uf_now;
            end else if (fire) begin
                o_valid <= 1'b0;
            end
            if (accept && ovf_now) ovf_in_cnt  <= ovf_in_cnt + 1'b1;
            if (fire && o_ovf)     ovf_out_cnt <= ovf_out_cnt + 1'b1;
        end
    end

    // Precedence: an overflow result delivered now must have been preceded by
    // an accepted overflowing input that has not yet been delivered.
    always @(posedge clk)
        if (o_valid && o_ready && o_ovf)
            assert (ovf_in_cnt != ovf_out_cnt);
endmodule

module burst_hold_arb #(
    parameter NREQ = 4,
    parameter LW   = 16,
    parameter OW   = 2
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire [NREQ-1:0] req,
    input  wire [LW-1:0]   req_len,
    output wire [NREQ-1:0] gnt,
    output wire            busy,
    output wire            last_beat
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_ARM  = 2'd1;
    localparam [1:0] S_XFER = 2'd2;

    reg [1:0]    phase      = S_IDLE;
    reg [OW-1:0] owner      = {OW{1'b0}};
    reg [LW-1:0] beats      = {LW{1'b0}};
    reg          seen_grant = 1'b0;
    reg          pv         = 1'b0;

    reg [OW-1:0] winner;
    integer i;
    always @(*) begin
        winner = {OW{1'b0}};
        for (i = NREQ-1; i >= 0; i = i - 1)
            if (req[i]) winner = i;
    end

    wire [LW-1:0] eff_len = (req_len == {LW{1'b0}}) ? {{(LW-1){1'b0}}, 1'b1} : req_len;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase      <= S_IDLE;
            owner      <= {OW{1'b0}};
            beats      <= {LW{1'b0}};
            seen_grant <= 1'b0;
        end else if (ce) begin
            case (phase)
                S_IDLE: begin
                    if (|req) begin
                        owner      <= winner;
                        beats      <= eff_len;
                        phase      <= S_ARM;
                        seen_grant <= 1'b1;
                    end
                end
                S_ARM: begin
                    phase <= S_XFER;
                end
                S_XFER: begin
                    beats <= beats - {{(LW-1){1'b0}}, 1'b1};
                    if (beats == {{(LW-1){1'b0}}, 1'b1})
                        phase <= S_IDLE;
                end
                default: begin
                    phase <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign gnt       = (phase == S_XFER) ? ({{(NREQ-1){1'b0}}, 1'b1} << owner) : {NREQ{1'b0}};
    assign busy      = (phase != S_IDLE);
    assign last_beat = (phase == S_XFER) && (beats == {{(LW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (pv && seen_grant && $stable(beats))
            assert ($stable(owner));
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter KW    = 8,
    parameter IW    = 2,
    parameter SW    = 3,
    parameter LVL   = 2
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          in_valid,
    input  wire          in_op,
    input  wire [KW-1:0] in_key,
    output wire          in_ready,
    output reg  [KW-1:0] o_key,
    output wire [SW-1:0] o_size,
    output wire          o_busy
);
    reg [DEPTH*KW-1:0] heap = {(DEPTH*KW){1'b0}};
    reg [SW-1:0] size  = {SW{1'b0}};
    reg          busy  = 1'b0;
    reg          dir   = 1'b0;
    reg [IW-1:0] idx   = {IW{1'b0}};
    reg [1:0]    timer = 2'd0;
    reg          armed = 1'b0;
    initial o_key = {KW{1'b0}};

    assign in_ready = i_ce && !busy && (in_op ? (size != {SW{1'b0}}) : (size != DEPTH));
    wire accept = in_valid && in_ready;
    assign o_size = size;
    assign o_busy = busy;

    wire [IW-1:0] last   = size - 1'b1;
    wire [KW-1:0] k_root = heap[KW-1:0];
    wire [KW-1:0] k_last = heap[last*KW +: KW];
    wire [KW-1:0] k_idx  = heap[idx*KW +: KW];

    // sift-up
    wire [IW-1:0] up_par  = (idx - 1'b1) >> 1;
    wire [KW-1:0] k_par   = heap[up_par*KW +: KW];
    wire          up_swap = (idx != {IW{1'b0}}) && (k_idx < k_par);

    // sift-down
    wire [SW:0]   lc    = {idx, 1'b1};
    wire [SW:0]   rc    = lc + 1'b1;
    wire [IW-1:0] lci   = lc[IW-1:0];
    wire [IW-1:0] rci   = rc[IW-1:0];
    wire [KW-1:0] k_lc  = heap[lci*KW +: KW];
    wire [KW-1:0] k_rc  = heap[rci*KW +: KW];
    wire          lc_ok = lc < {1'b0, size};
    wire          rc_ok = rc < {1'b0, size};
    wire          l_lt  = lc_ok && (k_lc < k_idx);
    wire [IW-1:0] sm1   = l_lt ? lci : idx;
    wire [KW-1:0] k_sm1 = l_lt ? k_lc : k_idx;
    wire          r_lt  = rc_ok && (k_rc < k_sm1);
    wire [IW-1:0] sm    = r_lt ? rci : sm1;
    wire [KW-1:0] k_sm  = r_lt ? k_rc : k_sm1;
    wire          dn_swap = (sm != idx);
    wire [SW:0]   sm_lc = {sm, 1'b1};
    wire          dn_more = sm_lc < {1'b0, size};

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                armed <= 1'b1;
                timer <= LVL;
                if (!in_op) begin
                    heap[size[IW-1:0]*KW +: KW] <= in_key;
                    idx  <= size[IW-1:0];
                    size <= size + 1'b1;
                    busy <= (size != {SW{1'b0}});
                    dir  <= 1'b0;
                end else begin
                    o_key <= k_root;
                    heap[KW-1:0] <= k_last;
                    size  <= size - 1'b1;
                    idx   <= {IW{1'b0}};
                    busy  <= (size > 3'd2);
                    dir   <= 1'b1;
                end
            end else if (busy) begin
                if (!dir) begin
                    if (up_swap) begin
                        heap[idx*KW +: KW]    <= k_par;
                        heap[up_par*KW +: KW] <= k_idx;
                        idx   <= up_par;
                        timer <= timer - 1'b1;
                        busy  <= (up_par != {IW{1'b0}});
                        if (up_par == {IW{1'b0}}) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end else begin
                    if (dn_swap) begin
                        heap[idx*KW +: KW] <= k_sm;
                        heap[sm*KW +: KW]  <= k_idx;
                        idx   <= sm;
                        timer <= timer - 1'b1;
                        busy  <= dn_more;
                        if (!dn_more) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end
            end else begin
                armed <= 1'b0;
            end
        end
    end

    // bounded response: while the accepted request is still sifting, its budget never runs out
    always @(posedge clk)
        if (armed) assert (!busy || timer != 2'd0);
endmodule

module axi_w_upsizer #(
    parameter NW    = 16,
    parameter LANES = 16,
    parameter LW    = 4,
    parameter SW    = 2*LANES
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              i_awvalid,
    output wire              o_awready,
    input  wire [15:0]       i_awlen,
    input  wire [2:0]        i_awsize,
    input  wire              i_wvalid,
    output wire              o_wready,
    input  wire [NW-1:0]     i_wdata,
    output wire              o_wvalid,
    input  wire              i_wready,
    output wire [NW*LANES-1:0] o_wdata,
    output wire [SW-1:0]     o_wstrb,
    output wire              o_wlast,
    output wire [2:0]        o_cap_size,
    output wire [15:0]       o_beats_left
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_PACK = 2'd2, P_OUT = 2'd3;

    reg [1:0]          phase      = P_IDLE;
    reg                aw_seen    = 1'b0;
    reg [LW-1:0]       lane       = {LW{1'b0}};
    reg [SW-1:0]       strb       = {SW{1'b0}};
    reg [NW*LANES-1:0] pbuf       = {(NW*LANES){1'b0}};
    reg [15:0]         beats_left = 16'd0;
    reg [2:0]          cap_size   = 3'd0;
    reg                last_q     = 1'b0;

    assign o_awready    = (phase == P_IDLE);
    assign o_wready     = (phase == P_ARMED) || (phase == P_PACK);
    assign o_wvalid     = (phase == P_OUT);
    assign o_wdata      = pbuf;
    assign o_wstrb      = strb;
    assign o_wlast      = last_q;
    assign o_cap_size   = cap_size;
    assign o_beats_left = beats_left;

    wire aw_hs  = i_awvalid && o_awready;
    wire w_hs   = i_wvalid  && o_wready;
    wire out_hs = o_wvalid  && i_wready;

    wire          end_wide  = (lane == LANES-1) || (beats_left == 16'd0);
    wire [SW-1:0] lane_strb = {{(SW-2){1'b0}}, 2'b11} << {lane, 1'b0};

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            aw_seen    <= 1'b0;
            lane       <= {LW{1'b0}};
            strb       <= {SW{1'b0}};
            pbuf       <= {(NW*LANES){1'b0}};
            beats_left <= 16'd0;
            cap_size   <= 3'd0;
            last_q     <= 1'b0;
        end else begin
            if (aw_hs) begin
                phase      <= P_ARMED;
                aw_seen    <= 1'b1;
                beats_left <= i_awlen;
                cap_size   <= i_awsize;
                lane       <= {LW{1'b0}};
                strb       <= {SW{1'b0}};
            end
            if (w_hs) begin
                pbuf[lane*NW +: NW] <= i_wdata;
                strb <= strb | lane_strb;
                if (end_wide) begin
                    phase  <= P_OUT;
                    last_q <= (beats_left == 16'd0);
                end else begin
                    phase <= P_PACK;
                    lane  <= lane + 1'b1;
                end
                if (beats_left != 16'd0)
                    beats_left <= beats_left - 16'd1;
            end
            if (out_hs) begin
                strb <= {SW{1'b0}};
                lane <= {LW{1'b0}};
                pbuf <= {(NW*LANES){1'b0}};
                if (last_q) begin
                    phase   <= P_IDLE;
                    aw_seen <= 1'b0;
                    last_q  <= 1'b0;
                end else begin
                    phase <= P_PACK;
                end
            end
        end
    end

    // chain precedence: a wide beat (finish) is never offered unless the
    // address was captured (arm) and the first lane was packed (start)
    assert property (!o_wvalid || (aw_seen && strb[1:0] == 2'b11));
endmodule

module sha256_msg_sched #(
    parameter WIDTH = 32,
    parameter NWIN  = 16,
    parameter NEXP  = 48
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire             out_last
);
    typedef enum logic [1:0] {IDLE = 2'd0, LOAD = 2'd1, EXPAND = 2'd2} state_t;

    state_t state;
    initial state = IDLE;
    reg [31:0] cnt;
    initial cnt = 32'd0;
    reg armed;
    initial armed = 1'b1;
    reg [NWIN*WIDTH-1:0] win;
    initial win = {(NWIN*WIDTH){1'b0}};

    function [31:0] ssig0(input [31:0] x);
        ssig0 = {x[6:0], x[31:7]} ^ {x[17:0], x[31:18]} ^ (x >> 3);
    endfunction
    function [31:0] ssig1(input [31:0] x);
        ssig1 = {x[16:0], x[31:17]} ^ {x[18:0], x[31:19]} ^ (x >> 10);
    endfunction

    wire [WIDTH-1:0] w0  = win[0*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w1  = win[1*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w9  = win[9*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w14 = win[14*WIDTH +: WIDTH];

    assign out_data  = ssig1(w14) + w9 + ssig0(w1) + w0;
    assign in_ready  = (state == IDLE) || (state == LOAD);
    assign out_valid = (state == EXPAND);
    assign out_last  = out_valid && (cnt == NEXP - 1);

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            cnt   <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_fire) begin
                        win   <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        cnt   <= 32'd1;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    if (in_fire) begin
                        win <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NWIN - 1) begin
                            cnt   <= 32'd0;
                            state <= EXPAND;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                EXPAND: begin
                    if (out_fire) begin
                        win <= {out_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NEXP - 1) begin
                            cnt   <= 32'd0;
                            state <= IDLE;
                            armed <= 1'b0;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assert property (!armed || cnt <= NEXP);
endmodule

module ldpc_cnp #(
    parameter DEG = 32,
    parameter W   = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(DEG);

    reg [W-1:0]   cnt       = {W{1'b0}};
    reg [W-1:0]   oidx      = {W{1'b0}};
    reg           out_phase = 1'b0;
    reg [W-2:0]   min1      = {(W-1){1'b1}};
    reg [W-2:0]   min2      = {(W-1){1'b1}};
    reg [W-1:0]   min_idx   = {W{1'b0}};
    reg           sign_prod = 1'b0;
    reg [DEG-1:0] sign_mem  = {DEG{1'b0}};
    reg           armed     = 1'b0;

    assign in_ready  = !out_phase;
    assign out_valid = out_phase;

    wire          accept = in_valid && in_ready;
    wire          emit   = out_valid && out_ready;
    wire          in_sgn = in_data[W-1];
    wire [W-2:0]  in_mag = in_data[W-2:0];

    assign out_data = { sign_prod ^ sign_mem[oidx[IW-1:0]],
                        (oidx == min_idx) ? min2 : min1 };

    always @(posedge clk) begin
        if (accept) armed <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= {W{1'b0}};
            oidx      <= {W{1'b0}};
            out_phase <= 1'b0;
            min1      <= {(W-1){1'b1}};
            min2      <= {(W-1){1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
        end else if (accept) begin
            sign_mem[cnt[IW-1:0]] <= in_sgn;
            sign_prod <= sign_prod ^ in_sgn;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= cnt;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            cnt <= cnt + 1'b1;
            if (cnt == DEG - 1)
                out_phase <= 1'b1;
        end else if (emit) begin
            if (oidx == DEG - 1) begin
                oidx      <= {W{1'b0}};
                cnt       <= {W{1'b0}};
                out_phase <= 1'b0;
                min1      <= {(W-1){1'b1}};
                min2      <= {(W-1){1'b1}};
                min_idx   <= {W{1'b0}};
                sign_prod <= 1'b0;
            end else begin
                oidx <= oidx + 1'b1;
            end
        end
    end

    assert property (!armed || cnt <= DEG);
endmodule

module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
   output wire [10:0] o_seq_stat
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                       if (arm_req || seq_rearm) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module tplan_px_drain (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire abort_req,
   input wire frame_act,
   input wire push,
   input wire push_eof,
   input wire [7:0] push_pix,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire ready,
   output wire drained,
   output wire eof_pend_o,
   output wire [2:0] fill_o,
   output wire [4:0] col_o,
   output wire [7:0] px_o,
   output wire px_vld_o,
   output wire px_eol_o,
   output wire hblank_o,
   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
   initial div_cnt = 4'd0;
   initial hb_cnt = 4'd0;
   initial col_out = 5'd0;
   initial px_q = 8'h00;
   initial px_vld = 1'b0;
   initial px_eol = 1'b0;
   initial eof_pend = 1'b0;
   initial sig_run = 8'h00;
   initial sig_last = 8'h00;
   initial stall_cnt = 8'd0;

   function [7:0] crc8_step;
       input [7:0] c;
       input [7:0] d;
       integer b;
       reg [7:0] x;
       begin
           x = c ^ d;
           for (b = 0; b < 8; b = b + 1)
               x = x[7] ? ((x << 1) ^ 8'h07) : (x << 1);
           crc8_step = x;
       end
   endfunction

   wire full = (cnt == DEPTH);
   wire empty = (cnt == 3'd0);
   wire tick = (div_cnt == 4'd0);
   wire in_hb = (hb_cnt != 4'd0);
   wire acc = push && !full;
   wire pop = tick && !in_hb && !empty;
   wire [7:0] head_pix = fifo[rd_ptr] ^ {8{cfg_inv}};

   assign ready = !full;
   assign drained = eof_pend && empty && tick && !in_hb;
   assign eof_pend_o = eof_pend;
   assign fill_o = cnt;
   assign col_o = col_out;
   assign px_o = px_q;
   assign px_vld_o = px_vld;
   assign px_eol_o = px_eol;
   assign hblank_o = in_hb;
   assign sig_o = sig_last;
   assign stall_o = stall_cnt;

   always @(posedge clk) begin
       if (!rst_n) begin
           for (j = 0; j < 4; j = j + 1)
               fifo[j] <= 8'h00;
           wr_ptr <= 2'd0;
           rd_ptr <= 2'd0;
           cnt <= 3'd0;
           cfg_div <= 4'd0;
           cfg_hblank <= 4'd0;
           cfg_inv <= 1'b0;
           cfg_blank <= 8'h00;
           div_cnt <= 4'd0;
           hb_cnt <= 4'd0;
           col_out <= 5'd0;
           px_q <= 8'h00;
           px_vld <= 1'b0;
           px_eol <= 1'b0;
           eof_pend <= 1'b0;
           sig_run <= 8'h00;
           sig_last <= 8'h00;
           stall_cnt <= 8'd0;
       end else if (en) begin
           if (frame_act && full && !abort_req && (stall_cnt != 8'hFF))
               stall_cnt <= stall_cnt + 8'd1;
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: cfg_hblank <= csr_wdata[3:0];
                   3'd6: begin
                       cfg_inv <= csr_wdata[0];
                       if (csr_wdata[7])
                           stall_cnt <= 8'd0;
                   end
                   3'd7: cfg_blank <= csr_wdata;
               endcase
           end
           if (abort_req) begin
               wr_ptr <= 2'd0;
               rd_ptr <= 2'd0;
               cnt <= 3'd0;
               div_cnt <= 4'd0;
               hb_cnt <= 4'd0;
               col_out <= 5'd0;
               px_q <= cfg_blank;
               px_vld <= 1'b0;
               px_eol <= 1'b0;
               eof_pend <= 1'b0;
               sig_run <= 8'h00;
           end else begin
               if (acc) begin
                   fifo[wr_ptr] <= push_pix;
                   wr_ptr <= wr_ptr + 2'd1;
                   if (push_eof)
                       eof_pend <= 1'b1;
               end
               if (acc && !pop)
                   cnt <= cnt + 3'd1;
               else if (pop && !acc)
                   cnt <= cnt - 3'd1;
               if (!tick)
                   div_cnt <= div_cnt - 4'd1;
               else if (pop || in_hb)
                   div_cnt <= cfg_div;
               if (tick) begin
                   if (in_hb) begin
                       hb_cnt <= hb_cnt - 4'd1;
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end else if (pop) begin
                       px_q <= head_pix;
                       px_vld <= 1'b1;
                       rd_ptr <= rd_ptr + 2'd1;
                       sig_run <= crc8_step(sig_run, head_pix);
                       if (col_out == LINE_LAST) begin
                           col_out <= 5'd0;
                           hb_cnt <= cfg_hblank;
                           px_eol <= 1'b1;
                       end else begin
                           col_out <= col_out + 5'd1;
                           px_eol <= 1'b0;
                       end
                   end else begin
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end
               end
               if (drained) begin
                   eof_pend <= 1'b0;
                   sig_last <= sig_run;
                   sig_run <= 8'h00;
               end
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire [7:0] o_scan_pix,
  output wire o_scan_vld,
  output wire o_scan_eol,
  output wire o_scan_hblank,
  output wire o_scan_ready,
  output wire o_drain_busy,
  output wire [7:0] o_scan_fill_col,
  output wire [7:0] o_frame_sig,
  output wire [7:0] o_scan_stall
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
  wire dr_ready, dr_drained, dr_eof_pend;
  wire dr_px_vld, dr_px_eol, dr_hblank;
  wire [2:0] dr_fill;
  wire [4:0] dr_col;
  wire [7:0] dr_px;
  wire [7:0] dr_sig;
  wire [7:0] dr_stall;
  wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
  wire px_push = (phase == RUN) && !abort_req && dr_ready;
  wire frame_end = px_push && last_col && last_row;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  tplan_px_drain u_drain (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .abort_req(abort_req),
      .frame_act(phase == RUN),
      .push(px_push),
      .push_eof(last_col && last_row),
      .push_pix(gen_pix),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .ready(dr_ready),
      .drained(dr_drained),
      .eof_pend_o(dr_eof_pend),
      .fill_o(dr_fill),
      .col_o(dr_col),
      .px_o(dr_px),
      .px_vld_o(dr_px_vld),
      .px_eol_o(dr_px_eol),
      .hblank_o(dr_hblank),
      .sig_o(dr_sig),
      .stall_o(dr_stall)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                      if (dr_ready) begin
                       pix_row <= gen_pix;
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                      end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !dr_eof_pend) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
              if (dr_drained)
                  done <= 1'b1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_scan_pix = dr_px;
  assign o_scan_vld = dr_px_vld;
  assign o_scan_eol = dr_px_eol;
  assign o_scan_hblank = dr_hblank;
  assign o_scan_ready = dr_ready;
  assign o_drain_busy = dr_eof_pend;
  assign o_scan_fill_col = {dr_fill, dr_col};
  assign o_frame_sig = dr_sig;
  assign o_scan_stall = dr_stall;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module modexp_sdr (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] in_base,
    input  wire [7:0] in_exp,
    output wire [7:0] o_result,
    output wire       o_busy
);
    localparam [7:0] MOD = 8'd251;

    reg [7:0] base_r = 8'd0;
    reg [7:0] result = 8'd1;
    reg [7:0] exp_sr = 8'd0;
    reg [7:0] cnt    = 8'd0;
    reg       busy   = 1'b0;

    // square-and-multiply datapath (MSB first)
    wire [15:0] sq_full  = {8'd0, result} * {8'd0, result};
    wire [15:0] sq_mod   = sq_full % {8'd0, MOD};
    wire [7:0]  sq       = sq_mod[7:0];
    wire [15:0] mul_full = {8'd0, sq} * {8'd0, base_r};
    wire [15:0] mul_mod  = mul_full % {8'd0, MOD};
    wire [7:0]  mul      = mul_mod[7:0];
    wire [7:0]  next_res = exp_sr[7] ? mul : sq;

    wire [15:0] base_mod = {8'd0, in_base} % {8'd0, MOD};

    // bits of the exponent register already consumed must be zero
    wire [7:0] exp_tail = exp_sr << cnt;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (start) begin
                    base_r <= base_mod[7:0];
                    result <= 8'd1;
                    exp_sr <= in_exp;
                    cnt    <= 8'd8;
                    busy   <= 1'b1;
                end
            end else begin
                result <= next_res;
                exp_sr <= {exp_sr[6:0], 1'b0};
                cnt    <= cnt - 8'd1;
                if (cnt == 8'd1)
                    busy <= 1'b0;
            end
        end
    end

    assign o_result = result;
    assign o_busy   = busy;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside the busy window: on the final exponent bit, only the MSB may remain
    always @(posedge clk)
        if (pv && $past(busy) && ($past(cnt) == 8'd1))
            assert (($past(exp_sr) & 8'h7F) == 8'h00);
endmodule

module awesome_frame_sync (
    input wire clk,
    input wire rst,
    input wire en,
    input wire hdr_ok,
    input wire win_clr,
    output reg [1:0] state
);
    localparam [1:0] HUNT = 2'd0, PRESYNC = 2'd1, SYNC = 2'd2;
    reg [31:0] good_cnt;
    reg [31:0] bad_cnt;
    reg [3:0]  bad_hist;
    reg        win;
    initial begin
        state = HUNT; good_cnt = 32'd0; bad_cnt = 32'd0; bad_hist = 4'd0; win = 1'b0;
    end

    wire q_evt = en && (state == PRESYNC) && hdr_ok && (good_cnt == 32'd2);

    always @(posedge clk) begin
        if (rst) begin
            state <= HUNT; good_cnt <= 32'd0; bad_cnt <= 32'd0; bad_hist <= 4'd0; win <= 1'b0;
        end else if (en) begin
            if (win_clr) win <= 1'b0;
            else if (q_evt) win <= 1'b1;
            case (state)
                HUNT: begin
                    if (hdr_ok) begin
                        state <= PRESYNC;
                        good_cnt <= 32'd1;
                    end
                end
                PRESYNC: begin
                    if (hdr_ok) begin
                        if (good_cnt == 32'd2) begin
                            state <= SYNC;
                            good_cnt <= 32'd0;
                            bad_cnt <= 32'd0;
                            bad_hist <= 4'd0;
                        end else begin
                            good_cnt <= good_cnt + 32'd1;
                        end
                    end else begin
                        state <= HUNT;
                        good_cnt <= 32'd0;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end
                end
                SYNC: begin
                    if (hdr_ok) begin
                        bad_cnt <= 32'd0;
                        bad_hist <= {bad_hist[2:0], 1'b0};
                    end else if (bad_hist[2:0] == 3'b111) begin
                        state <= HUNT;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end else begin
                        bad_cnt <= bad_cnt + 32'd1;
                        bad_hist <= {bad_hist[2:0], 1'b1};
                    end
                end
                default: begin
                    state <= HUNT;
                    good_cnt <= 32'd0;
                    bad_cnt <= 32'd0;
                    bad_hist <= 4'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && state == 2'd2)
            assert (bad_cnt <= 32'd3);
endmodule

module json_key_fuzzy_match (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] key_in,
    input wire [7:0] query,
    input wire ld_tol,
    input wire [3:0] tol_in,
    input wire q_open,
    input wire q_close,
    output reg near,
    output reg far,
    output reg win
);
    reg [3:0] tol;
    reg pv;
    initial tol = 4'd0;
    initial near = 1'b0;
    initial far = 1'b1;
    initial win = 1'b0;
    initial pv = 1'b0;

    wire [7:0] diff = key_in ^ query;
    wire [3:0] dist = {3'd0, diff[0]} + {3'd0, diff[1]} + {3'd0, diff[2]} + {3'd0, diff[3]}
                    + {3'd0, diff[4]} + {3'd0, diff[5]} + {3'd0, diff[6]} + {3'd0, diff[7]};
    wire near_nxt = (dist <= tol);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            tol  <= 4'd0;
            near <= 1'b0;
            far  <= 1'b1;
            win  <= 1'b0;
        end else if (en) begin
            if (ld_tol) tol <= tol_in;
            near <= near_nxt;
            far  <= far ^ (near ^ near_nxt);
            win  <= q_open ? 1'b1 : (q_close ? 1'b0 : win);
        end
    end

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(near) && $past(far)));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, en_cyc[2:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module prio_skid (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_valid,
    input  wire [7:0] i_req,
    input  wire       o_ready,   // downstream ready
    output wire       i_ready,
    output wire       o_valid,
    output wire [2:0] o_idx,
    output wire       o_hit
);
    // ---------------- combinational priority encoder ----------------
    wire       enc_hit = |i_req;
    wire [2:0] enc_idx = i_req[7] ? 3'd7 :
                         i_req[6] ? 3'd6 :
                         i_req[5] ? 3'd5 :
                         i_req[4] ? 3'd4 :
                         i_req[3] ? 3'd3 :
                         i_req[2] ? 3'd2 :
                         i_req[1] ? 3'd1 : 3'd0;

    // ---------------- registered output stage ----------------
    reg       out_vld;
    reg [2:0] out_idx;
    reg       out_hit;
    reg [7:0] out_req;

    // ---------------- skid buffer (only meaningful while sk_full) ----
    reg       sk_full;
    reg [7:0] sk_req;
    reg [2:0] sk_idx;
    reg       sk_hit;

    // ---------------- stall history and sticky arm ----------------
    reg       stalled;   // registered copy of the stall condition
    reg       armed;     // sticky: set the first time an input word is offered

    initial begin
        out_vld = 1'b0; out_idx = 3'd0; out_hit = 1'b0; out_req = 8'h00;
        sk_full = 1'b0; sk_req  = 8'h00; sk_idx  = 3'd0; sk_hit  = 1'b0;
        stalled = 1'b0; armed   = 1'b0;
    end

    wire stall = out_vld && !o_ready;

    assign i_ready = !sk_full;
    assign o_valid = out_vld;
    assign o_idx   = out_idx;
    assign o_hit   = out_hit;

    always @(posedge clk) begin
        if (i_ce) begin
            armed   <= armed | i_valid;
            stalled <= stall;

            if (!stall) begin
                if (sk_full) begin
                    out_vld <= 1'b1;
                    out_idx <= sk_idx;
                    out_hit <= sk_hit;
                    out_req <= sk_req;
                    sk_full <= 1'b0;
                end else begin
                    out_vld <= i_valid;
                    out_idx <= enc_idx;
                    out_hit <= enc_hit;
                    out_req <= i_req;
                end
            end else begin
                // output stage blocked: park the incoming word in the skid
                if (i_valid && !sk_full) begin
                    sk_full <= 1'b1;
                    sk_req  <= i_req;
                    sk_idx  <= enc_idx;
                    sk_hit  <= enc_hit;
                end
            end
        end
    end

    // ---------------- property ----------------
    // Once an input word has ever been offered (armed), whenever the stage has
    // recorded a stall the buffered encoding must point at a set request bit.
    always @(posedge clk)
        if (armed && stalled)
            assert (!sk_hit || sk_req[sk_idx]);

endmodule

module lefdef_parse_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] tok,
    output reg  [2:0] state,
    output reg        hdr_seen,
    output reg  [3:0] macro_cnt
);
    // binary-encoded parser FSM; encodings 3'd6 and 3'd7 are never entered
    localparam S_IDLE   = 3'd0;  // waiting for a file
    localparam S_HEADER = 3'd1;  // VERSION / UNITS block
    localparam S_MACRO  = 3'd2;  // MACRO record
    localparam S_PINS   = 3'd3;  // PIN records of current macro
    localparam S_LAYER  = 3'd4;  // LAYER / PORT geometry
    localparam S_END    = 3'd5;  // END LIBRARY

    initial state     = S_IDLE;
    initial hdr_seen  = 1'b0;    // shadow register: header block was parsed
    initial macro_cnt = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            state     <= S_IDLE;
            hdr_seen  <= 1'b0;
            macro_cnt <= 4'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tok == 2'd1)
                        state <= S_HEADER;
                end
                S_HEADER: begin
                    if (tok == 2'd2) begin
                        hdr_seen <= 1'b1;   // header fully consumed
                        state    <= S_MACRO;
                    end
                end
                S_MACRO: begin
                    if (tok == 2'd3)
                        state <= S_PINS;
                    else if (tok == 2'd0)
                        state <= S_END;
                end
                S_PINS: begin
                    if (tok == 2'd3)
                        state <= S_LAYER;
                end
                S_LAYER: begin
                    if (tok == 2'd0) begin
                        state     <= S_MACRO;
                        macro_cnt <= macro_cnt + 4'd1;
                    end
                end
                S_END: begin
                    if (tok == 2'd1)
                        state <= S_IDLE;
                end
                default: begin
                    // illegal encoding recovery path (never taken in practice)
                    state <= S_PINS;
                end
            endcase
        end
    end

    // Precedence: pin records can only be seen after the header was parsed.
    always @(posedge clk)
        if (state == S_PINS)
            assert (hdr_seen);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
output wire       o_done,
output reg  [3:0] o_activity
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;
// the leg adder is retimed one stage: a freshly decoded leg parks in leg_q
// and merges into credit on the next enabled cycle, so the terminating leg
// has to flush both halves of the pending batch into steps at once
reg       leg_q;
initial   leg_q = 1'b0;
reg [2:0] ev_seen;
initial   ev_seen = 3'd0;
initial   o_activity = 4'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
leg_q     <= 1'b0;
ev_seen    <= 3'd0;
o_activity <= 4'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;
ev_seen    <= ev_seen | delta;
o_activity <= {1'b0, ev_seen} + {3'b0, (delta != 3'b000)};

            if (bad_ev) begin
                stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
               credit <= 2'd0;
leg_q  <= 1'b0;
            end else begin
credit <= credit + {1'b0, leg_q};
leg_q  <= 1'b0;
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
leg_q   <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
leg_q     <= 1'b1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
                      credit <= 2'd0;
leg_q  <= 1'b0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module tage_predictor #(
    parameter ENTRIES = 32,
    parameter IDXW    = 5,
    parameter TAGW    = 4,
    parameter CTRW    = 3,
    parameter BCTRW   = 2,
    parameter HISTW   = 16,
    parameter CW      = 16,
    parameter [15:0] TICK_MAX = 16'd15
)(
    input  wire          clk,
    input  wire          rst_n,
    input  wire          i_ce,
    input  wire [15:0]   i_pc,
    input  wire          i_taken,
    input  wire          i_arm,
    output wire          o_pred,
    output wire [CW-1:0] o_ucnt
);
    // base bimodal table and two tagged tables (history lengths 4 and 8)
    reg [ENTRIES*BCTRW-1:0] base_ctr;
    reg [ENTRIES*TAGW-1:0]  t1_tag;
    reg [ENTRIES*CTRW-1:0]  t1_ctr;
    reg [ENTRIES-1:0]       t1_u;
    reg [ENTRIES*TAGW-1:0]  t2_tag;
    reg [ENTRIES*CTRW-1:0]  t2_ctr;
    reg [ENTRIES-1:0]       t2_u;
    reg [HISTW-1:0]         ghist;
    reg [CW-1:0]            t1_ucnt;
    reg [CW-1:0]            tick;
    reg                     armed;

    initial begin
        base_ctr = 0; t1_tag = 0; t1_ctr = 0; t1_u = 0;
        t2_tag = 0; t2_ctr = 0; t2_u = 0; ghist = 0;
        t1_ucnt = 0; tick = 0; armed = 0;
    end

    // folded global history, geometric lengths 4 (T1) and 8 (T2)
    wire [IDXW-1:0] fold1 = {1'b0, ghist[3:0]};
    wire [IDXW-1:0] fold2 = ghist[4:0] ^ {2'b00, ghist[7:5]};
    wire [IDXW-1:0] idx0  = i_pc[IDXW-1:0];
    wire [IDXW-1:0] idx1  = i_pc[IDXW-1:0] ^ fold1;
    wire [IDXW-1:0] idx2  = i_pc[IDXW-1:0] ^ fold2;
    wire [TAGW-1:0] tag1  = i_pc[8:5] ^ ghist[3:0];
    wire [TAGW-1:0] tag2  = i_pc[8:5] ^ ghist[7:4] ^ {ghist[2:0], ghist[3]};

    wire [BCTRW-1:0] b_c   = base_ctr[idx0*BCTRW +: BCTRW];
    wire [TAGW-1:0]  t1_t  = t1_tag[idx1*TAGW +: TAGW];
    wire [CTRW-1:0]  t1_c  = t1_ctr[idx1*CTRW +: CTRW];
    wire             t1_uo = t1_u[idx1];
    wire [TAGW-1:0]  t2_t  = t2_tag[idx2*TAGW +: TAGW];
    wire [CTRW-1:0]  t2_c  = t2_ctr[idx2*CTRW +: CTRW];
    wire             t2_uo = t2_u[idx2];

    wire hit1 = (t1_t == tag1);
    wire hit2 = (t2_t == tag2);
    wire base_pred = b_c[BCTRW-1];
    wire t1_pred   = t1_c[CTRW-1];
    wire t2_pred   = t2_c[CTRW-1];
    wire prov_t2 = hit2;
    wire prov_t1 = !hit2 && hit1;
    wire prov_b  = !hit2 && !hit1;
    wire alt_pred = prov_t2 ? (hit1 ? t1_pred : base_pred) : base_pred;
    wire pred     = prov_t2 ? t2_pred : (prov_t1 ? t1_pred : base_pred);
    wire mispred  = (pred != i_taken);
    assign o_pred = pred;
    assign o_ucnt = t1_ucnt;

    // saturating counter next values
    wire [BCTRW-1:0] b_nxt  = i_taken ? ((b_c  == 2'd3) ? b_c  : b_c  + 2'd1) : ((b_c  == 2'd0) ? b_c  : b_c  - 2'd1);
    wire [CTRW-1:0]  t1_nxt = i_taken ? ((t1_c == 3'd7) ? t1_c : t1_c + 3'd1) : ((t1_c == 3'd0) ? t1_c : t1_c - 3'd1);
    wire [CTRW-1:0]  t2_nxt = i_taken ? ((t2_c == 3'd7) ? t2_c : t2_c + 3'd1) : ((t2_c == 3'd0) ? t2_c : t2_c - 3'd1);
    wire [CTRW-1:0]  weak   = i_taken ? 3'd4 : 3'd3;

    // usefulness and allocation
    wire u1_set      = prov_t1 && !mispred && (alt_pred != t1_pred);
    wire u1_dec      = prov_t1 &&  mispred && (alt_pred != t1_pred);
    wire alloc1_try  = prov_b && mispred;
    wire alloc1_ok   = alloc1_try && !t1_uo;
    wire alloc1_fail = alloc1_try &&  t1_uo;
    wire alloc2_try  = prov_t1 && mispred;
    wire alloc2_ok   = alloc2_try && !t2_uo;
    wire alloc2_fail = alloc2_try &&  t2_uo;
    wire u1_clr      = u1_dec || alloc1_fail;
    wire u2_set      = prov_t2 && !mispred && (alt_pred != t2_pred);
    wire u2_clr      = (prov_t2 && mispred && (alt_pred != t2_pred)) || alloc2_fail;
    wire any_fail    = alloc1_fail || alloc2_fail;
    wire u_reset     = any_fail && (tick == TICK_MAX);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            base_ctr <= 0; t1_tag <= 0; t1_ctr <= 0; t1_u <= 0;
            t2_tag <= 0; t2_ctr <= 0; t2_u <= 0; ghist <= 0;
            t1_ucnt <= 0; tick <= 0; armed <= 0;
        end else if (i_ce) begin
            ghist <= {ghist[HISTW-2:0], i_taken};
            if (prov_b)  base_ctr[idx0*BCTRW +: BCTRW] <= b_nxt;
            if (prov_t1) t1_ctr[idx1*CTRW +: CTRW] <= t1_nxt;
            if (alloc1_ok) begin
                t1_tag[idx1*TAGW +: TAGW] <= tag1;
                t1_ctr[idx1*CTRW +: CTRW] <= weak;
            end
            if (prov_t2) t2_ctr[idx2*CTRW +: CTRW] <= t2_nxt;
            if (alloc2_ok) begin
                t2_tag[idx2*TAGW +: TAGW] <= tag2;
                t2_ctr[idx2*CTRW +: CTRW] <= weak;
            end
            if (u_reset) begin
                t1_u <= 0; t2_u <= 0; t1_ucnt <= 0; tick <= 0;
            end else begin
                if (any_fail) tick <= tick + 16'd1;
                if (u1_set && !t1_uo) begin
                    t1_u[idx1] <= 1'b1;
                    t1_ucnt <= t1_ucnt + 16'd1;
                end else if (u1_clr && t1_uo) begin
                    t1_u[idx1] <= 1'b0;
                    t1_ucnt <= t1_ucnt - 16'd1;
                end
                if (u2_set) t2_u[idx2] <= 1'b1;
                else if (u2_clr) t2_u[idx2] <= 1'b0;
            end
            // scope window: opened by i_arm, closed by the periodic usefulness reset
            if (u_reset) armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;
        end
    end

    // absence: the useful-entry count never reads zero while some T1 entry is marked useful
    always @(posedge clk)
        if (armed)
            assert (!((t1_ucnt == 16'd0) && (t1_u != 32'd0)));
endmodule

module rst_seq24 (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_cfg_we,
    input  wire [127:0] i_cfg_order,
    input  wire [127:0] i_cfg_delay,
    input  wire         i_start,
    output wire [23:0]  o_dom_rst,
    output wire         o_busy
);
    localparam [4:0] LAST   = 5'd23;
    localparam [9:0] BUDGET = 10'd768;

    // programmed release order (24 x 5-bit domain ids) and per-step delays (24 x 5-bit)
    reg [127:0] cfg_order = 128'd0;
    reg [127:0] cfg_delay = 128'd0;
    reg [4:0]   step_idx  = 5'd0;
    reg [4:0]   dly_cnt   = 5'd0;
    reg [23:0]  dom_rst   = 24'hFFFFFF;
    reg         busy      = 1'b0;
    reg [9:0]   budget    = 10'd0;

    wire [4:0] cur_dom = cfg_order[step_idx*5 +: 5];
    wire [4:0] nxt_dly = cfg_delay[(step_idx + 5'd1)*5 +: 5];

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                if (i_cfg_we) begin
                    cfg_order <= i_cfg_order;
                    cfg_delay <= i_cfg_delay;
                end else if (i_start) begin
                    busy     <= 1'b1;
                    step_idx <= 5'd0;
                    dly_cnt  <= cfg_delay[4:0];
                    budget   <= BUDGET;
                    dom_rst  <= 24'hFFFFFF;
                end
            end else begin
                budget <= budget - 10'd1;
                if (dly_cnt != 5'd0) begin
                    dly_cnt <= dly_cnt - 5'd1;
                end else begin
                    if (cur_dom < 5'd24)
                        dom_rst[cur_dom] <= 1'b0;
                    if (step_idx == LAST) begin
                        busy     <= 1'b0;
                        step_idx <= 5'd0;
                    end else begin
                        step_idx <= step_idx + 5'd1;
                        dly_cnt  <= nxt_dly;
                    end
                end
            end
        end
    end

    assign o_dom_rst = dom_rst;
    assign o_busy    = busy;

    // after start accepted until sequence done: watchdog countdown never expires
    always @(*)
        assert (!busy || budget != 10'd0);
endmodule

module cnn_act_shreg (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [1:0] mode,
    input  wire [7:0] din,
    input  wire       flush,
    output wire       out_sat
);
    reg [7:0] win;
    reg [7:0] cnt;
    reg       loaded;
    reg       pristine;
    reg       pv;
    initial win = 8'h00;
    initial cnt = 8'h00;
    initial loaded = 1'b0;
    initial pristine = 1'b1;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            win      <= 8'h00;
            cnt      <= 8'h00;
            loaded   <= 1'b0;
            pristine <= 1'b1;
        end else if (en) begin
            if (flush) begin
                win      <= 8'h00;
                pristine <= 1'b0;
            end else begin
                case (mode)
                    2'b01: win <= {win[6:0], 1'b0};
                    2'b10: win <= {1'b0, win[7:1]};
                    2'b11: begin
                        win <= din;
                        if (cnt != 8'hFF) cnt <= cnt + 8'h01;
                        if (din != 8'h00) loaded <= 1'b1;
                    end
                    default: win <= win;
                endcase
            end
        end
    end

    assign out_sat = win[7];

    always @(posedge clk)
        if (pv && pristine && $rose(win[7]))
            assert (loaded);
endmodule

module warm_rst_quiesce #(
    parameter NPORTS = 4,
    parameter DW = 128,
    parameter TMO_CYCLES = 10,
    parameter TW = $clog2(TMO_CYCLES + 1)
) (
    input  wire              clk,
    // warm reset request stream (valid/ready), carries a 128-bit reset context word
    input  wire              wr_valid,
    output wire              wr_ready,
    input  wire [DW-1:0]     wr_ctx,
    // per-port drain/idle acknowledgments
    input  wire [NPORTS-1:0] ack_valid,
    output wire [NPORTS-1:0] ack_ready,
    // timeout timebase strobe
    input  wire              tick,
    // outgoing warm reset command (valid/ready)
    output wire              rst_valid,
    input  wire              rst_ready,
    output wire [DW-1:0]     rst_ctx,
    output wire              rst_forced,
    // block new bus transactions while quiescing / resetting
    output wire              blk_new
);
    localparam [TW-1:0] TMO_MAX = TMO_CYCLES;

    reg              qreq      = 1'b0;
    reg [NPORTS-1:0] ack       = {NPORTS{1'b0}};
    reg [TW-1:0]     tmo       = {TW{1'b0}};
    reg              rst_v     = 1'b0;
    reg              forced    = 1'b0;
    reg [DW-1:0]     ctx       = {DW{1'b0}};
    reg              qreq_seen = 1'b0;

    wire all_ack = &ack;

    assign wr_ready   = !qreq && !rst_v;
    assign ack_ready  = {NPORTS{qreq}};
    assign rst_valid  = rst_v;
    assign rst_ctx    = ctx;
    assign rst_forced = forced;
    assign blk_new    = qreq || rst_v;

    always @(posedge clk) begin
        if (wr_valid && wr_ready) begin
            qreq      <= 1'b1;
            ack       <= {NPORTS{1'b0}};
            tmo       <= {TW{1'b0}};
            ctx       <= wr_ctx;
            qreq_seen <= 1'b1;
        end else if (qreq) begin
            if (tick && (all_ack || tmo == TMO_MAX)) begin
                qreq   <= 1'b0;
                rst_v  <= 1'b1;
                forced <= !all_ack;
            end else begin
                ack <= ack | ack_valid;
                if (tick)
                    tmo <= tmo + 1'b1;
            end
        end else if (rst_v && rst_ready) begin
            rst_v     <= 1'b0;
            forced    <= 1'b0;
            qreq_seen <= 1'b0;
        end
    end

    // Precedence: a warm reset command is only presented after a quiesce request was accepted
    always @(posedge clk)
        if (rst_v)
            assert (qreq_seen);
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       o_ready,
    output wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
    // ---- pipeline stage registers ----
    reg       out_valid  = 1'b0;   // output register stage
    reg [7:0] out_data   = 8'h00;
    reg       skid_valid = 1'b0;   // stall flag
    reg [7:0] skid_data  = 8'h00;  // buffered word, meaningful only while skid_valid
    reg [1:0] occ        = 2'd0;   // independently maintained occupancy counter
    reg       pv         = 1'b0;   // past-valid

    assign i_ready = !skid_valid;
    assign o_valid = out_valid;
    assign o_data  = out_data;

    wire accept = ce && i_valid && !skid_valid;
    wire emit   = ce && out_valid && o_ready;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 2'd0;
        end else if (ce) begin
            if (emit) begin
                if (skid_valid) begin
                    // drain the buffered word into the output register
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else begin
                    out_valid <= accept;
                    if (accept) out_data <= i_data;
                end
            end else begin
                if (accept) begin
                    if (out_valid) begin
                        // downstream stalled: park the word in the skid buffer
                        skid_data  <= i_data;
                        skid_valid <= 1'b1;
                    end else begin
                        out_data  <= i_data;
                        out_valid <= 1'b1;
                    end
                end
            end
            occ <= occ + (accept ? 2'd1 : 2'd0) - (emit ? 2'd1 : 2'd0);
        end
    end

    // P: the moment the stall flag rises, the stage must be completely full
    always @(posedge clk)
        if (pv && $rose(skid_valid))
            assert (occ == 2'd2);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o,
output reg  [2:0]   out_tag,
output reg          out_last,
output reg          out_par,
output wire [1:0]   eq_lvl_o,
output wire [15:0]  eq_stall_o,
output wire         ln_busy_o,
output wire [2:0]   ra_lvl_o,
output reg  [2:0]   ra_hwm_o,
output reg  [7:0]   ra_lat_o,
output reg  [15:0]  ra_perr_o,
output reg  [15:0]  ra_blk_o,
output reg  [15:0]  ra_byp_o,
output reg  [15:0]  ra_fetch_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;
// egress retiming queue: decouples prefetch from the shared lane grant
reg [127:0] eq_data [0:1];
reg [3:0]   eq_tag  [0:1];
reg         eq_wp;
reg         eq_rp;
reg [1:0]   eq_used;
reg [15:0]  stall_cnt;
// lane output register: one beat parked until this source's grant slot
reg [127:0] ln_data;
reg [3:0]   ln_tag;
reg         ln_v;
// ROM read-ahead register file: fetches run ahead of prefetch acceptance;
// every slot keeps its own valid bit, write-time parity and fetch stamp
reg [127:0] ra_data [0:3];
reg [3:0]   ra_tag  [0:3];
reg [7:0]   ra_ts   [0:3];
reg [3:0]   ra_par;
reg [3:0]   ra_v;
reg [1:0]   ra_wp;
reg [1:0]   ra_rp;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
eq_data[0] = 128'h0;
eq_data[1] = 128'h0;
eq_tag[0]  = 4'd0;
eq_tag[1]  = 4'd0;
eq_wp      = 1'b0;
eq_rp      = 1'b0;
eq_used    = 2'd0;
stall_cnt  = 16'd0;
ln_data    = 128'h0;
ln_tag     = 4'd0;
ln_v       = 1'b0;
ra_data[0] = 128'h0;
ra_data[1] = 128'h0;
ra_data[2] = 128'h0;
ra_data[3] = 128'h0;
ra_tag[0]  = 4'd0;
ra_tag[1]  = 4'd0;
ra_tag[2]  = 4'd0;
ra_tag[3]  = 4'd0;
ra_ts[0]   = 8'd0;
ra_ts[1]   = 8'd0;
ra_ts[2]   = 8'd0;
ra_ts[3]   = 8'd0;
ra_par     = 4'd0;
ra_v       = 4'd0;
ra_wp      = 2'd0;
ra_rp      = 2'd0;
ra_hwm_o   = 3'd0;
ra_lat_o   = 8'd0;
ra_perr_o  = 16'd0;
ra_blk_o   = 16'd0;
ra_byp_o   = 16'd0;
ra_fetch_o = 16'd0;
out_tag    = 3'd0;
out_last   = 1'b0;
out_par    = 1'b0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       eq_full     = (eq_used == 2'd2);
   wire       eq_empty    = (eq_used == 2'd0);
wire       ln_pop      = win && ln_v && slot_gnt;
wire       ln_last     = (ln_tag == 4'd7);
wire       eq_pop      = win && !eq_empty && (!ln_v || ln_pop);
   wire       pf_pop      = win && !pf_empty && (!eq_full || eq_pop);
   wire       eq_push     = pf_pop;
// read-ahead control: slots are filled in order at ra_wp, drained at ra_rp
wire [2:0]   ra_lvl       = {2'b0, ra_v[0]} + {2'b0, ra_v[1]} + {2'b0, ra_v[2]} + {2'b0, ra_v[3]};
wire         ra_head_v    = ra_v[ra_rp];
wire         ra_slot_v    = ra_v[ra_wp];
wire         pf_room      = !pf_full || pf_pop;
wire         ra_pop       = win && ra_head_v && pf_room;
// empty buffer: the ROM word goes straight into prefetch, saving a cycle
wire         ra_byp       = win && (ra_lvl == 3'd0) && pf_room;
wire         ra_push      = win && !ra_byp && (!ra_slot_v || (ra_pop && (ra_wp == ra_rp)));
wire         rom_take     = ra_push || ra_byp;
wire         pf_push      = ra_pop || ra_byp;
wire [3:0]   ra_set       = ra_push ? (4'b0001 << ra_wp) : 4'b0000;
wire [3:0]   ra_clr       = ra_pop  ? (4'b0001 << ra_rp) : 4'b0000;
wire [3:0]   ra_v_nxt     = (ra_v & ~ra_clr) | ra_set;
wire [127:0] ra_head_data = ra_data[ra_rp];
wire [3:0]   ra_head_tag  = ra_tag[ra_rp];
wire [7:0]   ra_res       = beat_cnt[7:0] - ra_ts[ra_rp];
wire         ra_par_bad   = ra_par[ra_rp] ^ (^ra_head_data);
wire         rom_par      = ^rom_word;
wire [127:0] pf_in_data   = ra_byp ? rom_word : ra_head_data;
wire [3:0]   pf_in_tag    = ra_byp ? {1'b0, rd_ptr} : ra_head_tag;
wire         ra_blk       = win && ra_slot_v && !rom_take;
assign ra_lvl_o = ra_lvl;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire [3:0] eq_head_tag = eq_tag[eq_rp];
   wire       eq_last     = (eq_head_tag == 4'd7);
   wire       pf_stall    = win && !pf_empty && !pf_pop;
   assign eq_lvl_o   = eq_used;
   assign eq_stall_o = stall_cnt;
assign ln_busy_o  = ln_v;

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
eq_data[0] <= 128'h0;
eq_data[1] <= 128'h0;
eq_tag[0]  <= 4'd0;
eq_tag[1]  <= 4'd0;
eq_wp      <= 1'b0;
eq_rp      <= 1'b0;
eq_used    <= 2'd0;
stall_cnt  <= 16'd0;
ln_data    <= 128'h0;
ln_tag     <= 4'd0;
ln_v       <= 1'b0;
ra_data[0] <= 128'h0;
ra_data[1] <= 128'h0;
ra_data[2] <= 128'h0;
ra_data[3] <= 128'h0;
ra_tag[0]  <= 4'd0;
ra_tag[1]  <= 4'd0;
ra_tag[2]  <= 4'd0;
ra_tag[3]  <= 4'd0;
ra_ts[0]   <= 8'd0;
ra_ts[1]   <= 8'd0;
ra_ts[2]   <= 8'd0;
ra_ts[3]   <= 8'd0;
ra_par     <= 4'd0;
ra_v       <= 4'd0;
ra_wp      <= 2'd0;
ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
if (ln_pop && ln_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
if (pf_stall && !start && !stop)
    stall_cnt <= stall_cnt + 16'd1;
if (ra_blk && !start && !stop)
    ra_blk_o <= ra_blk_o + 16'd1;
if (ra_lvl > ra_hwm_o)
    ra_hwm_o <= ra_lvl;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
2'd2: stat_o <= {3'h0, eq_used, pf_used, wrap_cnt, 12'h0, ra_lvl, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
               eq_wp   <= 1'b0;
               eq_rp   <= 1'b0;
               eq_used <= 2'd0;
ln_v    <= 1'b0;
ra_v    <= 4'd0;
ra_wp   <= 2'd0;
ra_rp   <= 2'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (rom_take) begin
                   rd_ptr     <= rd_ptr + 3'd1;
                   ra_fetch_o <= ra_fetch_o + 16'd1;
               end
               if (ra_byp)
                   ra_byp_o <= ra_byp_o + 16'd1;
               if (ra_push) begin
                   ra_data[ra_wp] <= rom_word;
                   ra_tag[ra_wp]  <= {1'b0, rd_ptr};
                   ra_ts[ra_wp]   <= beat_cnt[7:0];
                   ra_par[ra_wp]  <= rom_par;
                   ra_wp          <= ra_wp + 2'd1;
               end
               if (ra_pop) begin
                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
               end
               ra_v <= ra_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
        cnt <= cnt + 4'd1;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ~gnt_q & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool > {3'b0, q_any});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
    gnt_q <= gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

module arb_book_rebuild (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_pkt_valid,
    input  wire [1:0]  i_pkt_type,
    input  wire [63:0] i_pkt_data,
    output wire [63:0] o_code,
    output wire        o_done
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [1:0]  phase;
    reg        hist_arm;
    reg        hist_start;
    reg [63:0] code;
    reg [63:0] seq_mem [0:31];

    initial phase    = P_IDLE;
    initial hist_arm = 1'b0;
    initial hist_start = 1'b0;
    initial code     = 64'd0;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            seq_mem[i] = {63'd0, i[1:0]};
    end

    // next-state lookup: price-delta codes of an order-book rebuild walk
    function [63:0] nxt;
        input [63:0] cur;
        begin
            case (cur[1:0])
                2'd0: nxt = 64'h1;
                2'd1: nxt = 64'h2;
                2'd2: nxt = 64'h3;
                default: nxt = 64'h0;
            endcase
        end
    endfunction

    wire [63:0] nxt_code = nxt(code);

    always @(posedge clk) begin
        if (rst) begin
            phase    <= P_IDLE;
            hist_arm <= 1'b0;
            hist_start <= 1'b0;
            code     <= 64'd0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_pkt_valid && i_pkt_type == 2'd1) begin
                        phase    <= P_ARM;
                        hist_arm <= 1'b1;
                        code     <= i_pkt_data;
                    end
                end
                P_ARM: begin
                    if (i_pkt_valid && i_pkt_type == 2'd2) begin
                        phase      <= P_RUN;
                        hist_start <= 1'b1;
                    end
                end
                P_RUN: begin
                    if (i_pkt_valid) begin
                        if (i_pkt_type == 2'd3) begin
                            phase <= P_DONE;
                        end else begin
                            code <= nxt_code;
                        end
                    end
                end
                default: begin
                    if (i_pkt_valid && i_pkt_type == 2'd0) begin
                        phase    <= P_IDLE;
                        hist_arm <= 1'b0;
                        hist_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assign o_code = code;
    assign o_done = (phase == P_DONE);

    // chain precedence: finish is never observed without arm and start
    always @(posedge clk)
        assert (phase != P_DONE || (hist_arm && hist_start));
endmodule

module thermo_window (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire warmer,
    output reg heat
);
    localparam [3:0] T_LOW  = 4'd4;
    localparam [3:0] T_HIGH = 4'd12;

    reg [3:0] temp;
    reg [1:0] win, heat_cycles, cool_cycles;

    initial begin
        temp = 4'd8; heat = 1'b0;
        win = 2'd0; heat_cycles = 2'd0; cool_cycles = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            temp <= 4'd8; heat <= 1'b0;
            win <= 2'd0; heat_cycles <= 2'd0; cool_cycles <= 2'd0;
        end else if (ce) begin
            win <= win + 2'd1;
            if (heat) heat_cycles <= heat_cycles + 2'd1;
            else      cool_cycles <= cool_cycles + 2'd1;
            temp <= warmer ? ((temp == 4'd15) ? temp : temp + 4'd1)
                           : ((temp == 4'd0)  ? temp : temp - 4'd1);
            if      (temp <= T_LOW)  heat <= 1'b1;
            else if (temp >= T_HIGH) heat <= 1'b0;
        end
    end

    always @(posedge clk)
        if (cool_cycles == 2'd0)
            assert (heat_cycles == win);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
            wbin  <= wbin + (i_incr ? 4'd1 : 4'd0);

            // synchronizer chain
            sync1 <= wgray;
            sync2 <= sync1;

            // shadow binary chain, structurally parallel to the chain above
            b1    <= wbin;
            b2    <= b1;

            // monitor
            last_delta <= delta;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
            if (sync1 != sync2)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module lssd_scan_dump (
    input  wire        clk,
    input  wire        en,
    input  wire        scan_req,
    input  wire        tdi,
    input  wire        cap,
    input  wire [63:0] sys_d0,
    input  wire [63:0] sys_d1,
    output wire        tdo,
    output wire        busy_o
);
    reg [63:0] l1_0 = 64'd0;
    reg [63:0] l1_1 = 64'd0;
    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

    assign tdo    = l2_1[63];
    assign busy_o = busy;

    always @(posedge clk) begin
        if (en) begin
            if (!busy) begin
                if (scan_req) begin
                    busy <= 1'b1;
                    cd   <= 8'd128;
                    sc   <= 7'd0;
                    ph   <= 1'b0;
                end else begin
                    if (cap) begin
                        l1_0 <= sys_d0;
                        l1_1 <= sys_d1;
                    end
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                end
            end else begin
                cd <= cd - 8'd1;
                if (!ph) begin
                    l1_0 <= {l2_0[62:0], tdi};
                    l1_1 <= {l2_1[62:0], l2_0[63]};
                    ph   <= 1'b1;
                end else begin
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                    ph   <= 1'b0;
                    if (sc == 7'd63) begin
                        busy <= 1'b0;
                        sc   <= 7'd0;
                    end else begin
                        sc   <= sc + 7'd1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (busy)
            assert (cd != 8'd0);
        else
            assert (cd == 8'd0);
    end
endmodule

module tcu_useq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [2:0]  op,
    input  wire        cond,
    input  wire [1:0]  sel,
    input  wire        tw_en,
    input  wire [1:0]  tw_idx,
    input  wire [15:0] tw_data,
    output wire [15:0] upc_o,
    output wire        ret_valid_o
);
    localparam [2:0] OP_INC  = 3'd0;
    localparam [2:0] OP_JMP  = 3'd1;
    localparam [2:0] OP_BR   = 3'd2;
    localparam [2:0] OP_CALL = 3'd3;
    localparam [2:0] OP_RET  = 3'd4;

    reg [15:0] upc;
    reg [15:0] jt0, jt1, jt2, jt3;
    reg [15:0] ret_reg;
    reg        ret_valid;
    reg [15:0] shadow_ret;
    reg        pv;

    initial upc = 16'h0000;
    initial jt0 = 16'h0000;
    initial jt1 = 16'h0000;
    initial jt2 = 16'h0000;
    initial jt3 = 16'h0000;
    initial ret_reg = 16'h0000;
    initial ret_valid = 1'b0;
    initial shadow_ret = 16'h0000;
    initial pv = 1'b0;

    reg [15:0] tgt;
    always @(*) begin
        case (sel)
            2'd0: tgt = jt0;
            2'd1: tgt = jt1;
            2'd2: tgt = jt2;
            default: tgt = jt3;
        endcase
    end

    wire [15:0] upc_inc = upc + 16'h0001;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            upc        <= 16'h0000;
            jt0        <= 16'h0000;
            jt1        <= 16'h0000;
            jt2        <= 16'h0000;
            jt3        <= 16'h0000;
            ret_reg    <= 16'h0000;
            ret_valid  <= 1'b0;
            shadow_ret <= 16'h0000;
        end else if (en) begin
            if (tw_en) begin
                case (tw_idx)
                    2'd0: jt0 <= tw_data;
                    2'd1: jt1 <= tw_data;
                    2'd2: jt2 <= tw_data;
                    default: jt3 <= tw_data;
                endcase
            end
            case (op)
                OP_INC:  upc <= upc_inc;
                OP_JMP:  upc <= tgt;
                OP_BR:   upc <= cond ? tgt : upc_inc;
                OP_CALL: begin
                    ret_reg    <= upc_inc;
                    shadow_ret <= upc_inc;
                    ret_valid  <= 1'b1;
                    upc        <= tgt;
                end
                OP_RET: begin
                    if (ret_valid) begin
                        upc       <= ret_reg;
                        ret_valid <= 1'b0;
                    end else begin
                        upc <= upc_inc;
                    end
                end
                default: upc <= upc_inc;
            endcase
        end
    end

    assign upc_o = upc;
    assign ret_valid_o = ret_valid;

    always @(posedge clk)
        if (pv && $past(en) && !$past(rst) && ($past(op) == 3'd4) && $past(ret_valid))
            assert (upc == $past(shadow_ret));
endmodule

module polyphase_resampler (
    input  wire         clk,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] in_data,
    output reg  [127:0] out_data,
    output reg          out_valid
);
    localparam [1:0] S_IDLE   = 2'd0;
    localparam [1:0] S_PRIMED = 2'd1;
    localparam [1:0] S_RUN    = 2'd2;
    localparam [1:0] S_DONE   = 2'd3;

    reg [127:0] hist [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) hist[i] = 128'd0;
    end

    reg [4:0] fill        = 5'd0;
    reg [4:0] phase       = 5'd0;
    reg [3:0] out_cnt     = 4'd0;
    reg [1:0] st          = S_IDLE;
    reg       q_seen      = 1'b0;
    reg       armed_seen  = 1'b0;
    reg       start_seen  = 1'b0;
    reg       finish_seen = 1'b0;
    initial out_data  = 128'd0;
    initial out_valid = 1'b0;

    wire [5:0] phase_sum = {1'b0, phase} + 6'd7;
    wire       wrap      = (phase_sum >= 6'd24);
    wire [4:0] phase_nxt = wrap ? (phase_sum[4:0] - 5'd24) : phase_sum[4:0];
    wire [4:0] tap       = 5'd23 - phase;

    always @(posedge clk) begin
        if (ce) begin
            if (in_valid) begin
                for (i = 23; i > 0; i = i - 1) hist[i] <= hist[i-1];
                hist[0] <= in_data;
                if (fill != 5'd24) fill <= fill + 5'd1;
                q_seen <= 1'b1;
            end
            phase     <= phase_nxt;
            out_valid <= 1'b0;
            case (st)
                S_IDLE: begin
                    if (fill == 5'd24) begin
                        st         <= S_PRIMED;
                        armed_seen <= 1'b1;
                    end
                end
                S_PRIMED: begin
                    if (wrap) begin
                        st         <= S_RUN;
                        start_seen <= 1'b1;
                        out_cnt    <= 4'd0;
                    end
                end
                S_RUN: begin
                    out_data  <= hist[phase] + hist[tap];
                    out_valid <= 1'b1;
                    if (out_cnt == 4'd11) begin
                        st          <= S_DONE;
                        finish_seen <= 1'b1;
                        out_cnt     <= 4'd0;
                    end else begin
                        out_cnt <= out_cnt + 4'd1;
                    end
                end
                S_DONE: begin
                    if (wrap) st <= S_RUN;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (q_seen && finish_seen)
            assert (start_seen && armed_seen);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
                    remain  <= LEN - 64'd1;
                    held    <= 64'd1;
                end
            end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module ntt_butterfly #(
    parameter N = 64,
    parameter LOGN = 6,
    parameter [31:0] Q = 32'd3329
)(
    input  wire        clk,
    // twiddle factor channel (arm)
    input  wire        tw_valid,
    output wire        tw_ready,
    input  wire [31:0] tw_in,
    // coefficient operand channel (start)
    input  wire        in_valid,
    output wire        in_ready,
    input  wire [31:0] in_a,
    input  wire [31:0] in_b,
    // butterfly result channel (finish)
    output wire        out_valid,
    input  wire        out_ready,
    output wire [31:0] out_a,
    output wire [31:0] out_b,
    output wire [31:0] o_stage,
    output wire [31:0] o_idx
);
    localparam [31:0] HALF = N / 2;
    localparam [23:0] Q24  = Q;
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_DONE  = 2'd2;

    reg [1:0]  phase   = P_IDLE;
    reg [31:0] tw      = 32'd0;
    reg [31:0] res_a   = 32'd0;
    reg [31:0] res_b   = 32'd0;
    reg [31:0] stage   = 32'd0;
    reg [31:0] idx     = 32'd0;
    reg [31:0] grp_cnt = 32'd0;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        before_r   = 1'b1;

    assign tw_ready  = (phase == P_IDLE);
    assign in_ready  = (phase == P_ARMED);
    assign out_valid = (phase == P_DONE);
    assign out_a     = res_a;
    assign out_b     = res_b;
    assign o_stage   = stage;
    assign o_idx     = idx;

    wire tw_fire  = tw_valid && tw_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    wire [31:0] glen          = HALF >> stage;
    wire        last_in_stage = (idx == HALF - 32'd1);
    wire        last_stage    = (stage == LOGN - 1);
    wire        last_in_group = (grp_cnt + 32'd1 == glen);

    // Cooley-Tukey butterfly: (a + w*b, a - w*b) mod Q
    wire [23:0] prod = tw[11:0] * in_b[11:0];
    wire [23:0] t24  = prod % Q24;
    wire [31:0] t    = {8'd0, t24};
    wire [31:0] sum  = in_a + t;
    wire [31:0] bf_a = (sum >= Q) ? (sum - Q) : sum;
    wire [31:0] dif  = in_a + Q - t;
    wire [31:0] bf_b = (dif >= Q) ? (dif - Q) : dif;

    always @(posedge clk) begin
        if (tw_fire) begin
            tw       <= tw_in;
            phase    <= P_ARMED;
            arm_seen <= 1'b1;
        end
        if (in_fire) begin
            res_a      <= bf_a;
            res_b      <= bf_b;
            phase      <= P_DONE;
            start_seen <= 1'b1;
        end
        if (out_fire) begin
            if (last_in_stage) begin
                idx     <= 32'd0;
                grp_cnt <= 32'd0;
                phase   <= P_IDLE;
                if (last_stage) begin
                    stage    <= 32'd0;
                    before_r <= 1'b0;
                end else begin
                    stage <= stage + 32'd1;
                end
            end else begin
                idx <= idx + 32'd1;
                if (last_in_group) begin
                    grp_cnt <= 32'd0;
                    phase   <= P_IDLE;
                end else begin
                    grp_cnt <= grp_cnt + 32'd1;
                    phase   <= P_ARMED;
                end
            end
        end
    end

    // Chain precedence, before the first transform completes:
    // a result can only be offered after a twiddle was armed and operands started.
    always @(posedge clk) assert (!(before_r && out_valid) || (arm_seen && start_seen));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
// first stage is split in two: the low pair re-samples on every enabled
// cycle, the upper pair only while armed, because the upper gray bits can
// only move on the cycle after the low half of the counter wraps, so the
// wide upper flops need not toggle their sample the rest of the time
reg [1:0] s1_lo;
reg [1:0] s1_hi;
reg       hi_arm;   // upper-pair re-sample window
wire [3:0] s1 = {s1_hi, s1_lo};
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
s1_lo  = 2'd0;
s1_hi  = 2'd0;
hi_arm = 1'b0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
s1_lo <= g[1:0];
if (hi_arm)
    s1_hi <= g[3:2];
hi_arm <= lo_tc;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
    assign o_upstream_ready = !hold;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // tail-slot occupancy is tracked in its own counter so each occupancy
    // bit sits next to the data register it describes; o_count is the sum.
    reg [1:0] tcnt;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial tcnt  = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            tcnt  <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            // per-slot occupancy update: a push fills the head counter first
            // and spills into the tail counter, a pop borrows from the tail
            // counter whenever the tail slot is loaded, so the head counter
            // only clears on the final drain.
            if (do_push && !do_pop) begin
                if (count == 2'd0) count <= 2'd1;
                else               tcnt  <= 2'd1;
            end else if (do_pop && !do_push) begin
                if (tcnt != 2'd0) tcnt  <= 2'd0;
                else              count <= 2'd0;
            end
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count + tcnt;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

module fetch_handshake (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,      // global enable: low => design idles
    input  wire       start,     // new cell fetch requested
    input  wire [7:0] cell_in,
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [7:0]  cell_q,
    output reg [3:0]  rows_done
);

    // four-phase handshake sequencer
    //   0 : idle          req=0 ack=0 busy=0
    //   1 : req asserted  req=1 ack=0 busy=1
    //   2 : ack asserted  req=1 ack=1 busy=1
    //   3 : req dropped   req=0 ack=1 busy=1
    reg [1:0] phase;

    initial begin
        phase     = 2'd0;
        req       = 1'b0;
        ack       = 1'b0;
        busy      = 1'b0;
        cell_q    = 8'd0;
        rows_done = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= 2'd0;
            req       <= 1'b0;
            ack       <= 1'b0;
            busy      <= 1'b0;
            cell_q    <= 8'd0;
            rows_done <= 4'd0;
        end else if (step) begin
            case (phase)
                2'd0: begin
                    // requester raises req and marks itself busy
                    if (start) begin
                        phase <= 2'd1;
                        req   <= 1'b1;
                        busy  <= 1'b1;
                    end
                end
                2'd1: begin
                    // responder acknowledges and presents the cell
                    phase  <= 2'd2;
                    ack    <= 1'b1;
                    cell_q <= cell_in;
                end
                2'd2: begin
                    // req may only drop after ack has risen
                    phase <= 2'd3;
                    req   <= 1'b0;
                end
                2'd3: begin
                    // responder retires the transaction; it releases ack
                    // only once it observes req deasserted
                    phase     <= 2'd0;
                    busy      <= 1'b0;
                    rows_done <= rows_done + 4'd1;
                    if (!req) ack <= 1'b0;
                end
            endcase
        end
    end

    // P: the busy flag covers every live handshake wire, in every state
    always @(posedge clk)
        if (req) assert (busy);

    always @(posedge clk)
        if (ack) assert (busy);

endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam [1:0] OV_DEPTH = 2'd2;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;
reg [127:0] ov_d0, ov_d1;
reg [127:0] ov_head;
reg [1:0] ov_tag;
reg ov_wp, ov_rp;
reg [1:0] ov_cnt;
reg [127:0] bq_in_data;
reg bq_in_tag;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;
initial ov_d0 = 128'h0;
initial ov_d1 = 128'h0;
initial ov_tag = 2'h0;
initial ov_wp = 1'b0;
initial ov_rp = 1'b0;
initial ov_cnt = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_space = !bq_full || bq_pop;
wire ov_empty = (ov_cnt == 2'd0);
wire ov_full = (ov_cnt >= OV_DEPTH);
wire ov_drain = en && !clr_cmd && !ov_empty && bq_space;
wire beat_direct = en && !clr_cmd && beat_valid && ov_empty && bq_space;
wire ov_fill = en && !clr_cmd && beat_valid && !beat_direct && (!ov_full || ov_drain);
wire beat_accept = beat_direct || ov_fill;
wire bq_push = ov_drain || beat_direct;
wire push_tag = (fsm == S_ARMED) && match0;
wire start_drop = en && !clr_cmd && push_tag && !beat_accept;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end
always @(*) begin
case (ov_rp)
1'b0: ov_head = ov_d0;
default: ov_head = ov_d1;
endcase
end
always @(*) begin
if (ov_empty) begin
bq_in_data = beat_data;
bq_in_tag = push_tag;
end else begin
bq_in_data = ov_head;
bq_in_tag = ov_tag[ov_rp];
end
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (start_drop && !started_seen) fsm_nxt = S_IDLE;
else if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_d0 <= 128'h0;
ov_d1 <= 128'h0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (beat_accept && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= bq_in_data;
2'd1: bq_d1 <= bq_in_data;
2'd2: bq_d2 <= bq_in_data;
default: bq_d3 <= bq_in_data;
endcase
bq_tag[bq_wp] <= bq_in_tag;
bq_wp <= bq_wp + 2'd1;
end
if (ov_drain) begin
ov_tag[ov_rp] <= 1'b0;
ov_rp <= ov_rp + 1'b1;
end
if (ov_fill) begin
case (ov_wp)
1'b0: ov_d0 <= beat_data;
default: ov_d1 <= beat_data;
endcase
ov_tag[ov_wp] <= push_tag;
ov_wp <= ov_wp + 1'b1;
end
case ({ov_fill, ov_drain})
2'b10: ov_cnt <= ov_cnt + 2'd1;
2'b01: ov_cnt <= ov_cnt - 2'd1;
default: ov_cnt <= ov_cnt;
endcase
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

// Instruction-fetch queue occupancy tracker with gray-coded pointers.
// Pointers are 4 bits (3 address bits + 1 wrap bit) over an 8-entry buffer.
// Each binary pointer carries a gray shadow used for the full/empty compare.
module ifq_gray_occupancy (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire        pop,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        full,
    output wire        empty
);
    // binary pointers
    reg [3:0] wbin    = 4'd0;
    reg [3:0] rbin    = 4'd0;
    // gray shadows of the binary pointers
    reg [3:0] wgray   = 4'd0;
    reg [3:0] rgray   = 4'd0;
    // occupancy and high-water mark
    reg [3:0] occ     = 4'd0;
    reg [3:0] hiwater = 4'd0;

    reg [31:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 32'd0;
    end

    wire [3:0] wbin_nxt  = wbin + 4'd1;
    wire [3:0] rbin_nxt  = rbin + 4'd1;
    wire [3:0] wgray_nxt = wbin_nxt ^ (wbin_nxt >> 1);
    wire [3:0] rgray_nxt = rbin_nxt ^ (rbin_nxt >> 1);

    // classic gray-pointer full / empty decode
    assign full  = (wgray == {~rgray[3:2], rgray[1:0]});
    assign empty = (wgray == rgray);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] occ_nxt = occ + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    assign dout = mem[rbin[2:0]];

    always @(posedge clk) begin
        if (rst) begin
            wbin    <= 4'd0;
            rbin    <= 4'd0;
            wgray   <= 4'd0;
            rgray   <= 4'd0;
            occ     <= 4'd0;
            hiwater <= 4'd0;
        end else begin
            if (do_push) begin
                wbin           <= wbin_nxt;
                wgray          <= wgray_nxt;
                mem[wbin[2:0]] <= din;
            end
            if (do_pop) begin
                rbin  <= rbin_nxt;
                rgray <= rgray_nxt;
            end
            occ <= occ_nxt;
            if (occ_nxt > hiwater)
                hiwater <= occ_nxt;
        end
    end

    // P (two parts): the queue never holds more than the 8 entries it has,
    // and the recorded peak occupancy never exceeds 8 either, even though the
    // 4-bit registers could represent up to 15.
    always @(posedge clk) assert (occ <= 4'd8);
    always @(posedge clk) assert (hiwater <= 4'd8);
endmodule

module zynq_pwr_dom (
    input  wire       clk,
    input  wire       en,
    input  wire       req_on,
    input  wire       req_off,
    input  wire [6:0] idx,
    output wire       root_ready,
    output wire       busy
);
    reg [127:0] dom_on;
    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

    wire do_on  = req_on && !req_off;
    wire do_off = req_off && !req_on && !pend;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (pend) begin
                prog <= prog + 8'd1;
                cd   <= cd - 8'd1;
                if (prog == 8'd19) begin
                    pend    <= 1'b0;
                    root_on <= 1'b1;
                end
            end
            if (do_on && !dom_on[idx]) begin
                dom_on[idx] <= 1'b1;
                refcnt      <= refcnt + 8'd1;
                if (refcnt == 8'd0 && !root_on && !pend) begin
                    pend <= 1'b1;
                    prog <= 8'd0;
                    cd   <= 8'd24;
                end
            end else if (do_off && dom_on[idx]) begin
                dom_on[idx] <= 1'b0;
                refcnt      <= refcnt - 8'd1;
                if (refcnt == 8'd1 && root_on) begin
                    root_on <= 1'b0;
                    first_n <= 1'b0;
                end
            end
        end
    end

    assign root_ready = root_on;
    assign busy       = pend;

    always @(posedge clk)
        if (pv && first_n && pend && $stable(pend))
            assert ($stable(cd == 8'd0) && cd != 8'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;
   reg [7:0] wbeat_d;
   reg       wbeat_v;

    initial pending = 3'd0;
    initial hold    = 8'h00;
   initial wbeat_v = 1'b0;
   initial wbeat_d = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
   // token out of the bucket.  A beat is first captured in the write-beat
   // stage and is retired into the copier on the following enabled cycle,
   // so the stage must be free before the queue may issue again.
   wire beat   = run && (pending != 3'd0) && (remaining != 4'd0) && !wbeat_v;
   wire commit = run && wbeat_v;

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
   wire load = tokens_hi && (pending == 3'd0) && !wbeat_v && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
           wbeat_v <= 1'b0;
           wbeat_d <= 8'h00;
       end else begin
           if (load) begin
            pending <= grant;
            hold    <= src_data;
           end else if (beat) begin
            pending <= pending - 3'd1;
           end
           // Write-beat pipeline stage: holds the in-flight beat until the
           // copier is enabled again.
           wbeat_v <= beat || (wbeat_v && !commit);
           if (beat) wbeat_d <= hold;
       end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
       .spend     (commit),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
       .ce        (commit),
       .rd_data   (wbeat_d),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module flash_prog_fsm (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] i_data,
    output reg  [7:0] o_data,
    output reg        o_rd,
    output reg        o_wr,
    output reg        busy
);
    // binary-encoded programmer FSM: 5 legal encodings out of 8
    localparam [2:0] S_IDLE  = 3'd0,
                     S_LOAD  = 3'd1,
                     S_SHIFT = 3'd2,
                     S_STORE = 3'd3,
                     S_FLUSH = 3'd4;

    reg [2:0] state;
    reg [7:0] latch;

    initial state  = S_IDLE;
    initial latch  = 8'h00;
    initial o_data = 8'h00;
    initial o_rd   = 1'b0;
    initial o_wr   = 1'b0;
    initial busy   = 1'b0;   // window register: set by start, cleared at FLUSH

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    o_rd <= start;
                    o_wr <= 1'b0;
                    if (start) begin
                        state <= S_LOAD;
                        busy  <= 1'b1;
                    end
                end
                S_LOAD: begin
                    latch <= i_data;
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    state <= S_SHIFT;
                end
                S_SHIFT: begin
                    latch <= {latch[6:0], latch[7]};
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b1;
                    state <= S_STORE;
                end
                S_STORE: begin
                    o_data <= latch;
                    o_rd   <= 1'b0;
                    o_wr   <= 1'b0;
                    state  <= S_FLUSH;
                end
                S_FLUSH: begin
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    busy  <= 1'b0;
                    state <= S_IDLE;
                end
                default: begin
                    // unreachable encodings 5/6/7: panic recovery drives both strobes
                    o_rd  <= 1'b1;
                    o_wr  <= 1'b1;
                    state <= S_IDLE;
                end
            endcase
        end
    end

    // Two assertions, both scoped to the open program window.
    always @(posedge clk) begin
        if (busy) assert (!(o_rd && o_wr));
        if (busy) assert (!o_wr || state == S_STORE);
    end
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

    always @(posedge clk) begin
        if (i_ce) begin
            o_retry <= retry;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
                v0 <= i_valid;
                occ <= occ + (i_valid ? 3'd1 : 3'd0) - (v1 ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

module bcd_divider #(
    parameter DIGITS = 16
) (
    input  wire                  clk,
    input  wire                  i_clr,
    input  wire                  i_ce,
    input  wire                  i_go,
    input  wire [4*DIGITS-1:0]   i_dividend,
    input  wire [4*DIGITS-1:0]   i_divisor,
    output wire [4*DIGITS-1:0]   o_quotient,
    output wire [4*DIGITS+3:0]   o_remainder,
    output wire                  o_done
);
    localparam W  = 4*DIGITS;
    localparam RW = W + 4;
    localparam PW = $clog2(DIGITS);

    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_TABLE = 2'd1;
    localparam [1:0] P_DIV   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    function [RW-1:0] bcd_add;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                s = {1'b0, a[4*i +: 4]} + {1'b0, b[4*i +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add[4*i +: 4] = s[3:0];
            end
        end
    endfunction

    function [RW-1:0] bcd_sub;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] d;
        reg br;
        begin
            br = 1'b0;
            bcd_sub = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                d = {1'b0, a[4*i +: 4]} - {1'b0, b[4*i +: 4]} - {4'd0, br};
                if (d[4]) begin d = d + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub[4*i +: 4] = d[3:0];
            end
        end
    endfunction

    reg [1:0]    phase      = P_IDLE;
    reg [3:0]    tbl_idx    = 4'd0;
    reg [PW-1:0] pos        = {PW{1'b0}};
    reg [W-1:0]  dvd        = {W{1'b0}};
    reg [W-1:0]  quo        = {W{1'b0}};
    reg [RW-1:0] rem        = {RW{1'b0}};
    reg [RW-1:0] acc        = {RW{1'b0}};
    reg [RW-1:0] mult [0:9];
    reg          seen_arm   = 1'b0;
    reg          seen_start = 1'b0;
    reg          done       = 1'b0;
    reg          win        = 1'b0;

    integer k;
    initial begin
        for (k = 0; k < 10; k = k + 1) mult[k] = {RW{1'b0}};
    end

    wire [RW-1:0] shifted = {rem[RW-5:0], dvd[pos*4 +: 4]};
    wire [RW-1:0] acc_sum = bcd_add(acc, mult[1]);

    reg [3:0]    qdig;
    reg [RW-1:0] qmul;
    integer j;
    always @(*) begin
        qdig = 4'd0;
        qmul = {RW{1'b0}};
        for (j = 1; j < 10; j = j + 1)
            if (shifted >= mult[j]) begin
                qdig = j;
                qmul = mult[j];
            end
    end

    wire [RW-1:0] rem_next = bcd_sub(shifted, qmul);

    always @(posedge clk) begin
        if (i_clr) begin
            phase      <= P_IDLE;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            done       <= 1'b0;
            win        <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE, P_DONE: begin
                    if (i_go) begin
                        dvd        <= i_dividend;
                        quo        <= {W{1'b0}};
                        rem        <= {RW{1'b0}};
                        mult[0]    <= {RW{1'b0}};
                        mult[1]    <= {4'd0, i_divisor};
                        acc        <= {4'd0, i_divisor};
                        tbl_idx    <= 4'd2;
                        phase      <= P_TABLE;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        done       <= 1'b0;
                        win        <= 1'b1;
                    end
                end
                P_TABLE: begin
                    for (k = 2; k < 10; k = k + 1)
                        if (tbl_idx == k) mult[k] <= acc_sum;
                    acc <= acc_sum;
                    if (tbl_idx == 4'd9) begin
                        phase      <= P_DIV;
                        seen_start <= 1'b1;
                        pos        <= DIGITS - 1;
                    end else begin
                        tbl_idx <= tbl_idx + 4'd1;
                    end
                end
                P_DIV: begin
                    rem <= rem_next;
                    quo <= {quo[W-5:0], qdig};
                    if (pos == {PW{1'b0}}) begin
                        phase <= P_DONE;
                        done  <= 1'b1;
                    end else begin
                        pos <= pos - 1'b1;
                    end
                end
                default: phase <= P_IDLE;
            endcase
        end
    end

    assign o_quotient  = quo;
    assign o_remainder = rem;
    assign o_done      = done;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(done))
            assert (seen_arm && seen_start);
endmodule

module round_disp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [34:0] din,
    input wire [1:0] mode_in,
    output reg [6:0] seg
);
    reg [31:0] trunc = 32'd0;
    reg [2:0]  grs = 3'b000;
    reg [1:0]  mode = 2'd0;
    reg [31:0] rounded = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    function inc_f;
        input [1:0] m;
        input [2:0] g;
        input lsb;
        begin
            case (m)
                2'd0: inc_f = g[2] & (g[1] | g[0] | lsb);
                2'd1: inc_f = 1'b0;
                2'd2: inc_f = g[2] | g[1] | g[0];
                default: inc_f = g[2];
            endcase
        end
    endfunction

    wire ld_inc = inc_f(mode_in, din[2:0], din[3]);
    wire rf_inc = inc_f(mode, grs, trunc[0]);

    always @(posedge clk) begin
        if (rst) begin
            trunc   <= 32'd0;
            grs     <= 3'b000;
            mode    <= 2'd0;
            rounded <= 32'd0;
            armed   <= 1'b0;
        end else if (en) begin
            if (load) begin
                trunc   <= din[34:3];
                grs     <= din[2:0];
                mode    <= mode_in;
                rounded <= din[34:3] + {31'd0, ld_inc};
                armed   <= 1'b1;
            end else begin
                rounded <= trunc + {31'd0, rf_inc};
            end
        end
    end

    always @(*) begin
        case (rounded[3:0])
            4'h0: seg = 7'b1111110;
            4'h1: seg = 7'b0110000;
            4'h2: seg = 7'b1101101;
            4'h3: seg = 7'b1111001;
            4'h4: seg = 7'b0110011;
            4'h5: seg = 7'b1011011;
            4'h6: seg = 7'b1011111;
            4'h7: seg = 7'b1110000;
            4'h8: seg = 7'b1111111;
            4'h9: seg = 7'b1111011;
            4'hA: seg = 7'b1110111;
            4'hB: seg = 7'b0011111;
            4'hC: seg = 7'b1001110;
            4'hD: seg = 7'b0111101;
            4'hE: seg = 7'b1001111;
            default: seg = 7'b1000111;
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && !$past(rst) && armed && $stable(trunc) && $stable(grs) && $stable(mode))
            assert ($stable(rounded));
endmodule

module kv_vault (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        wr_en,
    input  wire [2:0]  wr_slot,
    input  wire [63:0] wr_key,
    input  wire        perm_set,
    input  wire [2:0]  perm_slot,
    input  wire        lock_req,
    input  wire [2:0]  lock_slot,
    input  wire        use_req,
    input  wire [2:0]  use_slot,
    output reg  [63:0] cipher_key,
    output reg         use_gnt
);
    reg [511:0] key;
    reg [7:0]   perm;
    reg [7:0]   lock;
    reg [63:0]  use_cnt;
    reg         armed;

    initial key        = 512'd0;
    initial perm       = 8'd0;
    initial lock       = 8'd0;
    initial use_cnt    = 64'd0;
    initial armed      = 1'b0;
    initial cipher_key = 64'd0;
    initial use_gnt    = 1'b0;

    wire grant = use_req && perm[use_slot] && lock[use_slot];

    always @(posedge clk) begin
        if (!rst_n) begin
            key        <= 512'd0;
            perm       <= 8'd0;
            lock       <= 8'd0;
            use_cnt    <= 64'd0;
            armed      <= 1'b0;
            cipher_key <= 64'd0;
            use_gnt    <= 1'b0;
        end else if (en) begin
            if (wr_en && !lock[wr_slot])
                key[{wr_slot, 6'd0} +: 64] <= wr_key;
            if (perm_set && !lock[perm_slot])
                perm[perm_slot] <= 1'b1;
            if (lock_req) begin
                lock[lock_slot] <= 1'b1;
                if (lock_slot == 3'd0)
                    armed <= 1'b1;
            end
            use_gnt <= grant;
            if (grant) begin
                cipher_key <= key[{use_slot, 6'd0} +: 64];
                use_cnt    <= use_cnt + 64'd1;
            end else begin
                cipher_key <= 64'd0;
            end
        end
    end

    wire [63:0] key0 = key[63:0];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $past(armed) && $stable(use_cnt))
            assert ($stable(key0));
endmodule

module wallace_pipe_mul (
    input  wire          i_clk,
    input  wire          i_reset,
    input  wire          i_ce,
    input  wire          i_valid,
    input  wire [15:0]   i_a,
    input  wire [15:0]   i_b,
    input  wire          i_open,
    input  wire          i_close,
    output wire [31:0]   o_prod,
    output wire          o_valid,
    output wire          o_empty
);
    parameter W = 16;
    localparam PW = 2*W;

    function [PW-1:0] csa_s;
        input [PW-1:0] x, y, z;
        csa_s = x ^ y ^ z;
    endfunction

    function [PW-1:0] csa_c;
        input [PW-1:0] x, y, z;
        csa_c = ((x & y) | (x & z) | (y & z)) << 1;
    endfunction

    // partial products
    wire [PW-1:0] pp [0:W-1];
    genvar g;
    generate
        for (g = 0; g < W; g = g + 1) begin : g_pp
            assign pp[g] = i_a[g] ? ({{W{1'b0}}, i_b} << g) : {PW{1'b0}};
        end
    endgenerate

    // Wallace level 1: 16 -> 11
    wire [PW-1:0] l1 [0:10];
    generate
        for (g = 0; g < 5; g = g + 1) begin : g_l1
            assign l1[2*g]   = csa_s(pp[3*g], pp[3*g+1], pp[3*g+2]);
            assign l1[2*g+1] = csa_c(pp[3*g], pp[3*g+1], pp[3*g+2]);
        end
    endgenerate
    assign l1[10] = pp[15];

    // level 2: 11 -> 8
    wire [PW-1:0] l2 [0:7];
    generate
        for (g = 0; g < 3; g = g + 1) begin : g_l2
            assign l2[2*g]   = csa_s(l1[3*g], l1[3*g+1], l1[3*g+2]);
            assign l2[2*g+1] = csa_c(l1[3*g], l1[3*g+1], l1[3*g+2]);
        end
    endgenerate
    assign l2[6] = l1[9];
    assign l2[7] = l1[10];

    // level 3: 8 -> 6
    wire [PW-1:0] l3 [0:5];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l3
            assign l3[2*g]   = csa_s(l2[3*g], l2[3*g+1], l2[3*g+2]);
            assign l3[2*g+1] = csa_c(l2[3*g], l2[3*g+1], l2[3*g+2]);
        end
    endgenerate
    assign l3[4] = l2[6];
    assign l3[5] = l2[7];

    // level 4: 6 -> 4
    wire [PW-1:0] l4 [0:3];
    generate
        for (g = 0; g < 2; g = g + 1) begin : g_l4
            assign l4[2*g]   = csa_s(l3[3*g], l3[3*g+1], l3[3*g+2]);
            assign l4[2*g+1] = csa_c(l3[3*g], l3[3*g+1], l3[3*g+2]);
        end
    endgenerate

    // stage 1 pipeline registers (4 rows)
    reg [PW-1:0] r1_0, r1_1, r1_2, r1_3;
    reg          v1;
    initial begin r1_0 = 0; r1_1 = 0; r1_2 = 0; r1_3 = 0; v1 = 1'b0; end

    // level 5: 4 -> 3, level 6: 3 -> 2
    wire [PW-1:0] s5 = csa_s(r1_0, r1_1, r1_2);
    wire [PW-1:0] c5 = csa_c(r1_0, r1_1, r1_2);
    wire [PW-1:0] s6 = csa_s(s5, c5, r1_3);
    wire [PW-1:0] c6 = csa_c(s5, c5, r1_3);

    // stage 2 pipeline registers (carry-save pair)
    reg [PW-1:0] s2, c2;
    reg          v2;
    initial begin s2 = 0; c2 = 0; v2 = 1'b0; end

    // stage 3: final carry-propagate adder
    reg [PW-1:0] prod;
    reg          v3;
    initial begin prod = 0; v3 = 1'b0; end

    // occupancy counter and observation window
    reg [W-1:0] inflight;
    reg         win;
    initial begin inflight = {W{1'b0}}; win = 1'b0; end

    always @(posedge i_clk) begin
        if (i_reset) begin
            r1_0 <= 0; r1_1 <= 0; r1_2 <= 0; r1_3 <= 0;
            s2 <= 0; c2 <= 0; prod <= 0;
            v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= {W{1'b0}};
            win <= 1'b0;
        end else if (i_ce) begin
            r1_0 <= l4[0]; r1_1 <= l4[1]; r1_2 <= l4[2]; r1_3 <= l4[3];
            s2   <= s6;    c2   <= c6;
            prod <= s2 + c2;
            v1 <= i_valid;
            v2 <= v1;
            v3 <= v2;
            inflight <= inflight + {{(W-1){1'b0}}, i_valid} - {{(W-1){1'b0}}, v3};
            if (i_open)
                win <= 1'b1;
            else if (i_close)
                win <= 1'b0;
        end
    end

    wire empty = (inflight == {W{1'b0}});

    assign o_prod  = prod;
    assign o_valid = v3;
    assign o_empty = empty;

    // Absence, between open and close: empty flag and output-valid never together
    always @(*)
        assert (!win || !(empty && v3));
endmodule

module chacha_qr_lockstep (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire load,
    input wire [3:0] ld_idx,
    input wire [31:0] ld_word,
    input wire start,
    input wire abort,
    output wire o_mismatch,
    output wire [31:0] o_word0,
    output wire [31:0] o_rnd
);
    // 16 x 32-bit state words, flattened: word i at bits [i*32 +: 32]
    reg [511:0] st_a;
    reg [511:0] st_b;
    reg [31:0]  rnd;
    reg         win;

    initial begin
        st_a = 512'd0;
        st_b = 512'd0;
        rnd  = 32'd0;
        win  = 1'b0;
    end

    function [511:0] qr_step;
        input [511:0] s;
        input [2:0] sel;
        reg [3:0] ia, ib, ic, id;
        reg [31:0] a, b, c, d;
        reg [511:0] r;
        begin
            case (sel)
                3'd0: begin ia = 4'd0; ib = 4'd4; ic = 4'd8;  id = 4'd12; end
                3'd1: begin ia = 4'd1; ib = 4'd5; ic = 4'd9;  id = 4'd13; end
                3'd2: begin ia = 4'd2; ib = 4'd6; ic = 4'd10; id = 4'd14; end
                3'd3: begin ia = 4'd3; ib = 4'd7; ic = 4'd11; id = 4'd15; end
                3'd4: begin ia = 4'd0; ib = 4'd5; ic = 4'd10; id = 4'd15; end
                3'd5: begin ia = 4'd1; ib = 4'd6; ic = 4'd11; id = 4'd12; end
                3'd6: begin ia = 4'd2; ib = 4'd7; ic = 4'd8;  id = 4'd13; end
                default: begin ia = 4'd3; ib = 4'd4; ic = 4'd9; id = 4'd14; end
            endcase
            a = s[{ia, 5'b0} +: 32];
            b = s[{ib, 5'b0} +: 32];
            c = s[{ic, 5'b0} +: 32];
            d = s[{id, 5'b0} +: 32];
            a = a + b; d = d ^ a; d = {d[15:0], d[31:16]};
            c = c + d; b = b ^ c; b = {b[19:0], b[31:20]};
            a = a + b; d = d ^ a; d = {d[23:0], d[31:24]};
            c = c + d; b = b ^ c; b = {b[24:0], b[31:25]};
            r = s;
            r[{ia, 5'b0} +: 32] = a;
            r[{ib, 5'b0} +: 32] = b;
            r[{ic, 5'b0} +: 32] = c;
            r[{id, 5'b0} +: 32] = d;
            qr_step = r;
        end
    endfunction

    wire [511:0] nxt_a = qr_step(st_a, rnd[2:0]);
    wire [511:0] nxt_b = qr_step(st_b, rnd[2:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            st_a <= 512'd0;
            st_b <= 512'd0;
            rnd  <= 32'd0;
            win  <= 1'b0;
        end else if (en) begin
            if (load) begin
                st_a[{ld_idx, 5'b0} +: 32] <= ld_word;
                st_b[{ld_idx, 5'b0} +: 32] <= ld_word;
                rnd <= 32'd0;
            end else begin
                st_a <= nxt_a;
                st_b <= nxt_b;
                rnd  <= rnd + 32'd1;
            end
            if (abort)
                win <= 1'b0;
            else if (start)
                win <= 1'b1;
        end
    end

    assign o_mismatch = (st_a != st_b);
    assign o_word0    = st_a[31:0];
    assign o_rnd      = rnd;

    always @(*) assert (!win || (st_a[31:0] == st_b[31:0]));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] spent_total
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial spent_total = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            spent_total <= 4'd0;
        end else begin
            if (dec) spent_total <= spent_total + 4'd1;
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module lfsr_session_monitor (
    input  wire       clk,
    input  wire       ce,      // entropy-draw enable; low => all state frozen
    input  wire       start,   // Q: opens the sampling session window
    input  wire       stop,    // R: closes the sampling session window
    output reg  [7:0] lfsr,
    output reg        window,
    output reg        nz_seen,
    output reg  [2:0] count,
    output wire       done
);
    // ------------------------------------------------------------------
    // Maximal-length Fibonacci LFSR, x^8 + x^6 + x^5 + x^4 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    // ------------------------------------------------------------------
    initial lfsr    = 8'h01;
    initial window  = 1'b0;
    initial nz_seen = 1'b0;
    initial count   = 3'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    // a session is "done" once four draws have been consumed inside it
    assign done = window && (count == 3'd4);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (ce)
            lfsr <= {lfsr[6:0], fb};

    // window register: set by start, cleared by stop, may open/close repeatedly.
    // count counts draws inside the current window (saturates at 4).
    // nz_seen is the shadow register: records that a nonzero draw occurred.
    always @(posedge clk) begin
        if (start && !window) begin
            window  <= 1'b1;
            count   <= 3'd0;
            nz_seen <= 1'b0;
        end
        else if (stop && window) begin
            window  <= 1'b0;
        end
        else if (ce && window && (count != 3'd4)) begin
            count   <= count + 3'd1;
            nz_seen <= nz_seen | (lfsr != 8'h00);
        end
    end

    // Property: inside an open session, at the moment done rises, a nonzero
    // draw must already have been recorded earlier in that same session.
    always @(posedge clk)
        if (pv && window)
            assert (!$rose(done) || nz_seen);
endmodule

module mpop_fifo (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire [31:0] din,
    input wire [2:0] npop_req,
    input wire open,
    input wire close,
    output reg [31:0] dout0,
    output reg [31:0] dout1,
    output reg [31:0] dout2,
    output reg [31:0] dout3,
    output wire [2:0] npop_o,
    output wire [31:0] count_o
);
    reg [31:0] bank0 [0:3];
    reg [31:0] bank1 [0:3];
    reg [31:0] bank2 [0:3];
    reg [31:0] bank3 [0:3];
    integer k;
    initial begin
        for (k = 0; k < 4; k = k + 1) begin
            bank0[k] = 32'd0; bank1[k] = 32'd0; bank2[k] = 32'd0; bank3[k] = 32'd0;
        end
    end

    reg [4:0] wptr = 5'd0;
    reg [4:0] rptr = 5'd0;
    reg [31:0] count = 32'd0;
    reg win = 1'b0;
    reg push_ack = 1'b0;

    wire [4:0] occ = wptr - rptr;
    wire full = (occ >= 5'd16);
    wire do_push = push && !full;
    wire [2:0] req = (npop_req > 3'd4) ? 3'd4 : npop_req;
    wire [2:0] npop = ({2'b00, req} > occ) ? occ[2:0] : req;
    assign npop_o = npop;
    assign count_o = count;

    wire [3:0] i0 = rptr[3:0];
    wire [3:0] i1 = rptr[3:0] + 4'd1;
    wire [3:0] i2 = rptr[3:0] + 4'd2;
    wire [3:0] i3 = rptr[3:0] + 4'd3;

    always @(*) begin
        case (i0[1:0])
            2'd0: dout0 = bank0[i0[3:2]];
            2'd1: dout0 = bank1[i0[3:2]];
            2'd2: dout0 = bank2[i0[3:2]];
            default: dout0 = bank3[i0[3:2]];
        endcase
        case (i1[1:0])
            2'd0: dout1 = bank0[i1[3:2]];
            2'd1: dout1 = bank1[i1[3:2]];
            2'd2: dout1 = bank2[i1[3:2]];
            default: dout1 = bank3[i1[3:2]];
        endcase
        case (i2[1:0])
            2'd0: dout2 = bank0[i2[3:2]];
            2'd1: dout2 = bank1[i2[3:2]];
            2'd2: dout2 = bank2[i2[3:2]];
            default: dout2 = bank3[i2[3:2]];
        endcase
        case (i3[1:0])
            2'd0: dout3 = bank0[i3[3:2]];
            2'd1: dout3 = bank1[i3[3:2]];
            2'd2: dout3 = bank2[i3[3:2]];
            default: dout3 = bank3[i3[3:2]];
        endcase
    end

    always @(posedge clk) begin
        if (ce && do_push) begin
            case (wptr[1:0])
                2'd0: bank0[wptr[3:2]] <= din;
                2'd1: bank1[wptr[3:2]] <= din;
                2'd2: bank2[wptr[3:2]] <= din;
                default: bank3[wptr[3:2]] <= din;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            rptr <= 5'd0;
            count <= 32'd0;
            win <= 1'b0;
            push_ack <= 1'b0;
        end else if (ce) begin
            wptr <= wptr + {4'd0, do_push};
            rptr <= rptr + {2'd0, npop};
            count <= count + {31'd0, do_push} - {29'd0, npop};
            push_ack <= do_push;
            if (open) win <= 1'b1;
            else if (close) win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && $rose(push_ack))
            assert (count <= 32'd16);
endmodule

module axis_luma_compressor (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
);
    localparam [63:0] UNITY = 64'h0000_0001_0000_0000;
    localparam [63:0] SLEW_LEN = 64'd8;

    reg [63:0] env;
    reg [63:0] gain;
    reg [63:0] tgt;
    reg        pend;
    reg [63:0] cd;
    reg [63:0] step;
    reg [63:0] hist [0:7];
    reg        win;

    integer i;
    initial begin
        env  = 64'd0;
        gain = UNITY;
        tgt  = UNITY;
        pend = 1'b0;
        cd   = 64'd0;
        step = 64'd0;
        win  = 1'b0;
        for (i = 0; i < 8; i = i + 1) hist[i] = UNITY;
    end

    assign s_tready = en;
    wire acc = en && s_tvalid;

    wire [63:0] reduction = (env > thr) ? ((env - thr) >> ratio_sh) : 64'd0;
    wire [63:0] new_tgt   = (reduction >= gain) ? 64'd0 : (gain - reduction);
    wire [63:0] gain_next = (tgt < gain) ? (gain - ((gain - tgt) >> 3))
                                         : (gain + ((tgt - gain) >> 3));
    wire [63:0] env_next  = (s_luma > env) ? (env + ((s_luma - env) >> 2))
                                           : (env - ((env - s_luma) >> 5));

    always @(posedge clk) begin
        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
        end else if (en) begin
            if (acc)
                env <= env_next;
            if (!pend) begin
                if (acc && (env > thr)) begin
                    tgt  <= new_tgt;
                    pend <= 1'b1;
                    cd   <= SLEW_LEN;
                    step <= 64'd0;
                end
            end else begin
                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

    wire [127:0] prod = s_luma * gain;
    assign m_luma   = prod[95:32];
    assign m_tvalid = s_tvalid;
    assign m_tuser  = s_tuser;
    assign m_tlast  = s_tlast;
    assign o_gain   = gain;
    assign o_hist0  = hist[0];
    assign o_win    = win;

    always @(*) assert (!(win && pend) || cd != 64'd0);
endmodule

module fourphase_arb (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire start_a,
    input  wire start_b,
    input  wire clr_mon,
    output wire o_busy,
    output wire o_mon
);
    // Two four-phase req/ack channels sharing one resource.
    // Per channel the phase walks:
    //   idle : busy=0 req=0 ack=0   -- grant -> busy=1
    //   P1   : busy=1 req=0 ack=0   -- raise req
    //   P2   : busy=1 req=1 ack=0   -- raise ack
    //   P3   : busy=1 req=1 ack=1   -- drop req (req may not drop before ack)
    //   P4   : busy=1 req=0 ack=1   -- drop ack, release busy
    reg req_a, ack_a, busy_a;
    reg req_b, ack_b, busy_b;

    // window register: armed by the first completed handshake (Q),
    // closed only by clr_mon while the resource is free (R, may never arrive)
    reg mon;

    initial begin
        req_a  = 1'b0;
        ack_a  = 1'b0;
        busy_a = 1'b0;
        req_b  = 1'b0;
        ack_b  = 1'b0;
        busy_b = 1'b0;
        mon    = 1'b0;
    end

    // arbiter: a channel may only be granted when neither channel is busy,
    // channel A has priority
    wire grant_a = start_a && !busy_a && !busy_b;
    wire grant_b = start_b && !busy_b && !busy_a && !start_a;

    // a channel is finishing this cycle (ack about to fall, busy released)
    wire fin_a = busy_a && !req_a && ack_a;
    wire fin_b = busy_b && !req_b && ack_b;

    always @(posedge clk) begin
        if (rst) begin
            req_a  <= 1'b0;
            ack_a  <= 1'b0;
            busy_a <= 1'b0;
            req_b  <= 1'b0;
            ack_b  <= 1'b0;
            busy_b <= 1'b0;
            mon    <= 1'b0;
        end else if (ce) begin
            // ---- channel A phase walk ----
            if (!busy_a && !req_a && !ack_a) begin
                if (grant_a)
                    busy_a <= 1'b1;
            end else if (busy_a && !req_a && !ack_a) begin
                req_a <= 1'b1;
            end else if (busy_a && req_a && !ack_a) begin
                ack_a <= 1'b1;
            end else if (busy_a && req_a && ack_a) begin
                req_a <= 1'b0;
            end else if (busy_a && !req_a && ack_a) begin
                ack_a  <= 1'b0;
                busy_a <= 1'b0;
            end

            // ---- channel B phase walk ----
            if (!busy_b && !req_b && !ack_b) begin
                if (grant_b)
                    busy_b <= 1'b1;
            end else if (busy_b && !req_b && !ack_b) begin
                req_b <= 1'b1;
            end else if (busy_b && req_b && !ack_b) begin
                ack_b <= 1'b1;
            end else if (busy_b && req_b && ack_b) begin
                req_b <= 1'b0;
            end else if (busy_b && !req_b && ack_b) begin
                ack_b  <= 1'b0;
                busy_b <= 1'b0;
            end

            // ---- monitoring window ----
            if (fin_a || fin_b)
                mon <= 1'b1;
            else if (clr_mon && !busy_a && !busy_b)
                mon <= 1'b0;
        end
    end

    assign o_busy = busy_a || busy_b;
    assign o_mon  = mon;

    // P: once the monitoring window has opened, the two channels never both
    // drive a request, and never both drive an acknowledge.
    always @(posedge clk)
        if (mon)
            assert (!(req_a && req_b));

    always @(posedge clk)
        if (mon)
            assert (!(ack_a && ack_b));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
,
    output wire [W-1:0] in_cnt_o,
    output wire [W-1:0] out_cnt_o
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
    assign in_cnt_o = in_cnt;
    assign out_cnt_o = out_cnt;
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
,
    output wire [1:0] chain_o,
    output wire phase_o,
    output wire [31:0] rd_col_o,
    output wire [31:0] rd_row_o,
    output wire [31:0] wr_col_o,
    output wire [31:0] wr_row_o
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
    assign chain_o = chain;
    assign phase_o = phase;
    assign rd_col_o = rd_col;
    assign rd_row_o = rd_row;
    assign wr_col_o = wr_col;
    assign wr_row_o = wr_row;
endmodule

module rgb_ycc_tile_pipeline #(
    parameter INGRESS_DEPTH = 4,
    parameter BRIDGE_DEPTH = 4,
    parameter TILE_ROWS = 4,
    parameter TILE_COLS = 4
) (
    input wire clk,
    input wire rst,
    input wire cfg_we,
    input wire [3:0] cfg_addr,
    input wire [31:0] cfg_data,
    input wire i_valid,
    output wire i_ready,
    input wire [7:0] i_r, i_g, i_b,
    input wire i_first, i_last,
    output wire o_valid,
    input wire o_ready,
    output wire [23:0] o_data,
    output wire a_o_valid, a_o_ready,
    output wire [7:0] a_o_y, a_o_cb, a_o_cr,
    output wire a_o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] a_ingress_level,
    output wire [31:0] a_ingress_accepted,
    output wire [31:0] a_in_cnt, a_out_cnt,
    output wire [31:0] a_debug_status,
    output wire b_in_valid, b_in_ready,
    output wire [1:0] b_chain,
    output wire b_phase,
    output wire [31:0] b_rd_col, b_rd_row, b_wr_col, b_wr_row,
    output reg [$clog2(BRIDGE_DEPTH+1)-1:0] bridge_level,
    output reg [31:0] delivered_pixels,
    output wire [31:0] tile_held,
    output wire [31:0] pending_pixels,
    output reg pipeline_active,
    output wire busy
);
    localparam TILE_PIXELS = TILE_ROWS * TILE_COLS;
    localparam TOTAL_CAPACITY = INGRESS_DEPTH + 1 + BRIDGE_DEPTH + TILE_PIXELS;
    localparam BRIDGE_PTR_W = $clog2(BRIDGE_DEPTH);
    wire rst_n = !rst;
    reg [23:0] bridge_mem [0:BRIDGE_DEPTH-1];
    reg [BRIDGE_PTR_W-1:0] bridge_rd_ptr, bridge_wr_ptr;
    wire [23:0] b_in_data = bridge_mem[bridge_rd_ptr];
    wire bridge_push = a_o_valid && a_o_ready;
    wire bridge_pop = b_in_valid && b_in_ready;
    wire sink_fire = o_valid && o_ready;
    integer j;

    // A completed tile blocks its input until column-order draining finishes.
    assign b_in_valid = pipeline_active && (bridge_level != 0);
    assign a_o_ready = pipeline_active &&
                       ((bridge_level < BRIDGE_DEPTH) || bridge_pop);
    assign tile_held = b_phase
                     ? TILE_PIXELS - (b_rd_col * TILE_ROWS + b_rd_row)
                     : b_wr_row * TILE_COLS + b_wr_col;
    assign pending_pixels = a_ingress_accepted - delivered_pixels;
    assign busy = !pipeline_active || (a_ingress_level != 0) ||
                  a_o_valid || (bridge_level != 0) || (tile_held != 0);

    csc_rgb2ycc #(.W(32), .FRAC(16), .INGRESS_DEPTH(INGRESS_DEPTH)) color (
        .clk(clk), .rst(rst),
        .cfg_we(cfg_we), .cfg_addr(cfg_addr), .cfg_data(cfg_data),
        .i_valid(i_valid), .i_ready(i_ready),
        .i_r(i_r), .i_g(i_g), .i_b(i_b),
        .i_first(i_first), .i_last(i_last),
        .o_valid(a_o_valid), .o_ready(a_o_ready),
        .o_y(a_o_y), .o_cb(a_o_cb), .o_cr(a_o_cr), .o_last(a_o_last),
        .ingress_level(a_ingress_level), .ingress_accepted(a_ingress_accepted),
        .debug_status(a_debug_status), .in_cnt_o(a_in_cnt), .out_cnt_o(a_out_cnt)
    );
    transpose_buf #(
        .ROWS(TILE_ROWS), .COLS(TILE_COLS), .DEPTH(TILE_PIXELS), .DW(24)
    ) tile (
        .clk(clk), .rst_n(rst_n),
        .in_valid(b_in_valid), .in_ready(b_in_ready), .in_data(b_in_data),
        .out_valid(o_valid), .out_ready(o_ready), .out_data(o_data),
        .chain_o(b_chain), .phase_o(b_phase),
        .rd_col_o(b_rd_col), .rd_row_o(b_rd_row),
        .wr_col_o(b_wr_col), .wr_row_o(b_wr_row)
    );

    initial begin
        pipeline_active = 1'b0;
        bridge_level = 0;
        delivered_pixels = 32'd0;
        bridge_rd_ptr = {BRIDGE_PTR_W{1'b0}};
        bridge_wr_ptr = {BRIDGE_PTR_W{1'b0}};
        for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
            bridge_mem[j] = 24'd0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_active <= 1'b0;
            bridge_level <= 0;
            delivered_pixels <= 32'd0;
            bridge_rd_ptr <= {BRIDGE_PTR_W{1'b0}};
            bridge_wr_ptr <= {BRIDGE_PTR_W{1'b0}};
            for (j = 0; j < BRIDGE_DEPTH; j = j + 1)
                bridge_mem[j] <= 24'd0;
        end else begin
            pipeline_active <= 1'b1;
            case ({bridge_push, bridge_pop})
                2'b10: bridge_level <= bridge_level + 1'b1;
                2'b01: bridge_level <= bridge_level - 1'b1;
                default: ;
            endcase
            if (bridge_push) begin
                bridge_mem[bridge_wr_ptr] <= {a_o_y, a_o_cb, a_o_cr};
                bridge_wr_ptr <= (bridge_wr_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_wr_ptr + 1'b1;
            end
            if (bridge_pop)
                bridge_rd_ptr <= (bridge_rd_ptr == BRIDGE_DEPTH-1)
                               ? {BRIDGE_PTR_W{1'b0}} : bridge_rd_ptr + 1'b1;
            if (sink_fire)
                delivered_pixels <= delivered_pixels + 32'd1;
        end
    end

    always @(posedge clk) begin
        if (pipeline_active)
            assert (pending_pixels <= TOTAL_CAPACITY);
    end
endmodule

module branch_resolve_unit #(
    parameter XLEN = 64,
    parameter INST_BYTES = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    // resolved branch packet from execute (valid/ready)
    input  wire            br_valid,
    output wire            br_ready,
    input  wire [XLEN-1:0] br_pc,
    input  wire            br_pred_taken,
    input  wire [XLEN-1:0] br_pred_target,
    input  wire            br_taken,
    input  wire [XLEN-1:0] br_target,
    // redirect / flush request to fetch (valid/ready)
    output reg             redir_valid,
    input  wire            redir_ready,
    output reg  [XLEN-1:0] redir_addr,
    output wire            flush,
    // monitor window control
    input  wire            mon_open,
    input  wire            mon_close
);
    localparam [XLEN-1:0] ONE  = 1;
    localparam [XLEN-1:0] STEP = INST_BYTES;

    reg [XLEN-1:0] pred_target_q = 0;
    reg            pred_taken_q  = 1'b0;
    reg            act_taken_q   = 1'b0;
    reg [XLEN-1:0] mispred_cnt   = 0;
    reg [XLEN-1:0] correct_cnt   = 0;
    reg [XLEN-1:0] redir_cnt     = 0;
    reg            win           = 1'b0;
    reg            pv            = 1'b0;
    initial begin redir_valid = 1'b0; redir_addr = 0; end

    assign br_ready = !redir_valid;
    wire accept   = br_valid && br_ready;
    wire send     = redir_valid && redir_ready;
    assign flush  = send;

    wire mispredict = (br_pred_taken != br_taken) ||
                      (br_taken && (br_pred_target != br_target));
    wire [XLEN-1:0] fix_addr = br_taken ? br_target : (br_pc + STEP);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pred_target_q <= 0;
            pred_taken_q  <= 1'b0;
            act_taken_q   <= 1'b0;
            mispred_cnt   <= 0;
            correct_cnt   <= 0;
            redir_cnt     <= 0;
            redir_valid   <= 1'b0;
            redir_addr    <= 0;
        end else begin
            if (accept) begin
                pred_target_q <= br_pred_target;
                pred_taken_q  <= br_pred_taken;
                act_taken_q   <= br_taken;
                if (mispredict) begin
                    mispred_cnt <= mispred_cnt + ONE;
                    redir_valid <= 1'b1;
                    redir_addr  <= fix_addr;
                end else begin
                    correct_cnt <= correct_cnt + ONE;
                end
            end else if (send) begin
                redir_valid <= 1'b0;
                redir_cnt   <= redir_cnt + ONE;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            win <= 1'b0;
        end else begin
            if (mon_open)       win <= 1'b1;
            else if (mon_close) win <= 1'b0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win && $rose(redir_valid))
            assert (mispred_cnt == redir_cnt + ONE);
endmodule

// One-hot process-step sequencer for a lithography/etch cell.
// Exactly one state bit is ever set; transitions are legal only from
// specific states.  Shadow registers record that earlier process steps
// really happened, and a sticky arm register remembers the first LOAD.
module litho_step_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,        // global enable / idle condition
    input  wire i_start,
    input  wire i_dose_ok,
    input  wire i_ack,
    output wire o_busy,
    output wire o_done
);
    localparam S_IDLE    = 0;
    localparam S_LOAD    = 1;
    localparam S_EXPOSE  = 2;
    localparam S_DEVELOP = 3;
    localparam S_ETCH    = 4;
    localparam S_DONE    = 5;

    reg [5:0] state;
    initial   state = 6'b000001;

    // shadow registers: earlier-event recorders
    reg saw_expose;
    reg saw_develop;
    initial saw_expose  = 1'b0;
    initial saw_develop = 1'b0;

    // sticky scope arm: set the first time a wafer is LOADed, never cleared
    reg armed;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state       <= 6'b000001;
            saw_expose  <= 1'b0;
            saw_develop <= 1'b0;
        end else if (step) begin
            case (1'b1)
                state[S_IDLE]: begin
                    if (i_start) begin
                        state       <= 6'b000010; // LOAD
                        saw_expose  <= 1'b0;      // fresh wafer
                        saw_develop <= 1'b0;
                    end
                end
                state[S_LOAD]: begin
                    state <= 6'b000100;           // EXPOSE
                end
                state[S_EXPOSE]: begin
                    if (i_dose_ok) begin
                        state      <= 6'b001000;  // DEVELOP
                        saw_expose <= 1'b1;       // exposure really completed
                    end
                end
                state[S_DEVELOP]: begin
                    state       <= 6'b010000;     // ETCH
                    saw_develop <= 1'b1;          // develop really completed
                end
                state[S_ETCH]: begin
                    state <= 6'b100000;           // DONE
                end
                state[S_DONE]: begin
                    if (i_ack)
                        state <= 6'b000001;       // IDLE
                end
                default: begin
                    state <= 6'b000001;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst)
            armed <= 1'b0;
        else if (state[S_LOAD])
            armed <= 1'b1;
    end

    assign o_busy = ~state[S_IDLE];
    assign o_done = state[S_DONE];

    // Precedence, in the "after first LOAD" scope:
    // reaching ETCH requires a completed EXPOSE, reaching DONE a completed DEVELOP.
    always @(*) begin
        if (armed && state[S_ETCH])
            assert (saw_expose);
        if (armed && state[S_DONE])
            assert (saw_develop);
    end
endmodule

module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
    initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; end

    wire do_ins = i_ce && ins && !rem && (count != 2'd2);
    wire do_rem = i_ce && rem && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
        end else if (do_ins) begin
            count <= count + 2'd1;
            if (count == 2'd0) begin
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
                e1 <= val;  max_shadow <= val;
            end else begin
                e0 <= val;  e1 <= e0;  max_shadow <= e0;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule

module eye_scan_monitor #(
    parameter [63:0] NSAMP = 64'd16,
    parameter [63:0] H_PTS = 64'd4,
    parameter [63:0] V_PTS = 64'd4
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire        abort,
    input  wire        data_bit,
    input  wire        offset_bit,
    output wire        busy,
    output wire [63:0] o_mismatch,
    output wire [63:0] o_h_off,
    output wire [63:0] o_v_off
);
    typedef enum logic [1:0] {S_IDLE, S_SAMPLE, S_STEP, S_DONE} state_t;

    state_t     state;
    reg [63:0]  h_off;
    reg [63:0]  v_off;
    reg [63:0]  sample_cnt;
    reg [63:0]  mismatch_cnt;
    reg         window;

    initial begin
        state        = S_IDLE;
        h_off        = 64'd0;
        v_off        = 64'd0;
        sample_cnt   = 64'd0;
        mismatch_cnt = 64'd0;
        window       = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            h_off        <= 64'd0;
            v_off        <= 64'd0;
            sample_cnt   <= 64'd0;
            mismatch_cnt <= 64'd0;
            window       <= 1'b0;
        end else if (en) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state        <= S_SAMPLE;
                        h_off        <= 64'd0;
                        v_off        <= 64'd0;
                        sample_cnt   <= 64'd0;
                        mismatch_cnt <= 64'd0;
                        window       <= 1'b1;
                    end
                end
                S_SAMPLE: begin
                    if (abort) begin
                        state  <= S_IDLE;
                        window <= 1'b0;
                    end else begin
                        sample_cnt <= sample_cnt + 64'd1;
                        if (data_bit != offset_bit)
                            mismatch_cnt <= mismatch_cnt + 64'd1;
                        if (sample_cnt == NSAMP - 64'd1)
                            state <= S_STEP;
                    end
                end
                S_STEP: begin
                    sample_cnt   <= 64'd0;
                    mismatch_cnt <= 64'd0;
                    if (h_off == H_PTS - 64'd1) begin
                        h_off <= 64'd0;
                        if (v_off == V_PTS - 64'd1) begin
                            v_off <= 64'd0;
                            state <= S_DONE;
                        end else begin
                            v_off <= v_off + 64'd1;
                            state <= S_SAMPLE;
                        end
                    end else begin
                        h_off <= h_off + 64'd1;
                        state <= S_SAMPLE;
                    end
                end
                S_DONE: begin
                    window <= 1'b0;
                    state  <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign busy       = (state != S_IDLE);
    assign o_mismatch = mismatch_cnt;
    assign o_h_off    = h_off;
    assign o_v_off    = v_off;

    always @(posedge clk)
        if (window)
            assert (mismatch_cnt <= NSAMP);
endmodule

module qpsk_mw_cfg (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cs,
    input wire di,
    output wire dout,
    output reg do_oe
);
    localparam [2:0] IDLE = 3'd0, START = 3'd1, OPCODE = 3'd2, ADDR = 3'd3, DATA = 3'd4;

    reg [2:0]  phase;
    reg [63:0] cnt;
    reg [7:0]  oa_sr;
    reg [63:0] dat_sr;
    reg [63:0] mem [0:63];
    reg [63:0] wr_cnt;
    reg        pre_commit;
    integer i;

    initial begin
        phase = IDLE; cnt = 64'd0; oa_sr = 8'd0; dat_sr = 64'd0;
        do_oe = 1'b0; wr_cnt = 64'd0; pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) mem[i] = 64'd0;
    end

    wire [7:0]  oa_next  = {oa_sr[6:0], di};
    wire        is_read  = (oa_sr[7:6] == 2'b10);
    wire [63:0] dat_next = {dat_sr[62:0], di};

    assign dout = do_oe & dat_sr[63];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; cnt <= 64'd0; oa_sr <= 8'd0; dat_sr <= 64'd0;
            do_oe <= 1'b0; wr_cnt <= 64'd0; pre_commit <= 1'b1;
        end else if (en) begin
            if (!cs) begin
                phase <= IDLE;
                do_oe <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (di) phase <= START;
                    end
                    START: begin
                        phase <= OPCODE;
                        cnt <= 64'd2;
                    end
                    OPCODE: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= ADDR;
                            cnt <= 64'd6;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    ADDR: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= DATA;
                            cnt <= 64'd64;
                            do_oe <= (oa_next[7:6] == 2'b10);
                            if (oa_next[7:6] == 2'b10)
                                dat_sr <= mem[oa_next[5:0]];
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    DATA: begin
                        if (is_read)
                            dat_sr <= {dat_sr[62:0], 1'b0};
                        else
                            dat_sr <= dat_next;
                        if (cnt == 64'd1) begin
                            if (!is_read) begin
                                mem[oa_sr[5:0]] <= dat_next;
                                wr_cnt <= wr_cnt + 64'd1;
                                pre_commit <= 1'b0;
                            end
                            phase <= IDLE;
                            do_oe <= 1'b0;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    default: begin
                        phase <= IDLE;
                    end
                endcase
            end
        end
    end

    always @(*)
        if (pre_commit)
            assert (!(phase == 3'd3 && do_oe));
endmodule

module usb_ep_buf (
    input  wire        clk,
    input  wire        ce,
    input  wire        cfg_set,
    input  wire        out_valid,
    input  wire [31:0] out_data,
    input  wire        in_ready,
    output wire [31:0] in_data,
    output wire        in_toggle,
    output wire        out_toggle,
    output wire [31:0] level_o
);
    reg [31:0] mem [0:15];
    reg [31:0] wptr     = 32'd0;
    reg [31:0] rptr     = 32'd0;
    reg [31:0] count    = 32'd0;
    reg        tog_out  = 1'b0;
    reg        tog_in   = 1'b0;
    reg        ep_cfg   = 1'b0;
    reg        armed    = 1'b0;
    reg        pkt_done = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 32'd0;
    end

    wire [31:0] level   = wptr - rptr;
    wire        do_push = ce && ep_cfg && out_valid && (level != 32'd16);
    wire        do_pop  = ce && in_ready && (level != 32'd0);

    assign in_data    = mem[rptr[3:0]];
    assign in_toggle  = tog_in;
    assign out_toggle = tog_out;
    assign level_o    = count;

    always @(posedge clk) begin
        if (ce) begin
            if (cfg_set) ep_cfg <= 1'b1;
            pkt_done <= do_push;
        end
        if (do_push) begin
            mem[wptr[3:0]] <= out_data;
            wptr    <= wptr + 32'd1;
            tog_out <= ~tog_out;
            armed   <= 1'b1;
        end
        if (do_pop) begin
            rptr   <= rptr + 32'd1;
            tog_in <= ~tog_in;
        end
        case ({do_push, do_pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (armed && $rose(pkt_done))
            assert (count <= 32'd16);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
output wire [15:0]  qual_cnt_o,
output reg  [31:0]  dbg_o,
output wire         wdt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

   localparam [19:0] WDT_LIMIT = 20'd65535;

   reg [31:0] cyc_cnt;
   reg [31:0] beat_cnt;
   reg [15:0] wr0_cnt;
   reg [15:0] wr1_cnt;
   reg [15:0] arm_cnt;
   reg [15:0] clr_cnt;
   reg [15:0] hit_cnt;
   reg [15:0] sr_cnt;
   reg        done_d;
   reg        sr_d;
   reg [1:0]  fsm_d;
   reg [19:0] wdt_cnt;
   reg        wdt_to;
   reg [3:0]  err_bits;
   reg [2:0]  err_code;
   reg [31:0] err_ts;
   reg        err_valid;

   initial cyc_cnt   = 32'd0;
   initial beat_cnt  = 32'd0;
   initial wr0_cnt   = 16'd0;
   initial wr1_cnt   = 16'd0;
   initial arm_cnt   = 16'd0;
   initial clr_cnt   = 16'd0;
   initial hit_cnt   = 16'd0;
   initial sr_cnt    = 16'd0;
   initial done_d    = 1'b0;
   initial sr_d      = 1'b0;
   initial fsm_d     = 2'd0;
   initial wdt_cnt   = 20'd0;
   initial wdt_to    = 1'b0;
   initial err_bits  = 4'd0;
   initial err_code  = 3'd0;
   initial err_ts    = 32'd0;
   initial err_valid = 1'b0;
   initial dbg_o     = 32'd0;

   wire       dbg_fsm_busy  = (fsm_a == 2'd1) || (fsm_a == 2'd2);
   wire       dbg_fsm_move  = (fsm_a != fsm_d);
   wire       dbg_clr_a     = en_a && clr_cmd;
   wire       err_arm_busy  = en_a && arm_cmd && !clr_cmd && (fsm_a != 2'd0);
   wire       err_wr_busy   = en_a && wr_en && dbg_fsm_busy;
   wire       err_wdt       = dbg_fsm_busy && (wdt_cnt == WDT_LIMIT);
   wire       err_bod       = bod_clr && !en_b;
   wire [3:0] err_now       = {err_bod, err_wdt, err_wr_busy, err_arm_busy};
   wire [2:0] err_enc       = err_now[0] ? 3'd1 :
                              err_now[1] ? 3'd2 :
                              err_now[2] ? 3'd3 :
                              err_now[3] ? 3'd4 : 3'd0;
   wire       done_rise     = done_a && !done_d;
   wire       sr_rise       = slot_reset_b && !sr_d;

   reg [31:0] dbg_mux;
   always @(*) begin
       case ({wr_sel, sel_in})
           3'd0: dbg_mux = cyc_cnt;
           3'd1: dbg_mux = beat_cnt;
           3'd2: dbg_mux = {wr1_cnt, wr0_cnt};
           3'd3: dbg_mux = {arm_cnt, clr_cnt};
           3'd4: dbg_mux = {hit_cnt, sr_cnt};
           3'd5: dbg_mux = {err_valid, 3'd0, err_code, 1'b0, err_bits, wdt_to, wdt_cnt[18:0]};
           3'd6: dbg_mux = err_ts;
           default: dbg_mux = {thr_b, streak_b};
       endcase
   end

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
           cyc_cnt   <= 32'd0;
           beat_cnt  <= 32'd0;
           wr0_cnt   <= 16'd0;
           wr1_cnt   <= 16'd0;
           arm_cnt   <= 16'd0;
           clr_cnt   <= 16'd0;
           hit_cnt   <= 16'd0;
           sr_cnt    <= 16'd0;
           done_d    <= 1'b0;
           sr_d      <= 1'b0;
           fsm_d     <= 2'd0;
           wdt_cnt   <= 20'd0;
           wdt_to    <= 1'b0;
           err_bits  <= 4'd0;
           err_code  <= 3'd0;
           err_ts    <= 32'd0;
           err_valid <= 1'b0;
           dbg_o     <= 32'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
           cyc_cnt <= cyc_cnt + 32'd1;
           if (beat_valid && (beat_cnt != 32'hFFFFFFFF))
               beat_cnt <= beat_cnt + 32'd1;
           if (en_a && wr_en && !wr_sel && (wr0_cnt != 16'hFFFF))
               wr0_cnt <= wr0_cnt + 16'd1;
           if (en_a && wr_en && wr_sel && (wr1_cnt != 16'hFFFF))
               wr1_cnt <= wr1_cnt + 16'd1;
           if (en_a && arm_cmd && (arm_cnt != 16'hFFFF))
               arm_cnt <= arm_cnt + 16'd1;
           if (dbg_clr_a && (clr_cnt != 16'hFFFF))
               clr_cnt <= clr_cnt + 16'd1;
           done_d <= done_a;
           sr_d   <= slot_reset_b;
           fsm_d  <= fsm_a;
           if (done_rise && (hit_cnt != 16'hFFFF))
               hit_cnt <= hit_cnt + 16'd1;
           if (sr_rise && (sr_cnt != 16'hFFFF))
               sr_cnt <= sr_cnt + 16'd1;
           if (!dbg_fsm_busy || dbg_fsm_move || dbg_clr_a)
               wdt_cnt <= 20'd0;
           else if (wdt_cnt != WDT_LIMIT)
               wdt_cnt <= wdt_cnt + 20'd1;
           if (dbg_clr_a)
               wdt_to <= 1'b0;
           else if (err_wdt)
               wdt_to <= 1'b1;
           if (bod_clr && en_b) begin
               err_bits  <= 4'd0;
               err_code  <= 3'd0;
               err_ts    <= 32'd0;
               err_valid <= 1'b0;
           end else begin
               err_bits <= err_bits | err_now;
               if (!err_valid && (err_now != 4'd0)) begin
                   err_valid <= 1'b1;
                   err_code  <= err_enc;
                   err_ts    <= cyc_cnt;
               end
           end
           dbg_o <= dbg_mux;
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
   assign wdt_o      = wdt_to;
endmodule

module forth_rng_word (
    input  wire       clk,
    input  wire       ce,
    input  wire       go,
    output wire [7:0] rnd,
    output reg        busy
);
    reg [7:0] prng;
    reg [7:0] cd;
    reg [7:0] steps;
    initial begin prng = 8'h5A; cd = 8'd0; steps = 8'd0; busy = 1'b0; end

    // 8-bit xorshift (7,5,3)
    wire [7:0] x1 = prng ^ (prng << 7);
    wire [7:0] x2 = x1 ^ (x1 >> 5);
    wire [7:0] x3 = x2 ^ (x2 << 3);

    assign rnd = prng;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (go) begin
                    busy  <= 1'b1;
                    steps <= 8'd0;
                    cd    <= 8'd8;
                end
            end else begin
                prng <= x3;
                cd   <= cd - 8'd1;
                if (steps == 8'd7)
                    busy <= 1'b0;
                else
                    steps <= steps + 8'd1;
            end
        end
    end

    // countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (cd != 8'd0);

    // on the final shift round, exactly one tick of budget remains
    always @(posedge clk)
        if (busy && steps == 8'd7)
            assert (cd == 8'd1);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
output reg  o_clean,
output reg [3:0] o_evt_cnt
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid
   reg [3:0] evt_cnt  = 4'd0;  // distractor: counts disagreeing input steps

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;
   initial o_evt_cnt = 4'd0;
   initial evt_cnt   = 4'd0;

    always @(posedge clk)
        pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           if (i_raw ^ i_arm)
               evt_cnt <= evt_cnt + 4'd1;
           o_evt_cnt <= evt_cnt ^ {3'b000, i_disarm};
       end
   end

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
           // ---- writeback slot: applies the entry retired one step ago ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
           // the head hands its entry to the writeback slot; an entry whose
           // sample moved again in the meantime is dropped instead
           wb_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                               && !(cmt_ch == CH_B && b_chg);
           wb_val  <= cmt_val;
           wb_ch   <= cmt_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module axi_burst_hist (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,        // request from the AXI side
    input  wire       sample_valid, // enable: one sample per cycle
    input  wire [1:0] sel,          // which bin this sample lands in
    output wire       done
);
    // Each accepted request collects BURST samples into a 4-bin histogram.
    // The bins are incremented one at a time and always sum to `total`.
    localparam integer BURST    = 4;
    localparam [2:0]   DEADLINE = 3'd6;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;   // total samples collected in this burst
    reg [2:0] timer;   // bounded-response countdown
    reg       busy;    // window register: set by accept, cleared by done

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
    initial timer = 3'd0;
    initial busy  = 1'b0;

    wire [7:0] sum = bin0 + bin1 + bin2 + bin3;

    // burst finishes when the histogram has absorbed the last sample
    assign done = busy && sample_valid && (sum == BURST - 1);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            timer <= 3'd0;
            busy  <= 1'b0;
        end else if (!busy) begin
            if (start) begin          // Q: request accepted, window opens
                bin0  <= 4'd0;
                bin1  <= 4'd0;
                bin2  <= 4'd0;
                bin3  <= 4'd0;
                total <= 4'd0;
                timer <= DEADLINE;
                busy  <= 1'b1;
            end
        end else if (sample_valid) begin
            case (sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
            timer <= timer - 3'd1;
            if (sum == BURST - 1)     // R: last sample, window closes
                busy <= 1'b0;
        end
    end

    // Bounded response (safety): inside the open window the countdown
    // must never reach zero, i.e. the burst always completes in time.
    always @(posedge clk)
        if (busy)
            assert (timer != 3'd0);
endmodule

module bilinear_scaler (
    input  wire        clk,
    input  wire        ce,        // advance the fractional position accumulator
    input  wire        ld_en,     // load a sample into the line buffer
    input  wire [3:0]  ld_addr,
    input  wire [15:0] ld_data,
    input  wire [15:0] phase_step,
    output reg  [15:0] out_pix
);
    // ---- scaler state -------------------------------------------------
    reg [15:0] frac;     // fractional source position
    reg [15:0] fcomp;    // complementary weight, kept as ~frac by construction
    reg [15:0] pa;       // left  neighbour of the line buffer window
    reg [15:0] pb;       // right neighbour of the line buffer window
    reg [15:0] rd_idx;   // line buffer read cursor
    reg [15:0] lbuf [0:15];
    reg        pv;

    integer i;
    initial begin
        frac    = 16'h0000;
        fcomp   = 16'hFFFF;
        pa      = 16'h0000;
        pb      = 16'h0000;
        rd_idx  = 16'h0000;
        out_pix = 16'h0000;
        pv      = 1'b0;
        for (i = 0; i < 16; i = i + 1) lbuf[i] = 16'h0000;
    end

    // ---- fractional position accumulator -------------------------------
    wire [16:0] acc_sum   = {1'b0, frac} + {1'b0, phase_step};
    wire        carry     = acc_sum[16];
    wire [15:0] frac_next = acc_sum[15:0];

    // the complement register drives the neighbour choice of the blender
    wire        pick_a    = fcomp[15];

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ld_en)
            lbuf[ld_addr] <= ld_data;
        if (ce) begin
            frac    <= frac_next;
            fcomp   <= ~frac_next;
            out_pix <= pick_a ? pa : pb;
            if (carry) begin
                pa     <= pb;
                pb     <= lbuf[rd_idx[3:0]];
                rd_idx <= rd_idx + 16'd1;
            end
        end
    end

    // ---- property -------------------------------------------------------
    always @(posedge clk)
        if (pv && $past(ce))
            assert (out_pix == ($past(frac[15]) ? $past(pb) : $past(pa)));
endmodule

module relo_belt (
    input wire clk,
    input wire rst,
    input wire en,
    input wire drop,
    input wire [63:0] din,
    input wire [4:0] rd_pos,
    input wire ckpt_open,
    input wire ckpt_close,
    output wire [63:0] dout
);
    reg [63:0] slot [0:31];
    reg [4:0] head;
    reg [63:0] drops;
    reg [63:0] win_cnt;
    reg win;
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            slot[i] = 64'd0;
        head = 5'd0;
        drops = 64'd0;
        win_cnt = 64'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 32; i = i + 1)
                slot[i] <= 64'd0;
            head <= 5'd0;
            drops <= 64'd0;
            win_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (drop) begin
                slot[head] <= din;
                head <= head + 5'd1;
                drops <= drops + 64'd1;
                if (win)
                    win_cnt <= win_cnt + 64'd1;
            end
            if (ckpt_close) begin
                win <= 1'b0;
            end else if (ckpt_open) begin
                win <= 1'b1;
                win_cnt <= 64'd0;
            end
        end
    end

    assign dout = slot[head - 5'd1 - rd_pos];

    always @(posedge clk)
        if (win && !rst)
            assert (head == drops[4:0]);
endmodule

module ldpc_cnp_group_reduce #(
    parameter W = 32,
    parameter GROUPS = 4
) (
    input  wire clk,
    input  wire accept,
    input  wire clear,
    input  wire [W-1:0] edge_index,
    input  wire [W-1:0] magnitude,
    input  wire sign_bit,
    output reg [GROUPS*W-1:0] group_min1,
    output reg [GROUPS*W-1:0] group_min2,
    output reg [GROUPS-1:0] group_sign,
    output reg [W-1:0] folded_min1,
    output reg [W-1:0] folded_min2,
    output reg folded_sign
);
    localparam BW = $clog2(GROUPS);
    wire [BW-1:0] bank = edge_index % GROUPS;
    reg [W-1:0] low [0:GROUPS-1];
    reg [W-1:0] high [0:GROUPS-1];
    reg parity [0:GROUPS-1];
    reg [W-1:0] candidate_low, candidate_high;
    integer init_i, scan_i, reset_i;
    initial begin
        for (init_i = 0; init_i < GROUPS; init_i = init_i + 1) begin
            low[init_i] = {W{1'b1}};
            high[init_i] = {W{1'b1}};
            parity[init_i] = 1'b0;
        end
    end
    always @(*) begin
        folded_min1 = {W{1'b1}};
        folded_min2 = {W{1'b1}};
        folded_sign = 1'b0;
        for (scan_i = 0; scan_i < GROUPS; scan_i = scan_i + 1) begin
            group_min1[scan_i*W +: W] = low[scan_i];
            group_min2[scan_i*W +: W] = high[scan_i];
            group_sign[scan_i] = parity[scan_i];
            candidate_low = low[scan_i];
            candidate_high = high[scan_i];
            if (scan_i == bank) begin
                if (magnitude < low[scan_i]) begin
                    candidate_low = magnitude;
                    candidate_high = low[scan_i];
                end else if (magnitude < high[scan_i]) begin
                    candidate_high = magnitude;
                end
            end
            if (candidate_low < folded_min1) begin
                folded_min2 = folded_min1;
                folded_min1 = candidate_low;
            end else if (candidate_low < folded_min2) begin
                folded_min2 = candidate_low;
            end
            if (candidate_high < folded_min2)
                folded_min2 = candidate_high;
            folded_sign = folded_sign ^ parity[scan_i];
        end
        folded_sign = folded_sign ^ sign_bit;
    end
    always @(posedge clk) begin
        if (clear) begin
            for (reset_i = 0; reset_i < GROUPS; reset_i = reset_i + 1) begin
                low[reset_i] <= {W{1'b1}};
                high[reset_i] <= {W{1'b1}};
                parity[reset_i] <= 1'b0;
            end
        end else if (accept) begin
            parity[bank] <= parity[bank] ^ sign_bit;
            if (magnitude < low[bank]) begin
                high[bank] <= low[bank];
                low[bank] <= magnitude;
            end else if (magnitude < high[bank]) begin
                high[bank] <= magnitude;
            end
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter GROUPS = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [GROUPS*W-1:0] group_min1,
    output wire [GROUPS*W-1:0] group_min2,
    output wire [GROUPS-1:0] group_sign,
    output wire group_valid
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    wire [W-1:0] folded_min1, folded_min2;
    wire folded_sign;
    ldpc_cnp_group_reduce #(.W(W), .GROUPS(GROUPS)) group_reduce (
        .clk(clk), .accept(acc), .clear(rel),
        .edge_index(count), .magnitude(in_mag), .sign_bit(in_sign),
        .group_min1(group_min1), .group_min2(group_min2),
        .group_sign(group_sign), .folded_min1(folded_min1),
        .folded_min2(folded_min2), .folded_sign(folded_sign)
    );
    assign group_valid = (state == S_DONE);
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= folded_sign;
            min1 <= folded_min1;
            min2 <= folded_min2;
            if (in_mag < min1) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module token_bucket_chain (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // global enable: low => all state frozen
    input  wire tick,    // refill timer tick
    input  wire req,     // step 1: arm
    input  wire cancel,  // drop an arm before it starts
    input  wire go,      // step 2: request a grant (needs a token)
    input  wire done,    // step 3: finish
    output wire o_start,
    output wire o_finish,
    output reg  [2:0] tokens
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2;
    localparam [2:0] BURST  = 3'd4;

    reg [1:0] state;
    reg       armed_seen;
    reg       started_seen;

    initial begin
        state        = S_IDLE;
        tokens       = 3'd0;
        armed_seen   = 1'b0;
        started_seen = 1'b0;
    end

    // a grant may only be issued from the armed state and only if the
    // bucket holds at least one token
    wire can_start = (state == S_ARM) && go && !cancel && (tokens != 3'd0);
    wire do_refill = tick && (tokens < BURST);

    assign o_start  = ce && can_start;
    assign o_finish = ce && (state == S_RUN) && done;

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            tokens       <= 3'd0;
            armed_seen   <= 1'b0;
            started_seen <= 1'b0;
        end else if (ce) begin
            // token bucket: refill on tick up to the burst cap, drain on grant
            case ({do_refill, can_start})
                2'b10:   tokens <= tokens + 3'd1;
                2'b01:   tokens <= tokens - 3'd1;
                default: tokens <= tokens;
            endcase

            // arm -> start -> finish chain
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state        <= S_ARM;
                        armed_seen   <= 1'b1;
                        started_seen <= 1'b0;
                    end
                end
                S_ARM: begin
                    if (cancel) begin
                        state      <= S_IDLE;
                        armed_seen <= 1'b0;
                    end else if (can_start) begin
                        state        <= S_RUN;
                        started_seen <= 1'b1;
                    end
                end
                S_RUN: begin
                    if (done) begin
                        state        <= S_IDLE;
                        armed_seen   <= 1'b0;
                        started_seen <= 1'b0;
                    end
                end
                default: begin
                    state        <= S_IDLE;
                    armed_seen   <= 1'b0;
                    started_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence: a finish can never be observed unless this
    // transaction was armed and then started
    always @(*)
        if (o_finish)
            assert (armed_seen && started_seen);
endmodule

module hwm_stack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_en,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_item,
    output wire [3:0] o_sp,
    output wire [3:0] o_hwm,
    output wire       o_deep
);
    // Placement stack for footprint records: pointer plus a high-water mark
    // that only ever ratchets upward, and a shadow flag recording that the
    // stack was once at least half full.

    reg [3:0] sp;         // stack pointer, 0..8
    reg [3:0] hwm;        // high-water mark, 0..8
    reg       deep_flag;  // shadow: a deep occupancy event happened earlier
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        sp        = 4'd0;
        hwm       = 4'd0;
        deep_flag = 1'b0;
        for (k = 0; k < 8; k = k + 1) mem[k] = 8'd0;
    end

    wire do_push = i_en && i_push && !i_pop && (sp != 4'd8);
    wire do_pop  = i_en && i_pop  && !i_push && (sp != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 4'd0;
            hwm       <= 4'd0;
            deep_flag <= 1'b0;
        end else if (i_en) begin
            if (do_push) begin
                sp <= sp + 4'd1;
                if ((sp + 4'd1) > hwm)
                    hwm <= sp + 4'd1;
                mem[sp[2:0]] <= i_item;
            end else if (do_pop) begin
                sp <= sp - 4'd1;
            end
            // shadow register: remember that occupancy reached 4 or more
            deep_flag <= deep_flag || (sp >= 4'd4);
        end
    end

    assign o_sp   = sp;
    assign o_hwm  = hwm;
    assign o_deep = deep_flag;

    // Precedence: if the deep-occupancy flag is observed set now, the high
    // water mark must already record a depth of at least 4.
    always @(*)
        assert (!deep_flag || (hwm >= 4'd4));
endmodule

module elevator_cab (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,        // idle condition: low freezes all state
    input  wire       req_valid,
    input  wire [1:0] req_floor,
    output reg  [1:0] floor,
    output reg  [1:0] target,
    output reg  [1:0] dist,        // remaining floors of travel
    output reg        dir,         // 1 = up, 0 = down
    output reg        busy         // cab is in transit
);
    initial floor  = 2'd0;
    initial target = 2'd0;
    initial dist   = 2'd0;
    initial dir    = 1'b0;
    initial busy   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            floor  <= 2'd0;
            target <= 2'd0;
            dist   <= 2'd0;
            dir    <= 1'b0;
            busy   <= 1'b0;
        end else if (step) begin
            if (busy) begin
                // one floor of travel per step
                if (dir)
                    floor <= floor + 2'd1;
                else
                    floor <= floor - 2'd1;
                dist <= dist - 2'd1;
                if (dist == 2'd1)
                    busy <= 1'b0;
            end else if (req_valid && (req_floor != floor)) begin
                target <= req_floor;
                dir    <= (req_floor > floor);
                dist   <= (req_floor > floor) ? (req_floor - floor)
                                              : (floor - req_floor);
                busy   <= 1'b1;
            end
        end
    end

    // P: whenever the cab is not in transit, it is parked at its target floor
    always @(posedge clk)
        if (!busy)
            assert (floor == target);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module onehot_issue_window (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,   // Q: arms the observation window
    input  wire       i_close,   // R: closes the window (may never arrive)
    output wire [2:0] o_occ,
    output wire [3:0] o_state
);

    // one-hot FSM: IDLE -> ISSUE_A -> ISSUE_B -> DRAIN -> IDLE
    reg [3:0] state = 4'b0001;
    // outstanding-token occupancy: one token issued per ISSUE state,
    // all tokens retired in DRAIN
    reg [2:0] occ   = 3'd0;
    // window register: latched by the start pulse, cleared by i_close
    reg       armed = 1'b0;
    reg       pv    = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            state <= 4'b0001;
            occ   <= 3'd0;
        end else if (i_ce) begin
            case (1'b1)
                state[0]: begin
                    // leaving IDLE is only legal on a start pulse
                    if (i_start)
                        state <= 4'b0010;
                    occ <= 3'd0;
                end
                state[1]: begin
                    state <= 4'b0100;
                    occ   <= occ + 3'd1;
                end
                state[2]: begin
                    state <= 4'b1000;
                    occ   <= occ + 3'd1;
                end
                state[3]: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
                default: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
            endcase
        end

    always @(posedge clk)
        if (i_rst)
            armed <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                armed <= 1'b0;
            else if (i_start && state[0])
                armed <= 1'b1;
        end

    assign o_occ   = occ;
    assign o_state = state;

    // P: once the window has been armed, the occupancy of the previous
    //    cycle never exceeded two outstanding tokens
    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(occ) <= 3'd2);

endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;
// the leg adder is retimed one stage: a freshly decoded leg parks in leg_q
// and merges into credit on the next enabled cycle, so the terminating leg
// has to flush both halves of the pending batch into steps at once
reg       leg_q;
initial   leg_q = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
leg_q     <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
               credit <= 2'd0;
leg_q  <= 1'b0;
            end else begin
credit <= credit + {1'b0, leg_q};
leg_q  <= 1'b0;
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
leg_q   <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
leg_q     <= 1'b1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
                      credit <= 2'd0;
leg_q  <= 1'b0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

// Gray-coded write pointer crossing into a second domain through a
// two-flop synchronizer, with a shadow register recording the previously
// observed synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle condition: low freezes all state
    input  wire       push,
    output wire [3:0] o_gray,
    output wire [3:0] o_gray_shadow
);

    // source-domain binary pointer and its gray encoding
    reg [3:0] bin;
    reg [3:0] wgray;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow: the sample observed one enabled cycle earlier
    reg [3:0] s2_prev;

    initial begin
        bin     = 4'd0;
        wgray   = 4'd0;
        s1      = 4'd0;
        s2      = 4'd0;
        s2_prev = 4'd0;
    end

    wire [3:0] nbin = bin + (push ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin     <= 4'd0;
            wgray   <= 4'd0;
            s1      <= 4'd0;
            s2      <= 4'd0;
            s2_prev <= 4'd0;
        end else if (i_ce) begin
            bin     <= nbin;
            wgray   <= nbin ^ (nbin >> 1);
            s1      <= wgray;
            s2      <= s1;
            s2_prev <= s2;
        end
    end

    assign o_gray        = s2;
    assign o_gray_shadow = s2_prev;

    // Hamming distance between the present sample and the shadow sample
    wire [3:0] d_a = s2 ^ s2_prev;
    wire [2:0] n_a = {2'b0, d_a[0]} + {2'b0, d_a[1]} +
                     {2'b0, d_a[2]} + {2'b0, d_a[3]};

    // Hamming distance between the first-flop sample and the shadow sample
    wire [3:0] d_b = s1 ^ s2_prev;
    wire [2:0] n_b = {2'b0, d_b[0]} + {2'b0, d_b[1]} +
                     {2'b0, d_b[2]} + {2'b0, d_b[3]};

    // P1: whatever value is observed now must have been preceded by a value
    //     at most one bit away.
    always @(posedge clk)
        assert (n_a <= 3'd1);

    // P2: the value about to be observed is at most two bits away from the
    //     value observed two enabled cycles ago.
    always @(posedge clk)
        assert (n_b <= 3'd2);

endmodule

module decoded_timeout_tracker (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [2:0]  chan,
    output reg         done,
    output reg  [15:0] total
);
    // outstanding-request state
    reg        busy;
    reg  [2:0] sel;        // latched channel number
    reg  [7:0] onehot;     // latched binary-decoder word
    reg [15:0] timer;      // bounded-response countdown

    // per-channel completion counters: 8 entries, 16 bits each
    reg [15:0] cnt [0:7];
    integer i;

    initial begin
        busy   = 1'b0;
        sel    = 3'd0;
        onehot = 8'd0;
        timer  = 16'd0;
        done   = 1'b0;
        total  = 16'd0;
        for (i = 0; i < 8; i = i + 1) cnt[i] = 16'd0;
    end

    // request acceptance
    wire accept = ce && !busy && start;

    // combinational binary decoder: one of 8 outputs, selected by chan,
    // activated only under the accept enable
    wire [7:0] dec_out = accept ? (8'h01 << chan) : 8'h00;

    // completion is signalled through the latched decode: the countdown
    // tick is fanned out over the eight channel strobes
    wire        expire_tick = ce && busy && (timer == 16'd1);
    wire [7:0]  strobe      = onehot & {8{expire_tick}};
    wire        complete    = |strobe;

    always @(posedge clk) begin
        if (rst) begin
            busy   <= 1'b0;
            sel    <= 3'd0;
            onehot <= 8'd0;
            timer  <= 16'd0;
            done   <= 1'b0;
            total  <= 16'd0;
        end else begin
            if (ce)
                done <= complete;

            if (accept) begin
                busy   <= 1'b1;
                sel    <= chan;
                onehot <= dec_out;
                timer  <= 16'd8;
            end else if (complete) begin
                busy   <= 1'b0;
                timer  <= 16'd0;
            end else if (ce && busy) begin
                timer  <= timer - 16'd1;
            end

            if (complete) begin
                cnt[sel] <= cnt[sel] + 16'd1;
                total    <= total + 16'd1;
            end
        end
    end

    // P1: the countdown never expires while a request is still outstanding
    always @(posedge clk)
        if (busy)
            assert (timer != 16'd0);

    // P2: a completion is always reported through exactly one decoded channel
    always @(posedge clk)
        if (done)
            assert ((onehot != 8'd0) && ((onehot & (onehot - 8'd1)) == 8'd0));
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module cordic_rot64 (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        ack,
    input  wire [63:0] x_in,
    input  wire [63:0] y_in,
    input  wire [63:0] z_in,
    output wire [63:0] x_out,
    output wire [63:0] y_out,
    output wire [63:0] z_out,
    output wire        busy_o,
    output wire        done_o
);
    localparam [63:0] N_ITER = 64'd32;

    reg signed [63:0] x, y, z;
    reg [63:0] iter, remaining;
    reg busy, done, armed;

    initial begin
        x = 64'd0; y = 64'd0; z = 64'd0;
        iter = 64'd0; remaining = N_ITER;
        busy = 1'b0; done = 1'b0; armed = 1'b0;
    end

    // 32-entry arctangent ROM, angle in Q32 radians held in 64 bits
    function [63:0] atan_lut;
        input [4:0] i;
        begin
            case (i)
                5'd0: atan_lut = 64'h00000000C90FDAA2;
                5'd1: atan_lut = 64'h0000000076B19C16;
                5'd2: atan_lut = 64'h000000003EB6EBF2;
                5'd3: atan_lut = 64'h000000001FD5BA9B;
                5'd4: atan_lut = 64'h000000000FFAADDC;
                5'd5: atan_lut = 64'h0000000007FF556F;
                5'd6: atan_lut = 64'h0000000003FFEAAB;
                5'd7: atan_lut = 64'h0000000001FFFD55;
                default: atan_lut = 64'd1 << (6'd32 - {1'b0, i});
            endcase
        end
    endfunction

    wire [4:0] sh = iter[4:0];

    always @(posedge clk) begin
        if (rst) begin
            x <= 64'd0; y <= 64'd0; z <= 64'd0;
            iter <= 64'd0; remaining <= N_ITER;
            busy <= 1'b0; done <= 1'b0; armed <= 1'b0;
        end else if (ce) begin
            if (start && !busy) begin
                x <= x_in; y <= y_in; z <= z_in;
                iter <= 64'd0;
                remaining <= N_ITER;
                busy <= 1'b1;
                done <= 1'b0;
                armed <= 1'b1;
            end else begin
                if (ack) armed <= 1'b0;
                if (busy) begin
                    if (z[63] == 1'b0) begin
                        x <= x - (y >>> sh);
                        y <= y + (x >>> sh);
                        z <= z - atan_lut(sh);
                    end else begin
                        x <= x + (y >>> sh);
                        y <= y - (x >>> sh);
                        z <= z + atan_lut(sh);
                    end
                    iter <= iter + 64'd1;
                    remaining <= remaining - 64'd1;
                    if (iter == N_ITER - 64'd1) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                    end
                end
            end
        end
    end

    assign x_out = x;
    assign y_out = y;
    assign z_out = z;
    assign busy_o = busy;
    assign done_o = done;

    // After a start (armed) until ack: never busy with the iteration budget exhausted
    always @(posedge clk)
        if (armed)
            assert (!(busy && remaining == 64'd0));
endmodule

module delay_pulse_gen (
    input  wire        clk,
    input  wire        ce,
    input  wire        trig,
    input  wire        wr_cfg,
    input  wire [31:0] cfg_delay,
    input  wire [31:0] cfg_width,
    output wire        pulse,
    output wire        busy
);
    localparam [1:0] IDLE = 2'd0, DLY = 2'd1, WID = 2'd2;

    reg [31:0] delay_reg;
    reg [31:0] width_reg;
    reg [31:0] snap_delay;
    reg [31:0] snap_width;
    reg [31:0] cnt;
    reg [1:0]  phase;
    reg [33:0] since_trig;

    initial begin
        delay_reg  = 32'd0;
        width_reg  = 32'd0;
        snap_delay = 32'd0;
        snap_width = 32'd0;
        cnt        = 32'd0;
        phase      = IDLE;
        since_trig = 34'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (wr_cfg) begin
                delay_reg <= cfg_delay;
                width_reg <= cfg_width;
            end
            case (phase)
                IDLE: begin
                    if (trig) begin
                        phase      <= DLY;
                        cnt        <= 32'd0;
                        snap_delay <= delay_reg;
                        snap_width <= width_reg;
                        since_trig <= 34'd0;
                    end
                end
                DLY: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_delay) begin
                        phase <= WID;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                WID: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_width) begin
                        phase <= IDLE;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assign pulse = (phase == WID);
    assign busy  = (phase != IDLE);

    // Precedence: a pulse now implies the trigger came more than 'delay' cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig > {2'b00, snap_delay});

    // Precedence: a pulse now implies the trigger came no more than delay+width+1 cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig <= {2'b00, snap_delay} + {2'b00, snap_width} + 34'd1);
endmodule

module bfx_unit (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [2:0] i_op,
    input  wire       i_lock,
    input  wire       i_unlock,
    input  wire [7:0] i_src,
    input  wire [7:0] i_dst,
    output wire [7:0] o_res
);
    // field control: start position, width, and remaining headroom above the field
    reg [7:0] pos;
    reg [7:0] wid;
    reg [7:0] rem;
    reg [7:0] res;
    reg       win;
    initial pos = 8'd0;
    initial wid = 8'd0;
    initial rem = 8'd8;
    initial res = 8'd0;
    initial win = 1'b0;

    localparam OP_GROW = 3'd0, OP_SHRINK = 3'd1, OP_ADV = 3'd2, OP_RET = 3'd3,
               OP_EXTZ = 3'd4, OP_EXTS = 3'd5, OP_INS = 3'd6, OP_NOP = 3'd7;

    wire [7:0] mask = (wid >= 8'd8) ? 8'hFF : ((8'd1 << wid) - 8'd1);
    wire [7:0] ext  = (i_src >> pos) & mask;
    wire       sbit = ((wid != 8'd0) && (wid < 8'd8)) ? ext[wid[2:0] - 3'd1] : 1'b0;
    wire [7:0] exts = sbit ? (ext | ~mask) : ext;
    wire [7:0] ins  = (i_dst & ~(mask << pos)) | ((i_src & mask) << pos);

    always @(posedge clk) begin
        if (i_reset) begin
            pos <= 8'd0;
            wid <= 8'd0;
            rem <= 8'd8;
            res <= 8'd0;
            win <= 1'b0;
        end else if (i_ce) begin
            if (i_unlock)
                win <= 1'b0;
            else if (i_lock)
                win <= 1'b1;
            case (i_op)
                OP_GROW:   if (rem != 8'd0) begin wid <= wid + 8'd1; rem <= rem - 8'd1; end
                OP_SHRINK: if (wid != 8'd0) begin wid <= wid - 8'd1; rem <= rem + 8'd1; end
                OP_ADV:    if (rem != 8'd0) begin pos <= pos + 8'd1; rem <= rem - 8'd1; end
                OP_RET:    if (pos != 8'd0) begin pos <= pos - 8'd1; rem <= rem + 8'd1; end
                OP_EXTZ:   res <= ext;
                OP_EXTS:   res <= exts;
                OP_INS:    res <= ins;
                default:   ;
            endcase
        end
    end

    assign o_res = res;

    // between lock and unlock: field width never exceeds the word size
    always @(posedge clk)
        if (win) assert (wid <= 8'd8);
endmodule

module usb_stream_writer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire ack,
    input wire s_valid,
    input wire s_last,
    input wire [31:0] s_data,
    input wire trig_arm,
    input wire trig_disarm,
    output wire busy,
    output wire full,
    output wire [31:0] o_pkt_len,
    output wire o_eop
);
    parameter DEPTH = 16;
    parameter AW = 4;
    parameter DW = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, CAPTURE = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [DW-1:0] byte_cnt = {DW{1'b0}};
    reg [DW-1:0] pkt_len = {DW{1'b0}};
    reg eop = 1'b0;
    reg win = 1'b0;
    reg [DW-1:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    assign busy = (state == CAPTURE);
    assign full = (byte_cnt == DEPTH);
    assign o_pkt_len = pkt_len;
    assign o_eop = eop;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            wr_ptr <= {AW{1'b0}};
            byte_cnt <= {DW{1'b0}};
            pkt_len <= {DW{1'b0}};
            eop <= 1'b0;
            win <= 1'b0;
        end else if (ce) begin
            if (trig_arm)
                win <= 1'b1;
            else if (trig_disarm)
                win <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= CAPTURE;
                        wr_ptr <= {AW{1'b0}};
                        byte_cnt <= {DW{1'b0}};
                        eop <= 1'b0;
                    end
                end
                CAPTURE: begin
                    if (s_valid) begin
                        mem[wr_ptr] <= s_data;
                        wr_ptr <= wr_ptr + 1'b1;
                        byte_cnt <= byte_cnt + 1;
                        if (s_last || (wr_ptr == DEPTH-1)) begin
                            state <= DONE;
                            pkt_len <= byte_cnt + 1;
                            eop <= s_last;
                        end
                    end
                end
                DONE: begin
                    if (ack)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(*)
        if (win) assert (!(busy && full));
endmodule

module jls_remap_lut (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_v,
    input wire [63:0] wdata,
    input wire new_frame,
    input wire pix_v,
    input wire [4:0] pix_idx,
    output reg [63:0] out_q
);
    localparam [63:0] DEPTH = 64'd24;
    localparam [63:0] LAST  = 64'd23;

    reg [63:0] mem [0:23];
    reg [63:0] wp;
    reg full_q, empty_q, load_own, map_own, armed;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 64'd0;
        wp = 64'd0;
        full_q = 1'b0;
        empty_q = 1'b1;
        load_own = 1'b1;
        map_own = 1'b0;
        armed = 1'b0;
        out_q = 64'd0;
    end

    wire [4:0] sidx = (pix_idx > 5'd23) ? 5'd23 : pix_idx;
    wire do_wr = wr_v && load_own && (wp < DEPTH);

    always @(posedge clk) begin
        if (rst) begin
            wp <= 64'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
            load_own <= 1'b1;
            map_own <= 1'b0;
            armed <= 1'b0;
            out_q <= 64'd0;
        end else if (en) begin
            if (new_frame) begin
                wp <= 64'd0;
                empty_q <= 1'b1;
                full_q <= 1'b0;
                load_own <= 1'b1;
                map_own <= 1'b0;
            end else if (do_wr) begin
                mem[wp[4:0]] <= wdata;
                wp <= wp + 64'd1;
                empty_q <= empty_q && (wp != 64'd0);
                full_q <= full_q || (wp == LAST);
                load_own <= load_own && (wp != LAST);
                map_own <= map_own || (wp == LAST);
                if (wp == LAST) armed <= 1'b1;
            end
            if (pix_v && map_own)
                out_q <= mem[sidx];
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!(full_q && empty_q));

    always @(posedge clk)
        if (armed)
            assert (!(load_own && map_own));
endmodule

module chipkill_decoder (
    input wire clk,
    input wire i_ce,
    input wire i_scrub,
    input wire [31:0] i_data,
    input wire [31:0] i_chk,
    output wire [31:0] o_data,
    output wire o_uncorr,
    output wire o_fail_valid,
    output wire [1:0] o_fail_id
);
    reg [31:0] syn;
    reg [31:0] dat;
    reg [3:0] fail_oh;
    reg [1:0] fail_id;
    reg fail_valid;
    reg uncorr;
    reg armed;
    initial begin
        syn = 32'h0; dat = 32'h0; fail_oh = 4'd0; fail_id = 2'd0;
        fail_valid = 1'b0; uncorr = 1'b0; armed = 1'b0;
    end

    wire [31:0] s = i_data ^ i_chk;
    wire e0 = |s[7:0];
    wire e1 = |s[15:8];
    wire e2 = |s[23:16];
    wire e3 = |s[31:24];
    wire [2:0] nerr = {2'b00, e0} + {2'b00, e1} + {2'b00, e2} + {2'b00, e3};
    wire [1:0] c = e3 ? 2'd3 : (e2 ? 2'd2 : (e1 ? 2'd1 : 2'd0));
    wire any_err = (nerr != 3'd0);
    wire mark = !fail_valid && (nerr == 3'd1);
    wire bad = (nerr > 3'd1) || (fail_valid && (nerr == 3'd1) && (c != fail_id));

    always @(posedge clk) begin
        if (i_scrub) begin
            syn <= 32'h0;
            fail_oh <= 4'd0;
            fail_id <= 2'd0;
            fail_valid <= 1'b0;
            uncorr <= 1'b0;
        end else if (i_ce) begin
            syn <= s;
            dat <= i_data;
            if (any_err) armed <= 1'b1;
            if (mark) begin
                fail_valid <= 1'b1;
                fail_id <= c;
                fail_oh <= fail_oh | (4'd1 << c);
            end
            if (bad) uncorr <= 1'b1;
        end
    end

    wire [31:0] chip_mask = fail_valid ? (32'h000000FF << {fail_id, 3'b000}) : 32'h0;
    assign o_data = dat ^ (syn & chip_mask);
    assign o_uncorr = uncorr;
    assign o_fail_valid = fail_valid;
    assign o_fail_id = fail_id;

    always @(posedge clk)
        if (armed)
            assert ((fail_oh & (fail_oh - 4'd1)) == 4'd0);
endmodule

module aes_keyexp64 #(
    parameter [63:0] NR = 64'd10
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    output wire         s_ready,
    input  wire [255:0] s_key,
    input  wire         step,
    output reg          m_valid,
    input  wire         m_ready,
    output wire [255:0] m_key,
    output wire [63:0]  m_round
);
    reg [63:0] kw0, kw1, kw2, kw3;
    reg [63:0] round;
    reg [63:0] countdown;
    reg        busy;
    reg        armed;

    initial begin
        kw0 = 64'd0; kw1 = 64'd0; kw2 = 64'd0; kw3 = 64'd0;
        round = 64'd0;
        countdown = 64'd0;
        busy = 1'b0;
        armed = 1'b0;
        m_valid = 1'b0;
    end

    assign s_ready = !busy;
    wire accept = s_valid && s_ready;
    wire adv    = busy && armed && step;

    wire [63:0] rcon = 64'h1 << round[5:0];
    wire [63:0] g    = {kw3[55:0], kw3[63:56]} ^ rcon;
    wire [63:0] n0   = kw0 ^ g;
    wire [63:0] n1   = kw1 ^ n0;
    wire [63:0] n2   = kw2 ^ n1;
    wire [63:0] n3   = kw3 ^ n2;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            armed     <= 1'b0;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= 64'd0;
        end else if (accept) begin
            busy      <= 1'b1;
            armed     <= 1'b1;
            m_valid   <= 1'b0;
            round     <= 64'd0;
            countdown <= NR;
            kw0 <= s_key[63:0];
            kw1 <= s_key[127:64];
            kw2 <= s_key[191:128];
            kw3 <= s_key[255:192];
        end else if (adv) begin
            round     <= round + 64'd1;
            countdown <= countdown - 64'd1;
            kw0 <= n0;
            kw1 <= n1;
            kw2 <= n2;
            kw3 <= n3;
            if (round + 64'd1 == NR) begin
                armed   <= 1'b0;
                m_valid <= 1'b1;
            end
        end else if (m_valid && m_ready) begin
            m_valid <= 1'b0;
            busy    <= 1'b0;
        end
    end

    assign m_key   = {kw3, kw2, kw1, kw0};
    assign m_round = round;

    assert property (!armed || countdown != 64'd0);
endmodule

module orbit_mrs_unit (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        req_valid,
    input  wire [2:0]  req_idx,
    input  wire [15:0] req_data,
    input  wire        cfg_lock,
    output wire        busy,
    output reg         mrs_cmd_valid,
    output reg  [18:0] mrs_cmd
);
    reg [15:0] shadow [0:7];
    reg [7:0]  pend;
    reg [2:0]  cur_idx;
    reg [15:0] cur_data;
    reg [15:0] cnt;
    reg        win;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) shadow[i] = 16'd0;
        pend = 8'd0;
        cur_idx = 3'd0;
        cur_data = 16'd0;
        cnt = 16'd0;
        win = 1'b0;
        mrs_cmd_valid = 1'b0;
        mrs_cmd = 19'd0;
    end

    assign busy = |pend;

    wire accept   = req_valid && !busy;
    wire countdn  = busy && (cnt > 16'd1);
    wire complete = busy && (cnt == 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) shadow[i] <= 16'd0;
            pend <= 8'd0;
            cur_idx <= 3'd0;
            cur_data <= 16'd0;
            cnt <= 16'd0;
            win <= 1'b0;
            mrs_cmd_valid <= 1'b0;
            mrs_cmd <= 19'd0;
        end else if (en) begin
            mrs_cmd_valid <= 1'b0;
            if (accept) begin
                pend[req_idx] <= 1'b1;
                cur_idx <= req_idx;
                cur_data <= req_data;
                cnt <= 16'd8;
                mrs_cmd_valid <= 1'b1;
                mrs_cmd <= {req_idx, req_data};
            end else if (countdn) begin
                cnt <= cnt - 16'd1;
            end else if (complete) begin
                for (i = 0; i < 8; i = i + 1)
                    if (cur_idx == i[2:0]) shadow[i] <= cur_data;
                pend[cur_idx] <= 1'b0;
                cnt <= 16'd0;
            end
            if (accept)
                win <= 1'b1;
            else if (cfg_lock)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy) assert (cnt != 16'd0);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
output wire [W-1:0] q_mag,
input  wire         peer_in_valid,
output wire         peer_in_ready,
input  wire [W-1:0] peer_in_mag,
output wire         peer_out_valid,
input  wire         peer_out_ready,
output wire [W-1:0] peer_out_min1,
output wire [W-1:0] peer_out_min2,
input  wire         aux_in_valid,
output wire         aux_in_ready,
input  wire [W-1:0] aux_in_mag,
input  wire         aux_in_sign,
output wire         aux_out_valid,
input  wire         aux_out_ready,
output wire [W-1:0] aux_out_min1,
output wire [W-1:0] aux_out_min2,
output wire         aux_out_sign
);
localparam CHANNELS = 3, MINIMA = 2, PEER_CW = (DEG > 1) ? $clog2(DEG) : 1;
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

reg [W-1:0] minima [0:CHANNELS*MINIMA-1];
wire [W-1:0] min1 = minima[0], min2 = minima[1];
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
integer mi;
initial for (mi = 0; mi < CHANNELS*MINIMA; mi = mi + 1) minima[mi] = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
reg [PEER_CW-1:0] peer_count;
reg peer_done;
reg owner_peer;
initial begin peer_count = 0; peer_done = 0; owner_peer = 1; end
reg [PEER_CW-1:0] aux_count;
reg aux_done, aux_owner, aux_sign_prod;
initial begin
    aux_count = 0;
    aux_done = 0;
    aux_owner = 1;
    aux_sign_prod = 0;
end
wire frames_idle = (count == 0) && (peer_count == 0);
wire all_frames_idle = frames_idle && (aux_count == 0);
wire pair_request = (in_valid && state == S_ACCUM) ||
                    (peer_in_valid && !peer_done);
wire select_aux = all_frames_idle ?
    (aux_in_valid && !aux_done && (!pair_request || !aux_owner)) : aux_owner;
wire select_peer = frames_idle ? (peer_in_valid && !peer_done && (!in_valid || state != S_ACCUM || !owner_peer)) : owner_peer;
assign peer_in_ready = select_peer && !peer_done && !select_aux;
assign aux_in_ready = select_aux && !aux_done;
wire peer_acc = peer_in_valid && peer_in_ready;
wire aux_acc = aux_in_valid && aux_in_ready;
wire [W-1:0] cmp_mag = select_aux ? aux_in_mag :
                          (select_peer ? peer_in_mag : in_mag);
wire [W-1:0] cmp_min1 = select_aux ? minima[2*MINIMA] :
                           (select_peer ? minima[MINIMA] : min1);
wire [W-1:0] cmp_min2 = select_aux ? minima[2*MINIMA+1] :
                           (select_peer ? minima[MINIMA+1] : min2);
wire new_first = cmp_mag < cmp_min1;
wire [W-1:0] step_min1 = new_first ? cmp_mag : cmp_min1;
wire [W-1:0] step_min2 = new_first ? cmp_min1 : ((cmp_mag < cmp_min2) ? cmp_mag : cmp_min2);
assign peer_out_valid = peer_done;
assign peer_out_min1 = minima[MINIMA], peer_out_min2 = minima[MINIMA+1];
assign aux_out_valid = aux_done;
assign aux_out_min1 = minima[2*MINIMA];
assign aux_out_min2 = minima[2*MINIMA+1];
assign aux_out_sign = aux_sign_prod;

assign in_ready  = (state == S_ACCUM) && !select_peer && !select_aux;
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;
wire [CHANNELS-1:0] lane_acc = {aux_acc, peer_acc, acc};
wire [CHANNELS-1:0] lane_rel = {aux_out_valid && aux_out_ready,
                              peer_out_valid && peer_out_ready, rel};
integer lane;
always @(posedge clk) begin
    for (lane = 0; lane < CHANNELS; lane = lane + 1) begin
        if (lane_acc[lane] || lane_rel[lane]) begin
            minima[lane*MINIMA] <= lane_acc[lane] ? step_min1 : {W{1'b1}};
            minima[lane*MINIMA+1] <= lane_acc[lane] ? step_min2 : {W{1'b1}};
        end
    end
    if (acc || peer_acc) owner_peer <= select_peer;
    if (acc || peer_acc || aux_acc) aux_owner <= select_aux;
    if (peer_acc) begin
        if (peer_count == DEG - 1) begin peer_count <= 0; peer_done <= 1; end
        else peer_count <= peer_count + 1'b1;
    end else if (lane_rel[1]) peer_done <= 0;
end
always @(posedge clk) begin
    if (aux_acc) begin
        aux_sign_prod <= aux_sign_prod ^ aux_in_sign;
        if (aux_count == DEG - 1) begin
            aux_count <= 0;
            aux_done <= 1;
        end else begin
            aux_count <= aux_count + 1'b1;
        end
    end else if (lane_rel[2]) begin
        aux_done <= 0;
        aux_sign_prod <= 0;
    end
end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
if (new_first) min_idx <= count;
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
always @(posedge clk) if (pv) assert ((count == 0) || (peer_count == 0));
always @(posedge clk) if (pv) assert ((aux_count == 0) || ((count == 0) && (peer_count == 0)));
endmodule

module vend_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       coin_valid,
    input  wire [7:0] coin_val,
    input  wire       select,
    input  wire       cancel,
    output wire       vend,
    output wire       change_ret,
    output wire [7:0] change_out
);
    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_COLLECT = 2'd1;
    localparam [1:0] S_VEND    = 2'd2;
    localparam [1:0] S_CHANGE  = 2'd3;
    localparam [7:0] PRICE     = 8'd75;

    reg [1:0] state;
    reg [7:0] credit;
    reg [7:0] change_amt;
    reg       vend_r;
    reg       chg_r;
    reg       pv;
    initial begin
        state = S_IDLE; credit = 8'd0; change_amt = 8'd0;
        vend_r = 1'b0; chg_r = 1'b0; pv = 1'b0;
    end

    wire [8:0] sum     = {1'b0, credit} + {1'b0, coin_val};
    wire [7:0] sat_sum = sum[8] ? 8'd255 : sum[7:0];

    assign vend       = vend_r;
    assign change_ret = chg_r;
    assign change_out = change_amt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; credit <= 8'd0; change_amt <= 8'd0;
            vend_r <= 1'b0; chg_r <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (coin_valid) begin
                        credit <= sat_sum;
                        state  <= S_COLLECT;
                    end
                end
                S_COLLECT: begin
                    if (select && credit >= PRICE) begin
                        credit <= credit - PRICE;
                        state  <= S_VEND;
                        vend_r <= 1'b1;
                    end else if (cancel) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else if (coin_valid) begin
                        credit <= sat_sum;
                    end
                end
                S_VEND: begin
                    vend_r <= 1'b0;
                    if (credit != 8'd0) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_CHANGE: begin
                    chg_r      <= 1'b0;
                    change_amt <= 8'd0;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && $rose(vend_r))
            assert (!chg_r);
endmodule

module mmio_router_tmo (
    input wire clk,
    input wire en,
    input wire cfg_we,
    input wire [5:0] cfg_idx,
    input wire [63:0] cfg_base,
    input wire [63:0] cfg_limit,
    input wire req,
    input wire [63:0] req_addr,
    input wire win_clr,
    output wire o_busy,
    output wire o_win,
    output wire [5:0] o_sel
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base  [0:63];
    reg [63:0] limit [0:63];
    reg        busy;
    reg        win;
    reg [5:0]  sel;
    reg [63:0] cnt;
    reg [63:0] age;

    integer i;
    initial begin
        busy = 1'b0;
        win  = 1'b0;
        sel  = 6'd0;
        cnt  = 64'd0;
        age  = 64'd0;
        for (i = 0; i < 64; i = i + 1) begin
            base[i]  = 64'd0;
            limit[i] = 64'd0;
        end
    end

    reg       hit;
    reg [5:0] hidx;
    integer j;
    always @(*) begin
        hit  = 1'b0;
        hidx = 6'd0;
        for (j = 63; j >= 0; j = j - 1) begin
            if ((base[j] <= req_addr) && (req_addr <= limit[j])) begin
                hit  = 1'b1;
                hidx = j[5:0];
            end
        end
    end

    wire accept = req && hit && !busy;

    always @(posedge clk) begin
        if (en) begin
            if (cfg_we) begin
                base[cfg_idx]  <= cfg_base;
                limit[cfg_idx] <= cfg_limit;
            end
            if (win_clr)
                win <= 1'b0;
            else if (accept)
                win <= 1'b1;
            if (busy) begin
                if (age == K - 64'd1) begin
                    busy <= 1'b0;
                    cnt  <= 64'd0;
                    age  <= 64'd0;
                end else begin
                    cnt <= cnt - 64'd1;
                    age <= age + 64'd1;
                end
            end else if (accept) begin
                busy <= 1'b1;
                sel  <= hidx;
                cnt  <= K;
                age  <= 64'd0;
            end
        end
    end

    assign o_busy = busy;
    assign o_win  = win;
    assign o_sel  = sel;

    always @(posedge clk)
        if (win && busy)
            assert (cnt != 64'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cnt <= K);
endmodule

module ptw_walker (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire [15:0] i_va,
    input  wire [15:0] i_root,
    input  wire        i_mem_valid,
    input  wire [15:0] i_mem_data,
    input  wire        i_ack,
    output wire        o_mem_req,
    output wire [15:0] o_mem_addr,
    output wire        o_done,
    output wire        o_fault,
    output wire [15:0] o_pa
);
    localparam [1:0]  S_IDLE = 2'd0;
    localparam [1:0]  S_WALK = 2'd1;
    localparam [1:0]  S_DONE = 2'd2;
    localparam [15:0] LAST_LVL = 16'd3;

    reg [1:0]  state   = S_IDLE;
    reg [15:0] lvl     = 16'd0;
    reg [15:0] reads   = 16'd0;
    reg [15:0] desc    = 16'd0;
    reg [15:0] va      = 16'd0;
    reg [15:0] walk_id = 16'd0;
    reg        fault   = 1'b0;
    reg        armed   = 1'b0;
    reg        pv      = 1'b0;

    wire [3:0] idx = (lvl == 16'd0) ? va[15:12] :
                     (lvl == 16'd1) ? va[11:8]  :
                     (lvl == 16'd2) ? va[7:4]   : va[3:0];

    assign o_mem_req  = (state == S_WALK);
    assign o_mem_addr = {desc[15:4], idx};
    assign o_done     = (state == S_DONE);
    assign o_fault    = fault;
    assign o_pa       = {desc[15:4], va[3:0]};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            fault <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state   <= S_WALK;
                        lvl     <= 16'd0;
                        reads   <= 16'd0;
                        desc    <= i_root;
                        va      <= i_va;
                        walk_id <= walk_id + 16'd1;
                        fault   <= 1'b0;
                        armed   <= 1'b1;
                    end
                end
                S_WALK: begin
                    if (i_mem_valid) begin
                        reads <= reads + 16'd1;
                        desc  <= i_mem_data;
                        if (!i_mem_data[0] || (!i_mem_data[1] && lvl == LAST_LVL)) begin
                            fault <= 1'b1;
                            state <= S_DONE;
                        end else if (i_mem_data[1]) begin
                            state <= S_DONE;
                        end else begin
                            lvl <= lvl + 16'd1;
                        end
                    end
                end
                S_DONE: begin
                    if (i_ack) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (armed && pv && $stable(walk_id) && $past(reads) >= 16'd4)
            assert ($stable(reads));
endmodule

// 2x4 block interleaver: symbols written row-wise, read column-wise.
// 8 entries of 64-bit words, 64-bit write and read index counters.
module block_interleaver_ki (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire [63:0] i_sym,
    output wire [63:0] o_sym,
    output wire        o_valid
);
    // storage: 8 entries, 64-bit symbols
    reg [63:0] mem [0:7];

    // row-wise write index and column-wise read index (64-bit counters)
    reg [63:0] wr_cnt;
    reg [63:0] rd_cnt;

    // 0 = filling the block row-wise, 1 = draining the block column-wise
    reg        phase;

    // per-entry occupancy mask
    reg [7:0]  filled;

    integer idx;
    initial begin
        wr_cnt = 64'd0;
        rd_cnt = 64'd0;
        phase  = 1'b0;
        filled = 8'h00;
        for (idx = 0; idx < 8; idx = idx + 1)
            mem[idx] = 64'd0;
    end

    // row-wise write address
    wire [2:0] wr_addr = wr_cnt[2:0];

    // column-wise read address: k = c*2 + r  ->  addr = r*4 + c
    // which is a one-bit rotation of the 3-bit read index
    wire [2:0] rd_addr = { rd_cnt[0], rd_cnt[2:1] };

    always @(posedge i_clk) begin
        if (i_reset) begin
            wr_cnt <= 64'd0;
            rd_cnt <= 64'd0;
            phase  <= 1'b0;
            filled <= 8'h00;
        end else if (i_ce) begin
            if (phase == 1'b0) begin
                mem[wr_addr]    <= i_sym;
                filled[wr_addr] <= 1'b1;
                if (wr_cnt == 64'd7) begin
                    wr_cnt <= 64'd0;
                    rd_cnt <= 64'd0;
                    phase  <= 1'b1;
                end else begin
                    wr_cnt <= wr_cnt + 64'd1;
                end
            end else begin
                filled[rd_addr] <= 1'b0;
                if (rd_cnt == 64'd7) begin
                    rd_cnt <= 64'd0;
                    wr_cnt <= 64'd0;
                    phase  <= 1'b0;
                end else begin
                    rd_cnt <= rd_cnt + 64'd1;
                end
            end
        end
    end

    assign o_sym   = mem[rd_addr];
    assign o_valid = (phase == 1'b1);

    // P: whenever the interleaver is draining, the entry currently addressed
    // by the column-wise read pointer is an entry that has been written.
    always @(*)
        assert (phase == 1'b0 || filled[rd_addr]);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
    if (cnt != K) begin
        cnt <= cnt + 3'd1;
        if (cnt == K - 3'd1) begin
            // stage the commit; the flag and output move one step later
            cmt_pend <= 1'b1;
            cmt_val  <= samp;
        end
    end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == K with nothing staged: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
                idx <= idx + 2'd1;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module burst_addr_gen (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] i_base,
    input  wire [63:0] i_beats,
    output wire [63:0] o_addr,
    output wire        o_valid,
    output wire        o_last
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base       = 64'd0;
    reg [63:0] idx        = 64'd0;
    reg [63:0] beats      = 64'd0;
    reg [63:0] beats_left = 64'd0;
    reg        busy       = 1'b0;
    reg        win        = 1'b0;

    assign o_addr  = base + (idx << 3);
    assign o_valid = busy;
    assign o_last  = busy && (idx == beats - 64'd1);

    wire accept = req && !busy && (i_beats >= 64'd1) && (i_beats <= K);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                base       <= i_base;
                idx        <= 64'd0;
                beats      <= i_beats;
                beats_left <= i_beats;
                busy       <= 1'b1;
                win        <= 1'b1;
            end else if (busy) begin
                idx        <= idx + 64'd1;
                beats_left <= beats_left - 64'd1;
                busy       <= (idx != beats - 64'd1);
            end
        end
    end

    always @(*) begin
        if (win && busy)
            assert (beats_left != 64'd0);
    end
endmodule

module bar_req_queue #(
    parameter DEPTH = 8,
    parameter AW = 3
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    output wire       in_ready,
    input  wire [7:0] in_addr,
    output wire       out_valid,
    input  wire       out_ready,
    output wire [7:0] out_addr,
    input  wire       irq_on_done,
    input  wire       host_wr,
    input  wire       host_wdata,
    output wire       irq
);
    localparam [7:0] CAP = DEPTH;

    reg [7:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = 0;
    reg [AW-1:0] rptr = 0;
    reg [7:0] count = 8'd0;
    reg [7:0] credits = CAP;
    reg irq_pend = 1'b0;
    reg armed = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = 8'd0;
    end

    assign in_ready  = (credits != 8'd0);
    assign out_valid = (count != 8'd0);
    assign out_addr  = mem[rptr];
    assign irq       = irq_pend;

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    // request storage and credit accounting
    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0;
            rptr <= 0;
            count <= 8'd0;
            credits <= CAP;
        end else begin
            if (in_fire) begin
                mem[wptr] <= in_addr;
                wptr <= wptr + 1'b1;
            end
            if (out_fire) rptr <= rptr + 1'b1;
            case ({in_fire, out_fire})
                2'b10: begin count <= count + 8'd1; credits <= credits - 8'd1; end
                2'b01: begin count <= count - 8'd1; credits <= credits + 8'd1; end
                default: begin count <= count; credits <= credits; end
            endcase
        end
    end

    // dual-port latch: completion port and host port both write the shared pending bit
    wire en_a = out_fire;
    wire d_a  = irq_on_done;
    wire en_b = host_wr;
    wire d_b  = host_wdata;
    always @(posedge clk) begin
        if (rst)       irq_pend <= 1'b0;
        else if (en_a) irq_pend <= d_a;
        else if (en_b) irq_pend <= d_b;
        else           irq_pend <= irq_pend;
    end

    // after-Q scope: armed by the first accepted request, never cleared
    always @(posedge clk) begin
        if (in_fire) armed <= 1'b1;
    end

    always @(posedge clk) if (armed) assert (count <= CAP);
    always @(posedge clk) if (armed) assert (credits <= CAP);
endmodule

module tb_drv_demux (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire         i_req,
    input  wire [3:0]   i_sel,
    input  wire [15:0]  i_data,
    output wire [255:0] o_bus,
    output wire         o_busy
);
    localparam [15:0] K = 16'd8;

    reg [3:0]   sel_r;
    reg [15:0]  data_r;
    reg [255:0] out_q;
    reg         pending;
    reg [15:0]  cnt;
    reg [15:0]  ph;

    initial sel_r   = 4'd0;
    initial data_r  = 16'd0;
    initial out_q   = 256'd0;
    initial pending = 1'b0;
    initial cnt     = 16'd0;
    initial ph      = 16'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            sel_r   <= 4'd0;
            data_r  <= 16'd0;
            out_q   <= 256'd0;
            pending <= 1'b0;
            cnt     <= 16'd0;
            ph      <= 16'd0;
        end else if (i_ce) begin
            if (!pending) begin
                if (i_req) begin
                    pending <= 1'b1;
                    sel_r   <= i_sel;
                    data_r  <= i_data;
                    cnt     <= K;
                    ph      <= 16'd0;
                end
            end else begin
                if (ph == K - 16'd1) begin
                    out_q[sel_r*16 +: 16] <= data_r;
                    pending <= 1'b0;
                    cnt     <= 16'd0;
                    ph      <= 16'd0;
                end else begin
                    ph  <= ph + 16'd1;
                    cnt <= cnt - 16'd1;
                end
            end
        end
    end

    assign o_bus  = out_q;
    assign o_busy = pending;

    assert property (!pending || cnt != 16'd0);
endmodule

// Stack pointer with a ratcheting high-water mark, plus a three-step
// arm -> start -> finish transaction FSM whose start step needs live data
// on the stack.
module hwm_chain_precedence (
    input  wire clk,
    input  wire ce,
    input  wire i_push,
    input  wire i_pop,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_finish,
    input  wire i_clear,
    output wire o_finish,
    output wire [3:0] o_mark
);
    localparam [3:0] DEPTH = 4'd8;

    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_ARMED   = 2'd1;
    localparam [1:0] S_STARTED = 2'd2;
    localparam [1:0] S_DONE    = 2'd3;

    reg [3:0] sp;
    reg [3:0] hwm;      // high-water mark: never below sp, only ratchets up
    reg [1:0] stage;
    reg       saw_arm;
    reg       saw_start;
    reg       obs_en;    // sticky: set the first cycle a push is accepted

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial stage     = S_IDLE;
    initial saw_arm   = 1'b0;
    initial saw_start = 1'b0;
    initial obs_en    = 1'b0;

    wire do_push = ce && i_push && !i_pop && (sp <  DEPTH);
    wire do_pop  = ce && i_pop  && !i_push && (sp != 4'd0);

    wire [4:0] nxt_sp = {1'b0, sp} + 5'd1;

    // ---- stack pointer and high-water mark -------------------------------
    always @(posedge clk) begin
        if (do_push) begin
            sp     <= sp + 4'd1;
            obs_en <= 1'b1;
            if (nxt_sp > {1'b0, hwm})
                hwm <= nxt_sp[3:0];
        end else if (do_pop) begin
            sp <= sp - 4'd1;
        end
    end

    // ---- three-step chain: arm, then start, then finish ------------------
    always @(posedge clk) begin
        if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (i_arm) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_start && (sp != 4'd0)) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                end
                S_STARTED: begin
                    if (i_finish && (sp != 4'd0))
                        stage <= S_DONE;
                end
                default: begin
                    if (i_clear)
                        stage <= S_IDLE;
                end
            endcase
        end
    end

    assign o_finish = (stage == S_DONE);
    assign o_mark   = hwm;

    // Property: once the mark has been armed by a first push, a finish can
    // never be observed unless arm and start were both observed before it and
    // the high-water mark records that data was really on the stack.
    assert property (!obs_en || !o_finish ||
                     (saw_arm && saw_start && (hwm >= 4'd1)));
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage (committed in pairs)
output reg         ret_pend    // one retirement banked, not yet committed to n_acc_out
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
initial ret_pend  = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == (n_acc_out + {3'd0, ret_pend})));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
// retirements are banked in a half-slot and committed to the ledger in pairs;
// an idle cycle flushes a lone banked retirement
if (hit_q || miss_q) begin
    if (ret_pend) begin
        n_acc_out <= n_acc_out + 4'd2;
        ret_pend  <= 1'b0;
    end else
        ret_pend  <= 1'b1;
end else if (ret_pend) begin
    n_acc_out <= n_acc_out + 4'd1;
    ret_pend  <= 1'b0;
end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
        end else if (ce && !done) begin
            nchars <= nchars + 4'd1;
            if (ch_match)
                nmatch <= nmatch + 4'd1;
        end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule

module ecc_err_logger (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sw_arm,
    input wire err_valid,
    input wire err_ue,
    input wire [31:0] err_syn,
    input wire [31:0] err_addr,
    input wire sw_ack
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, CAPT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] syn_q, addr_q;
    reg        type_q;
    reg [31:0] ce_cnt, ue_cnt;
    reg [31:0] log_mem [0:127];
    reg [6:0]  wp;
    reg        arm_seen, start_seen, fin_seen;

    integer i;
    initial begin
        phase = IDLE;
        syn_q = 32'd0;
        addr_q = 32'd0;
        type_q = 1'b0;
        ce_cnt = 32'd0;
        ue_cnt = 32'd0;
        wp = 7'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        fin_seen = 1'b0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            syn_q <= 32'd0;
            addr_q <= 32'd0;
            type_q <= 1'b0;
            ce_cnt <= 32'd0;
            ue_cnt <= 32'd0;
            wp <= 7'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            fin_seen <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE, DONE: begin
                    if (sw_arm) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (err_valid) begin
                        phase <= CAPT;
                        start_seen <= 1'b1;
                        syn_q <= err_syn;
                        addr_q <= err_addr;
                        type_q <= err_ue;
                        if (err_ue) begin
                            if (ue_cnt != 32'hFFFFFFFF) ue_cnt <= ue_cnt + 32'd1;
                        end else begin
                            if (ce_cnt != 32'hFFFFFFFF) ce_cnt <= ce_cnt + 32'd1;
                        end
                        log_mem[wp] <= err_addr;
                        wp <= wp + 7'd1;
                    end
                end
                CAPT: begin
                    if (sw_ack) begin
                        phase <= DONE;
                        fin_seen <= 1'b1;
                    end
                end
                default: phase <= phase;
            endcase
        end
    end

    assert property (!fin_seen || (start_seen && arm_seen));
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
endmodule

module bayer_tile_demosaic (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire [63:0] pix_in,
    output reg [63:0] rgb_r,
    output reg [63:0] rgb_g,
    output reg [63:0] rgb_b,
    output reg done
);
    reg [63:0] tile [0:15];
    reg [63:0] idx;
    reg [63:0] cd;
    reg busy;
    reg [1:0] phase;
    reg win;
    reg pv;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1) tile[k] = 64'd0;
        idx = 64'd0;
        cd = 64'd0;
        busy = 1'b0;
        phase = 2'b00;
        win = 1'b0;
        pv = 1'b0;
        rgb_r = 64'd0;
        rgb_g = 64'd0;
        rgb_b = 64'd0;
        done = 1'b0;
    end

    wire [3:0] i0 = idx[3:0];
    wire [3:0] im = i0 - 4'd1;
    wire [3:0] ip = i0 + 4'd1;
    wire [63:0] c_px = tile[i0];
    wire [63:0] l_px = tile[im];
    wire [63:0] r_px = tile[ip];
    wire [63:0] avg = (l_px >> 1) + (r_px >> 1);
    wire [63:0] diag = (l_px >> 2) + (r_px >> 2) + (c_px >> 1);

    reg [63:0] nr, ng, nb;
    always @(*) begin
        case (phase)
            2'b00: begin nr = c_px; ng = avg;  nb = diag; end
            2'b01: begin nr = avg;  ng = c_px; nb = diag; end
            2'b10: begin nr = diag; ng = c_px; nb = avg;  end
            default: begin nr = diag; ng = avg; nb = c_px; end
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1) tile[k] <= 64'd0;
            idx <= 64'd0;
            cd <= 64'd0;
            busy <= 1'b0;
            phase <= 2'b00;
            win <= 1'b0;
            rgb_r <= 64'd0;
            rgb_g <= 64'd0;
            rgb_b <= 64'd0;
            done <= 1'b0;
        end else if (en) begin
            if (start && !busy) begin
                busy <= 1'b1;
                win <= 1'b1;
                idx <= 64'd0;
                cd <= 64'd16;
                phase <= 2'b00;
                done <= 1'b0;
            end else if (busy) begin
                tile[i0] <= pix_in;
                rgb_r <= nr;
                rgb_g <= ng;
                rgb_b <= nb;
                idx <= idx + 64'd1;
                cd <= cd - 64'd1;
                phase[0] <= ~phase[0];
                if (i0[1:0] == 2'b11) phase[1] <= ~phase[1];
                if (idx == 64'd15) begin
                    busy <= 1'b0;
                    win <= 1'b0;
                    done <= 1'b1;
                end else begin
                    done <= 1'b0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(win) && $past(busy))
            assert ($past(cd) != 64'd0);
endmodule

module farrow_apb_bridge (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire hwr,
    input wire [31:0] hwdata,
    input wire hmu_wr,
    input wire [31:0] hmu,
    input wire pread,
    output wire [31:0] prdata
);
    reg [31:0] x0, x1, x2, x3;
    reg [31:0] c0, c1, c2, c3;
    reg [31:0] mu;
    reg [31:0] fill_cnt;
    reg out_valid;
    reg [31:0] y;
    reg hist_wr;

    initial begin
        x0 = 32'd0; x1 = 32'd0; x2 = 32'd0; x3 = 32'd0;
        c0 = 32'd0; c1 = 32'd0; c2 = 32'd0; c3 = 32'd0;
        mu = 32'd0; fill_cnt = 32'd0; out_valid = 1'b0;
        y = 32'd0; hist_wr = 1'b0;
    end

    // cubic Lagrange sub-filter taps (truncated arithmetic)
    wire [31:0] d02  = x0 - x2;
    wire [31:0] t1   = $signed(d02) >>> 1;
    wire [31:0] x1m5 = x1 * 32'd5;
    wire [31:0] t2   = x2 - ($signed(x1m5) >>> 1) + (x0 << 1);
    wire [31:0] s3   = (x3 - x0) + ((x1 - x2) * 32'd3);
    wire [31:0] t3   = $signed(s3) >>> 1;

    // Horner evaluation in Q0.32 mu
    wire [63:0] p3 = {32'd0, c3} * {32'd0, mu};
    wire [31:0] h3 = p3[63:32] + c2;
    wire [63:0] p2 = {32'd0, h3} * {32'd0, mu};
    wire [31:0] h2 = p2[63:32] + c1;
    wire [63:0] p1 = {32'd0, h2} * {32'd0, mu};
    wire [31:0] y_next = p1[63:32] + c0;

    wire rd_done = pread && (fill_cnt == 32'd4);

    always @(posedge clk) begin
        if (!rst_n) begin
            x0 <= 32'd0; x1 <= 32'd0; x2 <= 32'd0; x3 <= 32'd0;
            c0 <= 32'd0; c1 <= 32'd0; c2 <= 32'd0; c3 <= 32'd0;
            mu <= 32'd0; fill_cnt <= 32'd0; out_valid <= 1'b0;
            y <= 32'd0; hist_wr <= 1'b0;
        end else if (en) begin
            if (hwr) begin
                x3 <= x2;
                x2 <= x1;
                x1 <= x0;
                x0 <= hwdata;
                fill_cnt <= (fill_cnt >= 32'd4) ? 32'd4 : fill_cnt + 32'd1;
                hist_wr <= 1'b1;
            end
            c0 <= x1;
            c1 <= t1;
            c2 <= t2;
            c3 <= t3;
            if (hmu_wr)
                mu <= hmu;
            out_valid <= rd_done;
            if (rd_done)
                y <= y_next;
        end
    end

    assign prdata = y;

    always @(posedge clk)
        if (out_valid)
            assert (hist_wr);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
,
    output wire armed_seen_a_o,
    output wire bo_flag_b_o,
    output wire brk_q_o,
    output wire [15:0] deb_cnt_b_o,
    output wire done_a_o,
    output wire [1:0] fsm_a_o,
    output wire q_ok_o,
    output wire [15:0] qual_cnt_obs,
    output wire started_seen_a_o,
    output wire [15:0] streak_b_o,
    output wire [15:0] thr_b_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
    assign armed_seen_a_o = armed_seen_a;
    assign bo_flag_b_o = bo_flag_b;
    assign brk_q_o = brk_q;
    assign deb_cnt_b_o = deb_cnt_b;
    assign done_a_o = done_a;
    assign fsm_a_o = fsm_a;
    assign q_ok_o = q_ok;
    assign qual_cnt_obs = qual_cnt;
    assign started_seen_a_o = started_seen_a;
    assign streak_b_o = streak_b;
    assign thr_b_o = thr_b;
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] deadline_o
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign deadline_o = deadline;
endmodule

module vbrk_gf8_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    input  wire         job_cap,
    input  wire         en_m,
    input  wire [7:0]   poly_in,
    input  wire         poly_we,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o,
    output wire         gf_done,
    output wire [7:0]   gf_result,
    output wire         job_pend_o,
    output wire         job_inflight_o,
    output wire [7:0]   job_wd_o,
    output wire         gf_busy_o,
output wire [7:0]   gf_deadline_o,
output wire [7:0]   job_iss_cnt_o,
output wire [7:0]   job_ret_cnt_o
);
    wire        a_done;
    wire        a_slot_reset;
    wire        a_brk;
    wire [15:0] a_qual_cnt_out;
    wire        a_armed_seen;
    wire        a_bo_flag;
    wire        a_brk_q;
    wire [15:0] a_deb_cnt;
    wire        a_done_mirror;
    wire [1:0]  a_fsm;
    wire        a_q_ok;
    wire [15:0] a_qual_cnt;
    wire        a_started_seen;
    wire [15:0] a_streak;
    wire [15:0] a_thr;

    wire        m_done;
    wire [7:0]  m_result;
    wire [7:0]  m_bitcnt;
    wire        m_busy;
    wire [7:0]  m_deadline;

    reg        job_pend     = 1'b0;
    reg [7:0]  job_a        = 8'd0;
    reg [7:0]  job_b        = 8'd0;
    reg        job_inflight = 1'b0;
    reg [7:0]  job_wd       = 8'd0;
reg [7:0]  job_iss_cnt  = 8'd0;
reg [7:0]  job_ret_cnt  = 8'd0;

    vbrk_bod_top u_a (
        .clk(clk),
        .rst(rst),
        .en_a(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .cap_en(cap_en),
        .en_b(en_b),
        .bod_clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .done(a_done),
        .slot_reset(a_slot_reset),
        .brk_o(a_brk),
        .qual_cnt_o(a_qual_cnt_out),
        .armed_seen_a_o(a_armed_seen),
        .bo_flag_b_o(a_bo_flag),
        .brk_q_o(a_brk_q),
        .deb_cnt_b_o(a_deb_cnt),
        .done_a_o(a_done_mirror),
        .fsm_a_o(a_fsm),
        .q_ok_o(a_q_ok),
        .qual_cnt_obs(a_qual_cnt),
        .started_seen_a_o(a_started_seen),
        .streak_b_o(a_streak),
        .thr_b_o(a_thr)
    );

    GF8MulCore u_m (
        .clk(clk),
        .rst(rst),
        .en(en_m),
        .req(job_pend),
        .a_in(job_a),
        .b_in(job_b),
        .poly_in(poly_in),
        .poly_we(poly_we),
        .done(m_done),
        .result(m_result),
        .bitcnt_o(m_bitcnt),
        .busy_o(m_busy),
        .deadline_o(m_deadline)
    );

    wire job_issue = en_m && job_pend && !m_busy;
wire job_drain  = (m_bitcnt == 8'd0) && (job_iss_cnt != job_ret_cnt);
wire job_retire = en_m && !job_issue && job_inflight && job_drain;

    always @(posedge clk) begin
        if (rst) begin
            job_pend     <= 1'b0;
            job_a        <= 8'd0;
            job_b        <= 8'd0;
            job_inflight <= 1'b0;
            job_wd       <= 8'd0;
job_iss_cnt  <= 8'd0;
job_ret_cnt  <= 8'd0;
        end else begin
            if (!job_pend) begin
                if (job_cap && a_brk_q) begin
                    job_pend <= 1'b1;
                    job_a    <= a_qual_cnt[7:0];
                    job_b    <= a_deb_cnt[7:0];
                end
            end else if (job_issue) begin
                job_pend <= 1'b0;
            end
            if (en_m) begin
if (job_issue)
job_iss_cnt <= job_iss_cnt + 8'd1;
if (job_retire)
job_ret_cnt <= job_ret_cnt + 8'd1;
                if (job_issue) begin
                    job_inflight <= 1'b1;
                    job_wd       <= 8'd9;
                end else if (job_inflight) begin
if (job_drain) begin
                        job_inflight <= 1'b0;
                        job_wd       <= 8'd0;
                    end else begin
                        job_wd <= job_wd - 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (job_inflight)
            assert (job_wd != 8'd0);

    assign done           = a_done;
    assign slot_reset     = a_slot_reset;
    assign brk_o          = a_brk;
    assign qual_cnt_o     = a_qual_cnt_out;
    assign gf_done        = m_done;
    assign gf_result      = m_result;
    assign job_pend_o     = job_pend;
    assign job_inflight_o = job_inflight;
    assign job_wd_o       = job_wd;
    assign gf_busy_o      = m_busy;
    assign gf_deadline_o  = m_deadline;
assign job_iss_cnt_o  = job_iss_cnt;
assign job_ret_cnt_o  = job_ret_cnt;
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b
);
    localparam NBF = NCOEF / 2;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end

    assign in_ready = !busy && !out_valid;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (accept) begin
            a_r   <= in_a;
            b_r   <= in_b;
            w_r   <= in_w;
            lat_q <= lat_eff;
            cd    <= lat_eff;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module traffic_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       preempt,
    output wire       ns_green,
    output wire       ew_green,
    output wire [2:0] phase_o
);
    // phases: 0 NS_GREEN, 1 NS_YELLOW, 2 ALL_RED_A, 3 EW_GREEN, 4 EW_YELLOW, 5 ALL_RED_B
    reg [2:0]  phase     = 3'd0;
    reg [15:0] timer     = 16'd39;
    reg [15:0] green_cnt = 16'd0;
    reg        armed     = 1'b1;
    reg        pv        = 1'b0;

    assign ns_green = (phase == 3'd0);
    assign ew_green = (phase == 3'd3);
    assign phase_o  = phase;

    function [15:0] dur;
        input [2:0] p;
        begin
            case (p)
                3'd0:    dur = 16'd39;
                3'd1:    dur = 16'd4;
                3'd2:    dur = 16'd1;
                3'd3:    dur = 16'd29;
                3'd4:    dur = 16'd4;
                default: dur = 16'd1;
            endcase
        end
    endfunction

    wire [2:0] nxt = (phase >= 3'd5) ? 3'd0 : phase + 3'd1;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            phase     <= 3'd0;
            timer     <= 16'd39;
            green_cnt <= 16'd0;
            armed     <= 1'b1;
        end else if (step) begin
            if (phase == 3'd0)
                green_cnt <= green_cnt + 16'd1;
            if (phase == 3'd0 && preempt) begin
                timer <= 16'd200;
                armed <= 1'b0;
            end else if (timer == 16'd0) begin
                phase <= nxt;
                timer <= dur(nxt);
                if (nxt == 3'd0)
                    green_cnt <= 16'd0;
            end else begin
                timer <= timer - 16'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(ns_green))
            assert (green_cnt <= 16'd40);
endmodule

module isqrt_handshake (
    input  wire              clk,
    input  wire              ce,      // idle condition: nothing moves when low
    input  wire              req,
    input  wire signed [7:0] din,
    output reg               ack,
    output reg               busy,
    output reg        [7:0]  result
);
    // magnitude of the (possibly negative) operand
    wire [7:0] mag   = din[7] ? (~din + 8'd1) : din;
    // number of reduction steps this request needs: structurally at most 7
    wire [3:0] steps = {1'b0, mag[2:0]};

    reg [3:0] work;   // reduction steps still to do
    reg [3:0] timer;  // completion budget (countdown)
    reg [7:0] acc;    // datapath scratch

    initial begin
        busy   = 1'b0;
        ack    = 1'b0;
        work   = 4'd0;
        timer  = 4'd0;
        acc    = 8'd0;
        result = 8'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (!busy && !ack) begin
                // phase 1: request accepted, busy mirrors the phase
                if (req) begin
                    busy  <= 1'b1;
                    work  <= steps;
                    timer <= 4'd11;   // budget strictly exceeds the work count
                    acc   <= mag;
                end
            end else if (busy) begin
                if (work != 4'd0) begin
                    work  <= work  - 4'd1;
                    timer <= timer - 4'd1;
                    acc   <= {1'b0, acc[7:1]};
                end else begin
                    // phase 2: completion, ack rises and busy drops
                    busy   <= 1'b0;
                    ack    <= 1'b1;
                    timer  <= 4'd0;
                    result <= acc;
                end
            end else begin
                // phase 3/4: ack held until req drops, then ack drops
                if (!req) ack <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the completion countdown must never
    // expire while a request is still outstanding.
    always @(*) begin
        if (busy) assert (timer != 4'd0);
    end
endmodule

module hls_pixclk_swallow (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [7:0] N,
    input wire [7:0] S,
    output wire strobe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, DONE = 2'd3;

    reg [3:0] pre_cnt = 4'd0;
    reg [7:0] p_cnt = 8'd0;
    reg [7:0] s_cnt = 8'd0;
    reg [7:0] n_reg = 8'd0;
    reg [7:0] s_reg = 8'd0;
    reg [1:0] phase = 2'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg q_seen = 1'b0;

    wire tc = (s_cnt != 8'd0) ? (pre_cnt == 4'd8) : (pre_cnt == 4'd7);
    wire hit = tc && (p_cnt <= 8'd1);
    assign strobe = en && !load && hit;

    always @(posedge clk) begin
        if (rst) begin
            pre_cnt <= 4'd0;
            p_cnt <= 8'd0;
            s_cnt <= 8'd0;
            n_reg <= 8'd0;
            s_reg <= 8'd0;
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            q_seen <= 1'b0;
        end else if (en) begin
            if (load) begin
                n_reg <= N;
                s_reg <= S;
                p_cnt <= N;
                s_cnt <= S;
                pre_cnt <= 4'd0;
                phase <= ARMED;
                armed_seen <= 1'b1;
                started_seen <= 1'b0;
                q_seen <= 1'b1;
            end else begin
                if (tc) begin
                    pre_cnt <= 4'd0;
                    if (p_cnt <= 8'd1) begin
                        p_cnt <= n_reg;
                        s_cnt <= s_reg;
                    end else begin
                        p_cnt <= p_cnt - 8'd1;
                        if (s_cnt != 8'd0)
                            s_cnt <= s_cnt - 8'd1;
                    end
                    case (phase)
                        ARMED: begin
                            phase <= STARTED;
                            started_seen <= 1'b1;
                        end
                        STARTED: begin
                            if (p_cnt <= 8'd1)
                                phase <= DONE;
                        end
                        default: phase <= phase;
                    endcase
                end else begin
                    pre_cnt <= pre_cnt + 4'd1;
                end
            end
        end
    end

    always @(*) assert (!(q_seen && phase == 2'd3) || (started_seen && armed_seen));
endmodule

module frac_xmul_cmp #(
    parameter W = 16,
    parameter [15:0] LAT = 16'd3
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         ce,
    input  wire         req,
    input  wire [W-1:0] a_num,
    input  wire [W-1:0] a_den,
    input  wire [W-1:0] c_num,
    input  wire [W-1:0] c_den,
    output wire         busy_o,
    output wire         done_o,
    output wire         lt_o,
    output wire         eq_o
);
    reg           busy    = 1'b0;
    reg  [1:0]    stage   = 2'd0;
    reg  [15:0]   cnt     = 16'd0;
    reg           armed   = 1'b0;
    reg  [W-1:0]  ra      = {W{1'b0}};
    reg  [W-1:0]  rb      = {W{1'b0}};
    reg  [W-1:0]  rc      = {W{1'b0}};
    reg  [W-1:0]  rd      = {W{1'b0}};
    reg  [2*W-1:0] prod_ad = {2*W{1'b0}};
    reg  [2*W-1:0] prod_cb = {2*W{1'b0}};
    reg           lt_r    = 1'b0;
    reg           eq_r    = 1'b0;
    reg           done_r  = 1'b0;

    assign busy_o = busy;
    assign done_o = done_r;
    assign lt_o   = lt_r;
    assign eq_o   = eq_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy    <= 1'b0;
            stage   <= 2'd0;
            cnt     <= 16'd0;
            armed   <= 1'b0;
            ra      <= {W{1'b0}};
            rb      <= {W{1'b0}};
            rc      <= {W{1'b0}};
            rd      <= {W{1'b0}};
            prod_ad <= {2*W{1'b0}};
            prod_cb <= {2*W{1'b0}};
            lt_r    <= 1'b0;
            eq_r    <= 1'b0;
            done_r  <= 1'b0;
        end else if (ce) begin
            done_r <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy  <= 1'b1;
                    armed <= 1'b1;
                    stage <= 2'd0;
                    cnt   <= LAT;
                    ra    <= a_num;
                    rb    <= a_den;
                    rc    <= c_num;
                    rd    <= c_den;
                end
            end else begin
                cnt <= cnt - 16'd1;
                case (stage)
                    2'd0: begin
                        prod_ad <= ra * rd;
                        prod_cb <= rc * rb;
                        stage   <= 2'd1;
                    end
                    2'd1: begin
                        lt_r  <= (prod_ad < prod_cb);
                        eq_r  <= (prod_ad == prod_cb);
                        stage <= 2'd2;
                    end
                    default: begin
                        busy   <= 1'b0;
                        done_r <= 1'b1;
                        stage  <= 2'd0;
                    end
                endcase
            end
        end
    end

    assert property (!armed || !busy || cnt != 16'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;

    initial pending = 3'd0;
    initial hold    = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
    // token out of the bucket.
    wire beat = run && (pending != 3'd0) && (remaining != 4'd0);

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
    wire load = tokens_hi && (pending == 3'd0) && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
        end else if (load) begin
            pending <= grant;
            hold    <= src_data;
        end else if (beat) begin
            pending <= pending - 3'd1;
        end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
        .spend     (beat),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
        .ce        (beat),
        .rd_data   (hold),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module lfsr_gpio (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_out,
    input wire wr_dir,
    input wire wr_lock,
    input wire wr_unlock,
    input wire [31:0] wdata,
    input wire [31:0] pins_in,
    input wire sample,
    output reg [31:0] pin_drive,
    output reg [33:0] box_sum
);
    reg [31:0] out_data;
    reg [31:0] dir;
    reg [31:0] cap0;
    reg [31:0] cap1;
    reg [31:0] cap2;
    reg        lock_win;
    reg        pv;

    initial out_data  = 32'h0000_0000;
    initial dir       = 32'h0000_0000;
    initial pin_drive = 32'h0000_0000;
    initial cap0      = 32'h0000_0000;
    initial cap1      = 32'h0000_0000;
    initial cap2      = 32'h0000_0000;
    initial box_sum   = 34'h0_0000_0000;
    initial lock_win  = 1'b0;
    initial pv        = 1'b0;

    wire [31:0] nxt_out = wr_out ? wdata : out_data;
    wire [31:0] nxt_dir = wr_dir ? wdata : dir;
    wire [31:0] new_cap = pins_in & ~dir;

    always @(posedge clk) begin
        if (rst) begin
            out_data  <= 32'h0000_0000;
            dir       <= 32'h0000_0000;
            pin_drive <= 32'h0000_0000;
            cap0      <= 32'h0000_0000;
            cap1      <= 32'h0000_0000;
            cap2      <= 32'h0000_0000;
            box_sum   <= 34'h0_0000_0000;
            lock_win  <= 1'b0;
        end else if (en) begin
            out_data  <= nxt_out;
            dir       <= nxt_dir;
            pin_drive <= nxt_out & nxt_dir;
            if (sample) begin
                cap0    <= new_cap;
                cap1    <= cap0;
                cap2    <= cap1;
                box_sum <= box_sum + {2'b00, new_cap} - {2'b00, cap2};
            end
            if (wr_unlock)
                lock_win <= 1'b0;
            else if (wr_lock)
                lock_win <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && lock_win && $past(lock_win) && $stable(out_data) && $stable(dir))
            assert ($stable(pin_drive));
endmodule

module udp_keccak_tagger (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_valid,
    input  wire        in_last,
    input  wire [15:0] in_data,
    input  wire        go,
    input  wire        ack,
    output wire [15:0] tag,
    output reg         done,
    output wire        busy
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [255:0] st;
    reg [3:0]   absorb_ptr;
    reg [4:0]   rnd;
    reg [1:0]   phase;
    reg         armed_flg;
    reg         started_flg;
    reg         seen_q;
    reg         done_q;

    initial begin
        st = 256'd0;
        absorb_ptr = 4'd0;
        rnd = 5'd0;
        phase = P_IDLE;
        armed_flg = 1'b0;
        started_flg = 1'b0;
        seen_q = 1'b0;
        done = 1'b0;
        done_q = 1'b0;
    end

    function [15:0] rotl;
        input [15:0] a;
        input [3:0]  r;
        begin
            rotl = (a << r) | (a >> (5'd16 - {1'b0, r}));
        end
    endfunction

    wire [15:0] rc = (16'h1 << rnd[3:0]) ^ {11'd0, rnd} ^ 16'h8081;

    reg [63:0]  C, D;
    reg [255:0] A1, B, nxt;
    integer x, y, i;

    always @(*) begin
        C = 64'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                C[16*x +: 16] = C[16*x +: 16] ^ st[16*(x+4*y) +: 16];
        for (x = 0; x < 4; x = x + 1)
            D[16*x +: 16] = C[16*((x+3)%4) +: 16] ^ rotl(C[16*((x+1)%4) +: 16], 4'd1);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                A1[16*(x+4*y) +: 16] = st[16*(x+4*y) +: 16] ^ D[16*x +: 16];
        B = 256'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                B[16*(y+4*((x+3*y)%4)) +: 16] = rotl(A1[16*(x+4*y) +: 16], (((x+4*y)*(x+4*y+1))/2) % 16);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                nxt[16*(x+4*y) +: 16] = B[16*(x+4*y) +: 16] ^ ((~B[16*(((x+1)%4)+4*y) +: 16]) & B[16*(((x+2)%4)+4*y) +: 16]);
        nxt[15:0] = nxt[15:0] ^ rc;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            st <= 256'd0;
            absorb_ptr <= 4'd0;
            rnd <= 5'd0;
            phase <= P_IDLE;
            armed_flg <= 1'b0;
            started_flg <= 1'b0;
            seen_q <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                P_IDLE: begin
                    if (in_valid) begin
                        for (i = 0; i < 16; i = i + 1)
                            if (i == absorb_ptr)
                                st[16*i +: 16] <= st[16*i +: 16] ^ in_data;
                        if (in_last) begin
                            phase <= P_ARMED;
                            armed_flg <= 1'b1;
                            seen_q <= 1'b1;
                            absorb_ptr <= 4'd0;
                        end else begin
                            absorb_ptr <= absorb_ptr + 4'd1;
                        end
                    end
                end
                P_ARMED: begin
                    if (go) begin
                        phase <= P_RUN;
                        rnd <= 5'd0;
                        started_flg <= 1'b1;
                    end
                end
                P_RUN: begin
                    st <= nxt;
                    if (rnd == 5'd23) begin
                        phase <= P_DONE;
                        done <= 1'b1;
                    end else begin
                        rnd <= rnd + 5'd1;
                    end
                end
                P_DONE: begin
                    if (ack) begin
                        phase <= P_IDLE;
                        done <= 1'b0;
                        armed_flg <= 1'b0;
                        started_flg <= 1'b0;
                        st <= 256'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) done_q <= done;

    assign tag  = st[15:0];
    assign busy = (phase == P_RUN);

    reg pv;
    initial pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && seen_q && done && !done_q)
            assert (armed_flg && started_flg);
endmodule

module tag_array_precedence (
    input wire clk,
    input wire ce,
    input wire fill,
    input wire [6:0] fill_set,
    input wire [7:0] fill_tag,
    input wire flush,
    input wire lookup,
    input wire [6:0] lookup_set,
    input wire [7:0] lookup_tag,
    output wire hit
);
    localparam [6:0] NSETS = 7'd96;

    reg [7:0] tag_mem [0:95];
    reg [95:0] valid;
    reg filled_any;
    reg [7:0] fill_cnt;
    reg hit_q;
    reg armed;

    integer i;
    initial begin
        for (i = 0; i < 96; i = i + 1) tag_mem[i] = 8'd0;
        valid = 96'd0;
        filled_any = 1'b0;
        fill_cnt = 8'd0;
        hit_q = 1'b0;
        armed = 1'b0;
    end

    wire fill_ok = fill && (fill_set < NSETS);
    wire look_ok = lookup && (lookup_set < NSETS);
    wire raw_hit = look_ok && valid[lookup_set] && (tag_mem[lookup_set] == lookup_tag);

    always @(posedge clk) begin
        if (ce && !flush && fill_ok)
            tag_mem[fill_set] <= fill_tag;
    end

    always @(posedge clk) begin
        if (ce) begin
            hit_q <= !flush && raw_hit;
            if (flush) begin
                valid <= 96'd0;
                filled_any <= 1'b0;
                fill_cnt <= 8'd0;
            end else if (fill_ok) begin
                valid[fill_set] <= 1'b1;
                filled_any <= 1'b1;
                if (fill_cnt != 8'hFF) fill_cnt <= fill_cnt + 8'd1;
                armed <= 1'b1;
            end
        end
    end

    assign hit = hit_q;

    always @(posedge clk)
        if (armed && hit_q)
            assert (filled_any);

    always @(posedge clk)
        if (armed && hit_q)
            assert (fill_cnt != 8'd0);
endmodule

module sorted_insert_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // enable: low freezes all sequencer state
    input  wire       i_arm,     // step 1: insertion request armed
    input  wire       i_scan,    // step 2: ordered scan started
    input  wire       i_commit,  // step 3: element spliced into the sorted list
    input  wire       i_abort,
    input  wire       i_open,    // Q: opens the observation window
    input  wire       i_close,   // R: closes it (may never arrive)
    output reg  [2:0] st,
    output reg  [2:0] size
);
    // binary-encoded FSM; encodings 1,3,4,7 are never entered
    localparam [2:0] S_IDLE   = 3'd0;
    localparam [2:0] S_ARMED  = 3'd2;
    localparam [2:0] S_SCAN   = 3'd5;
    localparam [2:0] S_COMMIT = 3'd6;

    reg did_arm;
    reg did_scan;
    reg win;

    initial begin
        st       = S_IDLE;
        size     = 3'd0;
        did_arm  = 1'b0;
        did_scan = 1'b0;
        win      = 1'b0;
    end

    // latched observation window: set by Q, cleared by R
    always @(posedge clk) begin
        if (rst)           win <= 1'b0;
        else if (i_close)  win <= 1'b0;
        else if (i_open)   win <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            st       <= S_IDLE;
            did_arm  <= 1'b0;
            did_scan <= 1'b0;
            size     <= 3'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_arm) begin
                        st      <= S_ARMED;
                        did_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_scan) begin
                        st       <= S_SCAN;
                        did_scan <= 1'b1;
                    end
                end
                S_SCAN: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_commit) begin
                        st <= S_COMMIT;
                    end
                end
                S_COMMIT: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                    if (size != 3'd4) size <= size + 1'b1;
                end
                default: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, after window-open until window-close:
    // a commit is never observed unless arm and scan already happened.
    always @(posedge clk)
        if (win && st == S_COMMIT)
            assert (did_arm && did_scan);
endmodule

module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
        end else if (sample) begin
            if (raw == out) begin
                cnt <= 3'd0;
                rem <= 3'd4;
            end else if (cnt == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

module sw_reset_ctrl #(
    parameter NPERIPH = 4,
    parameter IDXW = 2,
    parameter [31:0] PULSE_LEN = 32'd8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               cmd_valid,
    output wire               cmd_ready,
    input  wire [1:0]         cmd_op,
    input  wire [IDXW-1:0]    cmd_idx,
    input  wire               tick,
    output wire [NPERIPH-1:0] periph_rst,
    output wire               pulse_busy
);
    typedef enum logic [1:0] {IDLE = 2'd0, PULSE = 2'd1} state_t;

    localparam [1:0] OP_SET   = 2'd0;
    localparam [1:0] OP_CLR   = 2'd1;
    localparam [1:0] OP_PULSE = 2'd2;

    state_t            state     = IDLE;
    reg [NPERIPH-1:0]  rst_ctrl  = {NPERIPH{1'b0}};
    reg [31:0]         n_held    = 32'd0;
    reg [31:0]         pulse_cnt = 32'd0;
    reg [31:0]         remain    = 32'd0;
    reg [IDXW-1:0]     pulse_idx = {IDXW{1'b0}};
    reg                win       = 1'b0;

    assign cmd_ready = (state == IDLE) || (cmd_op != OP_PULSE);
    wire fire     = cmd_valid && cmd_ready;
    wire do_set   = fire && (cmd_op == OP_SET) && !rst_ctrl[cmd_idx];
    wire do_clr   = fire && (cmd_op == OP_CLR) &&  rst_ctrl[cmd_idx];
    wire do_pulse = fire && (cmd_op == OP_PULSE);

    assign pulse_busy = (state == PULSE);
    assign periph_rst = rst_ctrl | ((state == PULSE) ? ({{(NPERIPH-1){1'b0}}, 1'b1} << pulse_idx) : {NPERIPH{1'b0}});

    always @(posedge clk) begin
        if (rst) begin
            state     <= IDLE;
            rst_ctrl  <= {NPERIPH{1'b0}};
            n_held    <= 32'd0;
            pulse_cnt <= 32'd0;
            remain    <= 32'd0;
            pulse_idx <= {IDXW{1'b0}};
            win       <= 1'b0;
        end else begin
            if (do_set) begin
                rst_ctrl[cmd_idx] <= 1'b1;
                n_held <= n_held + 32'd1;
            end else if (do_clr) begin
                rst_ctrl[cmd_idx] <= 1'b0;
                n_held <= n_held - 32'd1;
            end
            case (state)
                IDLE: begin
                    if (do_pulse) begin
                        state     <= PULSE;
                        win       <= 1'b1;
                        pulse_cnt <= 32'd0;
                        remain    <= PULSE_LEN - 32'd1;
                        pulse_idx <= cmd_idx;
                    end
                end
                PULSE: begin
                    if (tick) begin
                        if (remain == 32'd0) begin
                            state <= IDLE;
                            win   <= 1'b0;
                        end else begin
                            pulse_cnt <= pulse_cnt + 32'd1;
                            remain    <= remain - 32'd1;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk) if (win) assert (pulse_cnt < PULSE_LEN);
    always @(posedge clk) if (win) assert (n_held <= NPERIPH);
endmodule

module fetchline_demux (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_flush,
    input  wire [1:0]   i_sel,
    input  wire [127:0] i_word,
    output wire [127:0] o_port0,
    output wire [127:0] o_port1,
    output wire [127:0] o_port2,
    output wire [127:0] o_port3,
    output wire [3:0]   o_occ
);
    // 8-entry store holding fetch lines (operand words) routed by the demux
    reg [127:0] mem [0:7];
    reg [3:0]   wptr  = 4'd0;   // next free entry
    reg [3:0]   occ   = 4'd0;   // number of valid entries
    reg         armed = 1'b0;   // sticky: set at the first store

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 128'd0;
    end

    wire do_store = i_ce && !i_flush && (occ != 4'd8) && (wptr != 4'd8);

    always @(posedge clk) begin
        if (do_store) begin
            mem[wptr[2:0]] <= i_word;
            wptr          <= wptr + 4'd1;
            occ           <= occ + 4'd1;
            armed         <= 1'b1;
        end else if (i_ce && i_flush) begin
            wptr  <= 4'd0;
            occ   <= 4'd0;
        end
    end

    // demux: route the incoming operand word to one of four output ports
    assign o_port0 = (i_sel == 2'd0) ? i_word : mem[0];
    assign o_port1 = (i_sel == 2'd1) ? i_word : mem[1];
    assign o_port2 = (i_sel == 2'd2) ? i_word : mem[2];
    assign o_port3 = (i_sel == 2'd3) ? i_word : mem[3];

    assign o_occ = occ;

    // after the first store, occupancy never exceeds the 8-entry store depth
    assert property (!armed || (occ <= 4'd8));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_start,
    input  wire       i_finish,
    output reg  [3:0] o_grant,
    output reg        o_fin
);
    // phase encoding: 0 = IDLE, 1 = ARMED (grant issued), 2 = RUNNING, 3 = FINISHED
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_FIN  = 2'd3;

    reg [1:0] last_grant;   // round-robin pointer
    reg [1:0] phase;
    reg [3:0] req_hold;     // request vector latched at grant time
    reg       r_arm_seen;   // this transaction was armed (granted)
    reg       r_start_seen; // this transaction was started
    reg       armed_q;      // sticky: an arbitration has happened at least once

    initial begin
        last_grant   = 2'd0;
        phase        = PH_IDLE;
        o_grant      = 4'b0000;
        o_fin        = 1'b0;
        req_hold     = 4'b0000;
        r_arm_seen   = 1'b0;
        r_start_seen = 1'b0;
        armed_q      = 1'b0;
    end

    // ---- round robin winner select, starting just after last_grant ----
    wire [1:0] c1 = last_grant + 2'd1;
    wire [1:0] c2 = last_grant + 2'd2;
    wire [1:0] c3 = last_grant + 2'd3;

    reg [1:0] win;
    reg       any;

    always @(*) begin
        any = 1'b1;
        if      (i_req[c1])         win = c1;
        else if (i_req[c2])         win = c2;
        else if (i_req[c3])         win = c3;
        else if (i_req[last_grant]) win = last_grant;
        else begin
            win = last_grant;
            any = 1'b0;
        end
    end

    // ---- arm / start / finish chain ----
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (any) begin
                        o_grant      <= (4'b0001 << win);
                        last_grant   <= win;
                        req_hold     <= i_req;
                        phase        <= PH_ARM;
                        r_arm_seen   <= 1'b1;
                        armed_q      <= 1'b1;
                    end
                end
                PH_ARM: begin
                    if (i_start) begin
                        phase        <= PH_RUN;
                        r_start_seen <= 1'b1;
                    end
                end
                PH_RUN: begin
                    if (i_finish) begin
                        phase        <= PH_FIN;
                        o_fin        <= 1'b1;
                    end
                end
                PH_FIN: begin
                    phase        <= PH_IDLE;
                    o_grant      <= 4'b0000;
                    o_fin        <= 1'b0;
                    req_hold     <= 4'b0000;
                    r_arm_seen   <= 1'b0;
                    r_start_seen <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, only required once arbitration has ever occurred:
    // a completion can never be observed unless this transaction was armed
    // and then started.
    always @(posedge clk)
        if (armed_q && o_fin)
            assert (r_start_seen && r_arm_seen);

endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // Banked grant position: the half-select bit is registered on its own, so
   // the aging path is an offset toggle plus a bank carry rather than a full
   // 2-bit incrementer feeding the index register.
   reg  bank;                         // 0: grant sits in req[1:0], 1: req[3:2]
   wire nxt_bank = bank ^ idx[0];     // rotation carries out of the current bank


    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
       bank   = 1'b0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
               bank  <= enc[1];
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
               // advance one slot: the offset toggles, the bank takes the carry
               idx  <= {nxt_bank, ~idx[0]};
               bank <= nxt_bank;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module wb_port_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       issue,
    input  wire [7:0] lat,
    input  wire       oreq,
    input  wire [7:0] olat,
    output wire       acc,
    output wire       oacc,
    output wire       wb_fire,
    output wire       wb_trk
);
    // result-bus reservation shift register: bit i = write port booked i steps ahead
    reg [47:0] resv = 48'd0;
    // slot booked by the tracked (watched) functional unit request
    reg [47:0] trk  = 48'd0;
    // window register: set when tracked request accepted, cleared on its writeback
    reg        pend = 1'b0;
    // bounded-response countdown
    reg [7:0]  cnt  = 8'd0;

    wire [47:0] rsh = resv >> 1;
    wire lat_ok  = (lat  < 8'd48) && ((rsh & (48'd1 << lat))  == 48'd0);
    wire olat_ok = (olat < 8'd48) && ((rsh & (48'd1 << olat)) == 48'd0);

    assign acc  = step && issue && !pend && lat_ok;
    assign oacc = step && oreq && olat_ok && !(acc && (olat == lat));
    assign wb_fire = step && resv[0];
    assign wb_trk  = step && pend && trk[0];

    always @(posedge clk) begin
        if (rst) begin
            resv <= 48'd0;
            trk  <= 48'd0;
            pend <= 1'b0;
            cnt  <= 8'd0;
        end else if (step) begin
            resv <= rsh | (acc ? (48'd1 << lat) : 48'd0) | (oacc ? (48'd1 << olat) : 48'd0);
            trk  <= (trk >> 1) | (acc ? (48'd1 << lat) : 48'd0);
            if (pend) begin
                if (trk[0]) begin
                    pend <= 1'b0;
                    cnt  <= 8'd0;
                end else begin
                    cnt  <= cnt - 8'd1;
                end
            end else if (acc) begin
                pend <= 1'b1;
                cnt  <= lat + 8'd1;
            end
        end
    end

    // after accept (pend set) until writeback (pend cleared): countdown never expires
    assert property (!pend || cnt != 8'd0);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module isp_fb_sema (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [31:0] req_id,
    input wire [5:0] cell_sel,
    input wire arm_req,
    input wire start_req,
    input wire fin_req,
    output wire [1:0] o_phase,
    output wire [47:0] o_locked,
    output wire [31:0] o_cur_owner
);
    reg [47:0] locked = 48'd0;
    reg [31:0] owner [0:47];
    reg [5:0] cur_cell = 6'd0;
    reg [1:0] phase = 2'd0;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) owner[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            locked <= 48'd0;
            cur_cell <= 6'd0;
            phase <= 2'd0;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
        end else if (en) begin
            case (phase)
                2'd0: begin
                    if (arm_req && (cell_sel < 6'd48) && !locked[cell_sel]) begin
                        locked[cell_sel] <= 1'b1;
                        owner[cell_sel] <= req_id;
                        cur_cell <= cell_sel;
                        phase <= 2'd1;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                2'd1: begin
                    if (start_req) begin
                        phase <= 2'd2;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                2'd2: begin
                    if (fin_req) begin
                        locked[cur_cell] <= 1'b0;
                        phase <= 2'd0;
                        fin_cnt <= fin_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_locked = locked;
    assign o_cur_owner = owner[cur_cell];

    always @(*) assert (((arm_cnt - start_cnt) <= 32'd1) && ((start_cnt - fin_cnt) <= 32'd1));
endmodule

module lane_tile_transpose #(
    parameter N = 4,
    parameter W = 64
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(N);
    localparam ENTRIES = N * N;

    typedef enum logic [0:0] {FILL = 1'b0, DRAIN = 1'b1} state_t;
    state_t state;
    initial state = FILL;

    // lane-sensor tile: rows = approach lanes, columns = signal phases
    reg [W-1:0] mem [0:ENTRIES-1];
    integer k;
    initial begin
        for (k = 0; k < ENTRIES; k = k + 1)
            mem[k] = {W{1'b0}};
    end

    reg [IW-1:0] wrow, wcol, rrow, rcol;
    initial wrow = 0;
    initial wcol = 0;
    initial rrow = 0;
    initial rcol = 0;

    // shadow history registers
    reg [63:0] wr_total, rd_total;
    initial wr_total = 64'd0;
    initial rd_total = 64'd0;

    // scope register: high until the first tile has been fully drained
    reg armed;
    initial armed = 1'b1;

    assign in_ready  = (state == FILL);
    assign out_valid = (state == DRAIN);
    assign out_data  = mem[{rrow, rcol}];

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wrow == N-1) && (wcol == N-1);
    wire rd_last = (rrow == N-1) && (rcol == N-1);

    always @(posedge clk) begin
        if (wr_fire) begin
            mem[{wrow, wcol}] <= in_data;
            wr_total <= wr_total + 64'd1;
            if (wcol == N-1) begin
                wcol <= 0;
                wrow <= wrow + 1'b1;
            end else begin
                wcol <= wcol + 1'b1;
            end
            if (wr_last)
                state <= DRAIN;
        end
        if (rd_fire) begin
            rd_total <= rd_total + 64'd1;
            if (rrow == N-1) begin
                rrow <= 0;
                rcol <= rcol + 1'b1;
            end else begin
                rrow <= rrow + 1'b1;
            end
            if (rd_last) begin
                state <= FILL;
                armed <= 1'b0;
            end
        end
    end

    // Precedence, before first drain completes: a phase column is offered only after the whole tile was written
    always @(posedge clk)
        if (armed && out_valid)
            assert (wr_total == ENTRIES);

    // Precedence, before first drain completes: every item read was written earlier
    always @(posedge clk)
        if (armed)
            assert (rd_total <= wr_total);
endmodule

module histo_hotbins (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] sel,
    output wire       full,
    output wire [2:0] o_hot
);
    // Sample histogram: four bins, one increment per accepted sample.
    // The bins always sum to the total-samples register, and the total
    // saturates at MAXTOT, so at most two bins can ever reach THRESH.
    localparam [3:0] MAXTOT = 4'd9;
    localparam [3:0] THRESH = 4'd4;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;
    reg [2:0] hot;    // number of bins that have reached THRESH
    reg       armed;  // sticky: set the first time hot reaches 2
    reg       pv;     // past-valid

    initial begin
        bin0  = 4'd0;
        bin1  = 4'd0;
        bin2  = 4'd0;
        bin3  = 4'd0;
        total = 4'd0;
        hot   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    wire accept = ce && !rst && (total < MAXTOT);

    wire [3:0] cur = (sel == 2'd0) ? bin0 :
                     (sel == 2'd1) ? bin1 :
                     (sel == 2'd2) ? bin2 : bin3;

    wire cross = accept && (cur == (THRESH - 4'd1));

    assign full  = (total == MAXTOT);
    assign o_hot = hot;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            hot   <= 3'd0;
            armed <= 1'b0;
        end else begin
            if (accept) begin
                total <= total + 4'd1;
                case (sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (cross)
                    hot <= hot + 3'd1;
            end
            if (hot >= 3'd2)
                armed <= 1'b1;
        end
    end

    // P: once the design has been armed (hot first reached its true
    // maximum of 2), the hot-bin occupancy can never change again --
    // i.e. it never exceeds 2, well below what the 3-bit register allows.
    always @(posedge clk)
        if (pv && armed)
            assert ($stable(hot));
endmodule

module ic_cap_unit (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm_ev,
    input  wire        sel_wr,
    input  wire        sel_val,
    input  wire        cap_req,
    input  wire        ext_edge,
    output reg         pending,
    output reg         over,
    output reg  [31:0] cap,
    output reg  [31:0] cd
);
    localparam [31:0] TIMEOUT = 32'd48;

    reg        edge_sel;
    reg        armed;
    reg  [31:0] timer;

    initial begin
        edge_sel = 1'b0;
        armed    = 1'b0;
        pending  = 1'b0;
        over     = 1'b0;
        cap      = 32'd0;
        timer    = 32'd0;
        cd       = 32'd0;
    end

    wire req_acc = !pending && cap_req;
    wire done    = pending && (timer == 32'd47);
    wire edge_det = (edge_sel ? ext_edge : !ext_edge);

    always @(posedge clk) begin
        if (ce) begin
            if (arm_ev)
                armed <= 1'b1;
            if (sel_wr)
                edge_sel <= sel_val;
            if (done) begin
                pending <= 1'b0;
                cd      <= 32'd0;
                if (edge_det)
                    over <= 1'b1;
            end else if (req_acc) begin
                pending <= 1'b1;
                timer   <= 32'd0;
                cd      <= TIMEOUT;
            end else if (pending) begin
                timer <= timer + 32'd1;
                cd    <= cd - 32'd1;
                if (edge_det) begin
                    cap <= timer;
                    over <= 1'b0;
                end
            end
        end
    end

    // after the unit has been armed: countdown never expires while the
    // capture request is still outstanding
    always @(posedge clk)
        if (armed && pending)
            assert (cd != 32'd0);

    // and the free-running timer never wraps while the engine is pending
    always @(posedge clk)
        if (armed && pending)
            assert (timer != 32'hFFFFFFFF);
endmodule

module razor_shadow_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [63:0] d_main,
    input  wire [63:0] d_late,
    output reg  [63:0] main_q,
    output reg  [63:0] shadow_q,
    output reg  [63:0] err_cnt,
    output reg         razor_err
);
    localparam [1:0] IDLE    = 2'd0;
    localparam [1:0] ARMED   = 2'd1;
    localparam [1:0] STARTED = 2'd2;
    localparam [1:0] DONE    = 2'd3;

    reg [1:0] phase = IDLE;
    reg armed = 1'b0;
    reg started = 1'b0;
    reg finished = 1'b0;

    initial begin
        main_q    = 64'd0;
        shadow_q  = 64'd0;
        err_cnt   = 64'd0;
        razor_err = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= IDLE;
            armed     <= 1'b0;
            started   <= 1'b0;
            finished  <= 1'b0;
            main_q    <= 64'd0;
            shadow_q  <= 64'd0;
            err_cnt   <= 64'd0;
            razor_err <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    main_q   <= d_main;
                    armed    <= 1'b1;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= ARMED;
                end
                ARMED: begin
                    shadow_q <= d_late;
                    started  <= 1'b1;
                    phase    <= STARTED;
                end
                STARTED: begin
                    razor_err <= (main_q != shadow_q);
                    if (main_q != shadow_q) begin
                        main_q  <= shadow_q;
                        err_cnt <= err_cnt + 64'd1;
                    end
                    finished <= 1'b1;
                    phase    <= DONE;
                end
                default: begin
                    armed    <= 1'b0;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (finished) assert (started && armed);
endmodule

module hs_tag_prec (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       start,
    input  wire       slv_rdy,
    input  wire [3:0] data,
    output wire       o_busy,
    output wire       o_req,
    output wire       o_ack,
    output wire [3:0] o_last_tag
);

    // four-phase request/acknowledge master
    //   phase 0 : idle           req=0 ack=0 busy=0
    //   phase 1 : request posted req=1 ack=0 busy=1
    //   phase 2 : ack received   req=1 ack=1 busy=1
    //   phase 3 : req withdrawn  req=0 ack=1 busy=1
    reg [1:0] phase;   initial phase   = 2'd0;
    reg       busy;    initial busy    = 1'b0;
    reg       req;     initial req     = 1'b0;
    reg       ack;     initial ack     = 1'b0;

    // tag posted with the request, and the tag captured when ack rose
    reg [3:0] tag;     initial tag     = 4'd0;
    reg [3:0] ack_tag; initial ack_tag = 4'd0;
    reg [3:0] last_tag;initial last_tag= 4'd0;

    // sticky arm: set the first time an acknowledge is taken
    reg       armed;   initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            busy     <= 1'b0;
            req      <= 1'b0;
            ack      <= 1'b0;
            tag      <= 4'd0;
            ack_tag  <= 4'd0;
            last_tag <= 4'd0;
            armed    <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (start) begin
                          phase <= 2'd1;
                          req   <= 1'b1;
                          busy  <= 1'b1;
                          tag   <= data;      // post the tag with the request
                      end
                2'd1: if (slv_rdy) begin
                          phase   <= 2'd2;
                          ack     <= 1'b1;
                          ack_tag <= tag;     // shadow of the earlier posted tag
                          armed   <= 1'b1;    // first handshake ever completed
                      end
                2'd2: begin
                          phase <= 2'd3;
                          req   <= 1'b0;      // req may only drop after ack rose
                      end
                2'd3: begin
                          phase    <= 2'd0;
                          ack      <= 1'b0;
                          busy     <= 1'b0;
                          last_tag <= ack_tag;
                      end
            endcase
        end
    end

    assign o_busy     = busy;
    assign o_req      = req;
    assign o_ack      = ack;
    assign o_last_tag = last_tag;

    // Precedence, after the first acknowledge has been seen:
    // whenever we observe the withdrawn-request phase (ack high, req low),
    // the acknowledged tag must be the tag that was posted earlier.
    always @(posedge clk)
        assert (!armed || !(ack && !req) || (ack_tag == tag));

endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
   assign o_upstream_ready = (space != 2'd0);
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

endmodule

// Gray-coded pointer crossing a domain boundary through a two-flop
// synchronizer, with a shadow register holding the previously observed
// synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       inc,     // advance the write pointer
    output wire [3:0] o_sync_gray,
    output wire [3:0] o_shadow_gray
);
    // producer side
    reg [3:0] bin;
    reg [3:0] gptr;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow register: the sample observed one enabled cycle earlier
    reg [3:0] prev_s2;

    // binary shadows of the pipeline stages (book-keeping only)
    reg [3:0] bs1, bs2, bs3;

    initial begin
        bin     = 4'b0000;
        gptr    = 4'b0000;
        s1      = 4'b0000;
        s2      = 4'b0000;
        prev_s2 = 4'b0000;
        bs1     = 4'b0000;
        bs2     = 4'b0000;
        bs3     = 4'b0000;
    end

    wire [3:0] bin_next = bin + (inc ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            bin     <= bin_next;
            gptr    <= bin_next ^ (bin_next >> 1);

            s1      <= gptr;
            s2      <= s1;
            prev_s2 <= s2;

            bs1     <= bin;
            bs2     <= bs1;
            bs3     <= bs2;
        end
    end

    assign o_sync_gray   = s2;
    assign o_shadow_gray = prev_s2;

    // difference vectors
    wire [3:0] d_shadow = s2 ^ prev_s2;
    wire [3:0] d_stage  = s1 ^ s2;

    // Precedence: whatever the synchronizer shows now must have been preceded
    // by a value at most one bit away, at both observation points.
    always @(posedge clk) begin
        assert ((d_shadow & (d_shadow - 4'd1)) == 4'd0);
        assert ((d_stage  & (d_stage  - 4'd1)) == 4'd0);
    end
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] spent_total
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;
   // staged level status: the threshold compare is registered one cycle
   // ahead of the reported flag so the status output path stays short
   reg hi_stage;

    initial tokens   = 3'd0;
   initial hi_stage = 1'b0;
    initial tokens_hi = 1'b0;
    initial spent_total = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
           hi_stage  <= 1'b0;
            tokens_hi <= 1'b0;
            spent_total <= 4'd0;
        end else begin
            if (dec) spent_total <= spent_total + 4'd1;
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

           if (inc && tokens == 3'd1)      hi_stage <= 1'b1;
           else if (dec && tokens == 3'd2) hi_stage <= 1'b0;
           tokens_hi <= hi_stage;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);
endmodule

module degate_trng_health (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [127:0] sample
);
    reg [127:0] last_smp = 128'd0;
    reg [127:0] ref_smp  = 128'd0;
    reg [127:0] hist [0:7];
    reg [2:0]   rep_cnt  = 3'd0;
    reg [2:0]   win_cnt  = 3'd0;
    reg [3:0]   apt_cnt  = 4'd0;
    reg         alarm    = 1'b0;
    reg         armed    = 1'b0;
    reg         pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            hist[i] = 128'd0;
    end

    wire       rep_match = (sample == last_smp);
    wire [2:0] rep_nxt   = rep_match ? ((rep_cnt == 3'd7) ? 3'd7 : rep_cnt + 3'd1) : 3'd0;

    reg [3:0] apt_nxt;
    reg [2:0] win_nxt;
    always @(*) begin
        if (win_cnt == 3'd0) begin
            apt_nxt = 4'd1;
            win_nxt = 3'd1;
        end else if (win_cnt == 3'd7) begin
            apt_nxt = 4'd0;
            win_nxt = 3'd0;
        end else begin
            apt_nxt = apt_cnt + ((sample == ref_smp) ? 4'd1 : 4'd0);
            win_nxt = win_cnt + 3'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            last_smp <= 128'd0;
            ref_smp  <= 128'd0;
            rep_cnt  <= 3'd0;
            win_cnt  <= 3'd0;
            apt_cnt  <= 4'd0;
            alarm    <= 1'b0;
            armed    <= 1'b0;
        end else if (en) begin
            hist[win_cnt] <= sample;
            last_smp <= sample;
            rep_cnt  <= rep_nxt;
            if (win_cnt == 3'd0)
                ref_smp <= sample;
            apt_cnt  <= apt_nxt;
            win_cnt  <= win_nxt;
            if (rep_nxt >= 3'd5 || apt_nxt >= 4'd6)
                alarm <= 1'b1;
            if (win_cnt == 3'd7)
                armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (pv && !rst && armed && $stable(alarm))
            assert (!(apt_cnt[3] && win_cnt != 3'd0));
    end
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module symbol_histogram (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_dec,        // 0 = tally an incoming symbol, 1 = retire one
    input wire [1:0] i_bin,  // modulation class of the symbol
    input wire i_flush,      // closes the measurement window
    output wire o_empty,
    output wire o_has_data,
    output wire o_armed
);
    // per-modulation symbol tallies
    reg [3:0] bin0, bin1, bin2, bin3;
    // total symbols currently accounted for
    reg [5:0] total;
    // window register: set by the first tally, cleared by a flush
    reg       armed;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 6'd0;
    initial armed = 1'b0;

    wire [3:0] sel = (i_bin == 2'd0) ? bin0 :
                     (i_bin == 2'd1) ? bin1 :
                     (i_bin == 2'd2) ? bin2 : bin3;

    wire do_flush = i_ce &&  i_flush;
    wire do_inc   = i_ce && !i_flush && !i_dec && (sel != 4'hF);
    wire do_dec   = i_ce && !i_flush &&  i_dec && (sel != 4'h0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_flush) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_inc) begin
            case (i_bin)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 6'd1;
            armed <= 1'b1;
        end else if (do_dec) begin
            case (i_bin)
                2'd0: bin0 <= bin0 - 4'd1;
                2'd1: bin1 <= bin1 - 4'd1;
                2'd2: bin2 <= bin2 - 4'd1;
                2'd3: bin3 <= bin3 - 4'd1;
            endcase
            total <= total - 6'd1;
        end
    end

    assign o_empty    = (total == 6'd0);
    assign o_has_data = (bin0 != 4'd0) || (bin1 != 4'd0) ||
                        (bin2 != 4'd0) || (bin3 != 4'd0);
    assign o_armed    = armed;

    // Absence, after arm until flush: the window never reports empty and
    // holding data at the same time.
    assert property (!armed || !(o_empty && o_has_data));
endmodule

module twiddle_rom_seq #(
    parameter N   = 256,
    parameter LGN = 8,
    parameter DW  = 64
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    output reg  [DW-1:0] o_re,
    output reg  [DW-1:0] o_im,
    output reg           o_unity,
    output reg           o_negj,
    output reg           o_win
);
    localparam HALF = N / 2;
    localparam QW   = N / 4;
    localparam SH   = DW - 2 - 2*(LGN-2);
    localparam [DW-1:0] ONE = {2'b01, {(DW-2){1'b0}}};

    // quarter-wave magnitude table: cos(pi*x/(N/2)) approximated as 1-(x/QW)^2
    function [DW-1:0] cmag;
        input [LGN-2:0] x;
        reg [2*(LGN-1)-1:0] sq;
        begin
            sq   = x * x;
            cmag = ONE - ({{(DW-2*(LGN-1)){1'b0}}, sq} << SH);
        end
    endfunction

    // real coefficient table: cos(2*pi*k/N), quadrant folded
    function [DW-1:0] re_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    re_rom =  cmag(r);
                2'd1:    re_rom = -cmag(QW - r);
                2'd2:    re_rom = -cmag(r);
                default: re_rom =  cmag(QW - r);
            endcase
        end
    endfunction

    // imaginary coefficient table: -sin(2*pi*k/N), quadrant folded
    function [DW-1:0] im_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    im_rom = -cmag(QW - r);
                2'd1:    im_rom = -cmag(r);
                2'd2:    im_rom =  cmag(QW - r);
                default: im_rom =  cmag(r);
            endcase
        end
    endfunction

    reg [DW-1:0]  pos;
    reg [DW-1:0]  stage;
    reg [LGN-1:0] re_addr;
    reg [LGN-1:0] im_addr;

    initial pos     = 0;
    initial stage   = 0;
    initial re_addr = 0;
    initial im_addr = 0;
    initial o_re    = 0;
    initial o_im    = 0;
    initial o_unity = 1'b0;
    initial o_negj  = 1'b0;
    initial o_win   = 1'b0;

    // twiddle index for butterfly position pos in stage: (pos << stage) mod N
    wire [LGN-1:0] tw_k = pos[LGN-1:0] << stage[2:0];

    always @(posedge clk) begin
        if (i_reset) begin
            pos     <= 0;
            stage   <= 0;
            re_addr <= 0;
            im_addr <= 0;
            o_re    <= 0;
            o_im    <= 0;
            o_unity <= 1'b0;
            o_negj  <= 1'b0;
            o_win   <= 1'b0;
        end else if (i_ce) begin
            // separate address registers for the real and imaginary ROM ports
            re_addr <= tw_k;
            im_addr <= tw_k;
            // registered coefficient output pair
            o_re    <= re_rom(re_addr);
            o_im    <= im_rom(im_addr);
            o_unity <= (re_addr == 0);
            o_negj  <= (im_addr == QW);
            if (pos == HALF-1) begin
                pos   <= 0;
                stage <= (stage == LGN-1) ? 0 : stage + 1;
            end else begin
                pos   <= pos + 1;
            end
            // stage window: opens at first butterfly, closes at last
            if (pos == 0)
                o_win <= 1'b1;
            else if (pos == HALF-1)
                o_win <= 1'b0;
        end
    end

    // within a stage window, the unity and -j coefficient markers never coincide
    assert property (!o_win || !(o_unity && o_negj));
endmodule

module pipe_ao22_track (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        in_valid,
    input  wire [31:0] din,
    input  wire        open_win,
    input  wire        close_win,
    output wire [31:0] dout,
    output wire        dout_valid
);
    reg        v1;
    reg [31:0] s1;
    reg        v2;
    reg [31:0] s2;
    reg        seen_in;
    reg [31:0] in_cnt;
    reg        armed;

    initial v1 = 1'b0;
    initial s1 = 32'd0;
    initial v2 = 1'b0;
    initial s2 = 32'd0;
    initial seen_in = 1'b0;
    initial in_cnt = 32'd0;
    initial armed = 1'b0;

    wire [31:0] s1_next;
    wire [31:0] s2_next;

    ao22 #(.W(32)) u_s1 (
        .a({32{in_valid}}), .b(din),
        .c({32{~in_valid}}), .d(s1),
        .y(s1_next)
    );

    ao22 #(.W(32)) u_s2 (
        .a({32{v1}}), .b(s1),
        .c({32{~v1}}), .d(s2),
        .y(s2_next)
    );

    assign dout = s2;
    assign dout_valid = v2;

    always @(posedge clk) begin
        if (rst) begin
            v1 <= 1'b0;
            s1 <= 32'd0;
            v2 <= 1'b0;
            s2 <= 32'd0;
            seen_in <= 1'b0;
            in_cnt <= 32'd0;
            armed <= 1'b0;
        end else if (step) begin
            v1 <= in_valid;
            s1 <= s1_next;
            v2 <= v1;
            s2 <= s2_next;
            seen_in <= seen_in | in_valid;
            if (in_valid && (in_cnt != 32'hFFFFFFFF))
                in_cnt <= in_cnt + 32'd1;
            if (open_win)
                armed <= 1'b1;
            else if (close_win)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed && v2) assert (seen_in);

    always @(posedge clk)
        if (armed && v2) assert (in_cnt != 32'd0);
endmodule

module ao22 #(parameter W = 32) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire [W-1:0] c,
    input  wire [W-1:0] d,
    output wire [W-1:0] y
);
    assign y = (a & b) | (c & d);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output reg  [31:0]  debug_status
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    reg [15:0] stat_accept = 16'd0;
    reg [15:0] stat_retire = 16'd0;
    reg [15:0] stat_inwait = 16'd0;
    reg [15:0] stat_outwait = 16'd0;
    reg [15:0] stat_busy = 16'd0;
    reg [15:0] stat_stall_run = 16'd0;
    reg [15:0] stat_stall_max = 16'd0;
    reg [PTR_W-1:0] stat_high_water = {PTR_W{1'b0}};
    reg [3:0] stat_events = 4'd0;
    reg [2:0] stat_page = 3'd0;
    reg [W-1:0] stat_last_lat = {W{1'b0}};
    reg [7:0] stat_epoch = 8'd0;
    reg [15:0] stat_checksum = 16'd0;
    initial begin
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (load_cfg) begin
            stat_epoch <= stat_epoch + 8'd1;
            stat_last_lat <= cfg_lat;
        end
        if (accept && stat_accept != 16'hffff)
            stat_accept <= stat_accept + 16'd1;
        if (retire && stat_retire != 16'hffff)
            stat_retire <= stat_retire + 16'd1;
        if (in_valid && !in_ready && stat_inwait != 16'hffff)
            stat_inwait <= stat_inwait + 16'd1;
        if (out_valid && !out_ready && stat_outwait != 16'hffff)
            stat_outwait <= stat_outwait + 16'd1;
        if (busy && ce && stat_busy != 16'hffff)
            stat_busy <= stat_busy + 16'd1;
        if (queued > stat_high_water)
            stat_high_water <= queued;
        if (accept)
            stat_checksum <= {stat_checksum[14:0], stat_checksum[15]} ^ in_a ^ in_b ^ in_w;
        if (out_valid && !out_ready) begin
            if (stat_stall_run != 16'hffff)
                stat_stall_run <= stat_stall_run + 16'd1;
            if (stat_stall_run >= stat_stall_max && stat_stall_run != 16'hffff)
                stat_stall_max <= stat_stall_run + 16'd1;
        end else begin
            stat_stall_run <= 16'd0;
        end
        if (in_valid && !in_ready)
            stat_events[0] <= 1'b1;
        if (out_valid && !out_ready)
            stat_events[1] <= 1'b1;
        if (accept && !ce)
            stat_events[2] <= 1'b1;
        if (load_cfg && busy)
            stat_events[3] <= 1'b1;
        if (ce) begin
            stat_page <= stat_page + 3'd1;
            case (stat_page)
                3'd0: debug_status <= {stat_retire, stat_accept};
                3'd1: debug_status <= {stat_outwait, stat_inwait};
                3'd2: debug_status <= {stat_stall_max, stat_stall_run};
                3'd3: debug_status <= {stat_checksum, stat_busy};
                3'd4: debug_status <= stat_high_water;
                3'd5: debug_status <= stat_last_lat;
                3'd6: debug_status <= {20'd0, stat_epoch, stat_events};
                3'd7: debug_status <= {24'd0, ce, busy, head_valid, q_full, q_empty, out_valid, in_valid, in_ready};
            endcase
        end
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rot_seq_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [1:0]  sym,
    input  wire [15:0] din,
    input  wire        load,
    input  wire        win_start,
    input  wire        win_stop,
    output reg  [15:0] word,
    output reg         hit
);
    // ---- sequence detector for pattern sym = 1, 2, 3 ----------------
    reg [2:0] prog;    // match progress, 0..3 (3 = full match)
    reg [3:0] onehot;  // one-hot shadow of prog, maintained structurally
    reg       armed;   // window register: opened by win_start, closed by win_stop
    reg       pv;      // past-valid

    initial begin
        prog   = 3'd0;
        onehot = 4'b0001;
        armed  = 1'b0;
        pv     = 1'b0;
        word   = 16'h0000;
        hit    = 1'b0;
    end

    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
            3'd1:    nprog = (sym == 2'd2) ? 3'd2 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            3'd2:    nprog = (sym == 2'd3) ? 3'd3 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            default: nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
        endcase
    end

    wire adv = (nprog == prog + 3'd1);

    // ---- barrel rotate: amount = 4*prog, stage selects taken from onehot ----
    wire [15:0] r4 = (onehot[1] | onehot[3]) ? {word[11:0], word[15:12]} : word;
    wire [15:0] r8 = (onehot[2] | onehot[3]) ? {r4[7:0],   r4[15:8]}     : r4;

    always @(posedge clk) begin
        if (rst) begin
            prog   <= 3'd0;
            onehot <= 4'b0001;
            armed  <= 1'b0;
            word   <= 16'h0000;
            hit    <= 1'b0;
        end else if (ce) begin
            prog <= nprog;
            if (adv)                onehot <= {onehot[2:0], 1'b0};
            else if (nprog == 3'd1) onehot <= 4'b0010;
            else                    onehot <= 4'b0001;

            word <= load ? din : r8;
            hit  <= (nprog == 3'd3);

            if (win_stop)       armed <= 1'b0;
            else if (win_start) armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // ---- property: inside the window, the previous one-hot shadow was live ----
    always @(posedge clk)
        if (pv && armed)
            assert ($past(onehot) != 4'd0);
endmodule

module grant_fsm (
    input  wire clk,
    input  wire rst,
    input  wire en,
    input  wire req_a,
    input  wire req_b,
    output wire grant_a,
    output wire grant_b
);
    // Binary-encoded arbiter FSM.  Only five of the eight 3-bit encodings
    // are ever entered; 3'd3, 3'd5 and 3'd7 are unreachable by construction.
    localparam S_IDLE  = 3'd0;  // 000
    localparam S_A     = 3'd1;  // 001  -> grants A next cycle
    localparam S_ACOOL = 3'd2;  // 010
    localparam S_B0    = 3'd4;  // 100  -> grants B next cycle
    localparam S_B1    = 3'd6;  // 110  -> grants B next cycle

    reg [2:0] st = S_IDLE;
    reg [2:0] nxt;

    // Registered (pipelined) grant outputs: bit 0 of the state decodes the
    // A grant, bit 2 decodes the B grant.
    reg ga = 1'b0;
    reg gb = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(*) begin
        case (st)
            S_IDLE:  nxt = req_a ? S_A : (req_b ? S_B0 : S_IDLE);
            S_A:     nxt = S_ACOOL;
            S_ACOOL: nxt = S_IDLE;
            S_B0:    nxt = S_B1;
            S_B1:    nxt = S_IDLE;
            default: nxt = S_IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            ga <= 1'b0;
            gb <= 1'b0;
        end else if (en) begin
            st <= nxt;
            ga <= st[0];
            gb <= st[2];
        end
    end

    assign grant_a = ga;
    assign grant_b = gb;

    // P: whenever the A grant rises, the B grant must not be asserted.
    always @(posedge clk)
        if (pv && $rose(ga))
            assert (!gb);
endmodule

module r2sdf_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    output reg  [63:0] y_out,
    output reg         y_valid
);
    // single-delay-feedback memory: N/2 = 64 entries
    reg [63:0] dly [0:63];
    reg [63:0] ptr;       // stage control counter (0..63)
    reg        phase;     // 0 = fill, 1 = compute (butterfly)
    reg [63:0] bfly_cnt;  // butterflies issued
    reg        armed;     // high until the first frame's compute pass completes
    integer i;

    initial begin
        ptr = 64'd0; phase = 1'b0; bfly_cnt = 64'd0; armed = 1'b1;
        y_out = 64'd0; y_valid = 1'b0;
        for (i = 0; i < 64; i = i + 1) dly[i] = 64'd0;
    end

    wire [5:0]  idx    = ptr[5:0];
    wire [63:0] fb     = dly[idx];
    wire [63:0] bf_sum = fb + x_in;
    wire [63:0] bf_dif = fb - x_in;
    wire        last   = (ptr == 64'd63);

    always @(posedge clk) begin
        if (rst) begin
            ptr <= 64'd0; phase <= 1'b0; bfly_cnt <= 64'd0; armed <= 1'b1;
            y_out <= 64'd0; y_valid <= 1'b0;
        end else if (en) begin
            if (phase) begin
                // compute: butterfly between delayed sample and new sample
                dly[idx] <= bf_dif;
                y_out    <= bf_sum;
                bfly_cnt <= bfly_cnt + 64'd1;
                if (last) armed <= 1'b0;
            end else begin
                // fill: push new sample into delay line, drain previous differences
                dly[idx] <= x_in;
                y_out    <= fb;
            end
            y_valid <= 1'b1;
            if (last) begin
                ptr   <= 64'd0;
                phase <= ~phase;
            end else begin
                ptr <= ptr + 64'd1;
            end
        end
    end

    // before the first frame completes, at most 63 butterflies have been issued
    always @(posedge clk) if (armed) assert (bfly_cnt <= 64'd63);
endmodule

module spi_master_face (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire cfg_wr,
    input wire [1:0] cfg_mode,
    input wire [7:0] tx_data,
    input wire miso,
    output reg cs_n,
    output reg sclk,
    output wire mosi,
    output reg [7:0] rx_data,
    output reg done
);
    reg busy;
    reg [7:0] shreg;
    reg [7:0] bitcnt;
    reg cpol;
    reg cpha;
    reg phase;
    reg samp;
    reg win;
    reg [1:0] mode_sh;
    reg pv;

    initial begin
        cs_n = 1'b1; sclk = 1'b0; rx_data = 8'd0; done = 1'b0;
        busy = 1'b0; shreg = 8'd0; bitcnt = 8'd0; cpol = 1'b0; cpha = 1'b0;
        phase = 1'b0; samp = 1'b0; win = 1'b0; mode_sh = 2'b00; pv = 1'b0;
    end

    assign mosi = shreg[7];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cs_n <= 1'b1; sclk <= 1'b0; done <= 1'b0; busy <= 1'b0;
            bitcnt <= 8'd0; cpol <= 1'b0; cpha <= 1'b0; phase <= 1'b0;
            win <= 1'b0; mode_sh <= 2'b00;
        end else if (ce) begin
            done <= 1'b0;
            if (!busy) begin
                if (cfg_wr) begin
                    cpol <= cfg_mode[1];
                    cpha <= cfg_mode[0];
                    sclk <= cfg_mode[1];
                end else if (start) begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    shreg <= tx_data;
                    bitcnt <= 8'd0;
                    phase <= 1'b0;
                    win <= 1'b1;
                    mode_sh <= {cpol, cpha};
                end
            end else begin
                sclk <= ~sclk;
                phase <= ~phase;
                if (!phase) begin
                    samp <= miso;
                end else begin
                    shreg <= {shreg[6:0], (cpha ? miso : samp)};
                    if (bitcnt == 8'd7) begin
                        bitcnt <= 8'd0;
                        busy <= 1'b0;
                        cs_n <= 1'b1;
                        win <= 1'b0;
                        done <= 1'b1;
                        rx_data <= {shreg[6:0], (cpha ? miso : samp)};
                    end else begin
                        bitcnt <= bitcnt + 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $stable(cs_n))
            assert ($stable({cpol, cpha}) && ({cpol, cpha} == mode_sh));
endmodule

module gf180_tapline_cal (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire [63:0] din,
    input  wire        cal_start,
    input  wire        cal_done,
    output wire [63:0] dout,
    output wire [7:0]  tok_o,
    output wire [63:0] cal_cnt_o,
    output wire        win_o
);
    reg [63:0] tap  [0:7];
    reg [63:0] samp [0:7];
    reg [7:0]  tok;
    reg        win;
    reg [63:0] cal_cnt;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 64'd0;
            samp[i] = 64'd0;
        end
        tok     = 8'd0;
        win     = 1'b0;
        cal_cnt = 64'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) begin
                tap[i]  <= 64'd0;
                samp[i] <= 64'd0;
            end
            tok     <= 8'd0;
            win     <= 1'b0;
            cal_cnt <= 64'd0;
        end else if (en) begin
            tap[0] <= din;
            for (i = 1; i < 8; i = i + 1)
                tap[i] <= tap[i-1];
            for (i = 0; i < 8; i = i + 1)
                samp[i] <= tap[i];
            if (cal_start) begin
                win     <= 1'b1;
                tok     <= 8'b0000_0001;
                cal_cnt <= 64'd0;
            end else if (cal_done) begin
                win <= 1'b0;
                tok <= 8'd0;
            end else if (win) begin
                tok <= tok << 1;
                if (cal_cnt != 64'hFFFF_FFFF_FFFF_FFFF)
                    cal_cnt <= cal_cnt + 64'd1;
            end else begin
                tok <= 8'd0;
            end
        end
    end

    assign dout      = samp[7];
    assign tok_o     = tok;
    assign cal_cnt_o = cal_cnt;
    assign win_o     = win;

    always @(*)
        if (win)
            assert (!(tok[6] && tok[7]));
endmodule

module ctr_drbg_engine (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] cmd,
    input wire [31:0] entropy,
    output reg busy,
    output reg [31:0] out_data,
    output reg [31:0] reseed_ctr
);
    // cmd: 2'b01 instantiate, 2'b10 reseed, 2'b11 generate
    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
endmodule

module call_debounce_lift (
    input  wire       clk,
    input  wire       ce,      // sample / step enable; low = whole design idles
    input  wire       btn,     // raw (bouncy) hall-call button at the top floor
    output reg  [1:0] floor,
    output reg        clean    // debounced call line
);
    localparam integer K          = 4;     // identical consecutive samples needed
    localparam [1:0]   CALL_FLOOR = 2'd3;

    reg [2:0] cnt;      // stability counter: consecutive samples differing from clean
    reg       req;      // latched pending request
    reg       moving;   // cab in motion
    reg       armed;    // starts high, cleared the first time the cab departs
    reg       pv;       // past-valid

    initial begin
        floor  = 2'd0;
        clean  = 1'b0;
        cnt    = 3'd0;
        req    = 1'b0;
        moving = 1'b0;
        armed  = 1'b1;
        pv     = 1'b0;
    end

    wire mismatch = (btn != clean);
    wire flip     = mismatch && (cnt == 3'd3);   // K-1 previous mismatches + this one
    wire go       = req && !moving;
    wire arrive   = moving && (floor == CALL_FLOOR);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            // ---- debouncer: K identical consecutive samples flip the clean output ----
            if (mismatch) begin
                if (cnt == 3'd3) cnt <= 3'd0;
                else             cnt <= cnt + 3'd1;
            end else begin
                cnt <= 3'd0;
            end

            if (flip) clean <= ~clean;

            // rising edge of the debounced line latches a hall call
            if (flip && !clean) req <= 1'b1;

            // ---- cab control: one floor of travel per step ----
            if (go) begin
                moving <= 1'b1;
                req    <= 1'b0;
                armed  <= 1'b0;      // first departure clears the scope register
            end else if (arrive) begin
                moving <= 1'b0;
            end else if (moving) begin
                floor <= floor + 2'd1;
            end
        end
    end

    // P: before the cab has ever departed, the floor register never changes
    always @(posedge clk)
        if (pv && armed)
            assert (floor == $past(floor));
endmodule

module btb_vec #(
    parameter NUM_ENTRIES = 12,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         upd_taken,
    input  wire         upd_nottaken,
    input  wire [W-1:0] upd_pc,
    input  wire [W-1:0] upd_target,
    input  wire [W-1:0] lookup_pc,
    output wire         hit,
    output wire [W-1:0] pred_target,
    output wire         full
);
    localparam [3:0] NE4 = NUM_ENTRIES;

    reg [NUM_ENTRIES-1:0]   valid;
    reg [NUM_ENTRIES*W-1:0] tag_flat;
    reg [NUM_ENTRIES*W-1:0] tgt_flat;
    reg [31:0]              n_valid;

    initial begin
        valid    = {NUM_ENTRIES{1'b0}};
        tag_flat = {(NUM_ENTRIES*W){1'b0}};
        tgt_flat = {(NUM_ENTRIES*W){1'b0}};
        n_valid  = 32'd0;
    end

    wire [3:0] u_raw = upd_pc[5:2];
    wire [3:0] uidx  = (u_raw >= NE4) ? (u_raw - NE4) : u_raw;
    wire [3:0] l_raw = lookup_pc[5:2];
    wire [3:0] lidx  = (l_raw >= NE4) ? (l_raw - NE4) : l_raw;

    wire [W-1:0] u_tag = tag_flat[uidx*W +: W];
    wire [W-1:0] l_tag = tag_flat[lidx*W +: W];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid    <= {NUM_ENTRIES{1'b0}};
            tag_flat <= {(NUM_ENTRIES*W){1'b0}};
            tgt_flat <= {(NUM_ENTRIES*W){1'b0}};
            n_valid  <= 32'd0;
        end else if (upd_taken) begin
            tag_flat[uidx*W +: W] <= upd_pc;
            tgt_flat[uidx*W +: W] <= upd_target;
            valid[uidx] <= 1'b1;
            if (!valid[uidx])
                n_valid <= n_valid + 32'd1;
        end else if (upd_nottaken) begin
            if (valid[uidx] && (u_tag == upd_pc)) begin
                valid[uidx] <= 1'b0;
                n_valid <= n_valid - 32'd1;
            end
        end
    end

    assign hit         = valid[lidx] && (l_tag == lookup_pc);
    assign pred_target = tgt_flat[lidx*W +: W];
    assign full        = (n_valid == NUM_ENTRIES);

    always @(posedge clk)
        if ($rose(full))
            assert (&valid);
endmodule

module preload_timer #(
    parameter W = 64,
    parameter [W-1:0] INIT_PERIOD = 64'd7
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         tick,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire         match,
    output wire         reload_evt
);
    reg [W-1:0] cnt           = INIT_PERIOD;
    reg [W-1:0] period        = INIT_PERIOD;
    reg [W-1:0] cmp_active    = {W{1'b0}};
    reg [W-1:0] shadow_period = INIT_PERIOD;
    reg [W-1:0] shadow_cmp    = {W{1'b0}};
    reg [W-1:0] deadline      = {W{1'b0}};
    reg         pending       = 1'b0;
    reg         armed         = 1'b0;
    reg         pv            = 1'b0;

    assign in_ready   = !pending;
    wire   accept     = in_valid && in_ready;
    wire   due        = (deadline == {W{1'b0}});
    assign reload_evt = tick && (cnt == {W{1'b0}});
    assign match      = (cnt == cmp_active);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cnt           <= INIT_PERIOD;
            period        <= INIT_PERIOD;
            cmp_active    <= {W{1'b0}};
            shadow_period <= INIT_PERIOD;
            shadow_cmp    <= {W{1'b0}};
            pending       <= 1'b0;
            deadline      <= {W{1'b0}};
        end else begin
            if (tick) begin
                if (cnt == {W{1'b0}}) begin
                    if (pending) begin
                        cnt        <= shadow_period;
                        period     <= shadow_period;
                        cmp_active <= shadow_cmp;
                        pending    <= 1'b0;
                    end else begin
                        cnt <= period;
                    end
                end else begin
                    cnt <= cnt - 1'b1;
                end
                if (pending && (cnt != {W{1'b0}}) && !due)
                    deadline <= deadline - 1'b1;
            end
            if (accept) begin
                shadow_period <= in_period;
                shadow_cmp    <= in_cmp;
                pending       <= 1'b1;
                armed         <= 1'b1;
                deadline      <= tick ? ((cnt == {W{1'b0}}) ? period : (cnt - 1'b1)) : cnt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && pending && $rose(due))
            assert (cnt == {W{1'b0}});
endmodule

module i2c_arb_monitor #(
    parameter FRAME_BITS = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire        drv_bit,
    input  wire        sda_in,
    output reg         lost,
    output reg  [31:0] lost_pos,
    output reg         last_drv
);
    localparam [31:0] FRAME = FRAME_BITS;

    reg        busy    = 1'b0;
    reg [31:0] bit_cnt = 32'd0;
    reg        win     = 1'b0;
    reg [31:0] sh_cnt  = 32'd0;

    initial begin
        lost     = 1'b0;
        lost_pos = 32'd0;
        last_drv = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            bit_cnt  <= 32'd0;
            lost     <= 1'b0;
            lost_pos <= 32'd0;
            last_drv <= 1'b1;
            win      <= 1'b0;
            sh_cnt   <= 32'd0;
        end else if (ce) begin
            if (stop) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (start && !busy) begin
                busy     <= 1'b1;
                bit_cnt  <= 32'd0;
                lost     <= 1'b0;
                lost_pos <= 32'd0;
                last_drv <= 1'b1;
                win      <= 1'b0;
                sh_cnt   <= 32'd0;
            end else if (busy) begin
                last_drv <= lost ? 1'b1 : drv_bit;
                if (!lost && drv_bit && !sda_in) begin
                    lost     <= 1'b1;
                    lost_pos <= bit_cnt;
                    win      <= 1'b1;
                    sh_cnt   <= 32'd0;
                end else if (win) begin
                    sh_cnt <= sh_cnt + 32'd1;
                end
                bit_cnt <= bit_cnt + 32'd1;
                if (bit_cnt == FRAME - 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win) assert (lost_pos < bit_cnt);

    always @(posedge clk)
        if (win) assert (sh_cnt < bit_cnt);
endmodule

module arduboy_tone_ripple #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         in_valid,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output wire         pin_a,
    output wire         pin_b,
    output wire [W-1:0] o_count
);
    localparam [W-1:0] HALF = {1'b1, {(W-1){1'b0}}};

    // a tone tick is accepted only when valid and ready are both high
    assign in_ready = !out_valid;
    wire accept = in_valid && in_ready;

    // ripple chain of toggle flip-flops: each stage toggles when the
    // previous stage falls (synchronous model of the ripple carry)
    wire [W:0]   t;
    wire [W-1:0] q;
    assign t[0] = accept;

    genvar i;
    generate
        for (i = 0; i < W; i = i + 1) begin : stage
            reg tff = 1'b0;
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n)
                    tff <= 1'b0;
                else if (t[i])
                    tff <= ~tff;
            end
            assign q[i]   = tff;
            assign t[i+1] = t[i] & tff;
        end
    endgenerate

    // shadow record of every tick accepted earlier
    reg [W-1:0] shadow = {W{1'b0}};
    initial out_valid = 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shadow    <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (accept)
                shadow <= shadow + 1'b1;
            if (t[W])
                out_valid <= 1'b1;          // full buzzer period completed
            else if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    // piezo wired between two pins, driven in antiphase
    assign pin_a   = q[W-1];
    assign pin_b   = ~q[W-1];
    assign o_count = q;

    // precedence: buzzer phase high now => half a period of ticks accepted earlier
    always @(*) assert (!q[W-1] || shadow >= HALF);
    // precedence: period-done offered now => the accepted-tick record has wrapped
    always @(*) assert (!out_valid || shadow == {W{1'b0}});
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
endmodule

module autobaud_detect (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_rx,
    input  wire        i_arm,
    input  wire        i_clr,
    output wire [31:0] o_divisor,
    output wire        o_locked
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_ARMED = 2'd1;
    localparam [1:0] S_MEAS  = 2'd2;
    localparam [1:0] S_DONE  = 2'd3;

    reg [1:0]  stage     = S_IDLE;
    reg        measuring = 1'b0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] divisor   = 32'd0;
    reg        rx_q      = 1'b1;
    reg        win       = 1'b0;
    reg        pv        = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            rx_q <= i_rx;
            if (i_clr) begin
                stage     <= S_IDLE;
                measuring <= 1'b0;
                timer     <= 32'd0;
                win       <= 1'b0;
            end else begin
                if (i_arm) win <= 1'b1;
                // edge-capture timer: count start-bit width
                if (measuring) begin
                    if (i_rx) begin
                        divisor   <= timer + 32'd1;
                        measuring <= 1'b0;
                    end else begin
                        timer <= timer + 32'd1;
                    end
                end
                // measurement-state register: arm -> start -> finish
                case (stage)
                    S_IDLE:  if (i_arm) stage <= S_ARMED;
                    S_ARMED: if (rx_q && !i_rx) begin
                                 stage     <= S_MEAS;
                                 measuring <= 1'b1;
                                 timer     <= 32'd0;
                             end
                    S_MEAS:  if (i_rx) stage <= S_DONE;
                    default: ;
                endcase
            end
        end
    end

    assign o_divisor = divisor;
    assign o_locked  = (stage == S_DONE);

    always @(posedge clk)
        if (pv && win && $stable(stage))
            assert ($stable(divisor));
endmodule

module autoneg_arb #(
    parameter [63:0] LINK_TIME  = 64'd12,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire        i_rx_valid,
    input  wire [63:0] i_rx_page,
    input  wire        i_link_fail,
    output wire        o_link_up,
    output wire [63:0] o_mode
);
    typedef enum logic [2:0] {AN_IDLE, AN_ABILITY, AN_ACK, AN_COMPLETE, AN_LINK_OK} an_state_t;

    an_state_t state;
    reg [63:0] link_tmr;
    reg [63:0] remain;
    reg [63:0] rx_abil;
    reg [63:0] mode;
    reg        win;

    initial state    = AN_IDLE;
    initial link_tmr = 64'd0;
    initial remain   = LINK_TIME;
    initial rx_abil  = 64'd0;
    initial mode     = 64'd0;
    initial win      = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            state    <= AN_IDLE;
            link_tmr <= 64'd0;
            remain   <= LINK_TIME;
            rx_abil  <= 64'd0;
            mode     <= 64'd0;
            win      <= 1'b0;
        end else if (i_ce) begin
            case (state)
                AN_IDLE: begin
                    if (i_start) begin
                        state    <= AN_ABILITY;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        win      <= 1'b1;
                    end
                end
                AN_ABILITY: begin
                    if (i_rx_valid) begin
                        rx_abil  <= i_rx_page;
                        link_tmr <= 64'd0;
                        remain   <= LINK_TIME;
                        state    <= AN_ACK;
                    end else if (remain == 64'd0) begin
                        state <= AN_IDLE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_ACK: begin
                    if (remain == 64'd0) begin
                        mode  <= rx_abil & LOCAL_ABIL;
                        state <= AN_COMPLETE;
                    end else begin
                        link_tmr <= link_tmr + 64'd1;
                        remain   <= remain - 64'd1;
                    end
                end
                AN_COMPLETE: begin
                    state <= AN_LINK_OK;
                    win   <= 1'b0;
                end
                AN_LINK_OK: begin
                    if (i_link_fail)
                        state <= AN_IDLE;
                end
                default: state <= AN_IDLE;
            endcase
        end
    end

    assign o_link_up = (state == AN_LINK_OK);
    assign o_mode    = mode;

    always @(posedge clk)
        if (win)
            assert (link_tmr <= LINK_TIME);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps  <= steps + {1'b0, credit} + 3'd1;
               credit <= 2'd0;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       credit  <= credit + 2'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       credit    <= credit + 2'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                      steps  <= steps + {1'b0, credit} + 3'd1;
                      credit <= 2'd0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg [15:0] dbg_status
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [7:0] WDOG_LIMIT = 8'd24;

    reg [7:0] ramp_cnt;
reg [7:0] req_total;
reg [7:0] busy_cycles;
reg [7:0] wdog_cnt;
reg wdog_trip;
reg overlap_err;
reg [3:0] overlap_cnt;
reg [3:0] done_cnt;
reg [3:0] ramp_seen;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
req_total = 8'd0; busy_cycles = 8'd0;
wdog_cnt = 8'd0; wdog_trip = 1'b0;
overlap_err = 1'b0; overlap_cnt = 4'd0;
done_cnt = 4'd0; ramp_seen = 4'd0;
dbg_status = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
req_total <= 8'd0; busy_cycles <= 8'd0;
wdog_cnt <= 8'd0; wdog_trip <= 1'b0;
overlap_err <= 1'b0; overlap_cnt <= 4'd0;
done_cnt <= 4'd0; ramp_seen <= 4'd0;
dbg_status <= 16'd0;
        end else if (i_ce) begin
if ((state == S_IDLE) && i_req && (req_total != 8'hFF))
req_total <= req_total + 8'd1;
if (win && (busy_cycles != 8'hFF))
busy_cycles <= busy_cycles + 8'd1;
if ((state != S_IDLE) && i_req) begin
overlap_err <= 1'b1;
if (overlap_cnt != 4'hF)
overlap_cnt <= overlap_cnt + 4'd1;
end
if (state == S_IDLE) begin
wdog_cnt <= 8'd0;
end else if (wdog_cnt == WDOG_LIMIT) begin
wdog_trip <= 1'b1;
end else begin
wdog_cnt <= wdog_cnt + 8'd1;
end
if (state == S_DONE)
done_cnt <= done_cnt + 4'd1;
if ((state == S_RAMP) && (ramp_cnt == RAMP_LAST))
ramp_seen <= ramp_seen + 4'd1;
dbg_status <= {wdog_trip, overlap_err, done_cnt[1:0] ^ ramp_seen[1:0],
req_total[3:0] ^ overlap_cnt, busy_cycles ^ wdog_cnt};
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module range_mask_insert (
    input  wire        clk,
    input  wire        req,
    input  wire        ce,
    input  wire [4:0]  i_start,
    input  wire [4:0]  i_end,
    input  wire [31:0] i_src,
    output wire [31:0] mask,
    output reg  [31:0] dst,
    output reg         busy
);
    reg [4:0]  start_idx = 5'd0;
    reg [4:0]  end_idx   = 5'd0;
    reg [4:0]  cur       = 5'd0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] src       = 32'd0;
    reg        arm       = 1'b0;
    initial busy = 1'b0;
    initial dst  = 32'd0;

    // contiguous range mask decoder: bits start_idx..end_idx asserted
    assign mask = (32'hFFFFFFFF << start_idx) & (32'hFFFFFFFF >> (5'd31 - end_idx));

    wire [4:0] off = cur - start_idx;

    always @(posedge clk) begin
        if (!busy) begin
            if (req && (i_start <= i_end)) begin
                start_idx <= i_start;
                end_idx   <= i_end;
                cur       <= i_start;
                src       <= i_src;
                busy      <= 1'b1;
                timer     <= 32'd32;
                arm       <= 1'b1;
            end
        end else if (ce) begin
            dst[cur] <= src[off];
            timer    <= timer - 32'd1;
            if (cur == end_idx)
                busy <= 1'b0;
            else
                cur <= cur + 5'd1;
        end
    end

    always @(*) assert (!arm || !busy || (timer != 32'd0));
endmodule

module mutex_arb (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire req_a,
    input wire req_b,
    input wire rel,
    input wire w_open,
    input wire w_close,
    output wire o_own_a,
    output wire o_own_b,
    output wire [31:0] o_grants
);
    localparam [1:0] IDLE = 2'd0, ARM = 2'd1, START = 2'd2, FIN = 2'd3;

    reg [1:0] phase;
    reg latch_a, latch_b;
    reg sync_a, sync_b;
    reg own_a, own_b;
    reg win;
    reg [31:0] n_grants;

    initial phase = IDLE;
    initial latch_a = 1'b0;
    initial latch_b = 1'b0;
    initial sync_a = 1'b0;
    initial sync_b = 1'b0;
    initial own_a = 1'b0;
    initial own_b = 1'b0;
    initial win = 1'b0;
    initial n_grants = 32'd0;

    // cross-coupled set terms: each side inhibited by the other, A wins ties
    wire set_a = req_a & ~latch_b;
    wire set_b = req_b & ~latch_a & ~set_a;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            latch_a <= 1'b0;
            latch_b <= 1'b0;
            sync_a <= 1'b0;
            sync_b <= 1'b0;
            own_a <= 1'b0;
            own_b <= 1'b0;
            win <= 1'b0;
            n_grants <= 32'd0;
        end else if (i_ce) begin
            if (w_open)
                win <= 1'b1;
            else if (w_close)
                win <= 1'b0;
            case (phase)
                IDLE: begin
                    if (set_a | set_b) begin
                        latch_a <= latch_a | set_a;
                        latch_b <= latch_b | set_b;
                        phase <= ARM;
                    end
                end
                ARM: begin
                    sync_a <= latch_a;
                    sync_b <= latch_b;
                    phase <= START;
                end
                START: begin
                    own_a <= sync_a;
                    own_b <= sync_b;
                    n_grants <= n_grants + 32'd1;
                    phase <= FIN;
                end
                FIN: begin
                    if (rel) begin
                        latch_a <= 1'b0;
                        latch_b <= 1'b0;
                        sync_a <= 1'b0;
                        sync_b <= 1'b0;
                        own_a <= 1'b0;
                        own_b <= 1'b0;
                        phase <= IDLE;
                    end
                end
            endcase
        end
    end

    assign o_own_a = own_a;
    assign o_own_b = own_b;
    assign o_grants = n_grants;

    // Chain precedence inside the window: ownership (finish) only with filter (start) and latch (arm)
    assert property (!win || ((!own_a || (sync_a && latch_a)) && (!own_b || (sync_b && latch_b))));
endmodule

module pkt_stream_mux #(
    parameter NSRC = 4,
    parameter DW   = 128,
    parameter CNTW = 3,
    parameter SRCW = $clog2(NSRC)
) (
    input  wire                 clk,
    input  wire                 rst_n,
    input  wire [NSRC-1:0]      s_valid,
    input  wire [NSRC*DW-1:0]   s_data,
    input  wire [NSRC-1:0]      s_last,
    output wire [NSRC-1:0]      s_ready,
    output reg                  o_valid,
    output reg  [DW-1:0]        o_data,
    output reg                  o_last,
    output reg  [SRCW-1:0]      o_src,
    input  wire                 o_ready
);
    reg [SRCW-1:0] cur_src  = {SRCW{1'b0}};
    reg            locked   = 1'b0;
    reg [CNTW-1:0] beat_cnt = {CNTW{1'b0}};
    initial begin
        o_valid = 1'b0;
        o_data  = {DW{1'b0}};
        o_last  = 1'b0;
        o_src   = {SRCW{1'b0}};
    end

    wire            can_load = !o_valid || o_ready;
    wire            take     = can_load && s_valid[cur_src];
    wire [DW-1:0]   sel_data = s_data[cur_src*DW +: DW];
    wire            sel_last = s_last[cur_src];
    wire [SRCW-1:0] next_src = (cur_src == NSRC-1) ? {SRCW{1'b0}} : cur_src + {{(SRCW-1){1'b0}},1'b1};

    assign s_ready = can_load ? ({{(NSRC-1){1'b0}},1'b1} << cur_src) : {NSRC{1'b0}};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_src  <= {SRCW{1'b0}};
            locked   <= 1'b0;
            beat_cnt <= {CNTW{1'b0}};
            o_valid  <= 1'b0;
            o_data   <= {DW{1'b0}};
            o_last   <= 1'b0;
            o_src    <= {SRCW{1'b0}};
        end else begin
            if (take) begin
                o_valid <= 1'b1;
                o_data  <= sel_data;
                o_last  <= sel_last;
                o_src   <= cur_src;
                if (sel_last) begin
                    locked   <= 1'b0;
                    beat_cnt <= {CNTW{1'b0}};
                    cur_src  <= next_src;
                end else begin
                    locked   <= 1'b1;
                    beat_cnt <= (beat_cnt == {CNTW{1'b1}}) ? beat_cnt : beat_cnt + {{(CNTW-1){1'b0}},1'b1};
                end
            end else begin
                if (o_valid && o_ready)
                    o_valid <= 1'b0;
                if (!locked && !s_valid[cur_src] && (|s_valid))
                    cur_src <= next_src;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && $rose(locked))
            assert (beat_cnt == {{(CNTW-1){1'b0}},1'b1});
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool != 4'd0);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;
    wire       gnt_any = |gnt;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
        end else begin
            hold <= (hold | gnt) & ~rel;
            pool <= pool - {3'b0, gnt_any} + {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
endmodule
